window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["EXO"]={"book":"EXO","editions":{"fin-biblia1776":[[1,1,"Nämät ovat Israelin lasten nimet, jotka Jakobin kanssa tulivat Egyptiin, itsekukin huoneinensa he sinne tulivat,","Nämät ovat Israelin lasten nimet, jotka Jakobin kanssa tulivat Egyptiin, itsekukin huoneinensa he sinne tulivat,"],[1,2,"Ruben, Simeon, Levi ja Juuda.","Ruben, Simeon, Levi ja Juuda."],[1,3,"Isaskar, Zebulon ja Benjamin.","Isaskar, Zebulon ja Benjamin."],[1,4,"Dan, Naphtali, Gad ja Asser.","Dan, Naphtali, Gad ja Asser."],[1,5,"Ja kaikki henget, jotka Jakobin kupeista olivat tulleet, olivat seitsemänkymmentä henkeä. Mutta Joseph oli (ennen) Egyptissä.","Ja kaikki henget, jotka Jakobin kupeista olivat tulleet, olivat seitsemänkymmentä henkeä. Mutta Joseph oli (ennen) Egyptissä."],[1,6,"Ja Joseph oli kuollut, ja kaikki hänen veljensä, ja kaikki sen aikaiset.","Ja Joseph oli kuollut, ja kaikki hänen veljensä, ja kaikki sen aikaiset."],[1,7,"Ja Israelin lapset olivat hedelmälliset ja suuresti enenivät ja lisääntyivät, ja sangen voimallisesti vahvistuivat, niin että maa täytettiin heistä.","Ja Israelin lapset olivat hedelmälliset ja suuresti enenivät ja lisääntyivät, ja sangen voimallisesti vahvistuivat, niin että maa täytettiin heistä."],[1,8,"Niin uusi kuningas tuli Egyptiin, joka ei Josephista mitään tietänyt.","Niin uusi kuningas tuli Egyptiin, joka ei Josephista mitään tietänyt."],[1,9,"Hän sanoi kansallensa: katso, Israelin lasten joukko on suurempi ja väkevämpi meitä.","Hän sanoi kansallensa: katso, Israelin lasten joukko on suurempi ja väkevämpi meitä."],[1,10,"Tulkaat, käykäämme kavalasti heidän kimppuunsa, ettei heitä tulisi niin paljo. Sillä jos joku sota nousis, tohtisivat he mennä meidän vihamiestemme puolelle, ja sotia meitä vastaan, ja lähteä maalta pois.","Tulkaat, käykäämme kavalasti heidän kimppuunsa, ettei heitä tulisi niin paljo. Sillä jos joku sota nousis, tohtisivat he mennä meidän vihamiestemme puolelle, ja sotia meitä vastaan, ja lähteä maalta pois."],[1,11,"Niin asetettiin heidän päällensä veron päämiehet, vaivaamaan heitä orjuudella; sillä Pharaolle rakennettiin verokaupungit, Pitom ja Raamses.","Niin asetettiin heidän päällensä veron päämiehet, vaivaamaan heitä orjuudella; sillä Pharaolle rakennettiin verokaupungit, Pitom ja Raamses."],[1,12,"Mutta jota enemmin he rasittivat kansaa, sitä enemmin se lisääntyi ja kasvoi. Ja he tulivat suutuksiin Israelin lasten tähden.","Mutta jota enemmin he rasittivat kansaa, sitä enemmin se lisääntyi ja kasvoi. Ja he tulivat suutuksiin Israelin lasten tähden."],[1,13,"Ja Egyptiläiset vaivasivat Israelin lapsia orjuudella armaitsemata.","Ja Egyptiläiset vaivasivat Israelin lapsia orjuudella armaitsemata."],[1,14,"Ja saattivat heidän elämänsä katkeraksi raskaalla saven ja tiilein työllä, ja kaikkinaisella rasituksella kedolla, ja kaikkinaisella työllä, kuin he taisivat heidän päällensä panna, armaitsemata.","Ja saattivat heidän elämänsä katkeraksi raskaalla saven ja tiilein työllä, ja kaikkinaisella rasituksella kedolla, ja kaikkinaisella työllä, kuin he taisivat heidän päällensä panna, armaitsemata."],[1,15,"Ja Egyptin kuningas puhui Heprealaisille lastenämmille, joista yhden nimi oli Siphra, ja toisen nimi Pua.","Ja Egyptin kuningas puhui Heprealaisille lastenämmille, joista yhden nimi oli Siphra, ja toisen nimi Pua."],[1,16,"Ja hän sanoi: Koska te autatte Hebreailaisia vaimoja heidän synnyttäissänsä, ja näette istuimella, jos on poika, niin surmatkaat häntä; mutta jos se tytär on, niin se eläköön.","Ja hän sanoi: Koska te autatte Hebreailaisia vaimoja heidän synnyttäissänsä, ja näette istuimella, jos on poika, niin surmatkaat häntä; mutta jos se tytär on, niin se eläköön."],[1,17,"Mutta lastenämmät pelkäsivät Jumalaa, ja ei tehneet niinkuin Egyptin kuningas oli heille sanonut; mutta antoivat poikaiset elää.","Mutta lastenämmät pelkäsivät Jumalaa, ja ei tehneet niinkuin Egyptin kuningas oli heille sanonut; mutta antoivat poikaiset elää."],[1,18,"Niin Egyptin kuningas kutsui lastenämmät, ja sanoi heille: miksi te tämän teitte, että te annoitte poikaisten elää?","Niin Egyptin kuningas kutsui lastenämmät, ja sanoi heille: miksi te tämän teitte, että te annoitte poikaisten elää?"],[1,19,"Niin lastenämmät vastasivat Pharaota: Heprealaiset vaimot ei ole niinkuin Egyptiläiset; sillä he ovat vahvemmat luonnostansa, ja ennenkuin lastenämmä tulee heidän tykönsä, ovat he synnyttäneet.","Niin lastenämmät vastasivat Pharaota: Heprealaiset vaimot ei ole niinkuin Egyptiläiset; sillä he ovat vahvemmat luonnostansa, ja ennenkuin lastenämmä tulee heidän tykönsä, ovat he synnyttäneet."],[1,20,"Sentähden teki Jumala lastenämmille hyvin, ja kansa lisääntyi ja vahvistui sangen suuresti.","Sentähden teki Jumala lastenämmille hyvin, ja kansa lisääntyi ja vahvistui sangen suuresti."],[1,21,"Ja että lastenämmät pelkäsivät Jumalaa, rakensi hän heille huoneita.","Ja että lastenämmät pelkäsivät Jumalaa, rakensi hän heille huoneita."],[1,22,"Niin käski Pharao kaikelle kansallensa, sanoen: kaikki pojat kuin syntyvät pitää teidän heittämän virtaan, mutta kaikki tyttäret antakaat elää.","Niin käski Pharao kaikelle kansallensa, sanoen: kaikki pojat kuin syntyvät pitää teidän heittämän virtaan, mutta kaikki tyttäret antakaat elää."],[2,1,"Niin mies Leevin huoneesta meni ja nai Levin tyttären.","Niin mies Leevin huoneesta meni ja nai Levin tyttären."],[2,2,"Ja se vaimo tuli raskaaksi, ja synnytti pojan. Ja koska hän näki, että se oli ihana lapsi, salasi hän sen kolme kuukautta.","Ja se vaimo tuli raskaaksi, ja synnytti pojan. Ja koska hän näki, että se oli ihana lapsi, salasi hän sen kolme kuukautta."],[2,3,"Ja kuin ei hän taitanut häntä enää salata, otti hän kaisilaisen arkun, ja sivui sen savella ja pijellä, ja pani lapsen siihen ja laski sen kaisilistoon, virran partaalle.","Ja kuin ei hän taitanut häntä enää salata, otti hän kaisilaisen arkun, ja sivui sen savella ja pijellä, ja pani lapsen siihen ja laski sen kaisilistoon, virran partaalle."],[2,4,"Ja hänen sisarensa seisoi taampana, että hän näkis, mitä hänelle tapahtuis.","Ja hänen sisarensa seisoi taampana, että hän näkis, mitä hänelle tapahtuis."],[2,5,"Niin Pharaon tytär meni alas pesemään itseänsä virtaan, ja hänen piikansa käyskentelivät virran partaalla; ja kuin hän näki arkun kaisilistossa, lähetti hän piikansa ja antoi hänen ottaa ylös.","Niin Pharaon tytär meni alas pesemään itseänsä virtaan, ja hänen piikansa käyskentelivät virran partaalla; ja kuin hän näki arkun kaisilistossa, lähetti hän piikansa ja antoi hänen ottaa ylös."],[2,6,"Ja kuin hän avasi, näki hän lapsen, ja katso, lapsi itki; niin hän armahti sen päälle, ja sanoi: tämä on Heprealaisten lapsia.","Ja kuin hän avasi, näki hän lapsen, ja katso, lapsi itki; niin hän armahti sen päälle, ja sanoi: tämä on Heprealaisten lapsia."],[2,7,"Niin sanoi hänen sisarensa Pharaon tyttärelle: tahdotkos että minä menen kutsumaan sinulle imettäväisen Heprealaisen vaimon, joka sinulle sen lapsen imettäis.","Niin sanoi hänen sisarensa Pharaon tyttärelle: tahdotkos että minä menen kutsumaan sinulle imettäväisen Heprealaisen vaimon, joka sinulle sen lapsen imettäis."],[2,8,"Pharaon tytär sanoi hänelle: mene. Niin piika meni ja kutsui lapsen äidin.","Pharaon tytär sanoi hänelle: mene. Niin piika meni ja kutsui lapsen äidin."],[2,9,"Ja Pharaon tytär sanoi hänelle: ota tämä lapsi, ja imetä häntä minulle, ja minä annan palkan sinulle. Niin vaimo otti lapsen, ja imetti sen.","Ja Pharaon tytär sanoi hänelle: ota tämä lapsi, ja imetä häntä minulle, ja minä annan palkan sinulle. Niin vaimo otti lapsen, ja imetti sen."],[2,10,"Mutta koska lapsi oli kasvanut, toi hän sen Pharaon tyttärelle, ja hän otti sen pojaksensa, ja kutsui hänen Moses; sillä hän sanoi: vedestä olen minä hänen ottanut.","Mutta koska lapsi oli kasvanut, toi hän sen Pharaon tyttärelle, ja hän otti sen pojaksensa, ja kutsui hänen Moses; sillä hän sanoi: vedestä olen minä hänen ottanut."],[2,11,"Siihen aikaan koska Moses oli suureksi tullut, meni hän veljeinsä tykö ja näki heidän orjuutensa, ja äkkäsi Egyptiläisen lyövän Hebrealaista miestä hänen veljistänsä.","Siihen aikaan koska Moses oli suureksi tullut, meni hän veljeinsä tykö ja näki heidän orjuutensa, ja äkkäsi Egyptiläisen lyövän Hebrealaista miestä hänen veljistänsä."],[2,12,"Ja hän katseli ympärillensä sinne ja tänne, ja kuin hän näki, ettei yhtään läsnä ollut, tappoi hän sen Egyptiläisen ja kätki santaan.","Ja hän katseli ympärillensä sinne ja tänne, ja kuin hän näki, ettei yhtään läsnä ollut, tappoi hän sen Egyptiläisen ja kätki santaan."],[2,13,"Ja hän meni toisna päivänä ulos, ja katso, kaksi Heprealaista miestä tappelivat keskenänsä, ja hän sanoi väärintekiälle: miksis lyöt lähimmäistäs.","Ja hän meni toisna päivänä ulos, ja katso, kaksi Heprealaista miestä tappelivat keskenänsä, ja hän sanoi väärintekiälle: miksis lyöt lähimmäistäs."],[2,14,"Hän vastasi: kuka sinun on asettanut päämieheksemme ja tuomariksemme? Tahdotkos minunkin tappaa, niinkuin sinä tapoit Egyptiläisen? Niin Moses pelkäsi, ja sanoi: tosin on tämä ilmi tullut.","Hän vastasi: kuka sinun on asettanut päämieheksemme ja tuomariksemme? Tahdotkos minunkin tappaa, niinkuin sinä tapoit Egyptiläisen? Niin Moses pelkäsi, ja sanoi: tosin on tämä ilmi tullut."],[2,15,"Ja se tuli Pharaon eteen, ja hän etsi Mosesta tappaaksensa. Mutta Moses pakeni Pharaon edestä, ja seisahtui Midianin maalla, ja istui kaivon tykönä.","Ja se tuli Pharaon eteen, ja hän etsi Mosesta tappaaksensa. Mutta Moses pakeni Pharaon edestä, ja seisahtui Midianin maalla, ja istui kaivon tykönä."],[2,16,"Mutta Midianin papilla oli seitsemän tytärtä; ne tulivat vettä ammuntamaan ja täyttivät ruuhet, juottaaksensa isänsä lampaita.","Mutta Midianin papilla oli seitsemän tytärtä; ne tulivat vettä ammuntamaan ja täyttivät ruuhet, juottaaksensa isänsä lampaita."],[2,17,"niin tulivat muutamat paimenet ja ajoivat heidät pois. Mutta Moses nousi ja autti heitä, ja juotti heidän lampaansa.","niin tulivat muutamat paimenet ja ajoivat heidät pois. Mutta Moses nousi ja autti heitä, ja juotti heidän lampaansa."],[2,18,"Ja kuin he tulivat isänsä Reguelin tykö, sanoi hän: miksi te tänäpänä niin pian jouduitte?","Ja kuin he tulivat isänsä Reguelin tykö, sanoi hän: miksi te tänäpänä niin pian jouduitte?"],[2,19,"He sanoivat: Egyptin mies autti meitä paimenien käsistä, ja myös viriästi ammunsi meille, ja juotti lampaat.","He sanoivat: Egyptin mies autti meitä paimenien käsistä, ja myös viriästi ammunsi meille, ja juotti lampaat."],[2,20,"Ja hän sanoi tyttärillensä: kussa hän on? Miksi te niin jätitte miehen? Kutsukaat häntä syömään meidän kanssamme.","Ja hän sanoi tyttärillensä: kussa hän on? Miksi te niin jätitte miehen? Kutsukaat häntä syömään meidän kanssamme."],[2,21,"Ja Moses mielistyi asumaan sen miehen tykönä, ja hän antoi Mosekselle tyttärensä Ziporan emännäksi.","Ja Moses mielistyi asumaan sen miehen tykönä, ja hän antoi Mosekselle tyttärensä Ziporan emännäksi."],[2,22,"Se synnytti pojan ja hän kutsui hänen nimensä Gersom; sillä hän sanoi: minä olen muukalainen vieraalla maalla.","Se synnytti pojan ja hän kutsui hänen nimensä Gersom; sillä hän sanoi: minä olen muukalainen vieraalla maalla."],[2,23,"Ja pitkän ajan perästä kuoli Egyptin kuningas. Ja Israelin lapset huokasivat orjuuden tähden ja huusivat, ja heidän huutonsa astui ylös Jumalan tykö heidän orjuutensa tähden.","Ja pitkän ajan perästä kuoli Egyptin kuningas. Ja Israelin lapset huokasivat orjuuden tähden ja huusivat, ja heidän huutonsa astui ylös Jumalan tykö heidän orjuutensa tähden."],[2,24,"Ja Jumala kuuli heidän huokauksensa: ja muisti liittonsa Abrahamin, Isaakin ja Jakobin kanssa.","Ja Jumala kuuli heidän huokauksensa: ja muisti liittonsa Abrahamin, Isaakin ja Jakobin kanssa."],[2,25,"Ja Jumala katsahti Israelin lasten puoleen, ja Jumala piti heistä murheen.","Ja Jumala katsahti Israelin lasten puoleen, ja Jumala piti heistä murheen."],[3,1,"Ja Moses kaitsi appensa Jetron Midianin papin lampaita: ja hän ajoi lampaat taamma korpeen, ja tuli Jumalan vuoren Horebin tykö.","Ja Moses kaitsi appensa Jetron Midianin papin lampaita: ja hän ajoi lampaat taamma korpeen, ja tuli Jumalan vuoren Horebin tykö."],[3,2,"Ja Herran enkeli näkyi hänelle pensaasta, tulen liekissä: ja hän näki, ja katso, pensas paloi tulesta, ja ei kuitenkaan kulunut.","Ja Herran enkeli näkyi hänelle pensaasta, tulen liekissä: ja hän näki, ja katso, pensas paloi tulesta, ja ei kuitenkaan kulunut."],[3,3,"Ja Moses sanoi: minä käyn tuonne, ja katson tätä suurta näkyä, miksi ei pensas pala ylös?","Ja Moses sanoi: minä käyn tuonne, ja katson tätä suurta näkyä, miksi ei pensas pala ylös?"],[3,4,"Koska Herra näki hänen menevän katsomaan, huusi Jumala häntä pensaasta, ja sanoi: Moses, Moses. Hän vastasi: tässä minä olen.","Koska Herra näki hänen menevän katsomaan, huusi Jumala häntä pensaasta, ja sanoi: Moses, Moses. Hän vastasi: tässä minä olen."],[3,5,"Hän sanoi: älä lähesty tänne; riisu kenkäs jalvoistas; sillä paikka, jossas seisot, on pyhä maa.","Hän sanoi: älä lähesty tänne; riisu kenkäs jalvoistas; sillä paikka, jossas seisot, on pyhä maa."],[3,6,"Ja hän vielä sanoi: Minä olen sinun isäs Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala. Ja Moses peitti kasvonsa; sillä hän pelkäsi katsoa Jumalan päälle.","Ja hän vielä sanoi: Minä olen sinun isäs Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala. Ja Moses peitti kasvonsa; sillä hän pelkäsi katsoa Jumalan päälle."],[3,7,"Ja Herra sanoi: Minä olen hyvin kyllä nähnyt minun kansani ahdistuksen, joka on Egyptissä, ja minä olen kuullut heidän huutonsa, niiden tähden, jotka heitä ahdistavat; sillä minä tiedän heidän tuskansa.","Ja Herra sanoi: Minä olen hyvin kyllä nähnyt minun kansani ahdistuksen, joka on Egyptissä, ja minä olen kuullut heidän huutonsa, niiden tähden, jotka heitä ahdistavat; sillä minä tiedän heidän tuskansa."],[3,8,"Ja olen astunut alas heitä vapahtamaan Egyptiläisten käsistä, ja viemään heitä tältä maalta hyvään ja laviaan maahan, siihen maahan, jossa rieskaa ja hunajaa vuotaa, sille paikalle, jossa Kanaanealaiset, Hetiläiset, Amorilaiset, Pheresiläiset, Heviläiset ja Jebusilaiset asuvat.","Ja olen astunut alas heitä vapahtamaan Egyptiläisten käsistä, ja viemään heitä tältä maalta hyvään ja laviaan maahan, siihen maahan, jossa rieskaa ja hunajaa vuotaa, sille paikalle, jossa Kanaanealaiset, Hetiläiset, Amorilaiset, Pheresiläiset, Heviläiset ja Jebusilaiset asuvat."],[3,9,"Ja katso, Israelin lasten huuto on tullut minun eteeni, ja minä myös olen nähnyt heidän ahdistuksensa, jolla Egyptiläiset heitä ahdistavat.","Ja katso, Israelin lasten huuto on tullut minun eteeni, ja minä myös olen nähnyt heidän ahdistuksensa, jolla Egyptiläiset heitä ahdistavat."],[3,10,"Ja nyt mene, ja minä tahdon lähettää sinun Pharaon tykö, ja sinun pitää johdattaman minun kansaani Israelin lapsia ulos Egyptistä.","Ja nyt mene, ja minä tahdon lähettää sinun Pharaon tykö, ja sinun pitää johdattaman minun kansaani Israelin lapsia ulos Egyptistä."],[3,11,"Ja Moses sanoi Jumalalle: mikä minä olen menemään Pharaon tykö, ja viemään Israelin lapset ulos Egyptistä?","Ja Moses sanoi Jumalalle: mikä minä olen menemään Pharaon tykö, ja viemään Israelin lapset ulos Egyptistä?"],[3,12,"Hän sanoi: totisesti olen sinun kanssas; ja tämä olkoon sinulle merkiksi, että minä olen sinun lähettänyt. Koska olet johdattanut minun kansani Egyptistä, niin teidän pitää palveleman Jumalaa tällä vuorella.","Hän sanoi: totisesti olen sinun kanssas; ja tämä olkoon sinulle merkiksi, että minä olen sinun lähettänyt. Koska olet johdattanut minun kansani Egyptistä, niin teidän pitää palveleman Jumalaa tällä vuorella."],[3,13,"Moses sanoi Jumalalle: katso, koska minä tulen Israelin lasten tykö, ja sanon heille: teidän isäinne Jumala on minun lähettänyt teidän tykönne, ja he sanovat minulle: mikä hänen nimensä on? Mitä minun pitää heille sanoman?","Moses sanoi Jumalalle: katso, koska minä tulen Israelin lasten tykö, ja sanon heille: teidän isäinne Jumala on minun lähettänyt teidän tykönne, ja he sanovat minulle: mikä hänen nimensä on? Mitä minun pitää heille sanoman?"],[3,14,"Sanoi Jumala Mosekselle: Minä olen se kuin minä olen. Ja sanoi: niin pitää sinun sanoman Israelin lapsille: Minä olen lähetti minun teidän tykönne.","Sanoi Jumala Mosekselle: Minä olen se kuin minä olen. Ja sanoi: niin pitää sinun sanoman Israelin lapsille: Minä olen lähetti minun teidän tykönne."],[3,15,"Ja Jumala sanoi vielä Mosekselle: niin pitää sinun sanoman Israelin lapsille: Herra teidän isäinne Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala lähetti minun teidän tykönne; tämä on minun nimeni ijankaikkisesti, ja tämä on minun muistoni suvusta niin sukuun.","Ja Jumala sanoi vielä Mosekselle: niin pitää sinun sanoman Israelin lapsille: Herra teidän isäinne Jumala, Abrahamin Jumala, Isaakin Jumala, ja Jakobin Jumala lähetti minun teidän tykönne; tämä on minun nimeni ijankaikkisesti, ja tämä on minun muistoni suvusta niin sukuun."],[3,16,"Mene ja kokoo Israelin vanhemmat, ja sano heille: Herra teidän isäinne Jumala on näkynyt minulle, Abrahamin, Isaakin, ja Jakobin Jumala, sanoen: minä olen etsein etsinyt teitä, ja nähnyt, mitä teille on tapahtunut Egyptissä.","Mene ja kokoo Israelin vanhemmat, ja sano heille: Herra teidän isäinne Jumala on näkynyt minulle, Abrahamin, Isaakin, ja Jakobin Jumala, sanoen: minä olen etsein etsinyt teitä, ja nähnyt, mitä teille on tapahtunut Egyptissä."],[3,17,"Ja olen sanonut: minä tahdon johdattaa teitä ulos Egyptin ahdistuksesta, Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten ja Jebusilaisten maalle, jossa rieskaa ja hunajaa vuotaa.","Ja olen sanonut: minä tahdon johdattaa teitä ulos Egyptin ahdistuksesta, Kanaanealaisten, Hetiläisten, Amorilaisten, Pheresiläisten ja Jebusilaisten maalle, jossa rieskaa ja hunajaa vuotaa."],[3,18,"Ja heidän pitää kuuleman sinun äänes; ja sinun ja vanhimmat Israelista pitää menemän Egyptin kuninkaan tykö, ja sanoman hänelle: Herra Hebrealaisten Jumala on kohdannut meitä. Anna siis nyt meidän mennä kolmen päivän matka korpeen, uhraamaan Herralle meidän Jumalallemme.","Ja heidän pitää kuuleman sinun äänes; ja sinun ja vanhimmat Israelista pitää menemän Egyptin kuninkaan tykö, ja sanoman hänelle: Herra Hebrealaisten Jumala on kohdannut meitä. Anna siis nyt meidän mennä kolmen päivän matka korpeen, uhraamaan Herralle meidän Jumalallemme."],[3,19,"Mutta minä tiedän, ettei Egyptin kuningas laske teitä menemään; vaan väkevän käden kautta.","Mutta minä tiedän, ettei Egyptin kuningas laske teitä menemään; vaan väkevän käden kautta."],[3,20,"Silloin minä ojennan käteni, ja lyön Egyptin kaikkinaisilla minun ihmeilläni, joita minä tekevä olen heidän keskellänsä, ja sitte pitää hänen teidät päästämän.","Silloin minä ojennan käteni, ja lyön Egyptin kaikkinaisilla minun ihmeilläni, joita minä tekevä olen heidän keskellänsä, ja sitte pitää hänen teidät päästämän."],[3,21,"Ja minä annan armon tälle kansalle Egyptiläisten edessä, että koska te lähdette, ei teidän pidä tyhjin käsin lähtemän.","Ja minä annan armon tälle kansalle Egyptiläisten edessä, että koska te lähdette, ei teidän pidä tyhjin käsin lähtemän."],[3,22,"Vaan jokaisen vaimon pitää anoman kylänsä vaimolta, ja huonekuntalaiseltansa hopia- ja kulta-astiat ja vaatteet, ja paneman ne teidän poikainne ja tytärtenne päälle, ja paljastaman Egyptiläiset.","Vaan jokaisen vaimon pitää anoman kylänsä vaimolta, ja huonekuntalaiseltansa hopia- ja kulta-astiat ja vaatteet, ja paneman ne teidän poikainne ja tytärtenne päälle, ja paljastaman Egyptiläiset."],[4,1,"Moses vastasi, ja sanoi: katso, ei he usko minua, eikä ole kuuliaiset minun äänelleni; vaan sanovat: ei ole Herra näkynyt sinulle.","Moses vastasi, ja sanoi: katso, ei he usko minua, eikä ole kuuliaiset minun äänelleni; vaan sanovat: ei ole Herra näkynyt sinulle."],[4,2,"Herra sanoi hänelle: mikä se on sinun kädessäs? Hän sanoi: sauva.","Herra sanoi hänelle: mikä se on sinun kädessäs? Hän sanoi: sauva."],[4,3,"Ja hän sanoi: heitä se maahan, ja hän heitti sen maahan, ja se muuttui kärmeeksi. Ja Moses pakeni häntä.","Ja hän sanoi: heitä se maahan, ja hän heitti sen maahan, ja se muuttui kärmeeksi. Ja Moses pakeni häntä."],[4,4,"Mutta Herra sanoi Mosekselle: ojenna kätes, ja rupee hänen pyrstöönsä. Niin hän ojensi kätensä ja rupesi häneen, ja se muuttui sauvaksi hänen kädessänsä.","Mutta Herra sanoi Mosekselle: ojenna kätes, ja rupee hänen pyrstöönsä. Niin hän ojensi kätensä ja rupesi häneen, ja se muuttui sauvaksi hänen kädessänsä."],[4,5,"Sentähden pitää heidän uskoman, että Herra on näkynyt sinulle, heidän isäinsä Jumala, Abrahamin Jumala, Isaakin Jumala ja Jakobin Jumala.","Sentähden pitää heidän uskoman, että Herra on näkynyt sinulle, heidän isäinsä Jumala, Abrahamin Jumala, Isaakin Jumala ja Jakobin Jumala."],[4,6,"Ja Herra sanoi vielä hänelle: pistä nyt kätes povees. Ja hän pisti sen poveensa. Ja koska hän veti sen ulos, katso, hänen kätensä oli spitalinen niinkuin lumi.","Ja Herra sanoi vielä hänelle: pistä nyt kätes povees. Ja hän pisti sen poveensa. Ja koska hän veti sen ulos, katso, hänen kätensä oli spitalinen niinkuin lumi."],[4,7,"Ja hän sanoi: pistä kätes jällensä povees, ja hän pisti kätensä jälleen poveensa, ja veti jällensä sen ulos povestansa, ja katso, se tuli niinkuin hänen ihonsa.","Ja hän sanoi: pistä kätes jällensä povees, ja hän pisti kätensä jälleen poveensa, ja veti jällensä sen ulos povestansa, ja katso, se tuli niinkuin hänen ihonsa."],[4,8,"Ja on tapahtuva, jollei he sinua usko, eikä ole kuuliaiset sinun äänelles yhden ihmeen tähden, niin he uskovat sinun äänes toisen ihmeen tähden.","Ja on tapahtuva, jollei he sinua usko, eikä ole kuuliaiset sinun äänelles yhden ihmeen tähden, niin he uskovat sinun äänes toisen ihmeen tähden."],[4,9,"Jollei he usko niitä kahta ihmettä, eikä ole kuuliaiset sinun äänelles, niin ota vettä virrasta, ja kaada kuivalle maalle, niin se vesi, jonkas olet ottanut virrasta, tulee vereksi kuivalla maalla.","Jollei he usko niitä kahta ihmettä, eikä ole kuuliaiset sinun äänelles, niin ota vettä virrasta, ja kaada kuivalle maalle, niin se vesi, jonkas olet ottanut virrasta, tulee vereksi kuivalla maalla."],[4,10,"Niin sanoi Moses Herralle: Ah Herra, en ole minä tähän asti puhelias mies ollut, enkä myös sitte kuin sinä palvelias kanssa puhunut olet; sillä minulla on hidas puhe ja kankia kieli.","Niin sanoi Moses Herralle: Ah Herra, en ole minä tähän asti puhelias mies ollut, enkä myös sitte kuin sinä palvelias kanssa puhunut olet; sillä minulla on hidas puhe ja kankia kieli."],[4,11,"Ja Herra sanoi hänelle: kuka on luonut ihmisen suun? Eli kuka on tehnyt mykän taikka kuuron, eli näkevän taikka sokian? Enkö minä Herra (ole niitä tehnyt)?","Ja Herra sanoi hänelle: kuka on luonut ihmisen suun? Eli kuka on tehnyt mykän taikka kuuron, eli näkevän taikka sokian? Enkö minä Herra (ole niitä tehnyt)?"],[4,12,"Mene siis nyt, minä olen sinun suussas, ja opetan sinua, mitä sinun puhuman pitää.","Mene siis nyt, minä olen sinun suussas, ja opetan sinua, mitä sinun puhuman pitää."],[4,13,"Moses sanoi: Ah Herra, lähetä, jonkas tahdot lähettää.","Moses sanoi: Ah Herra, lähetä, jonkas tahdot lähettää."],[4,14,"Niin Herra vihastui suuresti Moseksen päälle, ja sanoi: enkö minä tunne Aaronia sinun veljeäs, Levin suvusta, että hän on puhelias? Ja katso, hän tulee sinua vastaan, ja koska hän näkee sinun, niin hän iloitsee sydämestänsä.","Niin Herra vihastui suuresti Moseksen päälle, ja sanoi: enkö minä tunne Aaronia sinun veljeäs, Levin suvusta, että hän on puhelias? Ja katso, hän tulee sinua vastaan, ja koska hän näkee sinun, niin hän iloitsee sydämestänsä."],[4,15,"Sinun pitää puhuman hänelle, ja paneman sanat hänen suuhunsa; ja minä olen sinun ja hänen suunsa kanssa, ja opetan teitä, mitä teidän pitää tekemän.","Sinun pitää puhuman hänelle, ja paneman sanat hänen suuhunsa; ja minä olen sinun ja hänen suunsa kanssa, ja opetan teitä, mitä teidän pitää tekemän."],[4,16,"Ja hänen pitää puhuman sinun puolestas kansalle. Hänen pitää oleman sinun suunas, ja sinun pitää oleman hänelle Jumalana.","Ja hänen pitää puhuman sinun puolestas kansalle. Hänen pitää oleman sinun suunas, ja sinun pitää oleman hänelle Jumalana."],[4,17,"Ja ota tämä sauva kätees, jolla sinun pitää tekemän ihmeitä.","Ja ota tämä sauva kätees, jolla sinun pitää tekemän ihmeitä."],[4,18,"Niin Moses läksi sieltä, ja tuli jällensä appensa Jetron tykö, ja sanoi hänelle: annas minun mennä, että minä palajaisin veljeini tykö, jotka ovat Egyptissä, ja näkisin heitä, jos he vielä elävät. Ja Jetro sanoi Mosekselle: mene rauhassa.","Niin Moses läksi sieltä, ja tuli jällensä appensa Jetron tykö, ja sanoi hänelle: annas minun mennä, että minä palajaisin veljeini tykö, jotka ovat Egyptissä, ja näkisin heitä, jos he vielä elävät. Ja Jetro sanoi Mosekselle: mene rauhassa."],[4,19,"Ja Herra sanoi Mosekselle Midianissa: mene ja palaja Egyptiin; sillä ne kaikki ovat kuolleet, jotka sinun henkes perään seisoivat.","Ja Herra sanoi Mosekselle Midianissa: mene ja palaja Egyptiin; sillä ne kaikki ovat kuolleet, jotka sinun henkes perään seisoivat."],[4,20,"Ja Moses otti emäntänsä ja poikansa, ja pani ne aasin päälle, ja palasi Egyptiin; ja otti Jumalan sauvan käteensä.","Ja Moses otti emäntänsä ja poikansa, ja pani ne aasin päälle, ja palasi Egyptiin; ja otti Jumalan sauvan käteensä."],[4,21,"Ja Herra sanoi Mosekselle: katso, koskas tulet Egyptiin jällensä, ettäs teet kaikki ne ihmeet Pharaon edessä, jotka minä olen antanut sinun kätees. Ja minä paadutan hänen sydämensä, ja ei hän päästä kansaa.","Ja Herra sanoi Mosekselle: katso, koskas tulet Egyptiin jällensä, ettäs teet kaikki ne ihmeet Pharaon edessä, jotka minä olen antanut sinun kätees. Ja minä paadutan hänen sydämensä, ja ei hän päästä kansaa."],[4,22,"Ja sinun pitää sanoman Pharaolle: näin sanoo Herra: Israel on minun poikani, minun esikoiseni.","Ja sinun pitää sanoman Pharaolle: näin sanoo Herra: Israel on minun poikani, minun esikoiseni."],[4,23,"Ja minä käsken sinulle: päästä minun poikani palvelemaan minua, ja jos et sinä tahdo häntä päästää, katso, minä tapan sinun poikas, sinun esikoises.","Ja minä käsken sinulle: päästä minun poikani palvelemaan minua, ja jos et sinä tahdo häntä päästää, katso, minä tapan sinun poikas, sinun esikoises."],[4,24,"Ja koska hän oli tiellä majassa, tuli Herra häntä vastaan, ja tahtoi hänen tappaa.","Ja koska hän oli tiellä majassa, tuli Herra häntä vastaan, ja tahtoi hänen tappaa."],[4,25,"Niin Zippora otti kiven, ja ympärileikkasi poikansa esinahan, ja rupesi hänen jalkoihinsa, ja sanoi: sinä olet minulle veriylkä.","Niin Zippora otti kiven, ja ympärileikkasi poikansa esinahan, ja rupesi hänen jalkoihinsa, ja sanoi: sinä olet minulle veriylkä."],[4,26,"Niin hän luopui hänestä. Mutta sanoi: veriylkä ympärileikkauksen tähden.","Niin hän luopui hänestä. Mutta sanoi: veriylkä ympärileikkauksen tähden."],[4,27,"Ja Herra sanoi Aaronille: mene Mosesta vastaan korpeen. Ja hän meni, ja tuli häntä vastaan Jumalan vuorella, ja antoi hänen suuta.","Ja Herra sanoi Aaronille: mene Mosesta vastaan korpeen. Ja hän meni, ja tuli häntä vastaan Jumalan vuorella, ja antoi hänen suuta."],[4,28,"Ja Moses ilmoitti Aaronille kaikki Herran sanat, jotka hänen lähetti, ja kaikki ihmeet, jotka hän hänet käskenyt oli.","Ja Moses ilmoitti Aaronille kaikki Herran sanat, jotka hänen lähetti, ja kaikki ihmeet, jotka hän hänet käskenyt oli."],[4,29,"Niin meni Moses ja Aaron, ja kokosivat kaikki Israelin lasten vanhimmat.","Niin meni Moses ja Aaron, ja kokosivat kaikki Israelin lasten vanhimmat."],[4,30,"Ja Aaron puhui kaikki ne sanat, jotka Herra Mosekselle puhunut oli, ja teki ihmeitä kansan edessä.","Ja Aaron puhui kaikki ne sanat, jotka Herra Mosekselle puhunut oli, ja teki ihmeitä kansan edessä."],[4,31,"Ja kansa uskoi. Ja kuin he kuulivat, että Herra oli etsinyt Israelin lapsia, nähnyt myös heidän ahdistuksensa, lankesivat he maahan ja rukoilivat.","Ja kansa uskoi. Ja kuin he kuulivat, että Herra oli etsinyt Israelin lapsia, nähnyt myös heidän ahdistuksensa, lankesivat he maahan ja rukoilivat."],[5,1,"Sitte menivät Moses ja Aaron Pharaon tykö, ja sanoivat: näin sanoo Herra Israelin Jumala: päästä minun kansani pitämään minulle juhlaa korvessa.","Sitte menivät Moses ja Aaron Pharaon tykö, ja sanoivat: näin sanoo Herra Israelin Jumala: päästä minun kansani pitämään minulle juhlaa korvessa."],[5,2,"Pharao vastasi: kuka on Herra, jonka ääntä minun pitäis kuuleman, ja päästämän Israelin? En minä siitä Herrasta mitään tiedä, enkä päästä Israelia.","Pharao vastasi: kuka on Herra, jonka ääntä minun pitäis kuuleman, ja päästämän Israelin? En minä siitä Herrasta mitään tiedä, enkä päästä Israelia."],[5,3,"Ja he sanoivat: Heprealaisten Jumala on kohdannut meitä; anna siis nyt meidän mennä kolmen päivän matka korpeen uhraamaan Herralle meidän Jumalallemme, ettei hän rutolla miekalla meidän päällemme tulis.","Ja he sanoivat: Heprealaisten Jumala on kohdannut meitä; anna siis nyt meidän mennä kolmen päivän matka korpeen uhraamaan Herralle meidän Jumalallemme, ettei hän rutolla miekalla meidän päällemme tulis."],[5,4,"Niin Egyptin kuningas sanoi heille: miksi te, Moses ja Aaron, pidätte kansan heidän työstänsä? Menkäät teidän työhönne.","Niin Egyptin kuningas sanoi heille: miksi te, Moses ja Aaron, pidätte kansan heidän työstänsä? Menkäät teidän työhönne."],[5,5,"Pharao sanoi vielä: katso, ilmankin on kansaa paljo maalla, ja te vielä nyt tahdotte heitä joutilaaksi saattaa heidän töistänsä.","Pharao sanoi vielä: katso, ilmankin on kansaa paljo maalla, ja te vielä nyt tahdotte heitä joutilaaksi saattaa heidän töistänsä."],[5,6,"Sentähden käski Pharao sinä päivänä kansan teettäjille ja heidän haltioillensa, sanoen:","Sentähden käski Pharao sinä päivänä kansan teettäjille ja heidän haltioillensa, sanoen:"],[5,7,"Ei teidän pidä tästälähin olkia antaman kansalle tiilejä tehdä niinkuin ennen; menkään he itse ja kootkaan itsellensä olkia.","Ei teidän pidä tästälähin olkia antaman kansalle tiilejä tehdä niinkuin ennen; menkään he itse ja kootkaan itsellensä olkia."],[5,8,"Kuitenkin se tiililuku, jonka he tekivät tähän asti, laskekaat heidän päällensä, ja älkäät siitä vähentäkö; sillä he ovat joutilasna, sentähden he huutavat, sanoen: me tahdomme mennä uhraamaan meidän Jumalallemme.","Kuitenkin se tiililuku, jonka he tekivät tähän asti, laskekaat heidän päällensä, ja älkäät siitä vähentäkö; sillä he ovat joutilasna, sentähden he huutavat, sanoen: me tahdomme mennä uhraamaan meidän Jumalallemme."],[5,9,"Rasitettakoon kansa työllä, että heillä olis kyllä tekemistä, eikä luottaisi valhepuheisiin.","Rasitettakoon kansa työllä, että heillä olis kyllä tekemistä, eikä luottaisi valhepuheisiin."],[5,10,"Niin kansan teettäjät ja heidän haltiansa menivät ja puhuivat kansalle, sanoen: näin sanoo Pharao: en minä tahdo teille olkia antaa.","Niin kansan teettäjät ja heidän haltiansa menivät ja puhuivat kansalle, sanoen: näin sanoo Pharao: en minä tahdo teille olkia antaa."],[5,11,"Menkäät itse kokoomaan teillenne olkia kusta ikänänsä te löydätte; mutta teidän työstänne ei pidä mitään vähennettämän.","Menkäät itse kokoomaan teillenne olkia kusta ikänänsä te löydätte; mutta teidän työstänne ei pidä mitään vähennettämän."],[5,12,"Niin kansa hajotti itsensä koko Egyptin maan ympärinsä hakemaan heillensä sänkiä, että heillä olkia olisi.","Niin kansa hajotti itsensä koko Egyptin maan ympärinsä hakemaan heillensä sänkiä, että heillä olkia olisi."],[5,13,"Ja teettäjät vaativat heitä, sanoen: täyttäkäät teidän päivätyönne, niinkuin silloinkin, koska teillä olkia oli.","Ja teettäjät vaativat heitä, sanoen: täyttäkäät teidän päivätyönne, niinkuin silloinkin, koska teillä olkia oli."],[5,14,"Ja Israelin lasten haltiat, jotka Pharaon teettäjät heidän päällensä asettaneet olivat, piestiin ja sanottiin heille: miksi ette eilen eikä tänäpänä täyttäneet teidän määrättyä päivätyötänne tiilein tekemisessä, niinkuin ennenkin.","Ja Israelin lasten haltiat, jotka Pharaon teettäjät heidän päällensä asettaneet olivat, piestiin ja sanottiin heille: miksi ette eilen eikä tänäpänä täyttäneet teidän määrättyä päivätyötänne tiilein tekemisessä, niinkuin ennenkin."],[5,15,"Niin Israelin lasten haltiat menivät ja huusivat Pharaon tykö, sanoen: miksis näin teet palvelioilles?","Niin Israelin lasten haltiat menivät ja huusivat Pharaon tykö, sanoen: miksis näin teet palvelioilles?"],[5,16,"Ei anneta sinun palvelioilles olkia, ja he sanovat meille: tehkäät tiilit, ja katso, sinun palvelias piestään, ja sinun kansalles nuhde on.","Ei anneta sinun palvelioilles olkia, ja he sanovat meille: tehkäät tiilit, ja katso, sinun palvelias piestään, ja sinun kansalles nuhde on."],[5,17,"Ja hän sanoi: te olette joutilaat, joutilaat te olette, sentähden te sanotte: menkäämme ja uhratkaamme Herralle.","Ja hän sanoi: te olette joutilaat, joutilaat te olette, sentähden te sanotte: menkäämme ja uhratkaamme Herralle."],[5,18,"Niin menkäät nyt, ja tehkäät työtä. Olkia ei pidä teille annettaman; mutta tiililuvun pitää teidän kuitenkin antaman.","Niin menkäät nyt, ja tehkäät työtä. Olkia ei pidä teille annettaman; mutta tiililuvun pitää teidän kuitenkin antaman."],[5,19,"Niin Israelin lasten haltiat näkivät itsensä olevan ahdistuksessa, sillä (heille) sanottiin: ei teidän pidä vähentämän teidän tiileistänne, kunkin päivän määrästä.","Niin Israelin lasten haltiat näkivät itsensä olevan ahdistuksessa, sillä (heille) sanottiin: ei teidän pidä vähentämän teidän tiileistänne, kunkin päivän määrästä."],[5,20,"Ja he kohtasivat Moseksen ja Aaronin, jotka seisoivat heitä vastassa, kuin he läksivät Pharaon tyköä.","Ja he kohtasivat Moseksen ja Aaronin, jotka seisoivat heitä vastassa, kuin he läksivät Pharaon tyköä."],[5,21,"Joille he sanoivat: Herra nähköön teitä ja tuomitkoon; sillä te olette tehneet meidän haisevaiseksi Pharaon edessä, ja hänen palveliainsa edessä, että te olette miekan antaneet heidän käteensä, surmata meitä.","Joille he sanoivat: Herra nähköön teitä ja tuomitkoon; sillä te olette tehneet meidän haisevaiseksi Pharaon edessä, ja hänen palveliainsa edessä, että te olette miekan antaneet heidän käteensä, surmata meitä."],[5,22,"Moses palasi Herran tykö, ja sanoi: Herra miksis niin pahasti teet tätä kansaa vastaan? Miksis olet minut tänne lähettänyt?","Moses palasi Herran tykö, ja sanoi: Herra miksis niin pahasti teet tätä kansaa vastaan? Miksis olet minut tänne lähettänyt?"],[5,23,"Sillä sitte kuin minä menin Pharaon tykö, puhuttelemaan häntä sinun nimees, on hän pahoin tehnyt tälle kansalle; ja et sinä ollenkaan ole pelastanut sinun kansaas.","Sillä sitte kuin minä menin Pharaon tykö, puhuttelemaan häntä sinun nimees, on hän pahoin tehnyt tälle kansalle; ja et sinä ollenkaan ole pelastanut sinun kansaas."],[6,1,"Niin sanoi myös Herra Mosekselle: nyt pitää sinun näkemän, mitä minä Pharaolle teen; sillä hänen pitää heitä päästämän väkevän käden kautta, ja hänen myös pitää väkevän käden kautta heitä ajaman ulos maaltansa.","Niin sanoi myös Herra Mosekselle: nyt pitää sinun näkemän, mitä minä Pharaolle teen; sillä hänen pitää heitä päästämän väkevän käden kautta, ja hänen myös pitää väkevän käden kautta heitä ajaman ulos maaltansa."],[6,2,"Ja Jumala puhui Mosekselle, ja sanoi hänelle: Minä (olen) Herra,","Ja Jumala puhui Mosekselle, ja sanoi hänelle: Minä (olen) Herra,"],[6,3,"Ja olen näkynyt Abrahamille, Isaakille ja Jakobille kaikkivaltiasna Jumalana. Mutta minun nimessäni HERRA, en ole minä tuttu heiltä.","Ja olen näkynyt Abrahamille, Isaakille ja Jakobille kaikkivaltiasna Jumalana. Mutta minun nimessäni HERRA, en ole minä tuttu heiltä."],[6,4,"Ja minä tein myös minun liittoni heidän kanssansa, antaakseni heille Kanaanin maan, heidän vaelluksensa maan, jossa he ovat muukalaiset olleet.","Ja minä tein myös minun liittoni heidän kanssansa, antaakseni heille Kanaanin maan, heidän vaelluksensa maan, jossa he ovat muukalaiset olleet."],[6,5,"Ja minä olen myös kuullut Israelin lasten huokauksen, joita Egyptiläiset orjuudella vaivaavat, ja olen minun liittoni muistanut.","Ja minä olen myös kuullut Israelin lasten huokauksen, joita Egyptiläiset orjuudella vaivaavat, ja olen minun liittoni muistanut."],[6,6,"Sentähden sano Israelin lapsille: minä olen Herra, ja minä johdatan teitä Egyptin kuorman alta, ja pelastan teitä orjuudestanne, ja vapahdan teitä ojetulla käsivarrella ja suurella oikeudella.","Sentähden sano Israelin lapsille: minä olen Herra, ja minä johdatan teitä Egyptin kuorman alta, ja pelastan teitä orjuudestanne, ja vapahdan teitä ojetulla käsivarrella ja suurella oikeudella."],[6,7,"Ja otan teitä minun kansakseni, ja olen teidän Jumalanne, että te tietäisitte, että minä olen teidän Jumalanne, joka teitä johdatan ulos Egyptin orjuudesta.","Ja otan teitä minun kansakseni, ja olen teidän Jumalanne, että te tietäisitte, että minä olen teidän Jumalanne, joka teitä johdatan ulos Egyptin orjuudesta."],[6,8,"Ja vien teitä sille maalle, jonka ylitse minä nostin minun käteni antaakseni sen Abrahamille, Isaakille ja Jakobille; sen minä tahdon antaa teille omaksi: minä Herra.","Ja vien teitä sille maalle, jonka ylitse minä nostin minun käteni antaakseni sen Abrahamille, Isaakille ja Jakobille; sen minä tahdon antaa teille omaksi: minä Herra."],[6,9,"Näin puhui Moses Israelin lapsille; vaan ei he kuulleet Mosesta henkensä ahdistuksen ja raskaan orjuutensa tähden.","Näin puhui Moses Israelin lapsille; vaan ei he kuulleet Mosesta henkensä ahdistuksen ja raskaan orjuutensa tähden."],[6,10,"Silloin puhui Herra Mosekselle, sanoen:","Silloin puhui Herra Mosekselle, sanoen:"],[6,11,"Mene ja puhu Pharaolle Egyptin kuninkaalle, että hän päästäis Israelin lapset hänen maaltansa.","Mene ja puhu Pharaolle Egyptin kuninkaalle, että hän päästäis Israelin lapset hänen maaltansa."],[6,12,"Mutta Moses puhui Herran edessä, sanoen: katso Israelin lapset ei kuulleet minua, kuinkasta Pharao kuulis minua, ja minulla on myös ympärileikkaamattomat huulet?","Mutta Moses puhui Herran edessä, sanoen: katso Israelin lapset ei kuulleet minua, kuinkasta Pharao kuulis minua, ja minulla on myös ympärileikkaamattomat huulet?"],[6,13,"Niin puhui Herra Mosekselle ja Aaronille, ja käski heitä Israelin lasten ja Pharaon Egyptin kuninkaan tykö, johdattamaan Israelin lapsia ulos Egyptin maalta.","Niin puhui Herra Mosekselle ja Aaronille, ja käski heitä Israelin lasten ja Pharaon Egyptin kuninkaan tykö, johdattamaan Israelin lapsia ulos Egyptin maalta."],[6,14,"Nämät olivat heidän isäinsä huonetten päät. Rubenin Israelin esikoisen lapset: Hanok ja Pallu, Hetsron ja Karmi: nämät ovat Rubenin sukukunnat.","Nämät olivat heidän isäinsä huonetten päät. Rubenin Israelin esikoisen lapset: Hanok ja Pallu, Hetsron ja Karmi: nämät ovat Rubenin sukukunnat."],[6,15,"Ja Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zoar ja Saul, sen Kanaanean vaimon poika: nämät ovat Simeonin sukukunnat.","Ja Simeonin lapset: Jemuel, Jamin, Ohad, Jakin, Zoar ja Saul, sen Kanaanean vaimon poika: nämät ovat Simeonin sukukunnat."],[6,16,"Ja nämät ovat Levin lasten nimet heidän sukukunnissansa: Gerson, Kahat ja Merari: Mutta Levin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa.","Ja nämät ovat Levin lasten nimet heidän sukukunnissansa: Gerson, Kahat ja Merari: Mutta Levin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa."],[6,17,"Gersonin lapset: Libni ja Simei heidän sukukunnissansa.","Gersonin lapset: Libni ja Simei heidän sukukunnissansa."],[6,18,"Kahatin lapset: Amram, Jesear, Hebro ja Usiel. Mutta Kahatin elämän vuodet olivat sata ja kolmeneljättäkymmentä ajastaikaa.","Kahatin lapset: Amram, Jesear, Hebro ja Usiel. Mutta Kahatin elämän vuodet olivat sata ja kolmeneljättäkymmentä ajastaikaa."],[6,19,"Ja Merarin pojat: Maheli ja Musi: nämät ovat Levin sukukunnat heidän polvisuvussansa.","Ja Merarin pojat: Maheli ja Musi: nämät ovat Levin sukukunnat heidän polvisuvussansa."],[6,20,"Ja Amram otti isänsä sisaren Jokebetin emännäksensä, joka synnytti hänelle Aaronin ja Moseksen. Ja Amramin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa.","Ja Amram otti isänsä sisaren Jokebetin emännäksensä, joka synnytti hänelle Aaronin ja Moseksen. Ja Amramin elämän vuodet olivat sata ja seitsemänneljättäkymmentä ajastaikaa."],[6,21,"Ja Jetsearin lapset: Kora, Nepheg ja Sikri.","Ja Jetsearin lapset: Kora, Nepheg ja Sikri."],[6,22,"Ja Usielin lapset: Misael, Eltsaphan ja Sitri.","Ja Usielin lapset: Misael, Eltsaphan ja Sitri."],[6,23,"Aaron otti itsellensä emännän Elitseban, Aminadabin tyttären, Nahassonin sisaren, joka hänelle synnytti Nadabin, Abihun, Eleatsarin ja Itamarin.","Aaron otti itsellensä emännän Elitseban, Aminadabin tyttären, Nahassonin sisaren, joka hänelle synnytti Nadabin, Abihun, Eleatsarin ja Itamarin."],[6,24,"Ja Koran lapset: Assir, Elkana ja Abiasaph: nämät ovat Koralaisten sukukunnat.","Ja Koran lapset: Assir, Elkana ja Abiasaph: nämät ovat Koralaisten sukukunnat."],[6,25,"Mutta Eleatsar Aaronin poika otti itsellensä Putielin tyttäristä emännän, joka synnytti hänelle Pinehaan. Nämät ovat Leviläisten isäin päät heidän sukukunnissansa.","Mutta Eleatsar Aaronin poika otti itsellensä Putielin tyttäristä emännän, joka synnytti hänelle Pinehaan. Nämät ovat Leviläisten isäin päät heidän sukukunnissansa."],[6,26,"Nämät ovat Aaron ja Moses, joille Herra sanoi: johdattakaat ulos Israelin lapset Egyptin maalta joukkoinensa.","Nämät ovat Aaron ja Moses, joille Herra sanoi: johdattakaat ulos Israelin lapset Egyptin maalta joukkoinensa."],[6,27,"Nämät ovat ne, jotka puhuivat Pharaon Egyptin kuninkaan kanssa, että heidän piti johdattaman ulos Israelin lapset Egyptistä: nämät ovat Moses ja Aaron.","Nämät ovat ne, jotka puhuivat Pharaon Egyptin kuninkaan kanssa, että heidän piti johdattaman ulos Israelin lapset Egyptistä: nämät ovat Moses ja Aaron."],[6,28,"Ja sinä päivänä puhui Herra Moseksen kanssa Egyptin maalla,","Ja sinä päivänä puhui Herra Moseksen kanssa Egyptin maalla,"],[6,29,"Ja sanoi hänelle: Minä olen Herra: puhu Pharaolle Egyptin kuninkaalle kaikki, mitä minä sinulle puhun.","Ja sanoi hänelle: Minä olen Herra: puhu Pharaolle Egyptin kuninkaalle kaikki, mitä minä sinulle puhun."],[6,30,"Niin vastasi Moses Herralle: katso, minä olen ympärileikkaamatoin huulilta, kuinkasta Pharao minua kuulee?","Niin vastasi Moses Herralle: katso, minä olen ympärileikkaamatoin huulilta, kuinkasta Pharao minua kuulee?"],[7,1,"Ja Herra sanoi Mosekselle: katso, minä olen asettanut sinun Pharaon Jumalaksi. Ja veljes Aaron pitää oleman sinun prophetas.","Ja Herra sanoi Mosekselle: katso, minä olen asettanut sinun Pharaon Jumalaksi. Ja veljes Aaron pitää oleman sinun prophetas."],[7,2,"Sinun pitää puhuman kaikki, mitä minä käsken sinulle, vaan Aaron sinun veljes pitää sen puhuman Pharaolle: että hän päästäis Israelin lapset maaltansa.","Sinun pitää puhuman kaikki, mitä minä käsken sinulle, vaan Aaron sinun veljes pitää sen puhuman Pharaolle: että hän päästäis Israelin lapset maaltansa."],[7,3,"Mutta minä tahdon paaduttaa Pharaon sydämen, ja tehdä monta minun ihmettäni ja tunnustähteäni Egyptin maalla.","Mutta minä tahdon paaduttaa Pharaon sydämen, ja tehdä monta minun ihmettäni ja tunnustähteäni Egyptin maalla."],[7,4,"Ja ei Pharao kuule teitä; ja minä tahdon osoittaa minun käteni Egyptissä, ja johdatan ulos minun joukkoni, minun kansani Israelin lapset Egyptin maalta suurella oikeudella.","Ja ei Pharao kuule teitä; ja minä tahdon osoittaa minun käteni Egyptissä, ja johdatan ulos minun joukkoni, minun kansani Israelin lapset Egyptin maalta suurella oikeudella."],[7,5,"Ja Egyptiläisten pitää tietämän, että minä olen Herra, ojetessani kättäni Egyptin ylitse, ja johdattaissani ulos Israelin lapset heidän keskeltänsä.","Ja Egyptiläisten pitää tietämän, että minä olen Herra, ojetessani kättäni Egyptin ylitse, ja johdattaissani ulos Israelin lapset heidän keskeltänsä."],[7,6,"Moses ja Aaron tekivät niinkuin Herra oli heille käskenyt.","Moses ja Aaron tekivät niinkuin Herra oli heille käskenyt."],[7,7,"Ja Moses oli kahdeksankymmenen ajastaikainen, ja Aaron kolmen ajastaikainen yhdeksättäkymmentä, koska he puhuivat Pharaon kanssa.","Ja Moses oli kahdeksankymmenen ajastaikainen, ja Aaron kolmen ajastaikainen yhdeksättäkymmentä, koska he puhuivat Pharaon kanssa."],[7,8,"Ja Herra puhui Mosekselle ja Aaronille, sanoen:","Ja Herra puhui Mosekselle ja Aaronille, sanoen:"],[7,9,"Koska Pharao puhuu teille, sanoen: osoittakaat teidän ihmeenne. Niin sinun pitää sanoman Aaronille: ota sauvas, ja heitä Pharaon eteen, ja se tulee kärmeeksi.","Koska Pharao puhuu teille, sanoen: osoittakaat teidän ihmeenne. Niin sinun pitää sanoman Aaronille: ota sauvas, ja heitä Pharaon eteen, ja se tulee kärmeeksi."],[7,10,"Niin Moses ja Aaron menivät Pharaon tykö, ja tekivät niinkuin Herra oli käskenyt. Ja Aaron heitti sauvansa Pharaon ja hänen palveliainsa eteen, ja se tuli kärmeeksi.","Niin Moses ja Aaron menivät Pharaon tykö, ja tekivät niinkuin Herra oli käskenyt. Ja Aaron heitti sauvansa Pharaon ja hänen palveliainsa eteen, ja se tuli kärmeeksi."],[7,11,"Niin Pharao myös kutsui tietäjät ja noidat, ja Egyptin noidat tekivät myös niin noitumisillansa.","Niin Pharao myös kutsui tietäjät ja noidat, ja Egyptin noidat tekivät myös niin noitumisillansa."],[7,12,"Ja itsekukin heistä heitti sauvansa maahan, ja ne tulivat kärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa.","Ja itsekukin heistä heitti sauvansa maahan, ja ne tulivat kärmeiksi. Mutta Aaronin sauva nieli heidän sauvansa."],[7,13,"Niin Pharaon sydän paatui, eikä myös kuullut heitä: niinkuin Herra oli sanonut.","Niin Pharaon sydän paatui, eikä myös kuullut heitä: niinkuin Herra oli sanonut."],[7,14,"Ja Herra sanoi Mosekselle: Pharaon sydän on kovettunut, ja ei tahdo päästää kansaa.","Ja Herra sanoi Mosekselle: Pharaon sydän on kovettunut, ja ei tahdo päästää kansaa."],[7,15,"Mene Pharaon tykö varhain aamulla, katso, hän kävelee vetten tykönä, ja seiso häntä vastassa virran reunalla, ja se sauva, joka oli kärmeeksi muuttunut, ota sinun kätees.","Mene Pharaon tykö varhain aamulla, katso, hän kävelee vetten tykönä, ja seiso häntä vastassa virran reunalla, ja se sauva, joka oli kärmeeksi muuttunut, ota sinun kätees."],[7,16,"Ja sano hänelle: Herra Hebrealaisten Jumala on minun lähettänyt sinun tykös, sanoen: laske minun kansani palvelemaan minua korvessa; ja katso, et ole sinä kuullut tähän asti.","Ja sano hänelle: Herra Hebrealaisten Jumala on minun lähettänyt sinun tykös, sanoen: laske minun kansani palvelemaan minua korvessa; ja katso, et ole sinä kuullut tähän asti."],[7,17,"Sentähden sanoo Herra näin: tästä pitää sinun tunteman minun olevan Herran: katso, minä lyön tällä sauvalla, joka on minun kädessäni, veteen, joka virrassa on, ja sen pitää muuttuman vereksi,","Sentähden sanoo Herra näin: tästä pitää sinun tunteman minun olevan Herran: katso, minä lyön tällä sauvalla, joka on minun kädessäni, veteen, joka virrassa on, ja sen pitää muuttuman vereksi,"],[7,18,"Niin että kalat, jotka virrassa ovat, pitää kuoleman, ja virran pitää haiseman, ja Egyptiläiset pitää kyylymän, koska he juovat vettä virrasta.","Niin että kalat, jotka virrassa ovat, pitää kuoleman, ja virran pitää haiseman, ja Egyptiläiset pitää kyylymän, koska he juovat vettä virrasta."],[7,19,"Ja Herra sanoi Mosekselle: sano Aaronille: ota sauvas, ja ojenna kätes Egyptin vetten ylitse, ja heidän virtainsa ylitse, ja heidän jokeinsa ylitse, ja heidän järveinsä ylitse, ja kaikkein heidän vesilammikkoinsa ylitse, ja ne pitää tuleman vereksi, ja pitää oleman veri koko Egyptin maassa, sekä puuastioissa että myös kiviastioissa.","Ja Herra sanoi Mosekselle: sano Aaronille: ota sauvas, ja ojenna kätes Egyptin vetten ylitse, ja heidän virtainsa ylitse, ja heidän jokeinsa ylitse, ja heidän järveinsä ylitse, ja kaikkein heidän vesilammikkoinsa ylitse, ja ne pitää tuleman vereksi, ja pitää oleman veri koko Egyptin maassa, sekä puuastioissa että myös kiviastioissa."],[7,20,"Niin Moses ja Aaron tekivät niinkuin Herra oli käskenyt, ja hän nosti sauvan ja löi veteen, joka virrassa oli, Pharaon ja hänen palveliainsa edessä: ja kaikki vedet, jotka olivat virrassa, muuttuivat vereksi.","Niin Moses ja Aaron tekivät niinkuin Herra oli käskenyt, ja hän nosti sauvan ja löi veteen, joka virrassa oli, Pharaon ja hänen palveliainsa edessä: ja kaikki vedet, jotka olivat virrassa, muuttuivat vereksi."],[7,21,"Ja kala, jotka olivat virrassa, kuolivat, ja virta haisi, niin ettei Egyptiläiset saaneet juoda vettä virrasta. Ja veri oli koko Egyptin maalla.","Ja kala, jotka olivat virrassa, kuolivat, ja virta haisi, niin ettei Egyptiläiset saaneet juoda vettä virrasta. Ja veri oli koko Egyptin maalla."],[7,22,"Egyptin noidat tekivät myös niin noituuksillansa. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli.","Egyptin noidat tekivät myös niin noituuksillansa. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli."],[7,23,"Ja Pharao käänsi itsensä ja palasi kotiansa, ja ei pannut sitäkään sydämeensä.","Ja Pharao käänsi itsensä ja palasi kotiansa, ja ei pannut sitäkään sydämeensä."],[7,24,"Mutta kaikki Egyptiläiset kaivoivat virran ympärillä vettä juodaksensa; sillä ei he saaneet juoda virran vesistä.","Mutta kaikki Egyptiläiset kaivoivat virran ympärillä vettä juodaksensa; sillä ei he saaneet juoda virran vesistä."],[7,25,"Ja se oli täyttä seitsemän päivää, sittenkuin Herra oli lyönyt virran.","Ja se oli täyttä seitsemän päivää, sittenkuin Herra oli lyönyt virran."],[8,1,"Ja Herra sanoi Mosekselle: mene Pharaon tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua.","Ja Herra sanoi Mosekselle: mene Pharaon tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua."],[8,2,"Vaan jos et sinä tahdo päästää; katso, niin minä rankaisen kaikki sinun maas ääret sammakoilla.","Vaan jos et sinä tahdo päästää; katso, niin minä rankaisen kaikki sinun maas ääret sammakoilla."],[8,3,"Niin että virran pitää kuohuman sammakoista, ja ne pitää astuman ylös, ja tuleman sinun huoneesees, ja sinun lepokammioos, ja sinun vuoteesees, niin myös sinun palveliais huoneesen, ja sinun kansas sekaan, ja sinun pätsiis, sinun taikina-astioihis;","Niin että virran pitää kuohuman sammakoista, ja ne pitää astuman ylös, ja tuleman sinun huoneesees, ja sinun lepokammioos, ja sinun vuoteesees, niin myös sinun palveliais huoneesen, ja sinun kansas sekaan, ja sinun pätsiis, sinun taikina-astioihis;"],[8,4,"Ja sinun päälles, ja sinun kansas ja kaikkein sinun palveliais päälle, pitää sammakot hyppelemän.","Ja sinun päälles, ja sinun kansas ja kaikkein sinun palveliais päälle, pitää sammakot hyppelemän."],[8,5,"Ja Herra sanoi Mosekselle: sanos Aaronille: ojenna kätes sauvoinensa virtain, jokein ja järvein ylitse, ja anna sammakot nousta ylitse koko Egyptin maan.","Ja Herra sanoi Mosekselle: sanos Aaronille: ojenna kätes sauvoinensa virtain, jokein ja järvein ylitse, ja anna sammakot nousta ylitse koko Egyptin maan."],[8,6,"Ja Aaron ojensi kätensä Egyptin vetten ylitse; ja sammakot tulivat sieltä ylös, ja peittivät koko Egyptin maan.","Ja Aaron ojensi kätensä Egyptin vetten ylitse; ja sammakot tulivat sieltä ylös, ja peittivät koko Egyptin maan."],[8,7,"Tekivät myös noidat niin noituuksillansa: ja antoivat sammakot tulla Egyptin maan ylitse.","Tekivät myös noidat niin noituuksillansa: ja antoivat sammakot tulla Egyptin maan ylitse."],[8,8,"Niin Pharao kutsui Moseksen ja Aaronin, ja sanoi: rukoilkaat Herraa, että hän ottais pois sammakot minulta ja minun kansaltani; niin minä päästän kansan uhraamaan Herralle.","Niin Pharao kutsui Moseksen ja Aaronin, ja sanoi: rukoilkaat Herraa, että hän ottais pois sammakot minulta ja minun kansaltani; niin minä päästän kansan uhraamaan Herralle."],[8,9,"Moses sanoi: pidä sinä se kunnia, (ettäs määräät) koska minun pitää rukoileman edestäs, ja palveliais ja kansas edestä, että sammakot pitäis hukutettaman sinulta, ja sinun huoneistas, ainoastansa virtaan jäämän.","Moses sanoi: pidä sinä se kunnia, (ettäs määräät) koska minun pitää rukoileman edestäs, ja palveliais ja kansas edestä, että sammakot pitäis hukutettaman sinulta, ja sinun huoneistas, ainoastansa virtaan jäämän."],[8,10,"Hän sanoi: huomenna. Hän vastasi: olkoon sanas jälkeen, ettäs tietäisit, ettei yksikään ole niinkuin Herra, meidän Jumalamme.","Hän sanoi: huomenna. Hän vastasi: olkoon sanas jälkeen, ettäs tietäisit, ettei yksikään ole niinkuin Herra, meidän Jumalamme."],[8,11,"Silloin sammakot pitää otettaman pois sinulta, ja sinun huoneistas, ja sinun palvelioiltas, ja sinun kansaltas, ainoastansa virtaan jäämän.","Silloin sammakot pitää otettaman pois sinulta, ja sinun huoneistas, ja sinun palvelioiltas, ja sinun kansaltas, ainoastansa virtaan jäämän."],[8,12,"Niin Moses ja Aaron läksivät Pharaon tyköä: ja Moses huusi Herran tykö sammakkoin tähden, jotka hän Pharaon päälle pannut oli.","Niin Moses ja Aaron läksivät Pharaon tyköä: ja Moses huusi Herran tykö sammakkoin tähden, jotka hän Pharaon päälle pannut oli."],[8,13,"Ja Herra teki Moseksen sanan jälkeen: ja sammakot kuolivat huoneista, kylistä ja kedoilta.","Ja Herra teki Moseksen sanan jälkeen: ja sammakot kuolivat huoneista, kylistä ja kedoilta."],[8,14,"Ja he heittivät ne suuriin roukkioihin, ja maa haisi siitä.","Ja he heittivät ne suuriin roukkioihin, ja maa haisi siitä."],[8,15,"Kun Pharao näki levon saaneensa, paadutti hän sydämensä, ja ei kuullut heitä: niinkuin Herra sanonut oli.","Kun Pharao näki levon saaneensa, paadutti hän sydämensä, ja ei kuullut heitä: niinkuin Herra sanonut oli."],[8,16,"Ja Herra sanoi Mosekselle: sano Aaronille: ojenna sauvas, ja lyö maan tomuun, että se tulis täiksi koko Egyptin maassa.","Ja Herra sanoi Mosekselle: sano Aaronille: ojenna sauvas, ja lyö maan tomuun, että se tulis täiksi koko Egyptin maassa."],[8,17,"Ja he tekivät niin: ja Aaron ojensi kätensä sauvoinensa, ja löi maan tomua, ja täit tulivat ihmisiin ja eläimiin: ja kaikki maan tomu muuttui täiksi koko Egyptin maassa.","Ja he tekivät niin: ja Aaron ojensi kätensä sauvoinensa, ja löi maan tomua, ja täit tulivat ihmisiin ja eläimiin: ja kaikki maan tomu muuttui täiksi koko Egyptin maassa."],[8,18,"Tekivät myös noidat noituuksillansa niin, täitä matkaan saattaaksensa; vaan ei he taitaneet. Ja täit olivat ihmisissä ja eläimissä.","Tekivät myös noidat noituuksillansa niin, täitä matkaan saattaaksensa; vaan ei he taitaneet. Ja täit olivat ihmisissä ja eläimissä."],[8,19,"Niin sanoivat noidat Pharaolle: tämä on Jumalan sormi. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli.","Niin sanoivat noidat Pharaolle: tämä on Jumalan sormi. Mutta Pharaon sydän paatui, ja ei kuullut heitä: niinkuin Herra sanonut oli."],[8,20,"Ja Herra sanoi Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä; katso, hän menee vetten tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua.","Ja Herra sanoi Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä; katso, hän menee vetten tykö, ja sano hänelle: näin sanoo Herra: päästä minun kansani palvelemaan minua."],[8,21,"Sillä jos et sinä päästä minun kansaani; katso, niin minä tahdon lähettää sinulle, ja sinun palvelioilles, ja sinun kansalles, ja sinun huoneisiis kaikkinaiset turilaat, niin että kaikki huoneet Egyptissä täytetään turilaista, niin myös se maa jonka päällä he ovat.","Sillä jos et sinä päästä minun kansaani; katso, niin minä tahdon lähettää sinulle, ja sinun palvelioilles, ja sinun kansalles, ja sinun huoneisiis kaikkinaiset turilaat, niin että kaikki huoneet Egyptissä täytetään turilaista, niin myös se maa jonka päällä he ovat."],[8,22,"Ja minä tahdon eroittaa sinä päivänä Gosenin maan, jossa minun kansani asuu, ettei siinä yhtään turilasta pidä oleman: ettäs tietäisit minun olevan Herran koko maan keskellä.","Ja minä tahdon eroittaa sinä päivänä Gosenin maan, jossa minun kansani asuu, ettei siinä yhtään turilasta pidä oleman: ettäs tietäisit minun olevan Herran koko maan keskellä."],[8,23,"Ja minä panen lunastuksen minun ja sinun kansas välille. Huomenna pitää tämän ihmeen tapahtuman.","Ja minä panen lunastuksen minun ja sinun kansas välille. Huomenna pitää tämän ihmeen tapahtuman."],[8,24,"Ja Herra teki niin. Ja tuli paljo turilaita Pharaon huoneesen, ja hänen palveliainsa huoneisiin, ja koko Egyptin maalle; ja maa turmeltiin turilailta.","Ja Herra teki niin. Ja tuli paljo turilaita Pharaon huoneesen, ja hänen palveliainsa huoneisiin, ja koko Egyptin maalle; ja maa turmeltiin turilailta."],[8,25,"Niin kutsui Pharao Moseksen ja Aaronin, ja sanoi: menkäät ja uhratkaat teidän Jumalallenne tällä maalla.","Niin kutsui Pharao Moseksen ja Aaronin, ja sanoi: menkäät ja uhratkaat teidän Jumalallenne tällä maalla."],[8,26,"Moses sanoi: ei sovi niin tehdä; sillä me uhraisimme Herralle meidän Jumalallemme Egyptiläisten kauhistuksen: katso, jos me Egyptin maan kauhistukset uhraisimme heidän edessänsä, eikö he meitä kivittäisi?","Moses sanoi: ei sovi niin tehdä; sillä me uhraisimme Herralle meidän Jumalallemme Egyptiläisten kauhistuksen: katso, jos me Egyptin maan kauhistukset uhraisimme heidän edessänsä, eikö he meitä kivittäisi?"],[8,27,"Kolmen päiväkunnan matkan menemme me korpeen, ja uhraamme Herralle meidän Jumalallemme, niinkuin hän on meille sanonut.","Kolmen päiväkunnan matkan menemme me korpeen, ja uhraamme Herralle meidän Jumalallemme, niinkuin hän on meille sanonut."],[8,28,"Pharao sanoi: minä päästän teidät, että te uhraisitte Herralle teidän Jumalallenne korvessa, ainoastansa ettétte kauvas menisi; rukoilkaat minun edestäni.","Pharao sanoi: minä päästän teidät, että te uhraisitte Herralle teidän Jumalallenne korvessa, ainoastansa ettétte kauvas menisi; rukoilkaat minun edestäni."],[8,29,"Moses sanoi: Katso, kuin minä menen sinun tyköäs, niin minä rukoilen Herraa, että turilaat otettaisiin pois Pharaolta, ja hänen palvelioiltansa, ja hänen kansaltansa huomenna: ainoastansa älä minua enää viettele, niin ettes päästä kansaa uhraamaan Herralle.","Moses sanoi: Katso, kuin minä menen sinun tyköäs, niin minä rukoilen Herraa, että turilaat otettaisiin pois Pharaolta, ja hänen palvelioiltansa, ja hänen kansaltansa huomenna: ainoastansa älä minua enää viettele, niin ettes päästä kansaa uhraamaan Herralle."],[8,30,"Ja Moses läksi Pharaon tyköä, ja rukoili Herraa.","Ja Moses läksi Pharaon tyköä, ja rukoili Herraa."],[8,31,"Ja Herra teki niinkuin Moses sanonut oli: ja otti turilaat Pharaolta ja hänen palvelioiltansa, ja hänen kansaltansa pois, niin ettei yhtäkään jäänyt.","Ja Herra teki niinkuin Moses sanonut oli: ja otti turilaat Pharaolta ja hänen palvelioiltansa, ja hänen kansaltansa pois, niin ettei yhtäkään jäänyt."],[8,32,"Mutta Pharao paadutti sydämensä vielä nyt tälläkin haavaa ja ei päästänyt kansaa.","Mutta Pharao paadutti sydämensä vielä nyt tälläkin haavaa ja ei päästänyt kansaa."],[9,1,"Niin Herra sanoi Mosekselle mene Pharaon tykö, ja sano hänelle: näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua.","Niin Herra sanoi Mosekselle mene Pharaon tykö, ja sano hänelle: näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua."],[9,2,"Vaan jolles päästä, mutta vielä pidätät heitä:","Vaan jolles päästä, mutta vielä pidätät heitä:"],[9,3,"Katso, Herran käsi on sinun karjas päällä, jotka ovat kedolla, hevosten päällä, aasein päällä, kamelein päällä, härkäin päällä, lammasten päällä, sangen raskaan ruttotaudin kanssa.","Katso, Herran käsi on sinun karjas päällä, jotka ovat kedolla, hevosten päällä, aasein päällä, kamelein päällä, härkäin päällä, lammasten päällä, sangen raskaan ruttotaudin kanssa."],[9,4,"Ja Herra on eroittava Israelin karjan Egyptin karjasta, niin ettei mitään kuole kaikesta kuin Israelin lapsilla on.","Ja Herra on eroittava Israelin karjan Egyptin karjasta, niin ettei mitään kuole kaikesta kuin Israelin lapsilla on."],[9,5,"Ja Herra määräsi ajan, sanoen: tämän Herra tekee huomenna maassa.","Ja Herra määräsi ajan, sanoen: tämän Herra tekee huomenna maassa."],[9,6,"Ja Herra teki niin toisna päivänä, ja kaikki Egyptin karja kuoli: vaan Israelin lasten karjasta ei yhtäkään kuollut.","Ja Herra teki niin toisna päivänä, ja kaikki Egyptin karja kuoli: vaan Israelin lasten karjasta ei yhtäkään kuollut."],[9,7,"Niin Pharao lähetti (tiedustelemaan) ja katso, ei ollut Israelin karjasta yhtäkään kuollut. Mutta Pharaon sydän paatui, ja ei päästänyt kansaa.","Niin Pharao lähetti (tiedustelemaan) ja katso, ei ollut Israelin karjasta yhtäkään kuollut. Mutta Pharaon sydän paatui, ja ei päästänyt kansaa."],[9,8,"Ja Herra sanoi Mosekselle ja Aaronille: ottakaat kätenne täyteen toton nokea, ja Moses paiskatkaan sen taivaasen päin Pharaon edessä.","Ja Herra sanoi Mosekselle ja Aaronille: ottakaat kätenne täyteen toton nokea, ja Moses paiskatkaan sen taivaasen päin Pharaon edessä."],[9,9,"Ja pitää tuleman tomuksi koko Egyptin maan päälle, ja pitää oleman ihmisten ja karjan päällä märkäpäistä punottavaiset paisumat koko Egyptin maalla.","Ja pitää tuleman tomuksi koko Egyptin maan päälle, ja pitää oleman ihmisten ja karjan päällä märkäpäistä punottavaiset paisumat koko Egyptin maalla."],[9,10,"Ja he ottivat nokea totosta, ja seisoivat Pharaon edessä, ja Moses paiskasi sen taivaasen päin: niin tulivat märkäpäistä punottavaiset paisumat ihmisiin ja karjaan.","Ja he ottivat nokea totosta, ja seisoivat Pharaon edessä, ja Moses paiskasi sen taivaasen päin: niin tulivat märkäpäistä punottavaiset paisumat ihmisiin ja karjaan."],[9,11,"Niin ettei noidatkaan saaneet seisoa Moseksen edessä paisumain tähden: sillä paisumat olivat niin noitain päällä, kuin kaikkien Egyptiläisten.","Niin ettei noidatkaan saaneet seisoa Moseksen edessä paisumain tähden: sillä paisumat olivat niin noitain päällä, kuin kaikkien Egyptiläisten."],[9,12,"Mutta Herra paadutti Pharaon sydämen, ja ei hän kuullut heitä: niinkuin Herra Mosekselle sanonut oli.","Mutta Herra paadutti Pharaon sydämen, ja ei hän kuullut heitä: niinkuin Herra Mosekselle sanonut oli."],[9,13,"Niin sanoi Herra Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä, ja sano hänelle: Näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua.","Niin sanoi Herra Mosekselle: nouse huomenna varhain, ja seiso Pharaon edessä, ja sano hänelle: Näin sanoo Herra Hebrealaisten Jumala: päästä minun kansani palvelemaan minua."],[9,14,"Muutoin minä tällä haavaa lähetän kaikki minun rangaistukseni sinun sydämees, ja sinun palveliais, ja sinun kansas päälle, tietääkses, ettei kaikessa maassa ole minun vertaani;","Muutoin minä tällä haavaa lähetän kaikki minun rangaistukseni sinun sydämees, ja sinun palveliais, ja sinun kansas päälle, tietääkses, ettei kaikessa maassa ole minun vertaani;"],[9,15,"Sillä minä olisin nyt jo ojentanut käteni, ja lyönyt sinun ja sinun kansas ruttotaudilla: että sinun olis täytynyt hukkua maan päältä.","Sillä minä olisin nyt jo ojentanut käteni, ja lyönyt sinun ja sinun kansas ruttotaudilla: että sinun olis täytynyt hukkua maan päältä."],[9,16,"Mutta tosin sentähden olen minä sinun antanut seisoa, että minä osoittaisin sinulle minun voimani, ja että minun nimeni julistettaisiin kaikessa maassa.","Mutta tosin sentähden olen minä sinun antanut seisoa, että minä osoittaisin sinulle minun voimani, ja että minun nimeni julistettaisiin kaikessa maassa."],[9,17,"Ja vieläkös nyt ylennät itses minun kansani päälle, etkä päästä heitä:","Ja vieläkös nyt ylennät itses minun kansani päälle, etkä päästä heitä:"],[9,18,"Katso, huomenna tällä ajalla annan minä sangen suuria rakeita sataa, jonka kaltaisia ei ole ollut Egyptissä, hamasta siitä päivästä kuin se perustettu on, niin tähän asti.","Katso, huomenna tällä ajalla annan minä sangen suuria rakeita sataa, jonka kaltaisia ei ole ollut Egyptissä, hamasta siitä päivästä kuin se perustettu on, niin tähän asti."],[9,19,"Lähetä siis nyt ja korjaa sinun karjas ja kaikki mitä sinulla on kedolla; sillä kaikki ihmiset ja karja kuin kedolla löydetään, ja ei ole korjatut huoneesen, niiden päälle lankeevat rakeet ja heidän pitää kuoleman.","Lähetä siis nyt ja korjaa sinun karjas ja kaikki mitä sinulla on kedolla; sillä kaikki ihmiset ja karja kuin kedolla löydetään, ja ei ole korjatut huoneesen, niiden päälle lankeevat rakeet ja heidän pitää kuoleman."],[9,20,"Joka Pharaon palvelioista pelkäsi Herran sanaa, se palveliansa ja karjansa huoneesen korjasi,","Joka Pharaon palvelioista pelkäsi Herran sanaa, se palveliansa ja karjansa huoneesen korjasi,"],[9,21,"Vaan jonka sydän ei totellut Herran sanaa, se jätti kedolle palveliansa ja karjansa.","Vaan jonka sydän ei totellut Herran sanaa, se jätti kedolle palveliansa ja karjansa."],[9,22,"Niin sanoi Herra Mosekselle: ojenna kätes taivaasen päin, että rakeita satais koko Egyptin maan päälle: ihmisten päälle, karjan päälle, ja kaikkein päälle, mitä kedolla vihottaa Egyptin maalla.","Niin sanoi Herra Mosekselle: ojenna kätes taivaasen päin, että rakeita satais koko Egyptin maan päälle: ihmisten päälle, karjan päälle, ja kaikkein päälle, mitä kedolla vihottaa Egyptin maalla."],[9,23,"Niin ojensi Moses sauvansa taivaasen päin, että Herra antais jylistä ja rakeita sataa, ja että pitkäisen tuli leimahtelis maan päälle; ja Herra antoi sataa rakeita Egyptin maan päälle,","Niin ojensi Moses sauvansa taivaasen päin, että Herra antais jylistä ja rakeita sataa, ja että pitkäisen tuli leimahtelis maan päälle; ja Herra antoi sataa rakeita Egyptin maan päälle,"],[9,24,"Että rakeet ja tuli sekaisin maahan lankesivat, niin raskaasti, ettei ikänänsä senkaltaista kaikessa Egyptin maassa tapahtunut ollut, siitä ajasta kuin kansa siinä asumaan rupesi.","Että rakeet ja tuli sekaisin maahan lankesivat, niin raskaasti, ettei ikänänsä senkaltaista kaikessa Egyptin maassa tapahtunut ollut, siitä ajasta kuin kansa siinä asumaan rupesi."],[9,25,"Ja rakeet löivät koko Egyptin maalla kaikki kuin kedolla olivat, sekä ihmiset että karjan: niin myös koko maan vihannan löivät rakeet kaikki, myös puut kedolla särkivät rikki.","Ja rakeet löivät koko Egyptin maalla kaikki kuin kedolla olivat, sekä ihmiset että karjan: niin myös koko maan vihannan löivät rakeet kaikki, myös puut kedolla särkivät rikki."],[9,26,"Ainoasti Gosenin maakunnassa, jossa Israelin lapset olivat, ei rakeita ollut.","Ainoasti Gosenin maakunnassa, jossa Israelin lapset olivat, ei rakeita ollut."],[9,27,"Niin lähetti Pharao ja kutsui Moseksen ja Aaronin, ja sanoi heille: minä olen tällä haavalla pahoin tehnyt; Herra on vanhurskas, vaan minä ja minun kansani olemme jumalattomat.","Niin lähetti Pharao ja kutsui Moseksen ja Aaronin, ja sanoi heille: minä olen tällä haavalla pahoin tehnyt; Herra on vanhurskas, vaan minä ja minun kansani olemme jumalattomat."],[9,28,"Sentähden rukoilkaat Herraa, että jo kyllä olis, ja että Jumalan jylinä ja rakeet lakkaisivat: niin minä päästän teidät, eikä teidän pidä enempi täällä viipymän.","Sentähden rukoilkaat Herraa, että jo kyllä olis, ja että Jumalan jylinä ja rakeet lakkaisivat: niin minä päästän teidät, eikä teidän pidä enempi täällä viipymän."],[9,29,"Ja Moses sanoi hänelle: koska minä lähden kaupungista, niin minä ojennan käteni Herran tykö: niin jylinä lakkaa ja rakeita ei pidä enempi oleman, ettäs tietäisit maan olevan Herran.","Ja Moses sanoi hänelle: koska minä lähden kaupungista, niin minä ojennan käteni Herran tykö: niin jylinä lakkaa ja rakeita ei pidä enempi oleman, ettäs tietäisit maan olevan Herran."],[9,30,"Mutta et sinä ja sinun palvelias, minä kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa.","Mutta et sinä ja sinun palvelias, minä kyllä tiedän, vielä nytkään pelkää Herraa Jumalaa."],[9,31,"Niin pellavat ja ohrat maahan lyötiin; sillä ohra oli tähkäpäällä ja pellava oli kulkulla.","Niin pellavat ja ohrat maahan lyötiin; sillä ohra oli tähkäpäällä ja pellava oli kulkulla."],[9,32,"Mutta nisu ja kaura (a) ei turmeltuneet, sillä ne olivat hiljakylvöt. (a) Spelta eli Turkin kaura.","Mutta nisu ja kaura (a) ei turmeltuneet, sillä ne olivat hiljakylvöt. (a) Spelta eli Turkin kaura."],[9,33,"Niin Moses meni ulos kaupungista Pharaon tyköä, ja ojensi kätensä Herran tykö: ja jylinä ja rakeet lakkasivat, ja sade ei enempi vuodatettu maan päälle.","Niin Moses meni ulos kaupungista Pharaon tyköä, ja ojensi kätensä Herran tykö: ja jylinä ja rakeet lakkasivat, ja sade ei enempi vuodatettu maan päälle."],[9,34,"Koska Pharao näki, että sade, ja rakeet, ja jylinät lakkasivat, teki hän vielä enemmin pahaa, ja paadutti sydämensä, sekä hän että hänen palveliansa.","Koska Pharao näki, että sade, ja rakeet, ja jylinät lakkasivat, teki hän vielä enemmin pahaa, ja paadutti sydämensä, sekä hän että hänen palveliansa."],[9,35,"Niin paatui Pharaon sydän, ja ei päästänyt Israelin lapsia: niinkuin Herra Moseksen kautta sanonut oli.","Niin paatui Pharaon sydän, ja ei päästänyt Israelin lapsia: niinkuin Herra Moseksen kautta sanonut oli."],[10,1,"Ja Herra sanoi Mosekselle: mene Pharaon tykö; sillä minä paadutin hänen ja hänen palveliainsa sydämet, tehdäkseni nämät minun ihmeeni heidän seassansa.","Ja Herra sanoi Mosekselle: mene Pharaon tykö; sillä minä paadutin hänen ja hänen palveliainsa sydämet, tehdäkseni nämät minun ihmeeni heidän seassansa."],[10,2,"Ja että sinä ilmoittaisit sinun lastes, ja sinun lastes lasten korviin, mitä minä tehnyt olen Egyptissä, ja minun ihmeeni, jotka minä tein heidän seassansa, että te tietäisitte, että minä olen Herra.","Ja että sinä ilmoittaisit sinun lastes, ja sinun lastes lasten korviin, mitä minä tehnyt olen Egyptissä, ja minun ihmeeni, jotka minä tein heidän seassansa, että te tietäisitte, että minä olen Herra."],[10,3,"Niin menivät Moses ja Aaron Pharaon tykö, ja sanoivat hänelle: näin sanoo Herra Hebrealaisten Jumala: kuinka kauan et sinä tahdo nöyryyttää itsiäs minun edessäni? Päästä minun kansani palvelemaan minua;","Niin menivät Moses ja Aaron Pharaon tykö, ja sanoivat hänelle: näin sanoo Herra Hebrealaisten Jumala: kuinka kauan et sinä tahdo nöyryyttää itsiäs minun edessäni? Päästä minun kansani palvelemaan minua;"],[10,4,"Sillä jos sinä estelet päästää minun kansani; katso, niin minä huomenna tuotan heinäsirkat kaikkiin sinun maas ääriin,","Sillä jos sinä estelet päästää minun kansani; katso, niin minä huomenna tuotan heinäsirkat kaikkiin sinun maas ääriin,"],[10,5,"Niin että heidän pitää peittämän maan, niin ettei maa pidä näkymän; ja heidän pitää syömän tähteet, mitkä teille on jääneet rakeilta, ja pitää syömän kaikki vihottavaiset puut teidän kedollanne,","Niin että heidän pitää peittämän maan, niin ettei maa pidä näkymän; ja heidän pitää syömän tähteet, mitkä teille on jääneet rakeilta, ja pitää syömän kaikki vihottavaiset puut teidän kedollanne,"],[10,6,"Ja täyttämän sinun huonees, ja kaikkein sinun palveliais huoneet, ja koko Egyptin huoneet; jonka kaltaisia sinun isäs ja isäis-isät ei nähneet ole, siitä päivästä kuin he maan päällä olleet ovat tähän päivään asti. Ja hän käänsi itsensä ja meni ulos Pharaon tyköä.","Ja täyttämän sinun huonees, ja kaikkein sinun palveliais huoneet, ja koko Egyptin huoneet; jonka kaltaisia sinun isäs ja isäis-isät ei nähneet ole, siitä päivästä kuin he maan päällä olleet ovat tähän päivään asti. Ja hän käänsi itsensä ja meni ulos Pharaon tyköä."],[10,7,"Niin sanoivat Pharaon palveliat hänelle: kuinka kauvan pitää hänen oleman meille paulaksi? Päästä kansa palvelemaan Herraa Jumalaansa: etkös vielä tiedä Egyptiä hävitetyksi?","Niin sanoivat Pharaon palveliat hänelle: kuinka kauvan pitää hänen oleman meille paulaksi? Päästä kansa palvelemaan Herraa Jumalaansa: etkös vielä tiedä Egyptiä hävitetyksi?"],[10,8,"Niin Moses ja Aaron palautettiin jällensä Pharaon tykö, joka sanoi heille: menkäät ja palvelkaat Herraa teidän Jumalaanne; vaan kutka ne ovat jotka menevät?","Niin Moses ja Aaron palautettiin jällensä Pharaon tykö, joka sanoi heille: menkäät ja palvelkaat Herraa teidän Jumalaanne; vaan kutka ne ovat jotka menevät?"],[10,9,"Ja Moses sanoi: me menemme meidän nuorten ja vanhain kanssa, poikinemme ja tyttärinemme, lammastemme ja karjamme kanssa; sillä meillä on Herran juhla.","Ja Moses sanoi: me menemme meidän nuorten ja vanhain kanssa, poikinemme ja tyttärinemme, lammastemme ja karjamme kanssa; sillä meillä on Herran juhla."],[10,10,"Ja hän sanoi heille: ikään niin, olkoon Herra teidän kanssanne. Pitäiskö minun päästämän teidät ja teidän lapsenne? Katsokaat, jollei teillä jotakin pahaa sydämessänne ole?","Ja hän sanoi heille: ikään niin, olkoon Herra teidän kanssanne. Pitäiskö minun päästämän teidät ja teidän lapsenne? Katsokaat, jollei teillä jotakin pahaa sydämessänne ole?"],[10,11,"Ei niin, mutta menkäät te miehet ja palvelkaat Herraa; sillä sitä te olette pyytäneetkin. Ja he ajoivat heidät pois Pharaon edestä.","Ei niin, mutta menkäät te miehet ja palvelkaat Herraa; sillä sitä te olette pyytäneetkin. Ja he ajoivat heidät pois Pharaon edestä."],[10,12,"Niin sanoi Herra Mosekselle: ojenna kätes Egyptin maan ylitse heinäsirkkain tähden, että he tulisivat Egyptin maan päälle, ja söisivät kaiken maan vihannon, kaikki mitä rakeilta jäänyt on.","Niin sanoi Herra Mosekselle: ojenna kätes Egyptin maan ylitse heinäsirkkain tähden, että he tulisivat Egyptin maan päälle, ja söisivät kaiken maan vihannon, kaikki mitä rakeilta jäänyt on."],[10,13,"Moses ojensi sauvansa Egyptin maan ylitse, ja Herra antoi tulla itätuulen sille maalle kaiken sen päivän ja kaiken sen yön; ja aamulla nosti itätuuli heinäsirkat.","Moses ojensi sauvansa Egyptin maan ylitse, ja Herra antoi tulla itätuulen sille maalle kaiken sen päivän ja kaiken sen yön; ja aamulla nosti itätuuli heinäsirkat."],[10,14,"Ja tulivat heinäsirkat koko Egyptin maan päälle, laskivat itsensä joka paikkaan Egyptin maalle, niin epälukuiset, ettei heidän kaltaisiansa heinäsirkkoja ennen ollut, eikä tästedes tule.","Ja tulivat heinäsirkat koko Egyptin maan päälle, laskivat itsensä joka paikkaan Egyptin maalle, niin epälukuiset, ettei heidän kaltaisiansa heinäsirkkoja ennen ollut, eikä tästedes tule."],[10,15,"Ja he peittivät kaiken maan, ja maa tuli mustaksi. Ja söivät kaikki maan vihannon, ja kaikki puiden hedelmät kuin jääneet olivat rakeilta, ja ei jäänyt ensinkään viheriäistä puihin ja kedon ruohoihin koko Egyptin maalla.","Ja he peittivät kaiken maan, ja maa tuli mustaksi. Ja söivät kaikki maan vihannon, ja kaikki puiden hedelmät kuin jääneet olivat rakeilta, ja ei jäänyt ensinkään viheriäistä puihin ja kedon ruohoihin koko Egyptin maalla."],[10,16,"Niin kutsui Pharao kiiruusti Moseksen ja Aaronin, ja sanoi: minä olen pahaa tehnyt Herraa teidän Jumalaanne, ja teitä vastaan.","Niin kutsui Pharao kiiruusti Moseksen ja Aaronin, ja sanoi: minä olen pahaa tehnyt Herraa teidän Jumalaanne, ja teitä vastaan."],[10,17,"Niin anna nyt minulle anteeksi minun rikokseni vielä tällä erällä, ja rukoilkaat Herraa teidän Jumalaanne, että hän ottais minulta pois vielä tämän kuoleman.","Niin anna nyt minulle anteeksi minun rikokseni vielä tällä erällä, ja rukoilkaat Herraa teidän Jumalaanne, että hän ottais minulta pois vielä tämän kuoleman."],[10,18,"Ja hän meni pois Pharaon tyköä, ja rukoili Herraa.","Ja hän meni pois Pharaon tyköä, ja rukoili Herraa."],[10,19,"Niin Herra käänsi tuulen aivan tuimaksi länsituuleksi, ja nostatti heinäsirkat ja heitti heidät Punaiseen mereen, niin ettei yhtäkään heinäsirkkaa jäänyt koko Egyptin maan ääriin.","Niin Herra käänsi tuulen aivan tuimaksi länsituuleksi, ja nostatti heinäsirkat ja heitti heidät Punaiseen mereen, niin ettei yhtäkään heinäsirkkaa jäänyt koko Egyptin maan ääriin."],[10,20,"Mutta Herra paadutti Pharaon sydämen, ja ei hän päästänyt Israelin lapsia.","Mutta Herra paadutti Pharaon sydämen, ja ei hän päästänyt Israelin lapsia."],[10,21,"Ja Herra sanoi Mosekselle: ojenna kätes taivaaseen päin, että pimeys tulis Egyptin maan päälle, niin että pimeyteen ruveta taidettaisiin.","Ja Herra sanoi Mosekselle: ojenna kätes taivaaseen päin, että pimeys tulis Egyptin maan päälle, niin että pimeyteen ruveta taidettaisiin."],[10,22,"Ja Moses ojensi kätensä taivaaseen päin, niin tuli synkiä pimeys koko Egyptin maan päälle kolmeksi päiväksi.","Ja Moses ojensi kätensä taivaaseen päin, niin tuli synkiä pimeys koko Egyptin maan päälle kolmeksi päiväksi."],[10,23,"Niin ettei toinen toistansa nähnyt, eikä myös noussut paikastansa kolmena päivänä. Mutta kaikilla Israelin lapsilla oli valkeus heidän asuinsioissansa.","Niin ettei toinen toistansa nähnyt, eikä myös noussut paikastansa kolmena päivänä. Mutta kaikilla Israelin lapsilla oli valkeus heidän asuinsioissansa."],[10,24,"Niin kutsui Pharao Moseksen, ja sanoi: menkäät ja palvelkaat Herraa; ainoastansa teidän lampaanne ja karjanne jääkään tänne: teidän lapsenne menkään myös teidän kanssanne.","Niin kutsui Pharao Moseksen, ja sanoi: menkäät ja palvelkaat Herraa; ainoastansa teidän lampaanne ja karjanne jääkään tänne: teidän lapsenne menkään myös teidän kanssanne."],[10,25,"Moses sanoi: sinun pitää myös salliman minun käsiini uhrini, ja polttouhrin, jota meidän pitää tekemän Herralle meidän Jumalallemme.","Moses sanoi: sinun pitää myös salliman minun käsiini uhrini, ja polttouhrin, jota meidän pitää tekemän Herralle meidän Jumalallemme."],[10,26,"Meidän karjamme pitää myös menemän meidän kanssamme, ja ei yhtäkään sorkkaa jäämän; sillä siitä meidän pitää ottaman ja tekemän palveluksen Herralle meidän Jumalallemme: ja emme tiedä, millä me palvelemme Herraa, siihenasti kuin me sinne tulemme.","Meidän karjamme pitää myös menemän meidän kanssamme, ja ei yhtäkään sorkkaa jäämän; sillä siitä meidän pitää ottaman ja tekemän palveluksen Herralle meidän Jumalallemme: ja emme tiedä, millä me palvelemme Herraa, siihenasti kuin me sinne tulemme."],[10,27,"Mutta Herra paadutti Pharaon sydämen, ja ei hän tahtonut päästää heitä.","Mutta Herra paadutti Pharaon sydämen, ja ei hän tahtonut päästää heitä."],[10,28,"Ja Pharao sanoi hänelle: mene pois minun tyköäni, ja karta ettes enempi silleen tule minun kasvoini eteen; sillä jona päivänä sinä tulet minun eteeni, pitää sinun kuoleman.","Ja Pharao sanoi hänelle: mene pois minun tyköäni, ja karta ettes enempi silleen tule minun kasvoini eteen; sillä jona päivänä sinä tulet minun eteeni, pitää sinun kuoleman."],[10,29,"Moses vastasi: niinkuin sinä sanonut olet, en tule minä enempi sinun kasvois eteen.","Moses vastasi: niinkuin sinä sanonut olet, en tule minä enempi sinun kasvois eteen."],[11,1,"Ja Herra oli sanonut Mosekselle: vielä minä annan tulla yhden rangaistuksen Pharaolle ja Egyptiin, sitte hän päästää teidät täältä, ja koska hän teidät kokonansa päästää, niin hän ajain ajaa teidät täältä ulos.","Ja Herra oli sanonut Mosekselle: vielä minä annan tulla yhden rangaistuksen Pharaolle ja Egyptiin, sitte hän päästää teidät täältä, ja koska hän teidät kokonansa päästää, niin hän ajain ajaa teidät täältä ulos."],[11,2,"Niin sano siis nyt kansalle: että joka mies anois lähimmäiseltänsä, ja jokainen vaimo lähimmäiseltänsä, hopia- ja kulta-astioita.","Niin sano siis nyt kansalle: että joka mies anois lähimmäiseltänsä, ja jokainen vaimo lähimmäiseltänsä, hopia- ja kulta-astioita."],[11,3,"Sillä Herra oli antanut armon kansalle Egyptiläisten edessä. Ja Moses oli sangen kuuluisa mies Egyptin maalla, Pharaon palveliain ja kansan edessä.","Sillä Herra oli antanut armon kansalle Egyptiläisten edessä. Ja Moses oli sangen kuuluisa mies Egyptin maalla, Pharaon palveliain ja kansan edessä."],[11,4,"Ja Moses sanoi: näin sanoo Herra: puoliyön aikaan minä vaellan Egyptin maan lävitse,","Ja Moses sanoi: näin sanoo Herra: puoliyön aikaan minä vaellan Egyptin maan lävitse,"],[11,5,"Ja jokainen esikoinen Egyptin maalla pitää kuoleman, Pharaon esikoisesta, joka hänen istuimellansa piti istuman, piian esikoiseen asti, joka myllyssä on, niin myös kaikkein eläinten esikoiset.","Ja jokainen esikoinen Egyptin maalla pitää kuoleman, Pharaon esikoisesta, joka hänen istuimellansa piti istuman, piian esikoiseen asti, joka myllyssä on, niin myös kaikkein eläinten esikoiset."],[11,6,"Ja suuren parun pitää oleman koko Egyptin maalla, jonkakaltaista ei ole ollut, eikä tuleman pidä.","Ja suuren parun pitää oleman koko Egyptin maalla, jonkakaltaista ei ole ollut, eikä tuleman pidä."],[11,7,"Mutta kaikkein Israelin lasten seassa ei koirakaan kieltänsä värväyttämän pidä ihmisiä taikka eläimiä vastaan: että te tietäisitte, kuinka Herra eroittaa Egyptin ja Israelin.","Mutta kaikkein Israelin lasten seassa ei koirakaan kieltänsä värväyttämän pidä ihmisiä taikka eläimiä vastaan: että te tietäisitte, kuinka Herra eroittaa Egyptin ja Israelin."],[11,8,"Silloin kaikki nämät sinun palvelias pitää tuleman minun tyköni, ja kumartaman minua, sanoen: lähde ulos, sinä ja kaikki kansa, jotka sinun allas ovat, ja sitte minä lähden. Ja hän läksi Pharaon tyköä sangen vihoissansa.","Silloin kaikki nämät sinun palvelias pitää tuleman minun tyköni, ja kumartaman minua, sanoen: lähde ulos, sinä ja kaikki kansa, jotka sinun allas ovat, ja sitte minä lähden. Ja hän läksi Pharaon tyköä sangen vihoissansa."],[11,9,"Mutta Herra oli sanonut Mosekselle: ei Pharao kuule teitä, että paljo minun ihmeitäni tapahtuis Egyptin maalla.","Mutta Herra oli sanonut Mosekselle: ei Pharao kuule teitä, että paljo minun ihmeitäni tapahtuis Egyptin maalla."],[11,10,"Ja Moses ja Aaron tekivät kaikki nämä ihmeet Pharaon edessä, vaan Herra paadutti hänen sydämensä, ja ei hän päästänyt Israelin lapsia maaltansa.","Ja Moses ja Aaron tekivät kaikki nämä ihmeet Pharaon edessä, vaan Herra paadutti hänen sydämensä, ja ei hän päästänyt Israelin lapsia maaltansa."],[12,1,"Herra oli puhunut Mosekselle ja Aaronille Egyptin maalla, sanoen:","Herra oli puhunut Mosekselle ja Aaronille Egyptin maalla, sanoen:"],[12,2,"Tämä kuukausi pitää oleman teidän tykönänne ensimäinen kuu; hänestä pitää teidän alkaman ajastajan kuukaudet.","Tämä kuukausi pitää oleman teidän tykönänne ensimäinen kuu; hänestä pitää teidän alkaman ajastajan kuukaudet."],[12,3,"Puhukaat koko Israelin seurakunnalle, sanoen: kymmenentenä päivänä tällä kuulla ottakaan itsekukin itsellensä karitsan, se joka perheen isäntä on, karitsan joka huoneelle;","Puhukaat koko Israelin seurakunnalle, sanoen: kymmenentenä päivänä tällä kuulla ottakaan itsekukin itsellensä karitsan, se joka perheen isäntä on, karitsan joka huoneelle;"],[12,4,"Vaan jos yksi huone vähä on karitsaa syömään, niin ottakaan kylänsä miehen kanssansa, joka likin hänen huonettansa on, että niin monta tulis, kuin voisivat karitsan syödä.","Vaan jos yksi huone vähä on karitsaa syömään, niin ottakaan kylänsä miehen kanssansa, joka likin hänen huonettansa on, että niin monta tulis, kuin voisivat karitsan syödä."],[12,5,"Ja sen karitsan pitää teille oleman virheettömän ajastaikaisen oinaan. Karitsoista eli vohlista pitää teidän sen ottaman.","Ja sen karitsan pitää teille oleman virheettömän ajastaikaisen oinaan. Karitsoista eli vohlista pitää teidän sen ottaman."],[12,6,"Ja sen teidän pitää tallella pitämän neljänteentoistakymmenenteen päivään asti tätä kuuta, ja koko Israelin kansan kokous pitää sen teurastaman kahden ehtoon välillä.","Ja sen teidän pitää tallella pitämän neljänteentoistakymmenenteen päivään asti tätä kuuta, ja koko Israelin kansan kokous pitää sen teurastaman kahden ehtoon välillä."],[12,7,"Ja heidän pitää ottaman verestä, ja sivuman molemmat pihtipielet ja huonetten ovenpäällisen, joissa he sitä syövät.","Ja heidän pitää ottaman verestä, ja sivuman molemmat pihtipielet ja huonetten ovenpäällisen, joissa he sitä syövät."],[12,8,"Ja heidän pitää sinä yönä syömän lihaa tulella paistettua ja happamatointa leipää; katkerain ruohoin kanssa pitää heidän sen syömän.","Ja heidän pitää sinä yönä syömän lihaa tulella paistettua ja happamatointa leipää; katkerain ruohoin kanssa pitää heidän sen syömän."],[12,9,"Ei teidän pidä sitä syömän uutena eikä vedellä keitettynä, mutta tulella paistettuna, pään, jalkain ja sisällysten kanssa.","Ei teidän pidä sitä syömän uutena eikä vedellä keitettynä, mutta tulella paistettuna, pään, jalkain ja sisällysten kanssa."],[12,10,"Eikä teidän pidä jättämän mitään huomeneksi; ja jos jotakin jää huomeneksi, se tulella poltettakaan.","Eikä teidän pidä jättämän mitään huomeneksi; ja jos jotakin jää huomeneksi, se tulella poltettakaan."],[12,11,"Mutta näin pitää teidän syömän sitä: teidän pitää oleman vyötetyt kupeista, ja kengät jalassanne, ja sauva kädessänne, ja pitää sen syömän niinkuin matkaan kiiruhtavaiset: se on Herran pääsiäinen.","Mutta näin pitää teidän syömän sitä: teidän pitää oleman vyötetyt kupeista, ja kengät jalassanne, ja sauva kädessänne, ja pitää sen syömän niinkuin matkaan kiiruhtavaiset: se on Herran pääsiäinen."],[12,12,"Sillä minä käyn sinä yönä Egyptin maan lävitse, ja lyön kaikki esikoiset Egyptin maalla, ihmisistä karjaan asti, ja annan tulla minun rangaistukseni kaikkein Egyptiläisten epäjumalain päälle: Minä Herra.","Sillä minä käyn sinä yönä Egyptin maan lävitse, ja lyön kaikki esikoiset Egyptin maalla, ihmisistä karjaan asti, ja annan tulla minun rangaistukseni kaikkein Egyptiläisten epäjumalain päälle: Minä Herra."],[12,13,"Ja veren pitää oleman teille merkiksi huoneissanne, kussa te olette, että koska minä veren näen, niin minä menen teidän ohitsenne: ja ei pidä teille tuleman se rangaistus kadottamaan teitä, koska minä lyön Egyptin maata.","Ja veren pitää oleman teille merkiksi huoneissanne, kussa te olette, että koska minä veren näen, niin minä menen teidän ohitsenne: ja ei pidä teille tuleman se rangaistus kadottamaan teitä, koska minä lyön Egyptin maata."],[12,14,"Ja tämä päivä pitää oleman teille muistoksi, ja teidän pitää sen pyhittämän juhlaksi Herralle: ijankaikkiseksi säädyksi teidän sukukunnissanne teidän sen pyhittämän pitää.","Ja tämä päivä pitää oleman teille muistoksi, ja teidän pitää sen pyhittämän juhlaksi Herralle: ijankaikkiseksi säädyksi teidän sukukunnissanne teidän sen pyhittämän pitää."],[12,15,"Seitsemän päivää pitää teidän syömän happamatointa leipää, nimittäin ensimäisenä päivänä pitää teidän paneman pois happaman leivän teidän huoneissanne: sillä jokainen kuin hapointa leipää syö ensimäisestä päivästä niin seitsemänteen päivään asti, hänen sielunsa pitää hukutettaman Israelista.","Seitsemän päivää pitää teidän syömän happamatointa leipää, nimittäin ensimäisenä päivänä pitää teidän paneman pois happaman leivän teidän huoneissanne: sillä jokainen kuin hapointa leipää syö ensimäisestä päivästä niin seitsemänteen päivään asti, hänen sielunsa pitää hukutettaman Israelista."],[12,16,"Ensimäisenä päivänä on teillä pyhä kokous, ja myös seitsemäntenä päivänä on teillä pyhä kokous. Ei yhtäkään työtä pidä tehtämän niinä päivinä, mutta vaivoin mitä ruaksi tarvitaan jokaiselle hengelle, se ainoastansa tehkäät.","Ensimäisenä päivänä on teillä pyhä kokous, ja myös seitsemäntenä päivänä on teillä pyhä kokous. Ei yhtäkään työtä pidä tehtämän niinä päivinä, mutta vaivoin mitä ruaksi tarvitaan jokaiselle hengelle, se ainoastansa tehkäät."],[12,17,"Ja pitäkäät happamatoin leipä; sillä sinä päivänä olen minä teidän joukkonne johdattanut Egyptin maalta: ja teidän pitää pitämän tämän päivän teidän sukukunnissanne ijankaikkiseksi säädyksi.","Ja pitäkäät happamatoin leipä; sillä sinä päivänä olen minä teidän joukkonne johdattanut Egyptin maalta: ja teidän pitää pitämän tämän päivän teidän sukukunnissanne ijankaikkiseksi säädyksi."],[12,18,"Neljäntenätoistakymmenentenä päivänä ensimäisestä kuusta ehtoona pitää teidän syödä happamatointa leipää, hamaan ensimäiseen päivään asti kolmattakymmentä siitä kuusta, ehtoona.","Neljäntenätoistakymmenentenä päivänä ensimäisestä kuusta ehtoona pitää teidän syödä happamatointa leipää, hamaan ensimäiseen päivään asti kolmattakymmentä siitä kuusta, ehtoona."],[12,19,"Niin ettei seitsemänä päivänä löydetä hapointa leipää teidän huoneissanne; sillä jokainen joka hapointa leipää syö, hänen sielunsa pitää hukutettaman Israelin joukosta, joko hän muukalainen on eli omainen.","Niin ettei seitsemänä päivänä löydetä hapointa leipää teidän huoneissanne; sillä jokainen joka hapointa leipää syö, hänen sielunsa pitää hukutettaman Israelin joukosta, joko hän muukalainen on eli omainen."],[12,20,"Sentähden älkäät ensinkään syökö hapointa leipää; vaan happamatointa leipää syökäät kaikissa teidän asuinsioissanne.","Sentähden älkäät ensinkään syökö hapointa leipää; vaan happamatointa leipää syökäät kaikissa teidän asuinsioissanne."],[12,21,"Ja Moses kutsui kaikki Israelin vanhimmat, ja sanoi heille: menkäät ja ottakaat teillenne lampaita kukin perhekuntansa jälkeen, ja teurastakaat pääsiäiseksi","Ja Moses kutsui kaikki Israelin vanhimmat, ja sanoi heille: menkäät ja ottakaat teillenne lampaita kukin perhekuntansa jälkeen, ja teurastakaat pääsiäiseksi"],[12,22,"Ja ottakaat side isoppia, ja kastakaat vereen, joka on maljassa, ja sivukaat sillä oven päällinen, ja molemmat pihtipielet: ja ei yksikään ihminen pidä menemän ulos huoneensa ovesta huomeniseen asti.","Ja ottakaat side isoppia, ja kastakaat vereen, joka on maljassa, ja sivukaat sillä oven päällinen, ja molemmat pihtipielet: ja ei yksikään ihminen pidä menemän ulos huoneensa ovesta huomeniseen asti."],[12,23,"Sillä Herra tahtoo käydä ohitse lyömään Egyptiläisiä: ja koska hän saa nähdä veren ovenpäällisessä ja molemmissa pihtipielissä, menee Herra sen oven ohitse, ja ei salli hukuttajan tulla teidän huoneisiinne rankaisemaan.","Sillä Herra tahtoo käydä ohitse lyömään Egyptiläisiä: ja koska hän saa nähdä veren ovenpäällisessä ja molemmissa pihtipielissä, menee Herra sen oven ohitse, ja ei salli hukuttajan tulla teidän huoneisiinne rankaisemaan."],[12,24,"Sentähden pidä tämä sääty sinulle ja sinun lapsilles ijankaikkisesti.","Sentähden pidä tämä sääty sinulle ja sinun lapsilles ijankaikkisesti."],[12,25,"Ja koska te tulette siihen maahan, jonka Herra teille antava on, niinkuin hän sanonut on, niin pitäkäät tämä palvelus.","Ja koska te tulette siihen maahan, jonka Herra teille antava on, niinkuin hän sanonut on, niin pitäkäät tämä palvelus."],[12,26,"Ja koska teidän lapsenne sanovat teille: mikä palvelus tämä teillä on?","Ja koska teidän lapsenne sanovat teille: mikä palvelus tämä teillä on?"],[12,27,"Niin teidän pitää sanoman: tämä on Herran pääsiäisuhri, joka ohitse meni Israelin lasten huoneet Egyptissä, koska hän rankaisi Egyptiläisiä, ja meidän huoneemme vapahti: niin kansa maahan kumartain rukoili.","Niin teidän pitää sanoman: tämä on Herran pääsiäisuhri, joka ohitse meni Israelin lasten huoneet Egyptissä, koska hän rankaisi Egyptiläisiä, ja meidän huoneemme vapahti: niin kansa maahan kumartain rukoili."],[12,28,"Ja Israelin lapset menivät ja tekivät niinkuin Herra Mosekselle ja Aaronille käskenyt oli.","Ja Israelin lapset menivät ja tekivät niinkuin Herra Mosekselle ja Aaronille käskenyt oli."],[12,29,"Ja tapahtui puoliyön aikana, että Herra löi kaikki esikoiset Egyptin maalla, Pharaon esikoisesta, joka hänen istuimellansa istuman piti, niin vangin esikoiseen asti, joka oli vankihuoneessa, ja kaikki eläinten esikoiset.","Ja tapahtui puoliyön aikana, että Herra löi kaikki esikoiset Egyptin maalla, Pharaon esikoisesta, joka hänen istuimellansa istuman piti, niin vangin esikoiseen asti, joka oli vankihuoneessa, ja kaikki eläinten esikoiset."],[12,30,"Sinä yönä nousi Pharao ja kaikki hänen palveliansa, ja kaikki Egyptiläiset, ja suuri parku oli Egyptissä; sillä ei siellä ollut huonetta, jossa ei kuollutta ollut.","Sinä yönä nousi Pharao ja kaikki hänen palveliansa, ja kaikki Egyptiläiset, ja suuri parku oli Egyptissä; sillä ei siellä ollut huonetta, jossa ei kuollutta ollut."],[12,31,"Ja hän kutsui Moseksen ja Aaronin yöllä, ja sanoi: nouskaat ja menkäät pois minun kansastani, sekä te että Israelin lapset: ja menkäät matkaanne ja palvelkaat Herraa, niinkuin te sanoneet olette.","Ja hän kutsui Moseksen ja Aaronin yöllä, ja sanoi: nouskaat ja menkäät pois minun kansastani, sekä te että Israelin lapset: ja menkäät matkaanne ja palvelkaat Herraa, niinkuin te sanoneet olette."],[12,32,"Ottakaat myös myötänne teidän lampaanne ja teidän karjanne, niinkuin te sanoneet olette, menkäät matkaanne; ja siunatkaat myös minua.","Ottakaat myös myötänne teidän lampaanne ja teidän karjanne, niinkuin te sanoneet olette, menkäät matkaanne; ja siunatkaat myös minua."],[12,33,"Ja Egyptiläiset vaativat kansaa, ja hoputtaen ajoivat heitä pois maalta; sillä he sanoivat: me kuolemme jokainen.","Ja Egyptiläiset vaativat kansaa, ja hoputtaen ajoivat heitä pois maalta; sillä he sanoivat: me kuolemme jokainen."],[12,34,"Ja kansa kantoi taikinansa, ennenkuin se happani, nimittäin tähteensä, sidottuna vaatteisiin olallansa.","Ja kansa kantoi taikinansa, ennenkuin se happani, nimittäin tähteensä, sidottuna vaatteisiin olallansa."],[12,35,"Ja Israelin lapset olivat tehneet Moseksen sanan jälkeen, ja olivat anoneet Egyptiläisiltä hopia- ja kultaastioita ja vaatteita.","Ja Israelin lapset olivat tehneet Moseksen sanan jälkeen, ja olivat anoneet Egyptiläisiltä hopia- ja kultaastioita ja vaatteita."],[12,36,"Ja Herra oli antanut kansalle armon Egyptiläisten edessä, että he lainasivat, ja niin he paljastivat Egyptiläiset.","Ja Herra oli antanut kansalle armon Egyptiläisten edessä, että he lainasivat, ja niin he paljastivat Egyptiläiset."],[12,37,"Niin matkustivat Israelin lapset Rameksesta Sukkotiin, lähes kuusisataa tuhatta jalkamiestä, paitsi lapsia.","Niin matkustivat Israelin lapset Rameksesta Sukkotiin, lähes kuusisataa tuhatta jalkamiestä, paitsi lapsia."],[12,38,"Ja paljo kaikkinaista kansaa meni heidän kanssansa, ja lampaita, ja karjaa, ja sangen paljon eläimiä.","Ja paljo kaikkinaista kansaa meni heidän kanssansa, ja lampaita, ja karjaa, ja sangen paljon eläimiä."],[12,39,"Ja he leipoivat siitä uudesta taikinasta, jonka he olivat tuoneet Egyptistä, happamattomia leipiä; sillä ei se ollut hapannut, sentähden että he ajettiin Egyptistä pois, eikä myös saaneet viipyä, ja ei semminkään saaneet heillensä evästä valmistaa.","Ja he leipoivat siitä uudesta taikinasta, jonka he olivat tuoneet Egyptistä, happamattomia leipiä; sillä ei se ollut hapannut, sentähden että he ajettiin Egyptistä pois, eikä myös saaneet viipyä, ja ei semminkään saaneet heillensä evästä valmistaa."],[12,40,"Se aika kuin Israelin lapset asuivat Egyptissä, oli neljäsataa ja kolmekymmentä ajastaikaa.","Se aika kuin Israelin lapset asuivat Egyptissä, oli neljäsataa ja kolmekymmentä ajastaikaa."],[12,41,"Ja koska ne olivat kuluneet, läksi koko Herran joukko yhtenä päivänä Egyptin maalta.","Ja koska ne olivat kuluneet, läksi koko Herran joukko yhtenä päivänä Egyptin maalta."],[12,42,"Sentähden tämä yö pidetään Herralle, että hän vei heidät ulos Egyptin maalta: tämä on se yö, joka pidettämän pitää Herralle kaikilta Israelin lapsilta heidän sukukunnissansa.","Sentähden tämä yö pidetään Herralle, että hän vei heidät ulos Egyptin maalta: tämä on se yö, joka pidettämän pitää Herralle kaikilta Israelin lapsilta heidän sukukunnissansa."],[12,43,"Ja Herra sanoi Mosekselle ja Aaronille: tämä on sääty pitää pääsiäistä: ei yksikään muukalainen pidä siitä syömän.","Ja Herra sanoi Mosekselle ja Aaronille: tämä on sääty pitää pääsiäistä: ei yksikään muukalainen pidä siitä syömän."],[12,44,"Jokainen ostettu orja pitää ympärileikattaman, ja sitten syökään siitä.","Jokainen ostettu orja pitää ympärileikattaman, ja sitten syökään siitä."],[12,45,"Muukalainen ja päivämiehen ei pidä syömän sitä.","Muukalainen ja päivämiehen ei pidä syömän sitä."],[12,46,"Yhdessä huoneessa pitää se syötämän. Ei teidän pidä huoneesta viemän ulos sitä lihaa, eikä teidän pidä luuta rikkoman siitä.","Yhdessä huoneessa pitää se syötämän. Ei teidän pidä huoneesta viemän ulos sitä lihaa, eikä teidän pidä luuta rikkoman siitä."],[12,47,"Koko Israelin seurakunta pitää näin tekemän.","Koko Israelin seurakunta pitää näin tekemän."],[12,48,"Jos joku muukalainen asuu sinun tykönäs, ja tahtoo pitää Herralle pääsiäistä, niin ympärileikattakaan kaikki miehenpuolet, ja sitten käykään sitä tekemään, ja olkaan niinkuin maan omainen; sillä ei yhdenkään ympärileikkaamattoman pidä sitä syömän.","Jos joku muukalainen asuu sinun tykönäs, ja tahtoo pitää Herralle pääsiäistä, niin ympärileikattakaan kaikki miehenpuolet, ja sitten käykään sitä tekemään, ja olkaan niinkuin maan omainen; sillä ei yhdenkään ympärileikkaamattoman pidä sitä syömän."],[12,49,"Yksi sääty pitää oleman omaisella ja muukalaisella, joka asuu teidän seassanne.","Yksi sääty pitää oleman omaisella ja muukalaisella, joka asuu teidän seassanne."],[12,50,"Ja kaikki Israelin lapset tekivät niinkuin Herra oli Mosekselle ja Aaronille käskenyt.","Ja kaikki Israelin lapset tekivät niinkuin Herra oli Mosekselle ja Aaronille käskenyt."],[12,51,"Niin Herra yhtenä päivänä johdatti Israelin lapset ulos Egyptin maalta, heidän joukoissansa.","Niin Herra yhtenä päivänä johdatti Israelin lapset ulos Egyptin maalta, heidän joukoissansa."],[13,1,"Ja Herra puhui Mosekselle ja sanoi:","Ja Herra puhui Mosekselle ja sanoi:"],[13,2,"Pyhitä minulle jokainen esikoinen, kuka ikänänsä äitinsä kohdun avaa Israelin lasten seassa, sekä ihmisistä että eläimistä: ne ovat minun.","Pyhitä minulle jokainen esikoinen, kuka ikänänsä äitinsä kohdun avaa Israelin lasten seassa, sekä ihmisistä että eläimistä: ne ovat minun."],[13,3,"Niin sanoi Moses kansalle: muistakaat tämä päivä, jona te olette lähteneet Egyptistä, orjuuden huoneesta, että Herra on teidät täältä johdattanut väkevällä kädellä. Sentähden ei pidä syötämän hapointa.","Niin sanoi Moses kansalle: muistakaat tämä päivä, jona te olette lähteneet Egyptistä, orjuuden huoneesta, että Herra on teidät täältä johdattanut väkevällä kädellä. Sentähden ei pidä syötämän hapointa."],[13,4,"Tänäpänä olette lähteneet, sillä kuulla Abib.","Tänäpänä olette lähteneet, sillä kuulla Abib."],[13,5,"Ja on tapahtuva, koska Herra sinun tulla antaa Kanaanealaisten, Hetiläisten, Amorilaisten, Heviläisten ja Jebusilaisten maalle, jonka hän sinun isilles on vannonut antaaksensa sinulle: sen maan, jossa rieskaa ja hunajaa vuotaa, niin sinun pitää tämän palveluksen tekemän tällä kuulla:","Ja on tapahtuva, koska Herra sinun tulla antaa Kanaanealaisten, Hetiläisten, Amorilaisten, Heviläisten ja Jebusilaisten maalle, jonka hän sinun isilles on vannonut antaaksensa sinulle: sen maan, jossa rieskaa ja hunajaa vuotaa, niin sinun pitää tämän palveluksen tekemän tällä kuulla:"],[13,6,"Seitsemän päivää pitää sinun syömän happamatointa leipää, ja seitsemäntenä päivänä on Herran juhla.","Seitsemän päivää pitää sinun syömän happamatointa leipää, ja seitsemäntenä päivänä on Herran juhla."],[13,7,"Sentähden pitää seitsemän päivää syötämän happamatointa leipää, ja ei pidä sinun tykönäs yhtään hapointa taikinaa nähtämän; eikä hapointa leipää pidä nähtämän kaikissa sinun maas äärissä.","Sentähden pitää seitsemän päivää syötämän happamatointa leipää, ja ei pidä sinun tykönäs yhtään hapointa taikinaa nähtämän; eikä hapointa leipää pidä nähtämän kaikissa sinun maas äärissä."],[13,8,"Ja sinun pitää ilmoittaman sinun pojalles sinä päivänä, sanoen: (tämän minä pidän) sentähden että Herra teki näin minun kanssani, koska minä läksin Egyptistä.","Ja sinun pitää ilmoittaman sinun pojalles sinä päivänä, sanoen: (tämän minä pidän) sentähden että Herra teki näin minun kanssani, koska minä läksin Egyptistä."],[13,9,"Sentähden pitää tämä oleman sinulle merkiksi sinun kädessäs, ja muistoksi sinun edessäs, että Herran käsky pitää oleman sinun suussas; sillä Herra on väkevällä kädellä sinun johdattanut Egyptistä.","Sentähden pitää tämä oleman sinulle merkiksi sinun kädessäs, ja muistoksi sinun edessäs, että Herran käsky pitää oleman sinun suussas; sillä Herra on väkevällä kädellä sinun johdattanut Egyptistä."],[13,10,"Sentähden pidä tämä sääty ajallansa vuosi vuodelta.","Sentähden pidä tämä sääty ajallansa vuosi vuodelta."],[13,11,"Ja koska Herra on sinun vienyt Kanaanealaisten maalle, niinkuin hän sinulle ja sinun isilles vannonut on, ja antanut sen sinulle,","Ja koska Herra on sinun vienyt Kanaanealaisten maalle, niinkuin hän sinulle ja sinun isilles vannonut on, ja antanut sen sinulle,"],[13,12,"Niin pitää sinun eroittaman Herralle jokaisen kuin avaa äitinsä kohdun, ja jokaisen esikoisen eläinten seassa, kuin sinulla on: kaikki miehenpuoli on Herran.","Niin pitää sinun eroittaman Herralle jokaisen kuin avaa äitinsä kohdun, ja jokaisen esikoisen eläinten seassa, kuin sinulla on: kaikki miehenpuoli on Herran."],[13,13,"Mutta kaikki aasin esikoiset pitää sinun lunastaman karitsalla; jollet sinä lunasta sitä, niin väännä niskat rikki. Mutta jokaisen esikoisen ihmisistä sinun lastes seassa pitää sinun lunastaman.","Mutta kaikki aasin esikoiset pitää sinun lunastaman karitsalla; jollet sinä lunasta sitä, niin väännä niskat rikki. Mutta jokaisen esikoisen ihmisistä sinun lastes seassa pitää sinun lunastaman."],[13,14,"Ja koska sinun poikas kysyy sinulta tästedes: mikä tämä on? pitää sinun sanoman hänelle: Herra on johdattanut meitä väkevällä kädellä Egyptistä, orjuuden huoneesta.","Ja koska sinun poikas kysyy sinulta tästedes: mikä tämä on? pitää sinun sanoman hänelle: Herra on johdattanut meitä väkevällä kädellä Egyptistä, orjuuden huoneesta."],[13,15,"Sillä se tapahtui, koska Pharao kovuutti itsensä ja ei tahtonut meitä päästää, että Herra löi kuoliaaksi jokaisen esikoisen Egyptin maalla, ihmisen esikoisesta niin eläinten esikoiseen asti: sentähden uhraan minä Herralle jokaisen kuin äitinsä kohdun avaa, joka miehenpuoli on, ja jokaisen, esikoisen minun lapsistani lunastan minä.","Sillä se tapahtui, koska Pharao kovuutti itsensä ja ei tahtonut meitä päästää, että Herra löi kuoliaaksi jokaisen esikoisen Egyptin maalla, ihmisen esikoisesta niin eläinten esikoiseen asti: sentähden uhraan minä Herralle jokaisen kuin äitinsä kohdun avaa, joka miehenpuoli on, ja jokaisen, esikoisen minun lapsistani lunastan minä."],[13,16,"Ja tämän pitää oleman merkiksi sinun kädessäs, ja muistoksi sinun edessäs: että Herra on johdattanut meidät väkevällä kädellä Egyptistä.","Ja tämän pitää oleman merkiksi sinun kädessäs, ja muistoksi sinun edessäs: että Herra on johdattanut meidät väkevällä kädellä Egyptistä."],[13,17,"Ja tapahtui, koska Pharao oli päästänyt kansan, niin ei Jumala johdattanut heitä tietä Philistealaisten maan lävitse, joka tärkin oli; sillä Jumala sanoi, ettei kansa joskus katuisi, koska he näkisivät sodan heitänsä vastaan, ja palajaisi Egyptiin.","Ja tapahtui, koska Pharao oli päästänyt kansan, niin ei Jumala johdattanut heitä tietä Philistealaisten maan lävitse, joka tärkin oli; sillä Jumala sanoi, ettei kansa joskus katuisi, koska he näkisivät sodan heitänsä vastaan, ja palajaisi Egyptiin."],[13,18,"Sentähden hän johdatti kansan ympärinsä, korven lävitse Punaista merta kohden. Ja Israelin lapset läksivät viisin joukoin Egyptin maalta.","Sentähden hän johdatti kansan ympärinsä, korven lävitse Punaista merta kohden. Ja Israelin lapset läksivät viisin joukoin Egyptin maalta."],[13,19,"Ja Moses otti myötänsä Josephin luut: sillä hän oli kovasti vannottanut Israelin lapset, sanoen: Jumala on tosin teitä etsivä, niin viekäät minun luuni täältä myötänne.","Ja Moses otti myötänsä Josephin luut: sillä hän oli kovasti vannottanut Israelin lapset, sanoen: Jumala on tosin teitä etsivä, niin viekäät minun luuni täältä myötänne."],[13,20,"Niin he läksivät Sukkotista, ja sioittivat heitänsä Etamiin, joka on korven ääressä.","Niin he läksivät Sukkotista, ja sioittivat heitänsä Etamiin, joka on korven ääressä."],[13,21,"Ja Herra kävi heidän edellänsä päivällä pilven patsaassa, johdattaaksensa heitä tiellä, ja yöllä tulen patsaassa, valistaaksensa heitä vaeltamaan, sekä yöllä että päivällä.","Ja Herra kävi heidän edellänsä päivällä pilven patsaassa, johdattaaksensa heitä tiellä, ja yöllä tulen patsaassa, valistaaksensa heitä vaeltamaan, sekä yöllä että päivällä."],[13,22,"Pilven patsas ei erinnyt päivällä, eikä tulen patsas yöllä kansan edestä.","Pilven patsas ei erinnyt päivällä, eikä tulen patsas yöllä kansan edestä."],[14,1,"Ja Herra puhui Mosekselle sanoen:","Ja Herra puhui Mosekselle sanoen:"],[14,2,"Puhu Israelin lapsille, että he palajaisivat ja sioittaisivat heitänsä Hiirotin laakson kohdalle, Migdolin ja meren vaiheelle, BaalZephonin eteen ja sen kohdalle sioittaen heitänsä meren tykö.","Puhu Israelin lapsille, että he palajaisivat ja sioittaisivat heitänsä Hiirotin laakson kohdalle, Migdolin ja meren vaiheelle, BaalZephonin eteen ja sen kohdalle sioittaen heitänsä meren tykö."],[14,3,"Ja Pharao sanoo Israelin lapsista: he käyvät eksyksissä maalla, korpi on heidät sulkenut.","Ja Pharao sanoo Israelin lapsista: he käyvät eksyksissä maalla, korpi on heidät sulkenut."],[14,4,"Ja minä paadutan Pharaon sydämen, ja hän ajaa heitä takaa; ja minä voitan kunnian Pharaosta ja kaikesta hänen sotaväestänsä. Ja Egyptiläisten pitää tietämän, että minä olen Herra. Ja he tekivät niin.","Ja minä paadutan Pharaon sydämen, ja hän ajaa heitä takaa; ja minä voitan kunnian Pharaosta ja kaikesta hänen sotaväestänsä. Ja Egyptiläisten pitää tietämän, että minä olen Herra. Ja he tekivät niin."],[14,5,"Ja kuin sanottiin Egyptin kuninkaalle, että kansa pakeni, tuli hänen ja hänen palveliainsa sydän käännetyksi kansaa vastaan, ja he sanoivat: miksi me olemme niin tehneet, että me päästimme Israelin palvelemasta meitä?","Ja kuin sanottiin Egyptin kuninkaalle, että kansa pakeni, tuli hänen ja hänen palveliainsa sydän käännetyksi kansaa vastaan, ja he sanoivat: miksi me olemme niin tehneet, että me päästimme Israelin palvelemasta meitä?"],[14,6,"Ja hän valmisti vaununsa, ja otti väkensä myötänsä.","Ja hän valmisti vaununsa, ja otti väkensä myötänsä."],[14,7,"Ja otti kuusisataa parasta vaunua, niin myös kaikki muut Egyptin vaunut, ja päämiehet niiden kaikkein päälle.","Ja otti kuusisataa parasta vaunua, niin myös kaikki muut Egyptin vaunut, ja päämiehet niiden kaikkein päälle."],[14,8,"Ja Herra paadutti Pharaon Egyptin kuninkaan sydämen, ja hän ajoi takaa Israelin lapsia, jotka kuitenkin olivat korkian käden kautta lähteneet.","Ja Herra paadutti Pharaon Egyptin kuninkaan sydämen, ja hän ajoi takaa Israelin lapsia, jotka kuitenkin olivat korkian käden kautta lähteneet."],[14,9,"Niin Egyptiläiset ajoivat heitä takaa, ja saavuttivat heidät meren tykönä, kussa he itsensä sioittaneet olivat, kaikki Pharaon vaunuhevoset, hänen ratsasmiehensä, ja hänen sotajoukkonsa: Hiirotin laaksossa, BaalZephonin kohdalla.","Niin Egyptiläiset ajoivat heitä takaa, ja saavuttivat heidät meren tykönä, kussa he itsensä sioittaneet olivat, kaikki Pharaon vaunuhevoset, hänen ratsasmiehensä, ja hänen sotajoukkonsa: Hiirotin laaksossa, BaalZephonin kohdalla."],[14,10,"Ja kuin Pharao lähestyi heitä, nostivat Israelin lapset silmänsä, ja katso, Egyptiläiset tulivat heidän perässänsä; ja Israelin lapset peljästyivät sangen suuresti, ja huusivat Herran tykö.","Ja kuin Pharao lähestyi heitä, nostivat Israelin lapset silmänsä, ja katso, Egyptiläiset tulivat heidän perässänsä; ja Israelin lapset peljästyivät sangen suuresti, ja huusivat Herran tykö."],[14,11,"Ja sanoivat Mosekselle: Eikö hautoja ollut Egyptissä, ettäs rupesit meitä johdattamaan korpeen kuolemaan? Miksis meille niin olet tehnyt: ettäs meitä johdatit Egyptistä?","Ja sanoivat Mosekselle: Eikö hautoja ollut Egyptissä, ettäs rupesit meitä johdattamaan korpeen kuolemaan? Miksis meille niin olet tehnyt: ettäs meitä johdatit Egyptistä?"],[14,12,"Eikö tämä se ole, kuin me puhuimme Egyptissä, sanoen: anna meidän olla, että me palvelisimme Egyptiläisiä; sillä meidän olis parempi palvella Egyptiläisiä, kuin kuolla korvessa.","Eikö tämä se ole, kuin me puhuimme Egyptissä, sanoen: anna meidän olla, että me palvelisimme Egyptiläisiä; sillä meidän olis parempi palvella Egyptiläisiä, kuin kuolla korvessa."],[14,13,"Moses sanoi kansalle: älkäät peljätkö, seisokaat ja katsokaat minkä autuuden Herra tänäpänä tekee teille; sillä näitä Egyptiläisiä, jotka te tänäpänä näette, ei teidän pidä ikänänsä enempi näkemän ijankaikkisesti,","Moses sanoi kansalle: älkäät peljätkö, seisokaat ja katsokaat minkä autuuden Herra tänäpänä tekee teille; sillä näitä Egyptiläisiä, jotka te tänäpänä näette, ei teidän pidä ikänänsä enempi näkemän ijankaikkisesti,"],[14,14,"Herra sotii teidän puolestanne, ja teidän pitää alallanne oleman.","Herra sotii teidän puolestanne, ja teidän pitää alallanne oleman."],[14,15,"Ja Herra sanoi Mosekselle: mitäs huudat minun tyköni? Sano Israelin lapsille, että he vaeltaisivat.","Ja Herra sanoi Mosekselle: mitäs huudat minun tyköni? Sano Israelin lapsille, että he vaeltaisivat."],[14,16,"Mutta nosta sinä sauvas, ja ojenna kätes meren ylitse, ja eroita se yhdestä, että Israelin lapset kävisivät keskeltä merta kuivaa myöten.","Mutta nosta sinä sauvas, ja ojenna kätes meren ylitse, ja eroita se yhdestä, että Israelin lapset kävisivät keskeltä merta kuivaa myöten."],[14,17,"Ja katso, minä paadutan Egyptiläisten sydämet, ja he seuraavat teidän jälissänne; niin minä voitan kunnian Pharaosta ja kaikesta hänen sotajoukostansa, hänen vaunuistansa ja ratsasmiehistänsä.","Ja katso, minä paadutan Egyptiläisten sydämet, ja he seuraavat teidän jälissänne; niin minä voitan kunnian Pharaosta ja kaikesta hänen sotajoukostansa, hänen vaunuistansa ja ratsasmiehistänsä."],[14,18,"Ja Egyptiläisten pitää tietämän, että minä olen Herra, koska minä olen kunnian voittanut Pharaosta, ja hänen vaunuistansa ja ratsasmiehistänsä.","Ja Egyptiläisten pitää tietämän, että minä olen Herra, koska minä olen kunnian voittanut Pharaosta, ja hänen vaunuistansa ja ratsasmiehistänsä."],[14,19,"Niin Jumalan enkeli nousi, joka Israelin joukon edellä kävi, ja meni heidän takansa: ja pilven patsas siirsi itsensä heidän kasvoinsa edestä, ja seisoi heidän takanansa,","Niin Jumalan enkeli nousi, joka Israelin joukon edellä kävi, ja meni heidän takansa: ja pilven patsas siirsi itsensä heidän kasvoinsa edestä, ja seisoi heidän takanansa,"],[14,20,"Ja tuli Egyptiläisten ja Israelin joukkoin vaiheelle, ja oli pimiä pilvi, ja valaisi (näille) yön: niin ettei he koko yönä toinen toistansa taitaneet lähestyä.","Ja tuli Egyptiläisten ja Israelin joukkoin vaiheelle, ja oli pimiä pilvi, ja valaisi (näille) yön: niin ettei he koko yönä toinen toistansa taitaneet lähestyä."],[14,21,"Koska Moses ojensi kätensä meren ylitse, antoi Herra vedet juosta pois vahvalla itätuulella koko sen yön; ja teki meren kuiville, ja vedet erkanivat.","Koska Moses ojensi kätensä meren ylitse, antoi Herra vedet juosta pois vahvalla itätuulella koko sen yön; ja teki meren kuiville, ja vedet erkanivat."],[14,22,"Ja Israelin lapset kävivät keskeltä merta kuivaa myöten, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa.","Ja Israelin lapset kävivät keskeltä merta kuivaa myöten, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa."],[14,23,"Ja Egyptiläiset ajoivat heitä takaa ja seurasivat heidän perässänsä, ja kaikki Pharaon hevoset, hänen vaununsa ja ratsasmiehensä keskelle merta.","Ja Egyptiläiset ajoivat heitä takaa ja seurasivat heidän perässänsä, ja kaikki Pharaon hevoset, hänen vaununsa ja ratsasmiehensä keskelle merta."],[14,24,"Koska aamuvartio tuli, katsahti Herra Egyptiläisten joukon päälle tulen patsaasta ja pilvestä hukuttaaksensa Egyptiläisten joukon,","Koska aamuvartio tuli, katsahti Herra Egyptiläisten joukon päälle tulen patsaasta ja pilvestä hukuttaaksensa Egyptiläisten joukon,"],[14,25,"Ja hän syöksi pyörät erinänsä heidän vaunuistansa, niin että he työläästi vetivät niitä. Niin sanoivat Egyptiläiset: paetkaamme Israelia, sillä Herra sotii heidän puolestansa Egyptiläisiä vastaan.","Ja hän syöksi pyörät erinänsä heidän vaunuistansa, niin että he työläästi vetivät niitä. Niin sanoivat Egyptiläiset: paetkaamme Israelia, sillä Herra sotii heidän puolestansa Egyptiläisiä vastaan."],[14,26,"Mutta Herra sanoi Mosekselle: ojenna kätes meren ylitse, että vedet juoksisivat Egyptiläisten ylitse, heidän vaunuinsa ja ratsasmiestensä ylitse.","Mutta Herra sanoi Mosekselle: ojenna kätes meren ylitse, että vedet juoksisivat Egyptiläisten ylitse, heidän vaunuinsa ja ratsasmiestensä ylitse."],[14,27,"Niin ojensi Moses kätensä meren ylitse, ja meri palasi ennen huomenta voimaansa. Ja koska Egyptiläiset pakenivat, kohtasi heitä vesi, ja Herra syöksi heidät keskelle merta.","Niin ojensi Moses kätensä meren ylitse, ja meri palasi ennen huomenta voimaansa. Ja koska Egyptiläiset pakenivat, kohtasi heitä vesi, ja Herra syöksi heidät keskelle merta."],[14,28,"Ja vedet palasivat ja kävivät vaunuin, ja ratsasmiesten, ja koko Pharaon sotajoukon ylitse, jotka heitä olivat seuranneet mereen: niin ettei yksikään heistä päässyt.","Ja vedet palasivat ja kävivät vaunuin, ja ratsasmiesten, ja koko Pharaon sotajoukon ylitse, jotka heitä olivat seuranneet mereen: niin ettei yksikään heistä päässyt."],[14,29,"Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa.","Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta, ja vedet olivat heille niinkuin muuri heidän oikialla ja vasemmalla puolellansa."],[14,30,"Ja niin Herra vapahti Israelin sinä päivänä Egyptiläisten kädestä: ja Israel näki Egyptiläiset kuolleina meren reunalla.","Ja niin Herra vapahti Israelin sinä päivänä Egyptiläisten kädestä: ja Israel näki Egyptiläiset kuolleina meren reunalla."],[14,31,"Ja Israel näki myös sen suuren voiman, jonka Herra oli osottanut Egyptiläisten päälle. Ja kansa pelkäsi Herraa, ja he uskoivat Herran ja hänen palveliansa Moseksen.","Ja Israel näki myös sen suuren voiman, jonka Herra oli osottanut Egyptiläisten päälle. Ja kansa pelkäsi Herraa, ja he uskoivat Herran ja hänen palveliansa Moseksen."],[15,1,"Silloin veisasi Moses ja Israelin lapset Herralle tämän virren, ja sanoivat: Minä veisaan Herralle, sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi.","Silloin veisasi Moses ja Israelin lapset Herralle tämän virren, ja sanoivat: Minä veisaan Herralle, sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi."],[15,2,"Herra on minun väkevyyteni ja kiitosvirteni, ja on minun autuuteni. Hän on minun Jumalani, ja minä rakennan hänelle majan, hän on minun Isäni Jumala, ja minä ylistän häntä.","Herra on minun väkevyyteni ja kiitosvirteni, ja on minun autuuteni. Hän on minun Jumalani, ja minä rakennan hänelle majan, hän on minun Isäni Jumala, ja minä ylistän häntä."],[15,3,"Herra on äsken sotamies: Herra on hänen nimensä.","Herra on äsken sotamies: Herra on hänen nimensä."],[15,4,"Pharaon vaunut ja hänen sotaväkensä syöksi hän mereen. Hänen valitut päämiehensä ovat upotetut Punaiseen mereen.","Pharaon vaunut ja hänen sotaväkensä syöksi hän mereen. Hänen valitut päämiehensä ovat upotetut Punaiseen mereen."],[15,5,"Syvyys on heitä peittänyt, ja vajosivat pohjaan, niinkuin kivi.","Syvyys on heitä peittänyt, ja vajosivat pohjaan, niinkuin kivi."],[15,6,"Herra, sinun oikia kätes osotti hänensä voimalliseksi väkevyydessä: Herra, sinun oikia kätes on lyönyt vihollisen.","Herra, sinun oikia kätes osotti hänensä voimalliseksi väkevyydessä: Herra, sinun oikia kätes on lyönyt vihollisen."],[15,7,"Ja sinun suurella kunniallas olet sinä sinun vihollises kukistanut, sillä koska sinä lähetit hirmuisuutes, kulutti se heidät niinkuin korren.","Ja sinun suurella kunniallas olet sinä sinun vihollises kukistanut, sillä koska sinä lähetit hirmuisuutes, kulutti se heidät niinkuin korren."],[15,8,"Ja sinun vihas puhalluksen kautta kokoontuivat vedet; ja virrat seisoivat niinkuin roukkioissa, syvyydet niinkuin hyytyivät keskelle merta.","Ja sinun vihas puhalluksen kautta kokoontuivat vedet; ja virrat seisoivat niinkuin roukkioissa, syvyydet niinkuin hyytyivät keskelle merta."],[15,9,"Vihollinen sanoi: minä ajan takaa ja saavutan heitä, ja saalista jaan, ja heihin minun mieleni jäähdytän: minä vedän ulos miekkani, ja minun käteni pitää heitä hukuttaman.","Vihollinen sanoi: minä ajan takaa ja saavutan heitä, ja saalista jaan, ja heihin minun mieleni jäähdytän: minä vedän ulos miekkani, ja minun käteni pitää heitä hukuttaman."],[15,10,"Silloin sinun tuules puhalsi, ja meri peitti heidät, ja he pohjaan vajosivat, niinkuin lyijy, väkevissä vesissä.","Silloin sinun tuules puhalsi, ja meri peitti heidät, ja he pohjaan vajosivat, niinkuin lyijy, väkevissä vesissä."],[15,11,"Herra, kuka on sinun vertas jumalten seassa? Kuka on sinun kaltaises, joka olet niin korkia ja pyhä, hirmullinen, kiitettävä ja ihmetten tekiä?","Herra, kuka on sinun vertas jumalten seassa? Kuka on sinun kaltaises, joka olet niin korkia ja pyhä, hirmullinen, kiitettävä ja ihmetten tekiä?"],[15,12,"Koskas oikian kätes ojensit, niin maa heidät nieli.","Koskas oikian kätes ojensit, niin maa heidät nieli."],[15,13,"Sinä olet johdattanut laupiudessas tämän kansan, jonkas pelastit, ja olet vienyt heidän väkevyydessäs sinun pyhään asumisees.","Sinä olet johdattanut laupiudessas tämän kansan, jonkas pelastit, ja olet vienyt heidän väkevyydessäs sinun pyhään asumisees."],[15,14,"Koska kansat sen kuulevat, vapisevat he: ahdistus käsittää Philistealaiset.","Koska kansat sen kuulevat, vapisevat he: ahdistus käsittää Philistealaiset."],[15,15,"Silloin hämmästyvät Edomin ruhtinaat, ja vapistus tarttuu Moabin sankareihin: kaikki kanaanin maan asuvaiset raukeavat.","Silloin hämmästyvät Edomin ruhtinaat, ja vapistus tarttuu Moabin sankareihin: kaikki kanaanin maan asuvaiset raukeavat."],[15,16,"Tulkoon hämmästys heidän päällensä, ja pelko sinun väkevän käsivartes kautta, he vaijetkoon niinkuin kivi, siihenasti että sinun kansas, Herra, lävitse käy, jonka sinä saanut olet.","Tulkoon hämmästys heidän päällensä, ja pelko sinun väkevän käsivartes kautta, he vaijetkoon niinkuin kivi, siihenasti että sinun kansas, Herra, lävitse käy, jonka sinä saanut olet."],[15,17,"Johdata heitä ja istuta heitä sinun perimises vuorelle, jonka sinä Herra asumisekses tehnyt olet: sinun pyhyytes tykö, Herra, jonka sinun kätes vahvistaneet ovat.","Johdata heitä ja istuta heitä sinun perimises vuorelle, jonka sinä Herra asumisekses tehnyt olet: sinun pyhyytes tykö, Herra, jonka sinun kätes vahvistaneet ovat."],[15,18,"Herra hallitsee alati ja ijankaikkisesti.","Herra hallitsee alati ja ijankaikkisesti."],[15,19,"Sillä Pharaon hevoset menivät mereen, vaunuinensa ja ratsasmiehinensä, ja Herra palautti meren vedet heidän päällensä. Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta.","Sillä Pharaon hevoset menivät mereen, vaunuinensa ja ratsasmiehinensä, ja Herra palautti meren vedet heidän päällensä. Mutta Israelin lapset kävivät kuivaa myöten keskeltä merta."],[15,20,"Ja MirJam prophetissa, Aaronin sisar, otti kanteleen käteensä, ja kaikki vaimot seurasivat häntä kanteleilla ja hypyllä.","Ja MirJam prophetissa, Aaronin sisar, otti kanteleen käteensä, ja kaikki vaimot seurasivat häntä kanteleilla ja hypyllä."],[15,21,"Ja MirJam vastasi heitä: Veisatkaat Herralle: sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi.","Ja MirJam vastasi heitä: Veisatkaat Herralle: sillä hän on sangen jalon työn tehnyt, hevosen ja miehen hän mereen syöksi."],[15,22,"Niin Moses antoi Israelin lasten vaeltaa Punaisen meren tyköä, ja he menivät Suurin korpeen: ja matkustivat kolme päivää korvessa, ja ei löytäneet vettä.","Niin Moses antoi Israelin lasten vaeltaa Punaisen meren tyköä, ja he menivät Suurin korpeen: ja matkustivat kolme päivää korvessa, ja ei löytäneet vettä."],[15,23,"Niin he tulivat Maraan, vaan eivät saaneet juoda sitä vettä Marassa, sillä se oli ylen karvas; josta se paikka kutsutaan Mara.","Niin he tulivat Maraan, vaan eivät saaneet juoda sitä vettä Marassa, sillä se oli ylen karvas; josta se paikka kutsutaan Mara."],[15,24,"Siinä napisi kansa Mosesta vastaan, sanoen: mitä me juomme?","Siinä napisi kansa Mosesta vastaan, sanoen: mitä me juomme?"],[15,25,"Mutta hän huusi Herran tykö, ja Herra osotti hänelle puun, jonka hän heitti veteen, ja vedet tulivat makiaksi. Siinä pani hän heidän eteensä käskyn ja oikeuden, ja kiusasi siinä heitä.","Mutta hän huusi Herran tykö, ja Herra osotti hänelle puun, jonka hän heitti veteen, ja vedet tulivat makiaksi. Siinä pani hän heidän eteensä käskyn ja oikeuden, ja kiusasi siinä heitä."],[15,26,"Ja sanoi: jos sinä kuulet sinun Herras Jumalas äänen, ja teet mikä oikeus on hänen edessänsä, ja panet hänen käskynsä sinun korviis, ja pidät kaikki hänen säätynsä: niin en minä pane sinun päälles yhtäkään vitsausta niistä, jotka minä Egyptiläisten päälle pannut olen; sillä minä olen Herra sinun parantajas.","Ja sanoi: jos sinä kuulet sinun Herras Jumalas äänen, ja teet mikä oikeus on hänen edessänsä, ja panet hänen käskynsä sinun korviis, ja pidät kaikki hänen säätynsä: niin en minä pane sinun päälles yhtäkään vitsausta niistä, jotka minä Egyptiläisten päälle pannut olen; sillä minä olen Herra sinun parantajas."],[15,27,"Ja he tulivat Elimiin, siellä on kaksitoistakymmentä lähdettä, ja seitsemänkymmentä palmupuuta: siellä he sioittivat itsensä vetten tykö.","Ja he tulivat Elimiin, siellä on kaksitoistakymmentä lähdettä, ja seitsemänkymmentä palmupuuta: siellä he sioittivat itsensä vetten tykö."],[16,1,"Niin he matkustivat Elimistä, ja koko Israelin lasten joukko tuli Sinnin korpeen, joka on Elimin ja Sinain välillä: viidentenätoistakymmenentenä päivänä toisella kuulla sittenkuin he Egyptin maalta lähteneet olivat.","Niin he matkustivat Elimistä, ja koko Israelin lasten joukko tuli Sinnin korpeen, joka on Elimin ja Sinain välillä: viidentenätoistakymmenentenä päivänä toisella kuulla sittenkuin he Egyptin maalta lähteneet olivat."],[16,2,"Ja koko Israelin lasten joukko napisi Mosesta ja Aaronia vastaan korvessa.","Ja koko Israelin lasten joukko napisi Mosesta ja Aaronia vastaan korvessa."],[16,3,"Ja Israelin lapset sanoivat heille: joska me olisimme Egyptin maalla Herran käden kautta kuolleet, koska me istuimme lihapatain tykönä, ja oli leipää yltäkyllä syödä; sillä te olette sentähden meidän johdattaneet tähän korpeen kuolettaaksenne näljällä kaikkea tätä joukkoa.","Ja Israelin lapset sanoivat heille: joska me olisimme Egyptin maalla Herran käden kautta kuolleet, koska me istuimme lihapatain tykönä, ja oli leipää yltäkyllä syödä; sillä te olette sentähden meidän johdattaneet tähän korpeen kuolettaaksenne näljällä kaikkea tätä joukkoa."],[16,4,"Niin sanoi Herra Mosekselle: katso, minä annan sataa teille leipää taivaasta: ja kansan pitää menemän ulos ja kokooman joka päivä niin paljo kuin he tarvitsevat, koetellakseni heitä, jos he vaeltavat minun käskyssäni elikkä ei.","Niin sanoi Herra Mosekselle: katso, minä annan sataa teille leipää taivaasta: ja kansan pitää menemän ulos ja kokooman joka päivä niin paljo kuin he tarvitsevat, koetellakseni heitä, jos he vaeltavat minun käskyssäni elikkä ei."],[16,5,"Ja pitää tapahtuman, että he kuudentena päivänä valmistavat sen kuin he tuovat (kotia) ja kaksikertaisesti sen suhteen, minkä he muutoin joka päivä kokoovat.","Ja pitää tapahtuman, että he kuudentena päivänä valmistavat sen kuin he tuovat (kotia) ja kaksikertaisesti sen suhteen, minkä he muutoin joka päivä kokoovat."],[16,6,"Moses ja Aaron sanoivat kaikille Israelin lapsille: ehtoona pitää teidän tietämän Herran johdattaneen teidät Egyptin maalta.","Moses ja Aaron sanoivat kaikille Israelin lapsille: ehtoona pitää teidän tietämän Herran johdattaneen teidät Egyptin maalta."],[16,7,"Ja huomenna pitää teidän näkemän Herran kunnian; sillä hän on kuullut teidän napistuksenne Herraa vastaan. Ja mitkä me olemme, että te napisette meitä vastaan?","Ja huomenna pitää teidän näkemän Herran kunnian; sillä hän on kuullut teidän napistuksenne Herraa vastaan. Ja mitkä me olemme, että te napisette meitä vastaan?"],[16,8,"Vielä sanoi Moses: Herra antaa teille ehtoona lihaa syödäksenne, ja huomenna leipää teidän ravinnoksenne, että Herra on kuullut teidän napistuksenne, jolla te olette napisseet häntä vastaan. Sillä mitkä me olemme? Teidän napistuksenne ei ole meitä, vaan Herraa vastaan.","Vielä sanoi Moses: Herra antaa teille ehtoona lihaa syödäksenne, ja huomenna leipää teidän ravinnoksenne, että Herra on kuullut teidän napistuksenne, jolla te olette napisseet häntä vastaan. Sillä mitkä me olemme? Teidän napistuksenne ei ole meitä, vaan Herraa vastaan."],[16,9,"Ja Moses sanoi Aaronille: sano koko Israelin lasten joukolle: tulkaat Herran eteen, sillä hän on kuullut teidän napistuksenne.","Ja Moses sanoi Aaronille: sano koko Israelin lasten joukolle: tulkaat Herran eteen, sillä hän on kuullut teidän napistuksenne."],[16,10,"Ja tapahtui, kun Aaron näitä puhunut oli kaikelle Israelin lasten joukolle, käänsivät he itsensä korpeen päin, ja katso, Herran kunnia näkyi pilvessä.","Ja tapahtui, kun Aaron näitä puhunut oli kaikelle Israelin lasten joukolle, käänsivät he itsensä korpeen päin, ja katso, Herran kunnia näkyi pilvessä."],[16,11,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[16,12,"Minä olen kuullut Israelin lasten napistuksen, puhu heille sanoen: kahden ehtoon välillä pitää teillä oleman lihaa syödäksenne, ja aamulla pitää teidän ravituksi tuleman leivästä: ja teidän pitää tietämän, että minä olen Herra teidän Jumalanne.","Minä olen kuullut Israelin lasten napistuksen, puhu heille sanoen: kahden ehtoon välillä pitää teillä oleman lihaa syödäksenne, ja aamulla pitää teidän ravituksi tuleman leivästä: ja teidän pitää tietämän, että minä olen Herra teidän Jumalanne."],[16,13,"Ja tapahtui ehtoona, että peltokanat tulivat ja peittivät leirin, ja aamulla oli kaste leirin ympärinsä.","Ja tapahtui ehtoona, että peltokanat tulivat ja peittivät leirin, ja aamulla oli kaste leirin ympärinsä."],[16,14,"Ja kuin kaste nousi, katso, niin oli korvessa jotakin ymmyrjäistä ja pientä, niin kuin härmää maan päällä.","Ja kuin kaste nousi, katso, niin oli korvessa jotakin ymmyrjäistä ja pientä, niin kuin härmää maan päällä."],[16,15,"Ja kuin Israelin lapset sen näkivät, sanoivat he toinen toisellensa: Man tämä on; sillä he ei tietäneet mitä se oli. Mutta Moses sanoi heille: tämä on se leipä, jonka Herra teille on antanut syödäksenne.","Ja kuin Israelin lapset sen näkivät, sanoivat he toinen toisellensa: Man tämä on; sillä he ei tietäneet mitä se oli. Mutta Moses sanoi heille: tämä on se leipä, jonka Herra teille on antanut syödäksenne."],[16,16,"Tämä on se, josta Herra käskenyt on. Jokainen kootkaan sitä niin paljo kuin hän itse syö, ja ottakaan gomor joka pääluvulle, henkiluvun jälkeen joka on hänen majassansa.","Tämä on se, josta Herra käskenyt on. Jokainen kootkaan sitä niin paljo kuin hän itse syö, ja ottakaan gomor joka pääluvulle, henkiluvun jälkeen joka on hänen majassansa."],[16,17,"Ja Israelin lapset tekivät niin, ja kokosivat muutamat enemmän ja muutamat vähemmän.","Ja Israelin lapset tekivät niin, ja kokosivat muutamat enemmän ja muutamat vähemmän."],[16,18,"Ja kuin he mittasivat sen gomorilla, niin ei sillä mitään liiaksi ollut, joka paljo koonnut oli, eikä siltä mitään puuttunut, joka vähemmän kokosi, mutta jokainen oli koonnut niin paljo kuin he syödäksensä tarvitsivat.","Ja kuin he mittasivat sen gomorilla, niin ei sillä mitään liiaksi ollut, joka paljo koonnut oli, eikä siltä mitään puuttunut, joka vähemmän kokosi, mutta jokainen oli koonnut niin paljo kuin he syödäksensä tarvitsivat."],[16,19,"Ja Moses sanoi heille: ei kenenkään pidä siitä huomeneksi mitään jättämän.","Ja Moses sanoi heille: ei kenenkään pidä siitä huomeneksi mitään jättämän."],[16,20,"Mutta ei he kuulleet Mosesta, monikahdat jättivät siitä jotakin huomeneksi. Niin madot kasvoivat siihen, ja tuli haisemaan. Ja Moses vihastui heidän päällensä.","Mutta ei he kuulleet Mosesta, monikahdat jättivät siitä jotakin huomeneksi. Niin madot kasvoivat siihen, ja tuli haisemaan. Ja Moses vihastui heidän päällensä."],[16,21,"Niin he kokosivat siitä joka aamu, niin paljon kuin jokainen syödäksensä tarvitsi. Mutta koska päivä tuli palavaksi, niin se suli.","Niin he kokosivat siitä joka aamu, niin paljon kuin jokainen syödäksensä tarvitsi. Mutta koska päivä tuli palavaksi, niin se suli."],[16,22,"Ja tapahtui kuudentena päivänä, että he kokosivat kaksikertaisesti sitä leipää, kaksi gomoria kullekin. Ja kaikki päämiehet kansan seasta tulivat ja ilmoittivat sen Mosekselle.","Ja tapahtui kuudentena päivänä, että he kokosivat kaksikertaisesti sitä leipää, kaksi gomoria kullekin. Ja kaikki päämiehet kansan seasta tulivat ja ilmoittivat sen Mosekselle."],[16,23,"Ja hän sanoi heille: tämä on se minkä Herra sanonut on: huomenna on sabbati, pyhä lepo Herralle: mitä te leivotte, se leipokaat, ja mitä te keitätte, se keittäkäät; mutta mitä liiaksi on, jättäkäät se tähteelle pantaa huomeneksi.","Ja hän sanoi heille: tämä on se minkä Herra sanonut on: huomenna on sabbati, pyhä lepo Herralle: mitä te leivotte, se leipokaat, ja mitä te keitätte, se keittäkäät; mutta mitä liiaksi on, jättäkäät se tähteelle pantaa huomeneksi."],[16,24,"Ja he jättivät sitä huomeneksi, niinkuin Moses käskenyt oli: ja ei tullut se haisemaan, eikä matoa tullut siihen.","Ja he jättivät sitä huomeneksi, niinkuin Moses käskenyt oli: ja ei tullut se haisemaan, eikä matoa tullut siihen."],[16,25,"Niin sanoi Moses: syökäät se tänäpänä, sillä tätäpänä on Herran sabbati: tänäpänä ette sitä löydä kedolta.","Niin sanoi Moses: syökäät se tänäpänä, sillä tätäpänä on Herran sabbati: tänäpänä ette sitä löydä kedolta."],[16,26,"Kuusi päivää pitää teidän kokooman; mutta seitsemäntenä päivänä on sabbati, ja ei löydetä sitä.","Kuusi päivää pitää teidän kokooman; mutta seitsemäntenä päivänä on sabbati, ja ei löydetä sitä."],[16,27,"Ja tapahtui, että seitsemäntenä päivänä läksivät muutamat kansan seasta kokoomaan, ja ei he löytäneet mitään.","Ja tapahtui, että seitsemäntenä päivänä läksivät muutamat kansan seasta kokoomaan, ja ei he löytäneet mitään."],[16,28,"Niin Herra sanoi Mosekselle: kuinka kauvan ette tahdo pitää minun käskyjäni ja lakiani?","Niin Herra sanoi Mosekselle: kuinka kauvan ette tahdo pitää minun käskyjäni ja lakiani?"],[16,29,"Katsokaat, Herra on teille antanut sabbatin, ja sen tähden on hän antanut teille kuudentena päivänä kahden päivän leivän: niin olkaan siis jokainen kotonansa, ja älkään yksikään lähtekö siastansa seitsemäntenä päivänä.","Katsokaat, Herra on teille antanut sabbatin, ja sen tähden on hän antanut teille kuudentena päivänä kahden päivän leivän: niin olkaan siis jokainen kotonansa, ja älkään yksikään lähtekö siastansa seitsemäntenä päivänä."],[16,30,"Niin lepäsi kansa seitsemäntenä päivänä.","Niin lepäsi kansa seitsemäntenä päivänä."],[16,31,"Ja Israelin huone kutsui hänen nimensä man: ja se oli niinkuin korianderin siemen, valkia, ja maisti niinkuin sämpylä hunajan kanssa.","Ja Israelin huone kutsui hänen nimensä man: ja se oli niinkuin korianderin siemen, valkia, ja maisti niinkuin sämpylä hunajan kanssa."],[16,32,"Ja Moses sanoi: tämä on se minkä Herra käskenyt on: täytä gomor siitä, kätkettää teidän jälkeentulevaisillenne: että he näkisivät sen leivän, jolla minä olen teitä ruokkinut korvessa, koska minä johdatin teitä ulos Egyptin maalta.","Ja Moses sanoi: tämä on se minkä Herra käskenyt on: täytä gomor siitä, kätkettää teidän jälkeentulevaisillenne: että he näkisivät sen leivän, jolla minä olen teitä ruokkinut korvessa, koska minä johdatin teitä ulos Egyptin maalta."],[16,33,"Ja Moses sanoi Aaronille: ota astia, ja pane siihen gomorin täysi mannaa: ja pane se Herran eteen, tallella pidettää teidän jälkeen tulevaisillenne.","Ja Moses sanoi Aaronille: ota astia, ja pane siihen gomorin täysi mannaa: ja pane se Herran eteen, tallella pidettää teidän jälkeen tulevaisillenne."],[16,34,"Niinkuin Herra käskenyt oli Mosekselle, niin Aaron pani sen todistuksen eteen tallella pidettäväksi.","Niinkuin Herra käskenyt oli Mosekselle, niin Aaron pani sen todistuksen eteen tallella pidettäväksi."],[16,35,"Ja Israelin lapset söivät mannaa neljäkymmentä ajastaikaa, siihenasti kuin he tulivat sille maalle jossa heidän asuman piti: siihenasti kuin he tulivat Kanaanin maan rajoille, söivät he mannaa.","Ja Israelin lapset söivät mannaa neljäkymmentä ajastaikaa, siihenasti kuin he tulivat sille maalle jossa heidän asuman piti: siihenasti kuin he tulivat Kanaanin maan rajoille, söivät he mannaa."],[16,36,"Ja gomor on kymmenes osa ephaa.","Ja gomor on kymmenes osa ephaa."],[17,1,"Ja koko Israelin lasten joukko matkusti Sinnin korvesta, vaelluksissansa Herran käskyn jälkeen, ja sioittivat itsensä Raphidimiin, ja ei ollut vettä kansalle juoda.","Ja koko Israelin lasten joukko matkusti Sinnin korvesta, vaelluksissansa Herran käskyn jälkeen, ja sioittivat itsensä Raphidimiin, ja ei ollut vettä kansalle juoda."],[17,2,"Ja kansa riiteli Moseksen kanssa, ja sanoi: antakaat meille vettä juodaksemme. Moses sanoi heille: mitä te riitelette minun kanssani? Miksi kiusaatte Herraa?","Ja kansa riiteli Moseksen kanssa, ja sanoi: antakaat meille vettä juodaksemme. Moses sanoi heille: mitä te riitelette minun kanssani? Miksi kiusaatte Herraa?"],[17,3,"Ja kansa janosi juoda siellä vettä, ja he napisivat Mosesta vastaan, ja sanoivat: mitä vasten sinä olet meidät johdattanut Egyptistä tänne kuolettaakses minua ja minun lapsiani, ja minun eläimiäni janolla?","Ja kansa janosi juoda siellä vettä, ja he napisivat Mosesta vastaan, ja sanoivat: mitä vasten sinä olet meidät johdattanut Egyptistä tänne kuolettaakses minua ja minun lapsiani, ja minun eläimiäni janolla?"],[17,4,"Niin Moses huusi Herran tykö, sanoen: mitä minä teen tälle kansalle? Vähä puuttuu, ettei he kivitä minua.","Niin Moses huusi Herran tykö, sanoen: mitä minä teen tälle kansalle? Vähä puuttuu, ettei he kivitä minua."],[17,5,"Ja Herra sanoi Mosekselle: mene kansan edellä, ja ota kanssas muutamia Israelin vanhimmista, ja sinun sauvas, jolla sinä löit virtaa, ota sinun kätees ja mene.","Ja Herra sanoi Mosekselle: mene kansan edellä, ja ota kanssas muutamia Israelin vanhimmista, ja sinun sauvas, jolla sinä löit virtaa, ota sinun kätees ja mene."],[17,6,"Katso, minä seison siellä sinun edessäs kalliolla Horebissa: ja sinun pitää lyömän kalliota, ja siinä pitää vedet juokseman, niin että kansa siitä juoda saa. Ja Moses teki niin Israelin vanhimpain edessä.","Katso, minä seison siellä sinun edessäs kalliolla Horebissa: ja sinun pitää lyömän kalliota, ja siinä pitää vedet juokseman, niin että kansa siitä juoda saa. Ja Moses teki niin Israelin vanhimpain edessä."],[17,7,"Ja kutsui sen paikan nimen Massa ja Meriba, Israelin lasten riidan tähden, ja että he kiusasivat Herraa, sanoen: olleeko Herra meidän seassamme elikkä ei?","Ja kutsui sen paikan nimen Massa ja Meriba, Israelin lasten riidan tähden, ja että he kiusasivat Herraa, sanoen: olleeko Herra meidän seassamme elikkä ei?"],[17,8,"Niin Amalek tuli: ja soti Israelia vastaan Raphidimissa.","Niin Amalek tuli: ja soti Israelia vastaan Raphidimissa."],[17,9,"Ja Moses sanoi Josualle: valitse meille miehiä, mene ja sodi Amalekia vastaan: huomenna minä seison mäen kukkulalla, ja pidän Jumalan sauvan kädessäni.","Ja Moses sanoi Josualle: valitse meille miehiä, mene ja sodi Amalekia vastaan: huomenna minä seison mäen kukkulalla, ja pidän Jumalan sauvan kädessäni."],[17,10,"Ja Josua teki niinkuin Moses sanoi hänelle, ja soti Amalekia vastaan. Mutta Moses, Aaron ja Hur astuivat mäen kukkulalle.","Ja Josua teki niinkuin Moses sanoi hänelle, ja soti Amalekia vastaan. Mutta Moses, Aaron ja Hur astuivat mäen kukkulalle."],[17,11,"Ja tapahtui, että koska Moses piti kätensä ylhäällä, voitti Israel; mutta koska hän kätensä laski alas, voitti Amalek.","Ja tapahtui, että koska Moses piti kätensä ylhäällä, voitti Israel; mutta koska hän kätensä laski alas, voitti Amalek."],[17,12,"Mutta Moseksen kädet olivat raskaat, sentähden ottivat he kiven ja asettivat hänen alansa ja hän istui sen päällä; vaan Aaron ja Hur pitivät ylhäällä hänen käsiinsä kumpikin puoleltansa, niin pysyi hänen kätensä juuri vahvana auringon laskemaan asti.","Mutta Moseksen kädet olivat raskaat, sentähden ottivat he kiven ja asettivat hänen alansa ja hän istui sen päällä; vaan Aaron ja Hur pitivät ylhäällä hänen käsiinsä kumpikin puoleltansa, niin pysyi hänen kätensä juuri vahvana auringon laskemaan asti."],[17,13,"Ja Josua heikonsi Amalekin ja hänen kansansa miekan terällä.","Ja Josua heikonsi Amalekin ja hänen kansansa miekan terällä."],[17,14,"Ja Herra sanoi Mosekselle: kirjoita tämä muistoksi kirjaan, ja muistuta Josuan korvissa; sillä minä pyyhin kokonansa pois Amalekin muiston taivaan alta.","Ja Herra sanoi Mosekselle: kirjoita tämä muistoksi kirjaan, ja muistuta Josuan korvissa; sillä minä pyyhin kokonansa pois Amalekin muiston taivaan alta."],[17,15,"Ja Moses rakensi alttarin, ja kutsui sen nimen: Herra on minun lippuni.","Ja Moses rakensi alttarin, ja kutsui sen nimen: Herra on minun lippuni."],[17,16,"Ja hän sanoi: koska käsi oli Herran istuinta päin, oli Herralla sota Amalekia vastaan: (niin se on tästäkin lähin) suvusta sukuun.","Ja hän sanoi: koska käsi oli Herran istuinta päin, oli Herralla sota Amalekia vastaan: (niin se on tästäkin lähin) suvusta sukuun."],[18,1,"Ja Jetro Midianin pappi, Moseksen appi kuuli kaikki, mitä Jumala Mosekselle ja Israelin kansalle oli tehnyt: että Herra oli johdattanut Israelin pois Egyptistä.","Ja Jetro Midianin pappi, Moseksen appi kuuli kaikki, mitä Jumala Mosekselle ja Israelin kansalle oli tehnyt: että Herra oli johdattanut Israelin pois Egyptistä."],[18,2,"Ja Jetro Moseksen appi otti Ziporan Moseksen emännän, jonka hän oli takaperin lähettänyt,","Ja Jetro Moseksen appi otti Ziporan Moseksen emännän, jonka hän oli takaperin lähettänyt,"],[18,3,"Ja kaksi hänen poikaansa, joista yhden nimi oli Gersom, sillä hän sanoi: minä olin muukalainen vieraalla maalla.","Ja kaksi hänen poikaansa, joista yhden nimi oli Gersom, sillä hän sanoi: minä olin muukalainen vieraalla maalla."],[18,4,"Ja toisen nimi oli Elieser, sillä (hän sanoi) minun isäni Jumala on ollut minun apuni, ja on pelastanut minun Pharaon miekasta.","Ja toisen nimi oli Elieser, sillä (hän sanoi) minun isäni Jumala on ollut minun apuni, ja on pelastanut minun Pharaon miekasta."],[18,5,"Niin Jetro Moseksen appi, ja hänen poikansa, ja hänen emäntänsä tulivat Moseksen tykö siihen korpeen, kussa hän itsensä sioittanut oli Jumalan vuorella.","Niin Jetro Moseksen appi, ja hänen poikansa, ja hänen emäntänsä tulivat Moseksen tykö siihen korpeen, kussa hän itsensä sioittanut oli Jumalan vuorella."],[18,6,"Ja antoi sanoa Mosekselle: minä Jetro sinun appes olen tullut sinun tykös, ja sinun emäntäs, ja molemmat hänen poikansa hänen kanssansa.","Ja antoi sanoa Mosekselle: minä Jetro sinun appes olen tullut sinun tykös, ja sinun emäntäs, ja molemmat hänen poikansa hänen kanssansa."],[18,7,"Niin meni Moses appeansa vastaan, kumarsi itsensä, ja suuta antoi hänen; ja koska he olivat tervehtineet toinen toistansa, menivät he majaan.","Niin meni Moses appeansa vastaan, kumarsi itsensä, ja suuta antoi hänen; ja koska he olivat tervehtineet toinen toistansa, menivät he majaan."],[18,8,"Niin jutteli Moses apellensa kaikki, mitä Herra tehnyt oli Pharaolle, ja Egyptiläisille Israelin tähden, ja kaiken sen vaivan joka heillä tiellä oli ollut, ja että Herra oli auttanut heitä.","Niin jutteli Moses apellensa kaikki, mitä Herra tehnyt oli Pharaolle, ja Egyptiläisille Israelin tähden, ja kaiken sen vaivan joka heillä tiellä oli ollut, ja että Herra oli auttanut heitä."],[18,9,"Ja Jetro riemuitsi kaiken sen hyvyyden ylitse, jonka Herra oli tehnyt Israelille, että hän oli pelastanut heitä Egyptiläisten kädestä.","Ja Jetro riemuitsi kaiken sen hyvyyden ylitse, jonka Herra oli tehnyt Israelille, että hän oli pelastanut heitä Egyptiläisten kädestä."],[18,10,"Ja Jetro sanoi: kiitetty olkoon Herra, joka teidät pelastanut on Egyptiläisten ja Pharaon kädestä: joka on vapahtanut kansansa Egyptiläisten käden alta.","Ja Jetro sanoi: kiitetty olkoon Herra, joka teidät pelastanut on Egyptiläisten ja Pharaon kädestä: joka on vapahtanut kansansa Egyptiläisten käden alta."],[18,11,"Nyt minä tiedän, että Herra on suurempi kuin kaikki Jumalat; sillä siinä asiassa, jossa ylpeilivät, oli hän heidän ylitsensä (valtias).","Nyt minä tiedän, että Herra on suurempi kuin kaikki Jumalat; sillä siinä asiassa, jossa ylpeilivät, oli hän heidän ylitsensä (valtias)."],[18,12,"Ja Jetro Moseksen appi otti polttouhria ja muuta uhria Jumalalle. Niin tuli Aaron ja kaikki vanhimmat Israelista syömään leipää Moseksen apen kanssa Jumalan edessä.","Ja Jetro Moseksen appi otti polttouhria ja muuta uhria Jumalalle. Niin tuli Aaron ja kaikki vanhimmat Israelista syömään leipää Moseksen apen kanssa Jumalan edessä."],[18,13,"Ja tapahtui toisena päivänä, että Moses istui oikeutta tekemään kansalle; ja kansa seisoi Moseksen ympärillä aamusta niin ehtooseen asti.","Ja tapahtui toisena päivänä, että Moses istui oikeutta tekemään kansalle; ja kansa seisoi Moseksen ympärillä aamusta niin ehtooseen asti."],[18,14,"Koska Moseksen appi näki kaikki, mitä hän teki kansalle, sanoi hän: mikä tämä on kuin sinä teet kansalle? Miksis sinä istut yksinäs, ja kaikki kansa seisoo sinun edessäs, hamasta aamusta niin ehtooseen?","Koska Moseksen appi näki kaikki, mitä hän teki kansalle, sanoi hän: mikä tämä on kuin sinä teet kansalle? Miksis sinä istut yksinäs, ja kaikki kansa seisoo sinun edessäs, hamasta aamusta niin ehtooseen?"],[18,15,"Moses vastasi appeansa: sillä kansa tulee minun tyköni, ja kysyy Jumalalta neuvoa.","Moses vastasi appeansa: sillä kansa tulee minun tyköni, ja kysyy Jumalalta neuvoa."],[18,16,"Koska heillä on jotakin asiaa, tulevat he minun tyköni, että minun pitää oikeutta tekemän jokaisen välillä ja hänen lähimmäisensä välillä, ja osottaman heille Jumalan oikeudet ja käskyt.","Koska heillä on jotakin asiaa, tulevat he minun tyköni, että minun pitää oikeutta tekemän jokaisen välillä ja hänen lähimmäisensä välillä, ja osottaman heille Jumalan oikeudet ja käskyt."],[18,17,"Ja Moseksen appi sanoi hänelle: ei se ole hyvä kuin sinä teet.","Ja Moseksen appi sanoi hänelle: ei se ole hyvä kuin sinä teet."],[18,18,"Sinä väsytät peräti sekä itses että tämän kansan joka sinun kanssas on; sillä tämä asia on sinulle ylen raskas, et taida sinä sitä yksinäs toimittaa.","Sinä väsytät peräti sekä itses että tämän kansan joka sinun kanssas on; sillä tämä asia on sinulle ylen raskas, et taida sinä sitä yksinäs toimittaa."],[18,19,"Nyt kuule minun ääneni, minä neuvon sinua, ja Jumala on sinun kanssas. Ole sinä kansan puolesta Jumalan edessä, ja tuota heidän asiansa Jumalan eteen.","Nyt kuule minun ääneni, minä neuvon sinua, ja Jumala on sinun kanssas. Ole sinä kansan puolesta Jumalan edessä, ja tuota heidän asiansa Jumalan eteen."],[18,20,"Ja muistuta heille oikeudet ja käskyt: osota heille tie, jota heidän vaeltaman pitää, ja ne työt mitkä heidän tekemän pitää.","Ja muistuta heille oikeudet ja käskyt: osota heille tie, jota heidän vaeltaman pitää, ja ne työt mitkä heidän tekemän pitää."],[18,21,"Niin etsi sinä kaiken kansan seasta vaat miehet, Jumalaa pelkääväiset, totuuden miehet, ne jotka ahneutta vihaavat: ja aseta ne heille päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,","Niin etsi sinä kaiken kansan seasta vaat miehet, Jumalaa pelkääväiset, totuuden miehet, ne jotka ahneutta vihaavat: ja aseta ne heille päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,"],[18,22,"Että ne aina kansalle oikeuden tekisivät: mutta kuin joku raskas asia tulee, että he sen tuovat sinun eteesi mutta kaikki pienet asiat he itse ratkaiskaan: niin huojenna jotakin itseltäs, ja he kantavat kuormaa sinun kanssas.","Että ne aina kansalle oikeuden tekisivät: mutta kuin joku raskas asia tulee, että he sen tuovat sinun eteesi mutta kaikki pienet asiat he itse ratkaiskaan: niin huojenna jotakin itseltäs, ja he kantavat kuormaa sinun kanssas."],[18,23,"Jos sinä sen teet, ja Jumala sen sinulle käskee, niin sinä taidat voimassa pysyä, niin myös kaikki tämä kansa saa mennä kotiansa rauhassa.","Jos sinä sen teet, ja Jumala sen sinulle käskee, niin sinä taidat voimassa pysyä, niin myös kaikki tämä kansa saa mennä kotiansa rauhassa."],[18,24,"Ja Moses kuuli appensa äänen, ja teki kaikki mitä hän sanoi.","Ja Moses kuuli appensa äänen, ja teki kaikki mitä hän sanoi."],[18,25,"Ja valitsi vaat miehet kaikesta Israelista, ja asetti heidät kansan päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,","Ja valitsi vaat miehet kaikesta Israelista, ja asetti heidät kansan päämiehiksi, tuhanten päälle, sadan päälle, viidenkymmenen päälle, ja kymmenen päälle,"],[18,26,"Jotka tekivät kansalle oikeuden joka aika. Mutta jotka raskaat asiat olivat, lykkäsivät he Moseksen alle; vaan kaikki pienet asiat he itse ratkasivat.","Jotka tekivät kansalle oikeuden joka aika. Mutta jotka raskaat asiat olivat, lykkäsivät he Moseksen alle; vaan kaikki pienet asiat he itse ratkasivat."],[18,27,"Niin Moses antoi appensa mennä ja hän meni omalle maallensa.","Niin Moses antoi appensa mennä ja hän meni omalle maallensa."],[19,1,"Kolmantena kuukautena Israelin lasten lähtemisestä Egyptin maalta, tulivat he sinä päivänä Sinain korpeen.","Kolmantena kuukautena Israelin lasten lähtemisestä Egyptin maalta, tulivat he sinä päivänä Sinain korpeen."],[19,2,"Sillä he olivat lähteneet Raphidimista, ja tulivat Sinain korpeen, ja sioittivat itsensä korpeen: ja Israel sioitti itsensä siihen, vuoren kohdalle.","Sillä he olivat lähteneet Raphidimista, ja tulivat Sinain korpeen, ja sioittivat itsensä korpeen: ja Israel sioitti itsensä siihen, vuoren kohdalle."],[19,3,"Ja Moses astui ylös Jumalan tykö. Ja Herra huusi häntä vuorelta, ja sanoi: näin sinun pitää sanoman Jakobin huoneelle, ja Israelin lapsille ilmoittaman.","Ja Moses astui ylös Jumalan tykö. Ja Herra huusi häntä vuorelta, ja sanoi: näin sinun pitää sanoman Jakobin huoneelle, ja Israelin lapsille ilmoittaman."],[19,4,"Te olette nähneet, mitä minä Egyptiläisille tehnyt olen: ja kuinka minä olen teitä kantanut kotkan siivillä, ja olen saattanut teidät minun tyköni.","Te olette nähneet, mitä minä Egyptiläisille tehnyt olen: ja kuinka minä olen teitä kantanut kotkan siivillä, ja olen saattanut teidät minun tyköni."],[19,5,"Jos te siis minun ääneni ahkerasti kuulette, ja pidätte minun liittoni, niin teidän pitää oleman minulle kallis omaisuus kaikista kansoista, vaikka muutoin koko maa on minun.","Jos te siis minun ääneni ahkerasti kuulette, ja pidätte minun liittoni, niin teidän pitää oleman minulle kallis omaisuus kaikista kansoista, vaikka muutoin koko maa on minun."],[19,6,"Ja teidän pitää oleman minulle papillinen valtakunta ja pyhä kansa. Nämä ovat ne sanat, jotka sinun pitää Israelin lapsille, sanoman.","Ja teidän pitää oleman minulle papillinen valtakunta ja pyhä kansa. Nämä ovat ne sanat, jotka sinun pitää Israelin lapsille, sanoman."],[19,7,"Niin Moses tuli ja kutsui kokoon vanhimmat kansan seasta, ja jutteli heille kaikki sanat, jotka Herra hänen käskenyt oli.","Niin Moses tuli ja kutsui kokoon vanhimmat kansan seasta, ja jutteli heille kaikki sanat, jotka Herra hänen käskenyt oli."],[19,8,"Ja kaikki kansa vastasi yhtä haavaa, ja sanoi: kaikki mitä Herra puhunut on, me tahdomme tehdä. Ja Moses sanoi jällensä kansan sanat Herralle.","Ja kaikki kansa vastasi yhtä haavaa, ja sanoi: kaikki mitä Herra puhunut on, me tahdomme tehdä. Ja Moses sanoi jällensä kansan sanat Herralle."],[19,9,"Niin Herra sanoi Mosekselle: katso, minä tulen sinun tykös paksussa pilvessä, että kansa kuulee minun puhuvan sinun kanssas, ja uskoo sinua ijankaikkisesti. Ja Moses ilmoitti Herralle kansan puheen.","Niin Herra sanoi Mosekselle: katso, minä tulen sinun tykös paksussa pilvessä, että kansa kuulee minun puhuvan sinun kanssas, ja uskoo sinua ijankaikkisesti. Ja Moses ilmoitti Herralle kansan puheen."],[19,10,"Ja Herra sanoi Mosekselle: mene kansan tykö, ja pyhitä heitä tänäpänä ja huomenna: että he vaatteensa pesisivät.","Ja Herra sanoi Mosekselle: mene kansan tykö, ja pyhitä heitä tänäpänä ja huomenna: että he vaatteensa pesisivät."],[19,11,"Ja olisivat kolmantena päivänä valmiit; sillä kolmantena päivänä Herra on astuva alas kaiken kansan eteen Sinain vuorelle.","Ja olisivat kolmantena päivänä valmiit; sillä kolmantena päivänä Herra on astuva alas kaiken kansan eteen Sinain vuorelle."],[19,12,"Ja sinun pitää paneman rajan kansan ympärille, sanoen: karttakaat teitänne, ettette vuorelle astu taikka tartu sen rajaan: joka siihen vuoreen sattuu, sen pitää totisesti kuoleman.","Ja sinun pitää paneman rajan kansan ympärille, sanoen: karttakaat teitänne, ettette vuorelle astu taikka tartu sen rajaan: joka siihen vuoreen sattuu, sen pitää totisesti kuoleman."],[19,13,"Ei yksikään käsi pidä häneen rupeeman, vaan hän pitää täydellisesti kivitettämän, eli kohdastansa ammuttaman lävitse, joko se eläin taikka ihminen olis, ei pidä sen elämän. Koska ääni rupee pitkään kajahtamaan, silloin he vuorelle astukaan.","Ei yksikään käsi pidä häneen rupeeman, vaan hän pitää täydellisesti kivitettämän, eli kohdastansa ammuttaman lävitse, joko se eläin taikka ihminen olis, ei pidä sen elämän. Koska ääni rupee pitkään kajahtamaan, silloin he vuorelle astukaan."],[19,14,"Moses astui vuorelta kansan tykö, ja pyhitti heitä: ja he pesivät vaatteensa.","Moses astui vuorelta kansan tykö, ja pyhitti heitä: ja he pesivät vaatteensa."],[19,15,"Ja hän sanoi heille: olkaat kolmanteen päivään valmiit, ja älkäät lähestykö vaimoja.","Ja hän sanoi heille: olkaat kolmanteen päivään valmiit, ja älkäät lähestykö vaimoja."],[19,16,"Kuin kolmas päivä tuli, ja aamu oli, niin tuli pitkäisen jylinä ja leimaus, ja paksu pilvi vuoren päälle, ja sangen väkevä basunan ääni: niin kaikki kansa, jotka leirissä olivat, pelvosta vapisivat.","Kuin kolmas päivä tuli, ja aamu oli, niin tuli pitkäisen jylinä ja leimaus, ja paksu pilvi vuoren päälle, ja sangen väkevä basunan ääni: niin kaikki kansa, jotka leirissä olivat, pelvosta vapisivat."],[19,17,"Ja Moses johdatti kansan leiristä Jumalaa vastaan, ja he seisahtivat vuoren alle.","Ja Moses johdatti kansan leiristä Jumalaa vastaan, ja he seisahtivat vuoren alle."],[19,18,"Mutta koko Sinain vuori suitsi, siitä että Herra astui alas sen päälle tulessa, ja sen savu kävi ylös niinkuin pätsin savu, niin että koko vuori sangen kovaan vapisi.","Mutta koko Sinain vuori suitsi, siitä että Herra astui alas sen päälle tulessa, ja sen savu kävi ylös niinkuin pätsin savu, niin että koko vuori sangen kovaan vapisi."],[19,19,"Ja sen basunan helinä enemmin ja enemmin eneni. Moses puhui ja Jumala vastasi häntä kuultavasti.","Ja sen basunan helinä enemmin ja enemmin eneni. Moses puhui ja Jumala vastasi häntä kuultavasti."],[19,20,"Kuin nyt Herra oli tullut alas Sinain vuoren kukkulalle, niin Herra kutsui Moseksen vuoren kukkulalle. Ja Moses astui sinne ylös.","Kuin nyt Herra oli tullut alas Sinain vuoren kukkulalle, niin Herra kutsui Moseksen vuoren kukkulalle. Ja Moses astui sinne ylös."],[19,21,"Niin sanoi Herra hänelle: astu alas ja varoita kansaa, ettei he kävisi rajan ylitse Herran tykö, häntä näkemään, ja monta heistä lankeaisi.","Niin sanoi Herra hänelle: astu alas ja varoita kansaa, ettei he kävisi rajan ylitse Herran tykö, häntä näkemään, ja monta heistä lankeaisi."],[19,22,"Niin myös papit, jotka Herraa lähestyvät, pitää heitänsä pyhittämän, ettei Herra heitä hukuttaisi.","Niin myös papit, jotka Herraa lähestyvät, pitää heitänsä pyhittämän, ettei Herra heitä hukuttaisi."],[19,23,"Ja Moses sanoi Herralle: eipä kansa saa astua ylös Sinain vuorelle; sillä sinä olet meille todistanut ja sanonut: pane rajat vuoren ympärille, ja pyhitä se.","Ja Moses sanoi Herralle: eipä kansa saa astua ylös Sinain vuorelle; sillä sinä olet meille todistanut ja sanonut: pane rajat vuoren ympärille, ja pyhitä se."],[19,24,"Ja Herra sanoi hänelle: mene ja astu alas, ja astu ylös (jällensä) sinä ja Aaron sinun kanssas; mutta papit ja kansa älkään lähestykö astumaan ylös Herran tykö, ettei hän heitä hukuttaisi.","Ja Herra sanoi hänelle: mene ja astu alas, ja astu ylös (jällensä) sinä ja Aaron sinun kanssas; mutta papit ja kansa älkään lähestykö astumaan ylös Herran tykö, ettei hän heitä hukuttaisi."],[19,25,"Ja Moses astui alas kansan tykö ja sanoi nämät heille.","Ja Moses astui alas kansan tykö ja sanoi nämät heille."],[20,1,"Ja Jumala puhui kaikki nämät sanat, sanoen:","Ja Jumala puhui kaikki nämät sanat, sanoen:"],[20,2,"(1) Minä (olen) Herra sinun Jumalas; joka sinun Egyptin maalta orjuuden huoneesta ulos vienyt olen.","(1) Minä (olen) Herra sinun Jumalas; joka sinun Egyptin maalta orjuuden huoneesta ulos vienyt olen."],[20,3,"Ei sinun pidä muita jumalia pitämän minun edessäni.","Ei sinun pidä muita jumalia pitämän minun edessäni."],[20,4,"Ei sinun pidä tekemän sinulles kuvaa eikä jonkun muotoa, niiden jotka ylhäällä taivaassa ovat, eli niiden, jotka alhaalla ovat maan päällä, eikä niiden, jotka vesissä maan alla ovat.","Ei sinun pidä tekemän sinulles kuvaa eikä jonkun muotoa, niiden jotka ylhäällä taivaassa ovat, eli niiden, jotka alhaalla ovat maan päällä, eikä niiden, jotka vesissä maan alla ovat."],[20,5,"Ei sinun pidä kumartaman niitä, eikä myös palveleman niitä: Sillä minä, Herra sinun Jumalas, olen kiivas Jumala, joka etsiskelen isäin pahat teot lasten päälle, kolmanteen ja neljänteen polveen, jotka minua vihaavat;","Ei sinun pidä kumartaman niitä, eikä myös palveleman niitä: Sillä minä, Herra sinun Jumalas, olen kiivas Jumala, joka etsiskelen isäin pahat teot lasten päälle, kolmanteen ja neljänteen polveen, jotka minua vihaavat;"],[20,6,"Ja teen laupiuden monelle tuhannelle, jotka minua rakastavat, ja pitävät minun käskyni.","Ja teen laupiuden monelle tuhannelle, jotka minua rakastavat, ja pitävät minun käskyni."],[20,7,"(2) Ei sinun pidä turhaan lausuman sinun Herras Jumalas nimeä; sillä ei Herra pidä sitä rankaisemata, joka hänen nimensä turhaan lausuu.","(2) Ei sinun pidä turhaan lausuman sinun Herras Jumalas nimeä; sillä ei Herra pidä sitä rankaisemata, joka hänen nimensä turhaan lausuu."],[20,8,"(3) Muista sabbatin päivää, ettäs sen pyhittäisit.","(3) Muista sabbatin päivää, ettäs sen pyhittäisit."],[20,9,"Kuusi päivää pitää sinun työtä tekemän ja kaikki askarees toimittaman.","Kuusi päivää pitää sinun työtä tekemän ja kaikki askarees toimittaman."],[20,10,"Mutta seitsemäntenä päivänä on Herra sinun Jumalas sabbati: silloin ei sinun pidä yhtään työtä tekemän, eikä sinun, eikä sinun poikas, eikä sinun tyttäres, eikä sinun palvelias, eikä sinun piikas, eikä sinun juhtas, eikä sinun muukalaises, joka sinun portissas on.","Mutta seitsemäntenä päivänä on Herra sinun Jumalas sabbati: silloin ei sinun pidä yhtään työtä tekemän, eikä sinun, eikä sinun poikas, eikä sinun tyttäres, eikä sinun palvelias, eikä sinun piikas, eikä sinun juhtas, eikä sinun muukalaises, joka sinun portissas on."],[20,11,"Sillä kuutena päivänä on Herra, taivaan ja maan ja meren tehnyt, ja kaikki mitä niissä ovat, ja lepäsi seitsemäntenä päivänä. Sentähden siunasi Herra sabbatin päivän, ja pyhitti sen.","Sillä kuutena päivänä on Herra, taivaan ja maan ja meren tehnyt, ja kaikki mitä niissä ovat, ja lepäsi seitsemäntenä päivänä. Sentähden siunasi Herra sabbatin päivän, ja pyhitti sen."],[20,12,"(4) Sinun pitää kunnioittaman isääs ja äitiäs, ettäs kauvan eläisit maan päällä, jonka Herra sinun Jumalas antaa sinulle.","(4) Sinun pitää kunnioittaman isääs ja äitiäs, ettäs kauvan eläisit maan päällä, jonka Herra sinun Jumalas antaa sinulle."],[20,13,"(5) Ei sinun pidä tappaman.","(5) Ei sinun pidä tappaman."],[20,14,"(6) Ei sinun pidä huorin tekemän.","(6) Ei sinun pidä huorin tekemän."],[20,15,"(7) Ei sinun pidä varastaman.","(7) Ei sinun pidä varastaman."],[20,16,"(8) Ei sinun pidä väärää todistusta sanoman sinun lähimmäistäs vastaan.","(8) Ei sinun pidä väärää todistusta sanoman sinun lähimmäistäs vastaan."],[20,17,"(9) Ei sinun pidä pyytämän sinun lähimmäises huonetta. (10) Ei sinun pidä himoitseman sinun lähimmäises emäntää, eikä hänen palveliaansa, eikä piikaansa, eikä hänen härkäänsä, eikä mitään mikä sinun lähimmäises on.","(9) Ei sinun pidä pyytämän sinun lähimmäises huonetta. (10) Ei sinun pidä himoitseman sinun lähimmäises emäntää, eikä hänen palveliaansa, eikä piikaansa, eikä hänen härkäänsä, eikä mitään mikä sinun lähimmäises on."],[20,18,"Ja kaikki kansa näki pitkäisen jylinän, ja tulen leimaukset, ja basunan helinän, ja vuoren suitsevan: ja koska he sen näkivät, niin he pakenivat ja seisahtuivat taamma.","Ja kaikki kansa näki pitkäisen jylinän, ja tulen leimaukset, ja basunan helinän, ja vuoren suitsevan: ja koska he sen näkivät, niin he pakenivat ja seisahtuivat taamma."],[20,19,"Niin he sanoivat Mosekselle: puhu sinä meidän kanssamme, ja me kuulemme: ja älkään Jumala meidän kanssamme puhuko, ettemme kuolisi.","Niin he sanoivat Mosekselle: puhu sinä meidän kanssamme, ja me kuulemme: ja älkään Jumala meidän kanssamme puhuko, ettemme kuolisi."],[20,20,"Ja Moses sanoi kansalle: älkäät peljätkö; sillä Jumala on tullut teitä koettelemaan, ja että hänen pelkonsa olis teidän edessänne, ettette syntiä tekisi.","Ja Moses sanoi kansalle: älkäät peljätkö; sillä Jumala on tullut teitä koettelemaan, ja että hänen pelkonsa olis teidän edessänne, ettette syntiä tekisi."],[20,21,"Ja kansa seisahtui taamma; mutta Moses meni sen pimeyden tykö, jossa Jumala oli.","Ja kansa seisahtui taamma; mutta Moses meni sen pimeyden tykö, jossa Jumala oli."],[20,22,"Ja Herra sanoi Mosekselle: niin sinun pitää Israelin lapsille sanoman: te olette nähneet, että minä olen taivaasta teidän kanssanne puhunut.","Ja Herra sanoi Mosekselle: niin sinun pitää Israelin lapsille sanoman: te olette nähneet, että minä olen taivaasta teidän kanssanne puhunut."],[20,23,"Ei teidän pidä tekemän epäjumalia minun sivuuni: hopiaisia jumalia, ja kultaisia jumalia ei teidän pidä teillenne tekemän.","Ei teidän pidä tekemän epäjumalia minun sivuuni: hopiaisia jumalia, ja kultaisia jumalia ei teidän pidä teillenne tekemän."],[20,24,"Tee alttari maasta minulle, jonka päälle sinun pitää polttouhris ja kiitosuhris, sinun lampaas ja karjas uhraaman: mihinkä paikkaan ikänänsä minä säädän minun nimeni muiston, sinne minä tulen sinun tykös, ja siunaan sinua.","Tee alttari maasta minulle, jonka päälle sinun pitää polttouhris ja kiitosuhris, sinun lampaas ja karjas uhraaman: mihinkä paikkaan ikänänsä minä säädän minun nimeni muiston, sinne minä tulen sinun tykös, ja siunaan sinua."],[20,25,"Ja jos sinä teet minulle kivisen alttarin, niin älä tee sitä vuoltuista kivistä: jos sinä siihen veitses satutat, niin sinä sen saastutat.","Ja jos sinä teet minulle kivisen alttarin, niin älä tee sitä vuoltuista kivistä: jos sinä siihen veitses satutat, niin sinä sen saastutat."],[20,26,"Ei myös sinun pidä astumilla minun alttarilleni astuman, ettei sinun häpiäs sen päällä paljastettaisi.","Ei myös sinun pidä astumilla minun alttarilleni astuman, ettei sinun häpiäs sen päällä paljastettaisi."],[21,1,"Nämät ovat ne oikeudet, jotka sinun pitää paneman heidän eteensä:","Nämät ovat ne oikeudet, jotka sinun pitää paneman heidän eteensä:"],[21,2,"Jos sinä ostat Hebrealaisen orjan, hänen pitää sinua palveleman kuusi vuotta; vaan seitsemäntenä pitää hänen lähtemän vapaana lunastamatta;","Jos sinä ostat Hebrealaisen orjan, hänen pitää sinua palveleman kuusi vuotta; vaan seitsemäntenä pitää hänen lähtemän vapaana lunastamatta;"],[21,3,"Jos hän naimatoinna on ollut, naimatoinna pitää hänen myös lähtemän; vaan jos hän nainunna tuli, lähtekään emäntinensä.","Jos hän naimatoinna on ollut, naimatoinna pitää hänen myös lähtemän; vaan jos hän nainunna tuli, lähtekään emäntinensä."],[21,4,"Jos hänen isäntänsä antoi hänelle emännän, jos se on synnyttänyt hänelle poikia tai tyttäriä, niin hänen emäntänsä ja lapsensa pitää oleman hänen isäntänsä omat, vaan itse hänen pitää lähtemän yksinänsä.","Jos hänen isäntänsä antoi hänelle emännän, jos se on synnyttänyt hänelle poikia tai tyttäriä, niin hänen emäntänsä ja lapsensa pitää oleman hänen isäntänsä omat, vaan itse hänen pitää lähtemän yksinänsä."],[21,5,"Mutta jos orja julkisesti sanoo: minä rakastan minun isäntääni, vaimoani ja lapsiani: en tahdo tulla minä vapaaksi,","Mutta jos orja julkisesti sanoo: minä rakastan minun isäntääni, vaimoani ja lapsiani: en tahdo tulla minä vapaaksi,"],[21,6,"Niin hänen isäntänsä viekään hänen tuomarien tykö, ja seisauttakaan hänet oveen, taikka pihtipieleen, ja lävistäkään isäntä hänen korvansa naskalilla, ja olkaan ijäti hänen orjansa.","Niin hänen isäntänsä viekään hänen tuomarien tykö, ja seisauttakaan hänet oveen, taikka pihtipieleen, ja lävistäkään isäntä hänen korvansa naskalilla, ja olkaan ijäti hänen orjansa."],[21,7,"Jos joku myy tyttärensä orjaksi, ei hänen pidä lähtemän niinkuin orjat lähtevät.","Jos joku myy tyttärensä orjaksi, ei hänen pidä lähtemän niinkuin orjat lähtevät."],[21,8,"Jollei hän kelpaa isännällensä, joka ei tahdo häntä kihlata, niin hänen pitää antaman hänen lunastettaa; mutta muukalaiselle kansalle ei pidä oleman hänelle voimaa häntä myydä, tehden petollisesti hänen kanssansa.","Jollei hän kelpaa isännällensä, joka ei tahdo häntä kihlata, niin hänen pitää antaman hänen lunastettaa; mutta muukalaiselle kansalle ei pidä oleman hänelle voimaa häntä myydä, tehden petollisesti hänen kanssansa."],[21,9,"Mutta jos hän sen kihlaa pojallensa, niin antakaan hänen nautita tytärten oikeutta.","Mutta jos hän sen kihlaa pojallensa, niin antakaan hänen nautita tytärten oikeutta."],[21,10,"Jos hän pojallensa ottaa toisen, niin ei hänen pidä kieltämän häneltä hänen ravintoansa, vaatteitansa, ja asunto-oikeuttansa.","Jos hän pojallensa ottaa toisen, niin ei hänen pidä kieltämän häneltä hänen ravintoansa, vaatteitansa, ja asunto-oikeuttansa."],[21,11,"Jollei hän tee hänelle näitä kolmea, niin sen pitää vapaana lähtemän lunastamatta.","Jollei hän tee hänelle näitä kolmea, niin sen pitää vapaana lähtemän lunastamatta."],[21,12,"Joka lyö ihmisen niin että hän kuolee, hänen pitää totisesti kuoleman.","Joka lyö ihmisen niin että hän kuolee, hänen pitää totisesti kuoleman."],[21,13,"Vaan jollei hän ole häntä väijynyt, mutta Jumala on antanut hänen langeta hänen käsiinsä, niin minä määrään sinulle paikan, johonka hänen pakeneman pitää.","Vaan jollei hän ole häntä väijynyt, mutta Jumala on antanut hänen langeta hänen käsiinsä, niin minä määrään sinulle paikan, johonka hänen pakeneman pitää."],[21,14,"Mutta jos joku ylpeydestä tappaa lähimmäisensä kavaluudella; sen sinun pitää ottaman minun alttariltanikin pois, kuolettaa.","Mutta jos joku ylpeydestä tappaa lähimmäisensä kavaluudella; sen sinun pitää ottaman minun alttariltanikin pois, kuolettaa."],[21,15,"Joka lyö isäänsä taikka äitiänsä, sen pitää totisesti kuoleman.","Joka lyö isäänsä taikka äitiänsä, sen pitää totisesti kuoleman."],[21,16,"Joka varastaa ihmisen ja myy hänen, eli löydetään hänen tykönänsä, sen pitää totisesti kuoleman.","Joka varastaa ihmisen ja myy hänen, eli löydetään hänen tykönänsä, sen pitää totisesti kuoleman."],[21,17,"Ja joka kiroilee isäänsä ja äitiänsä, sen pitää totisesti kuoleman.","Ja joka kiroilee isäänsä ja äitiänsä, sen pitää totisesti kuoleman."],[21,18,"Koska miehet keskenänsä riitelevät, ja toinen lyö toistansa kivellä eli rusikalla, ja hän ei kuole vaan makaa vuoteessansa:","Koska miehet keskenänsä riitelevät, ja toinen lyö toistansa kivellä eli rusikalla, ja hän ei kuole vaan makaa vuoteessansa:"],[21,19,"Jos hän paranee, niin että hän käy ulos sauvansa nojalla, niin sen pitää syyttömän oleman joka löi: ainoastaan maksakaan hänen työnsä vahingon, josta hän on estetyksi tullut, ja hänen pitää kaiketi hänen terveeksi laittaman.","Jos hän paranee, niin että hän käy ulos sauvansa nojalla, niin sen pitää syyttömän oleman joka löi: ainoastaan maksakaan hänen työnsä vahingon, josta hän on estetyksi tullut, ja hänen pitää kaiketi hänen terveeksi laittaman."],[21,20,"Kun joku lyö palveliaansa eli palkkapiikaansa sauvalla, niin että hän kuolee hänen käsiinsä: hän pitää kaiketi kostettaman.","Kun joku lyö palveliaansa eli palkkapiikaansa sauvalla, niin että hän kuolee hänen käsiinsä: hän pitää kaiketi kostettaman."],[21,21,"Vaan jos hän päivän taikka kaksi elää, ei pidä häntä kostettaman, sillä se on hänen rahansa.","Vaan jos hän päivän taikka kaksi elää, ei pidä häntä kostettaman, sillä se on hänen rahansa."],[21,22,"Jos miehet tappelevat keskenänsä, ja loukkaavat raskaan vaimon, niin että hänen täytyy hedelmänsä kesken synnyttää; ja ei kuoleman vahinko tapahdu: niin hän pitää rahalla rangaistaman, sen jälkeen kuin vaimon mies häneltä anoo, ja se pitää annettaman arviomiesten ehdosta;","Jos miehet tappelevat keskenänsä, ja loukkaavat raskaan vaimon, niin että hänen täytyy hedelmänsä kesken synnyttää; ja ei kuoleman vahinko tapahdu: niin hän pitää rahalla rangaistaman, sen jälkeen kuin vaimon mies häneltä anoo, ja se pitää annettaman arviomiesten ehdosta;"],[21,23,"Mutta jos kuoleman vahinko tulee, niin pitää hänen antaman hengen hengestä.","Mutta jos kuoleman vahinko tulee, niin pitää hänen antaman hengen hengestä."],[21,24,"Silmän silmästä, hampaan hampaasta, käden kädestä, jalan jalasta.","Silmän silmästä, hampaan hampaasta, käden kädestä, jalan jalasta."],[21,25,"Polton poltosta, haavan haavasta, sinimarjan sinimarjasta.","Polton poltosta, haavan haavasta, sinimarjan sinimarjasta."],[21,26,"Joka lyö palveliansa eli palkkapiikansa silmän, ja turmeles sen, hänen pitää päästämän sen vapaaksi silmän tähden.","Joka lyö palveliansa eli palkkapiikansa silmän, ja turmeles sen, hänen pitää päästämän sen vapaaksi silmän tähden."],[21,27,"Niin myös jos hän lyö palvelialtansa taikka palkkapiialtansa hampaan suusta, niin pitää hänen päästämän sen vapaaksi hampaan tähden.","Niin myös jos hän lyö palvelialtansa taikka palkkapiialtansa hampaan suusta, niin pitää hänen päästämän sen vapaaksi hampaan tähden."],[21,28,"Jos härkä kuokaisee miehen eli vaimon, niin että hän kuolee: se härkä pitää kaiketi kivitettämän, ja ei pidä hänen lihaansa syötämän; ja niin on härjän isäntä viatoin.","Jos härkä kuokaisee miehen eli vaimon, niin että hän kuolee: se härkä pitää kaiketi kivitettämän, ja ei pidä hänen lihaansa syötämän; ja niin on härjän isäntä viatoin."],[21,29,"Mutta jos härkä ennen oli harjaantunut kuokkimaan, ja sen isännälle oli todistusten kanssa ilmoitettu, ja ei hän korjannut häntä; jos hän sitte tappaa miehen eli vaimon, niin pitää härkä kivitettämän, ja hänen isäntänsä kuoleman.","Mutta jos härkä ennen oli harjaantunut kuokkimaan, ja sen isännälle oli todistusten kanssa ilmoitettu, ja ei hän korjannut häntä; jos hän sitte tappaa miehen eli vaimon, niin pitää härkä kivitettämän, ja hänen isäntänsä kuoleman."],[21,30,"Mutta jos hän rahalla pääsee, niin pitää hänen antaman henkensä lunastukseksi niin paljo kuin määrätään.","Mutta jos hän rahalla pääsee, niin pitää hänen antaman henkensä lunastukseksi niin paljo kuin määrätään."],[21,31,"Jos hän pojan eli tyttären kuokaisee, niin pitää yhdellä tavalla hänen kanssansa tehtämän.","Jos hän pojan eli tyttären kuokaisee, niin pitää yhdellä tavalla hänen kanssansa tehtämän."],[21,32,"Jos joku härkä kuokaisee palvelian eli palkkapiian, niin pitää hänen antaman heidän isännällensä kolmekymmentä hopiasikliä, ja härkä pitää kivitettämän.","Jos joku härkä kuokaisee palvelian eli palkkapiian, niin pitää hänen antaman heidän isännällensä kolmekymmentä hopiasikliä, ja härkä pitää kivitettämän."],[21,33,"Jos joku avaa kuopan, taikka kaivaa kuopan, jos ei hän sitä peitä, ja härkä eli aasi siihen putoo:","Jos joku avaa kuopan, taikka kaivaa kuopan, jos ei hän sitä peitä, ja härkä eli aasi siihen putoo:"],[21,34,"Niin pitää sen kuopan isäntä maksaman rahalla sen isännälle; mutta sen kuolleen pitää hänen oleman.","Niin pitää sen kuopan isäntä maksaman rahalla sen isännälle; mutta sen kuolleen pitää hänen oleman."],[21,35,"Jos jonkun härkä kuokkii toisen miehen härjän, että se kuolee, niin pitää heidän myymän sen elävän härjän, ja jakaman rahan, niin myös sen kuolleen härjän pitää heidän jakaman.","Jos jonkun härkä kuokkii toisen miehen härjän, että se kuolee, niin pitää heidän myymän sen elävän härjän, ja jakaman rahan, niin myös sen kuolleen härjän pitää heidän jakaman."],[21,36,"Elikkä jos se oli tiettävä, että härkä on ennen tottunut kuokkimaan, ja hänen isäntänsä ei korjannut häntä, niin hänen pitää antaman härjän härjästä, ja se kuollut pitää hänen oleman.","Elikkä jos se oli tiettävä, että härkä on ennen tottunut kuokkimaan, ja hänen isäntänsä ei korjannut häntä, niin hänen pitää antaman härjän härjästä, ja se kuollut pitää hänen oleman."],[22,1,"Jos joku varastaa härjän taikka lampaan ja teurastaa eli myy sen; hänen pitää antaman viisi härkää yhdestä härjästä, ja neljä lammasta yhdestä lampaasta.","Jos joku varastaa härjän taikka lampaan ja teurastaa eli myy sen; hänen pitää antaman viisi härkää yhdestä härjästä, ja neljä lammasta yhdestä lampaasta."],[22,2,"Jos varas käsitetään, koska hän itsensä sisälle kangottaa, ja hän lyödään kuoliaaksi, niin ei pidä tappajan vereen vikapään oleman.","Jos varas käsitetään, koska hän itsensä sisälle kangottaa, ja hän lyödään kuoliaaksi, niin ei pidä tappajan vereen vikapään oleman."],[22,3,"Vaan jos aurinko on noussut hänen ylitsensä, niin pitää tappajan kuolemaan vikapään oleman: kaiketi pitää hänen jällensä maksaman; jollei hänellä ole varaa, niin myytäkään hän varkautensa tähden.","Vaan jos aurinko on noussut hänen ylitsensä, niin pitää tappajan kuolemaan vikapään oleman: kaiketi pitää hänen jällensä maksaman; jollei hänellä ole varaa, niin myytäkään hän varkautensa tähden."],[22,4,"Jos varkaan kappale löydetään täydellisesti hänen tyköänsä, härkä, aasi, eli lammas; niin pitää hänen jällensä kaksikertaisesti maksaman.","Jos varkaan kappale löydetään täydellisesti hänen tyköänsä, härkä, aasi, eli lammas; niin pitää hänen jällensä kaksikertaisesti maksaman."],[22,5,"Jos joku syöttää toisen pellon eli viinamäen, niin että hän päästää sisälle karjansa, ja syöttää toisen pellossa, hänen pitää siitä parhaasta, kuin hänen omassa pellossansa eli viinamäessänsä löydetään maksaman.","Jos joku syöttää toisen pellon eli viinamäen, niin että hän päästää sisälle karjansa, ja syöttää toisen pellossa, hänen pitää siitä parhaasta, kuin hänen omassa pellossansa eli viinamäessänsä löydetään maksaman."],[22,6,"Jos valkia vallallensa pääsee, ja orjantappuroihin syttyy, niin että kykäät eli laiho, eli pelto poltetaan, niin sen pitää maksaman, kuin valkian päästi.","Jos valkia vallallensa pääsee, ja orjantappuroihin syttyy, niin että kykäät eli laiho, eli pelto poltetaan, niin sen pitää maksaman, kuin valkian päästi."],[22,7,"Jos joku antaa lähimmäisellensä rahaa, eli muuta kalua kätköön, ja se varastetaan hänen huoneestansa: jos se varas löydetään, niin hänen pitää sen kaksikertaisesti maksaman.","Jos joku antaa lähimmäisellensä rahaa, eli muuta kalua kätköön, ja se varastetaan hänen huoneestansa: jos se varas löydetään, niin hänen pitää sen kaksikertaisesti maksaman."],[22,8,"Ja jos ei varas löydetä, niin pitää huoneen isäntä tuotaman tuomarien eteen vannotettaa, jos ei hän ole käsiänsä satuttanut lähimmäisensä kaluun.","Ja jos ei varas löydetä, niin pitää huoneen isäntä tuotaman tuomarien eteen vannotettaa, jos ei hän ole käsiänsä satuttanut lähimmäisensä kaluun."],[22,9,"Kaiken väärän asian tähden härjästä eli aasista, taikka lampaasta, eli vaatteesta ja kaiken sen tähden kuin pois tullut on, josta joku sanoo: tämä se on, niin pitää heidän molempain asiansa tuleman tuomarien eteen; jonka tuomarit vikapääksi löytävät, sen pitää lähimmäisellensä kaksikertaisesti maksaman.","Kaiken väärän asian tähden härjästä eli aasista, taikka lampaasta, eli vaatteesta ja kaiken sen tähden kuin pois tullut on, josta joku sanoo: tämä se on, niin pitää heidän molempain asiansa tuleman tuomarien eteen; jonka tuomarit vikapääksi löytävät, sen pitää lähimmäisellensä kaksikertaisesti maksaman."],[22,10,"Jos joku antaa lähimmäisellensä aasin, eli härjän, eli lampaan, taikka mikä eläin se olis, tähteelle, ja se kuolee, taikka saa muutoin vamman, taikka ajetaan pois, ettei yksikään sitä näe:","Jos joku antaa lähimmäisellensä aasin, eli härjän, eli lampaan, taikka mikä eläin se olis, tähteelle, ja se kuolee, taikka saa muutoin vamman, taikka ajetaan pois, ettei yksikään sitä näe:"],[22,11,"Niin pitää valan heidän molempain välillänsä käymän Herran kautta, ettei hän ole satuttanut kättänsä lähimmäisensä kaluun; ja sen jonka kalu oma oli, pitää siihen tyytymän, ja toisen ei pidä sitä maksaman.","Niin pitää valan heidän molempain välillänsä käymän Herran kautta, ettei hän ole satuttanut kättänsä lähimmäisensä kaluun; ja sen jonka kalu oma oli, pitää siihen tyytymän, ja toisen ei pidä sitä maksaman."],[22,12,"Jos varas sen varastaa häneltä, niin pitää hänen sen maksaman sen isännälle.","Jos varas sen varastaa häneltä, niin pitää hänen sen maksaman sen isännälle."],[22,13,"Mutta jos se raadeltu on, niin pitää hänen todistajat tuoman, ja ei mitään jälleen antaman.","Mutta jos se raadeltu on, niin pitää hänen todistajat tuoman, ja ei mitään jälleen antaman."],[22,14,"Jos joku ottaa lainaksi lähimmäiseltänsä, ja se tulee rivinomaksi eli kuolee, niin ettei sen isäntä ole läsnä, niin hänen pitää sen kokonansa maksaman.","Jos joku ottaa lainaksi lähimmäiseltänsä, ja se tulee rivinomaksi eli kuolee, niin ettei sen isäntä ole läsnä, niin hänen pitää sen kokonansa maksaman."],[22,15,"Mutta jos sen isäntä on siihen tykönä, niin ei hänen pidä sitä maksaman; jos se palkalla oli, niin saakoon palkkansa.","Mutta jos sen isäntä on siihen tykönä, niin ei hänen pidä sitä maksaman; jos se palkalla oli, niin saakoon palkkansa."],[22,16,"Jos joku viettelee neitseen, joka ei vielä ole kihlattu, ja makaa hänen, sen pitää kaiketi hänelle antaman huomenlahjan, ja ottaman hänen emännäksensä.","Jos joku viettelee neitseen, joka ei vielä ole kihlattu, ja makaa hänen, sen pitää kaiketi hänelle antaman huomenlahjan, ja ottaman hänen emännäksensä."],[22,17,"Jos hänen isänsä ei tahdo häntä antaa hänelle, niin hänen pitää antaman rahaa, niin paljo kuin neitseen huomenlahja on.","Jos hänen isänsä ei tahdo häntä antaa hänelle, niin hänen pitää antaman rahaa, niin paljo kuin neitseen huomenlahja on."],[22,18,"Velhonaista ei sinun pidä salliman elää.","Velhonaista ei sinun pidä salliman elää."],[22,19,"Joka järjettömäin luontokappalten kanssa yhteyntyy, sen pitää totisesti kuoleman.","Joka järjettömäin luontokappalten kanssa yhteyntyy, sen pitää totisesti kuoleman."],[22,20,"Se joka uhraa jumalille, ja ei ainoalle Herralle, hänen pitää kirottu oleman.","Se joka uhraa jumalille, ja ei ainoalle Herralle, hänen pitää kirottu oleman."],[22,21,"Muukalaisia ei sinun pidä ahdistaman, eikä myös polkuna pitämän: sillä te olette myös olleet muukalaisna Egyptin maalla.","Muukalaisia ei sinun pidä ahdistaman, eikä myös polkuna pitämän: sillä te olette myös olleet muukalaisna Egyptin maalla."],[22,22,"Ei teidän pidä yhtään leskeä eli orpolasta murheelliseksi saattaman.","Ei teidän pidä yhtään leskeä eli orpolasta murheelliseksi saattaman."],[22,23,"Koska sinä jonkun heistä murheelliseksi saatat: jos hän hartaasti huutaa minun tyköni, niin minä tahdon totisesti kuulla hänen huutonsa.","Koska sinä jonkun heistä murheelliseksi saatat: jos hän hartaasti huutaa minun tyköni, niin minä tahdon totisesti kuulla hänen huutonsa."],[22,24,"Ja minun vihani julmistuu, niin että minä tapan heidät miekalla; ja teidän emäntänne pitää tuleman leskiksi, ja teidän lapsenne orvoiksi.","Ja minun vihani julmistuu, niin että minä tapan heidät miekalla; ja teidän emäntänne pitää tuleman leskiksi, ja teidän lapsenne orvoiksi."],[22,25,"Koska sinä lainaat minun kansalleni rahaa, köyhälle kuin sinun tykönäs on, ei sinun pidä oleman häntä vastaan niinkuin kasvon ottaja, eli korkoa hänen päällensä paneman.","Koska sinä lainaat minun kansalleni rahaa, köyhälle kuin sinun tykönäs on, ei sinun pidä oleman häntä vastaan niinkuin kasvon ottaja, eli korkoa hänen päällensä paneman."],[22,26,"Koska sinä lähimmäiseltäs vaatteet otat pantiksi, niin sinun pitää antaman sen hänelle jällensä, ennen kuin aurinko laskee.","Koska sinä lähimmäiseltäs vaatteet otat pantiksi, niin sinun pitää antaman sen hänelle jällensä, ennen kuin aurinko laskee."],[22,27,"Sillä se on hänen ainoa verhonsa, ja vaate hänen ihollansa: missästä hän makais? Ja tapahtuu, että hän huutaa minun tyköni, niin minä kuulen häntä; sillä minä olen laupias.","Sillä se on hänen ainoa verhonsa, ja vaate hänen ihollansa: missästä hän makais? Ja tapahtuu, että hän huutaa minun tyköni, niin minä kuulen häntä; sillä minä olen laupias."],[22,28,"Tuomareita ei sinun pidä kiroileman, ja ylimmäistä sinun kansassas ei sinun pidä sadatteleman.","Tuomareita ei sinun pidä kiroileman, ja ylimmäistä sinun kansassas ei sinun pidä sadatteleman."],[22,29,"Sinun uutistas ja pisarias ei sinun pidä viivyttelemän. Esikoisen sinun pojistas pitää sinun antaman minulle.","Sinun uutistas ja pisarias ei sinun pidä viivyttelemän. Esikoisen sinun pojistas pitää sinun antaman minulle."],[22,30,"Niin pitää myös sinun tekemän härkäis ja lammastes kanssa. Seitsemän päivää anna heidän olla emäinsä tykönä, kahdeksantena päivänä pitää sinun sen antaman minulle.","Niin pitää myös sinun tekemän härkäis ja lammastes kanssa. Seitsemän päivää anna heidän olla emäinsä tykönä, kahdeksantena päivänä pitää sinun sen antaman minulle."],[22,31,"Teidän pitää oleman pyhä kansa minulle. Sentähden ei teidän pidä syömän lihaa, joka metsän pedoilta raadeltu on, mutta heittämän sen koirille.","Teidän pitää oleman pyhä kansa minulle. Sentähden ei teidän pidä syömän lihaa, joka metsän pedoilta raadeltu on, mutta heittämän sen koirille."],[23,1,"Ei sinun pidä uskoman valheita; ettäs auttaisit jumalatointa, ja tulisit vääräksi todistajaksi.","Ei sinun pidä uskoman valheita; ettäs auttaisit jumalatointa, ja tulisit vääräksi todistajaksi."],[23,2,"Ei sinun pidä joukkoa seuraaman pahuuteen, eikä myös vastaaman oikeuden edessä niin että sinä poikkeat joukon jälkeen pois oikeutta vääntämään.","Ei sinun pidä joukkoa seuraaman pahuuteen, eikä myös vastaaman oikeuden edessä niin että sinä poikkeat joukon jälkeen pois oikeutta vääntämään."],[23,3,"Ei sinun pidä kaunisteleman köyhää, hänen asiassansa.","Ei sinun pidä kaunisteleman köyhää, hänen asiassansa."],[23,4,"Koska sinä kohtaat vihollises härjän eli aasin eksyksissä niin sinun pitää johdattaman sen hänelle jällensä.","Koska sinä kohtaat vihollises härjän eli aasin eksyksissä niin sinun pitää johdattaman sen hänelle jällensä."],[23,5,"Koskas näet vihollises aasin makaavan kuorman alla, kavahda, ettes häntä jättäisi; vaan sinun pitää kaiketi auttaman häntä.","Koskas näet vihollises aasin makaavan kuorman alla, kavahda, ettes häntä jättäisi; vaan sinun pitää kaiketi auttaman häntä."],[23,6,"Ei sinun pidä kääntelemän sinun köyhäs oikeutta hänen asiassansa.","Ei sinun pidä kääntelemän sinun köyhäs oikeutta hänen asiassansa."],[23,7,"Ja ole kaukana vääristä asioista. Viatointa ja hurskasta ei sinun pidä tappaman; sillä en minä pidä jumalatointa hurskaana.","Ja ole kaukana vääristä asioista. Viatointa ja hurskasta ei sinun pidä tappaman; sillä en minä pidä jumalatointa hurskaana."],[23,8,"Ei sinun pidä lahjoja ottaman; sillä lahjat sokaisevat näkeväiset, ja kääntävät hurskasten asiat.","Ei sinun pidä lahjoja ottaman; sillä lahjat sokaisevat näkeväiset, ja kääntävät hurskasten asiat."],[23,9,"Ei teidän pidä solvaiseman muukalaisia; sillä te tiedätte muukalaisen sydämen, että te myös itse olette olleet muukalaiset Egyptin maalla.","Ei teidän pidä solvaiseman muukalaisia; sillä te tiedätte muukalaisen sydämen, että te myös itse olette olleet muukalaiset Egyptin maalla."],[23,10,"Kuusi vuotta pitää sinun kylvämän sinun maas, ja kokooman sen tulon.","Kuusi vuotta pitää sinun kylvämän sinun maas, ja kokooman sen tulon."],[23,11,"Vaan seitsemäntenä vuonna pitää sinun sen levolle jättämän, että köyhät sinun kansastas siitä syödä saisivat. Ja mitä jää, sen metsän pedot syökään. Niin pitää myös sinun tekemän viinamäkes ja öljymäkes kanssa.","Vaan seitsemäntenä vuonna pitää sinun sen levolle jättämän, että köyhät sinun kansastas siitä syödä saisivat. Ja mitä jää, sen metsän pedot syökään. Niin pitää myös sinun tekemän viinamäkes ja öljymäkes kanssa."],[23,12,"Kuusi päivää pitää sinun työtäs tekemän, mutta seitsemäntenä päivänä pitää sinun lepäämän: että sinun härkäs ja aasis saisivat levätä, ja sinun piikas poika ja muukalainen sais itsensä virvottaa.","Kuusi päivää pitää sinun työtäs tekemän, mutta seitsemäntenä päivänä pitää sinun lepäämän: että sinun härkäs ja aasis saisivat levätä, ja sinun piikas poika ja muukalainen sais itsensä virvottaa."],[23,13,"Kaikki ne mitkä minä olen teille sanonut, pitää teidän pitämän. Ja vierasten jumalain nimeä ei pidä teidän muistaman, ja sinun suustas ei pidä ne kuuluman.","Kaikki ne mitkä minä olen teille sanonut, pitää teidän pitämän. Ja vierasten jumalain nimeä ei pidä teidän muistaman, ja sinun suustas ei pidä ne kuuluman."],[23,14,"Kolmasti vuodessa pitää sinun minulle juhlaa pitämän.","Kolmasti vuodessa pitää sinun minulle juhlaa pitämän."],[23,15,"Happamattoman leivän juhlan pitää sinun pitämän, niin että sinä seitsemän päivää syöt happamatointa leipää, niinkuin minä sinulle käskenyt olen, määrättynä aikana sillä kuulla Abib. Sillä että sillä ajalla olet sinä lähtenyt Egyptistä; mutta älä tule tyhjin käsin minun eteeni.","Happamattoman leivän juhlan pitää sinun pitämän, niin että sinä seitsemän päivää syöt happamatointa leipää, niinkuin minä sinulle käskenyt olen, määrättynä aikana sillä kuulla Abib. Sillä että sillä ajalla olet sinä lähtenyt Egyptistä; mutta älä tule tyhjin käsin minun eteeni."],[23,16,"Ja sen juhlan, koskas ensin rupeet pellolta korjaamaan, mitäs siihen kylvänyt olet. Ja korjaamisen juhlan, vuoden lopussa, koska sinä työs kedolta korjannut olet.","Ja sen juhlan, koskas ensin rupeet pellolta korjaamaan, mitäs siihen kylvänyt olet. Ja korjaamisen juhlan, vuoden lopussa, koska sinä työs kedolta korjannut olet."],[23,17,"Kolmasti vuodessa pitää kaikki sinun miesväkes tuleman Herran Jumalan eteen.","Kolmasti vuodessa pitää kaikki sinun miesväkes tuleman Herran Jumalan eteen."],[23,18,"Ei sinun pidä uhraaman minun uhrini verta happaman taikinan kanssa; ja minun juhlani lihavuus ei pidä ylitse yön jäämän huomeneksi.","Ei sinun pidä uhraaman minun uhrini verta happaman taikinan kanssa; ja minun juhlani lihavuus ei pidä ylitse yön jäämän huomeneksi."],[23,19,"Uutista ensimäisestä sinun maas hedelmästä pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa emänsä rieskassa.","Uutista ensimäisestä sinun maas hedelmästä pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa emänsä rieskassa."],[23,20,"Katso, minä lähetän enkelin sinun edelles varjelemaan sinua tiellä, ja johdattamaan sinun siihen paikkaan, jonka minä olen valmistanut.","Katso, minä lähetän enkelin sinun edelles varjelemaan sinua tiellä, ja johdattamaan sinun siihen paikkaan, jonka minä olen valmistanut."],[23,21,"Pidä vaari itsestäs hänen kasvoinsa edessä ja kuule hänen äänensä, älä hänen mieltänsä pahoita; sillä ei hän jätä rankaisemata teidän ylitsekäymistänne: sillä minun nimeni on hänessä.","Pidä vaari itsestäs hänen kasvoinsa edessä ja kuule hänen äänensä, älä hänen mieltänsä pahoita; sillä ei hän jätä rankaisemata teidän ylitsekäymistänne: sillä minun nimeni on hänessä."],[23,22,"Vaan jos sinä ahkerasti kuulet hänen äänensä, ja teet kaikki mitä minä sinulle käsken, niin minä olen sinun vihollistes vihollinen, ja sinun vainoojais vainooja.","Vaan jos sinä ahkerasti kuulet hänen äänensä, ja teet kaikki mitä minä sinulle käsken, niin minä olen sinun vihollistes vihollinen, ja sinun vainoojais vainooja."],[23,23,"Sillä minun enkelini käy sinun edelläs, ja johdattaa sinun Amorilaisten, Hetiläisten, Pheresiläisten, Kanaanealaisten, Heviläisten, ja Jebusilaisten tykö, ja minä hävitän heitä.","Sillä minun enkelini käy sinun edelläs, ja johdattaa sinun Amorilaisten, Hetiläisten, Pheresiläisten, Kanaanealaisten, Heviläisten, ja Jebusilaisten tykö, ja minä hävitän heitä."],[23,24,"Niin ei sinun pidä kumartaman heidän jumaliansa, eikä myös heitä palveleman, eikä heidän tekoinsa jälkeen tekemän; mutta sinun pitää heidän epäjumalansa heittämän pois, ja lyömän heidän kuvansa rikki.","Niin ei sinun pidä kumartaman heidän jumaliansa, eikä myös heitä palveleman, eikä heidän tekoinsa jälkeen tekemän; mutta sinun pitää heidän epäjumalansa heittämän pois, ja lyömän heidän kuvansa rikki."],[23,25,"Mutta Herraa teidän Jumalaanne pitää teidän palveleman, niin hän siunaa sinun leipäs ja sinun vetes: ja minä otan sinulta pois kaikki sairaudet.","Mutta Herraa teidän Jumalaanne pitää teidän palveleman, niin hän siunaa sinun leipäs ja sinun vetes: ja minä otan sinulta pois kaikki sairaudet."],[23,26,"Ei yksikään kesken synnyttäväinen eikä hedelmätöin pidä oleman sinun maassas; ja minä tahdon täyttää sinun päiväs luvun.","Ei yksikään kesken synnyttäväinen eikä hedelmätöin pidä oleman sinun maassas; ja minä tahdon täyttää sinun päiväs luvun."],[23,27,"Minä lähetän minun pelkoni sinun edelles, ja hukutan kaiken kansan, jonka tykö sinä menet: ja saatan kaikki sinun vihollises pakoon sinun edestäs.","Minä lähetän minun pelkoni sinun edelles, ja hukutan kaiken kansan, jonka tykö sinä menet: ja saatan kaikki sinun vihollises pakoon sinun edestäs."],[23,28,"Minä lähetän hörhöläiset sinun edelles, jotka pitää ajaman pois sinun edestäs Heviläiset, Kanaanealaiset ja Hetiläiset.","Minä lähetän hörhöläiset sinun edelles, jotka pitää ajaman pois sinun edestäs Heviläiset, Kanaanealaiset ja Hetiläiset."],[23,29,"En minä heitä aja ulos yhtenä vuonna sinun edestäs, ettei maa autiaksi tulisi, eikä metsän pedot enenisi sinua vastaan.","En minä heitä aja ulos yhtenä vuonna sinun edestäs, ettei maa autiaksi tulisi, eikä metsän pedot enenisi sinua vastaan."],[23,30,"Vähittäin minä heitä ajan ulos sinun edestäs, siihenasti ettäs kasvat ja omistat maan.","Vähittäin minä heitä ajan ulos sinun edestäs, siihenasti ettäs kasvat ja omistat maan."],[23,31,"Ja minä panen sinun maas rajat Punaisesta merestä niin Philistealaisten mereen asti, ja korvesta niin virtaan asti: sillä minä annan maan asuvaiset sinun kätees, ajaakses heitä ulos edestäs.","Ja minä panen sinun maas rajat Punaisesta merestä niin Philistealaisten mereen asti, ja korvesta niin virtaan asti: sillä minä annan maan asuvaiset sinun kätees, ajaakses heitä ulos edestäs."],[23,32,"Ei sinun pidä liittoa tekemän heidän kanssansa, eikä heidän jumalainsa kanssa.","Ei sinun pidä liittoa tekemän heidän kanssansa, eikä heidän jumalainsa kanssa."],[23,33,"Ei heidän pidä asuman sinun maassas, ettei he kehoittaisi sinua syntiä tekemään minua vastaan, niin ettäs palvelet heidän jumaliansa, sillä se on sinulle paulaksi.","Ei heidän pidä asuman sinun maassas, ettei he kehoittaisi sinua syntiä tekemään minua vastaan, niin ettäs palvelet heidän jumaliansa, sillä se on sinulle paulaksi."],[24,1,"Ja hän sanoi Mosekselle: astu Herran tykö, sinä ja Aaron, Nadab ja Abihu, ja seitsemänkymmentä vanhinta Israelista: ja kumartakaat itsenne taampana.","Ja hän sanoi Mosekselle: astu Herran tykö, sinä ja Aaron, Nadab ja Abihu, ja seitsemänkymmentä vanhinta Israelista: ja kumartakaat itsenne taampana."],[24,2,"Mutta Moses lähestyköön yksinänsä Herran tykö, ja älkööt muut lähestykö: älköön myös kansa astuko ylös hänen kanssansa.","Mutta Moses lähestyköön yksinänsä Herran tykö, ja älkööt muut lähestykö: älköön myös kansa astuko ylös hänen kanssansa."],[24,3,"Ja Moses tuli ja jutteli kansalle kaikki Herran sanat, ja oikeudet. Niin vastasi kaikki kansa yhdellä äänellä, ja sanoi: kaikki ne sanat, mitkä Herra puhunut on, tahdomme me tehdä.","Ja Moses tuli ja jutteli kansalle kaikki Herran sanat, ja oikeudet. Niin vastasi kaikki kansa yhdellä äänellä, ja sanoi: kaikki ne sanat, mitkä Herra puhunut on, tahdomme me tehdä."],[24,4,"Niin kirjoitti Moses kaikki Herran sanat, ja nousi varhain aamulla, ja rakensi alttarin vuoren palttaan, kahdentoistakymmenen patsaan kanssa, kahdentoistakymmenen Israelin sukukunnan jälkeen.","Niin kirjoitti Moses kaikki Herran sanat, ja nousi varhain aamulla, ja rakensi alttarin vuoren palttaan, kahdentoistakymmenen patsaan kanssa, kahdentoistakymmenen Israelin sukukunnan jälkeen."],[24,5,"Ja lähetti sinne nuoria miehiä Israelin lapsista, jotka uhrasivat polttouhria, ja kiitosuhria Herralle, mulleista.","Ja lähetti sinne nuoria miehiä Israelin lapsista, jotka uhrasivat polttouhria, ja kiitosuhria Herralle, mulleista."],[24,6,"Ja Moses otti puolen verestä ja pani maljoihin; mutta toisen puolen verestä priiskotti hän alttarille.","Ja Moses otti puolen verestä ja pani maljoihin; mutta toisen puolen verestä priiskotti hän alttarille."],[24,7,"Ja otti liitonkirjan, ja luki sen kansan korvain kuullen, ja he sanoivat: kaikki mitä Herra puhunut on tahdomme me tehdä ja olla hänelle kuuliaiset.","Ja otti liitonkirjan, ja luki sen kansan korvain kuullen, ja he sanoivat: kaikki mitä Herra puhunut on tahdomme me tehdä ja olla hänelle kuuliaiset."],[24,8,"Niin Moses otti veren ja priiskotti kansan päälle, ja sanoi: katso, tämä on liiton veri, jonka Herra teki teidän kanssanne kaikkein näiden sanain päälle.","Niin Moses otti veren ja priiskotti kansan päälle, ja sanoi: katso, tämä on liiton veri, jonka Herra teki teidän kanssanne kaikkein näiden sanain päälle."],[24,9,"Niin astui Moses ja Aaron, Nadab ja Abihu ylös, ja seitsemänkymmentä Israelin vanhinta.","Niin astui Moses ja Aaron, Nadab ja Abihu ylös, ja seitsemänkymmentä Israelin vanhinta."],[24,10,"Ja näkivät Israelin Jumalan: hänen jalkainsa alla oli niinkuin teko saphirin kivestä, ja kuin itse taivas, koska seijes on;","Ja näkivät Israelin Jumalan: hänen jalkainsa alla oli niinkuin teko saphirin kivestä, ja kuin itse taivas, koska seijes on;"],[24,11,"Eikä ojentanut kättänsä Israelin lasten päämiesten tykö: ja kuin he olivat nähneet Jumalan, niin he söivät ja joivat.","Eikä ojentanut kättänsä Israelin lasten päämiesten tykö: ja kuin he olivat nähneet Jumalan, niin he söivät ja joivat."],[24,12,"Ja Herra sanoi Mosekselle: astu ylös minun tyköni vuorelle, ja ole siellä: ja minä annan sinulle kiviset taulut, ja lain, ja käskyt, jotka minä kirjoittanut olen, jotka sinun pitää heille opettaman.","Ja Herra sanoi Mosekselle: astu ylös minun tyköni vuorelle, ja ole siellä: ja minä annan sinulle kiviset taulut, ja lain, ja käskyt, jotka minä kirjoittanut olen, jotka sinun pitää heille opettaman."],[24,13,"Silloin nousi Moses ja hänen palveliansa Josua: ja Moses astui ylös Jumalan vuorelle.","Silloin nousi Moses ja hänen palveliansa Josua: ja Moses astui ylös Jumalan vuorelle."],[24,14,"Ja sanoi vanhimmille: olkaat tässä siihen asti, kuin me palajamme teidän tykönne: katso, Aaron ja Hur ovat teidän tykönänne: jolla joku asia on, se tulkaan heidän eteensä.","Ja sanoi vanhimmille: olkaat tässä siihen asti, kuin me palajamme teidän tykönne: katso, Aaron ja Hur ovat teidän tykönänne: jolla joku asia on, se tulkaan heidän eteensä."],[24,15,"Koska Moses tuli vuorelle, niin pilvi peitti vuoren,","Koska Moses tuli vuorelle, niin pilvi peitti vuoren,"],[24,16,"Ja Herran kunnia asui Sinain vuorella, ja pilvi peitti sen kuusi päivää: ja hän kutsui Moseksen pilven keskeltä seitsemäntenä päivänä.","Ja Herran kunnia asui Sinain vuorella, ja pilvi peitti sen kuusi päivää: ja hän kutsui Moseksen pilven keskeltä seitsemäntenä päivänä."],[24,17,"Ja Herran kunnia oli nähdä niinkuin kuluttavainen tuli, vuoren kukkulalla, Israelin lasten edessä.","Ja Herran kunnia oli nähdä niinkuin kuluttavainen tuli, vuoren kukkulalla, Israelin lasten edessä."],[24,18,"Ja Moses meni keskelle pilveä, ja astui ylös vuorelle: ja Moses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä.","Ja Moses meni keskelle pilveä, ja astui ylös vuorelle: ja Moses oli vuorella neljäkymmentä päivää ja neljäkymmentä yötä."],[25,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[25,2,"Puhu Israelin lapsille, että he tuovat minulle ylennysuhrin: joka mieheltä, jonka sydän hyvästä tahdosta sen antaa, pitää teidän minun ylennysuhrini ottaman.","Puhu Israelin lapsille, että he tuovat minulle ylennysuhrin: joka mieheltä, jonka sydän hyvästä tahdosta sen antaa, pitää teidän minun ylennysuhrini ottaman."],[25,3,"Ja tämä on ylennysuhri, jonka teidän pitää ottaman heiltä: kultaa ja hopiaa ja vaskea.","Ja tämä on ylennysuhri, jonka teidän pitää ottaman heiltä: kultaa ja hopiaa ja vaskea."],[25,4,"Sinisiä villoja, purpuraa, ja tulipunaisia villoja, niin myös kallista liinaa ja vuohen karvoja.","Sinisiä villoja, purpuraa, ja tulipunaisia villoja, niin myös kallista liinaa ja vuohen karvoja."],[25,5,"Punaisia oinaan nahkoja, tekasjim-nahkoja, ja sittimipuita,","Punaisia oinaan nahkoja, tekasjim-nahkoja, ja sittimipuita,"],[25,6,"Öljyä lamppuihin, yrttejä voide-öljyksi, ja hyvän hajullisia kaluja savuttamiseksi.","Öljyä lamppuihin, yrttejä voide-öljyksi, ja hyvän hajullisia kaluja savuttamiseksi."],[25,7,"Onikinkiviä, ja sisälle sovitettuja kiviä päällisvaatteeseen ja kilpeen.","Onikinkiviä, ja sisälle sovitettuja kiviä päällisvaatteeseen ja kilpeen."],[25,8,"Ja heidän pitää tekemän minulle pyhän, että minä asuisin heidän seassansa.","Ja heidän pitää tekemän minulle pyhän, että minä asuisin heidän seassansa."],[25,9,"Kaiken sen jälkeen kuin minä osotan sinulle Tabernaklin muodon, ja kaikkein sen astiain muodon: niin pitää teidän sen tekemän.","Kaiken sen jälkeen kuin minä osotan sinulle Tabernaklin muodon, ja kaikkein sen astiain muodon: niin pitää teidän sen tekemän."],[25,10,"Tehkäät arkki sittimipuusta, jonka pituus pitää oleman puolikolmatta kyynärää, ja leveys puolitoista kyynärää, ja korkeus puolitoista kyynärää.","Tehkäät arkki sittimipuusta, jonka pituus pitää oleman puolikolmatta kyynärää, ja leveys puolitoista kyynärää, ja korkeus puolitoista kyynärää."],[25,11,"Ja sinun pitää sen silaaman puhtaalla kullalla, sisältä ja ulkoa pitää sinun sen silaaman; ja sinun pitää tekemän kultaisen vanteen sen ympäri.","Ja sinun pitää sen silaaman puhtaalla kullalla, sisältä ja ulkoa pitää sinun sen silaaman; ja sinun pitää tekemän kultaisen vanteen sen ympäri."],[25,12,"Ja pitää myös valaman neljä kultaista rengasta, jotka sinun pitää paneman neljään kulmaan, niin että kaksi rengasta ovat hänen yhdellä puolellansa, ja toiset kaksi rengasta toisella puolellansa.","Ja pitää myös valaman neljä kultaista rengasta, jotka sinun pitää paneman neljään kulmaan, niin että kaksi rengasta ovat hänen yhdellä puolellansa, ja toiset kaksi rengasta toisella puolellansa."],[25,13,"Ja sinun pitää tekemän korennot sittimipuusta, ja silaaman ne kullalla.","Ja sinun pitää tekemän korennot sittimipuusta, ja silaaman ne kullalla."],[25,14,"Ja pitää pistämän korennot renkaisiin, arkin sivulle; että niillä arkki kannettaisiin.","Ja pitää pistämän korennot renkaisiin, arkin sivulle; että niillä arkki kannettaisiin."],[25,15,"Sen arkin renkaissa pitää oleman korennot; ja ei pidä niistä vedettämän ulos.","Sen arkin renkaissa pitää oleman korennot; ja ei pidä niistä vedettämän ulos."],[25,16,"Ja sinun pitää paneman arkkiin sen todistuksen, jonka minä sinulle annan.","Ja sinun pitää paneman arkkiin sen todistuksen, jonka minä sinulle annan."],[25,17,"Sinun pitää myös tekemän armoistuimen, puhtaasta kullasta, puolikolmatta kyynärää pitkän, ja puolitoista kyynärää leviän.","Sinun pitää myös tekemän armoistuimen, puhtaasta kullasta, puolikolmatta kyynärää pitkän, ja puolitoista kyynärää leviän."],[25,18,"Ja sinun pitää tekemän kaksi Kerubimiä kullasta: valetusta kullasta pitää sinun ne tekemän, molempiin päihin armo-istuinta.","Ja sinun pitää tekemän kaksi Kerubimiä kullasta: valetusta kullasta pitää sinun ne tekemän, molempiin päihin armo-istuinta."],[25,19,"Ja tee yksi Kerubimi tähän päähän ja toinen toiseen päähän: molempiin päihin armoistuinta pitää teidän Kerubimit tekemän.","Ja tee yksi Kerubimi tähän päähän ja toinen toiseen päähän: molempiin päihin armoistuinta pitää teidän Kerubimit tekemän."],[25,20,"Ja ne Kerubimit pitää hajottaman siipensä sen ylitse, niin että he peittävät armo-istuimen siivillänsä, ja heidän kasvonsa pitää oleman toinen toisensa puoleen: ja Kerubimin kasvot pitää oleman armo-istuinta päin.","Ja ne Kerubimit pitää hajottaman siipensä sen ylitse, niin että he peittävät armo-istuimen siivillänsä, ja heidän kasvonsa pitää oleman toinen toisensa puoleen: ja Kerubimin kasvot pitää oleman armo-istuinta päin."],[25,21,"Ja sinun pitää asettaman armo-istuimen arkin päälle, ja paneman arkkiin sen todistuksen, jonka minä sinulle annan.","Ja sinun pitää asettaman armo-istuimen arkin päälle, ja paneman arkkiin sen todistuksen, jonka minä sinulle annan."],[25,22,"Ja siinä minä sinulle olen saapuvilla, ja puhuttelen sinua armo-istuimelta, kahden Kerubimin väliltä, jotka ovat todistuksen arkin päällä, kaikista mitä minä sinun käsken sanoa Israelin lapsille.","Ja siinä minä sinulle olen saapuvilla, ja puhuttelen sinua armo-istuimelta, kahden Kerubimin väliltä, jotka ovat todistuksen arkin päällä, kaikista mitä minä sinun käsken sanoa Israelin lapsille."],[25,23,"Ja sinun pitää tekemän pöydän sittimipuusta: kaksi kyynärää pitää oleman hänen pituutensa, ja kyynärä hänen leveytensä, ja puolitoista kyynärää hänen korkeutensa.","Ja sinun pitää tekemän pöydän sittimipuusta: kaksi kyynärää pitää oleman hänen pituutensa, ja kyynärä hänen leveytensä, ja puolitoista kyynärää hänen korkeutensa."],[25,24,"Ja sinun pitää silaaman sen puhtaalla kullalla, ja tekemän ympärinsä sen päälle kultaisen vanteen.","Ja sinun pitää silaaman sen puhtaalla kullalla, ja tekemän ympärinsä sen päälle kultaisen vanteen."],[25,25,"Ja sinun pitää tekemän vanteen sen ympäri kämmentä korkian, ja tekemän kultaisen palteen vanteen ympäri.","Ja sinun pitää tekemän vanteen sen ympäri kämmentä korkian, ja tekemän kultaisen palteen vanteen ympäri."],[25,26,"Ja sinun pitää siihen tekemän neljä kultaista rengasta, ja paneman renkaat neljään kulmaan, jotka ovat neljän jalan päällä.","Ja sinun pitää siihen tekemän neljä kultaista rengasta, ja paneman renkaat neljään kulmaan, jotka ovat neljän jalan päällä."],[25,27,"Juuri vanteen kohdalla pitää ne renkaat oleman, että niihin taidettaisiin pistää korennot, joilla pöytä kannettaisiin.","Juuri vanteen kohdalla pitää ne renkaat oleman, että niihin taidettaisiin pistää korennot, joilla pöytä kannettaisiin."],[25,28,"Ja sinun pitää tekemän ne korennot sittimipuusta ja silaaman kullalla: ja pöytä niillä kannettaman.","Ja sinun pitää tekemän ne korennot sittimipuusta ja silaaman kullalla: ja pöytä niillä kannettaman."],[25,29,"Ja sinun pitää siihen myös tekemän sen vadit, ja lusikat, ja maljat ja pikarit, joilla ulos ja sisälle kaadetaan: puhtaasta kullasta pitää sinun ne tekemän.","Ja sinun pitää siihen myös tekemän sen vadit, ja lusikat, ja maljat ja pikarit, joilla ulos ja sisälle kaadetaan: puhtaasta kullasta pitää sinun ne tekemän."],[25,30,"Ja sinun pitää paneman aina pöydälle minun eteeni katumusleivät.","Ja sinun pitää paneman aina pöydälle minun eteeni katumusleivät."],[25,31,"Sinun pitää myös tekemän kynttiläjalan puhtaasta kullasta: valetusta kullasta pitää se kynttiläjalka tehtämän, jonka varsi haarainsa, maljainsa, nuppeinsa ja kukkaistensa kanssa pitää siitä samasta oleman.","Sinun pitää myös tekemän kynttiläjalan puhtaasta kullasta: valetusta kullasta pitää se kynttiläjalka tehtämän, jonka varsi haarainsa, maljainsa, nuppeinsa ja kukkaistensa kanssa pitää siitä samasta oleman."],[25,32,"Kuusi haaraa pitää käymän ulos hänen kyljistänsä: kolme kynttiläjalan haaraa hänen yhdestä kyljestänsä, ja kolme kynttiläjalan haaraa hänen toisesta kyljestänsä.","Kuusi haaraa pitää käymän ulos hänen kyljistänsä: kolme kynttiläjalan haaraa hänen yhdestä kyljestänsä, ja kolme kynttiläjalan haaraa hänen toisesta kyljestänsä."],[25,33,"Ja pitää oleman kolme maljaa niinkuin mandelpähkinät, yhdessä haarassa, niin myös nuppi ja kukkainen, ja kolme mandelpähkinän muotoista maljaa toisessa haarassa, ja nuppi ja kukkainen: niin pitää oleman niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät.","Ja pitää oleman kolme maljaa niinkuin mandelpähkinät, yhdessä haarassa, niin myös nuppi ja kukkainen, ja kolme mandelpähkinän muotoista maljaa toisessa haarassa, ja nuppi ja kukkainen: niin pitää oleman niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät."],[25,34,"Mutta kynttiläjalassa pitää oleman neljä maljaa mandelin muotoista, ja siihen nupit ja kukkaiset.","Mutta kynttiläjalassa pitää oleman neljä maljaa mandelin muotoista, ja siihen nupit ja kukkaiset."],[25,35,"Nimittäin yksi nuppi kahden haaran alla, ja taas yksi nuppi toisen haaran alla, ja vielä yksi nuppi kahden (jälkimäisen) haaran alla: niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät.","Nimittäin yksi nuppi kahden haaran alla, ja taas yksi nuppi toisen haaran alla, ja vielä yksi nuppi kahden (jälkimäisen) haaran alla: niissä kuudessa haarassa, jotka kynttiläjalasta ulos käyvät."],[25,36,"Niiden nupit ja niiden haarat pitää siitä oleman: ja kaikki tyyni pitää oleman valetusta kullasta.","Niiden nupit ja niiden haarat pitää siitä oleman: ja kaikki tyyni pitää oleman valetusta kullasta."],[25,37,"Ja sinun pitää tekemän seitsemän lamppua sen päälle, jotka lamput pitää sytytettämän, niin että ne valistaisivat toinen toisensa kohdalla.","Ja sinun pitää tekemän seitsemän lamppua sen päälle, jotka lamput pitää sytytettämän, niin että ne valistaisivat toinen toisensa kohdalla."],[25,38,"Ja kynttilän niistimet ja sammutuskalut puhtaasta kullasta.","Ja kynttilän niistimet ja sammutuskalut puhtaasta kullasta."],[25,39,"Yhdestä leiviskästä puhdasta kultaa pitää sinun sen tekemän, kaikkein näiden astiain kanssa.","Yhdestä leiviskästä puhdasta kultaa pitää sinun sen tekemän, kaikkein näiden astiain kanssa."],[25,40,"Niin katso, ja tee sen muodon jälkeen, kuin sinä näit vuorella.","Niin katso, ja tee sen muodon jälkeen, kuin sinä näit vuorella."],[26,1,"Ja Tabernaklin pitää sinun tekemän kymmenestä vaatteesta: kalliista kerratuista liinalangoista, sinisistä, purpuraisista, ja tulipunaisista villoista. Gerubimin sinun pitää tekemän taitavasti sen päälle.","Ja Tabernaklin pitää sinun tekemän kymmenestä vaatteesta: kalliista kerratuista liinalangoista, sinisistä, purpuraisista, ja tulipunaisista villoista. Gerubimin sinun pitää tekemän taitavasti sen päälle."],[26,2,"Kunkin vaatten pituus pitää oleman kahdeksan kyynärää kolmattakymmentä, ja leveys pitää oleman neljä kyynärää: ja niillä kaikilla vaatteilla pitää yksi mitta oleman.","Kunkin vaatten pituus pitää oleman kahdeksan kyynärää kolmattakymmentä, ja leveys pitää oleman neljä kyynärää: ja niillä kaikilla vaatteilla pitää yksi mitta oleman."],[26,3,"Viisi vaatetta pitää yhdistettämän toinen toiseensa, ja taas viisi yhdistettämän toinen toiseensa.","Viisi vaatetta pitää yhdistettämän toinen toiseensa, ja taas viisi yhdistettämän toinen toiseensa."],[26,4,"Sinun pitää myös tekemän silmukset sinisistä villoista ensimäisen vaatteen reunaan, äärimäiset kulmat yhteen sidottaa: ja niin sinun pitää tekemän äärimäisen vaatteen reunaan, sen kulmat yhteenpantaa toistamiseen.","Sinun pitää myös tekemän silmukset sinisistä villoista ensimäisen vaatteen reunaan, äärimäiset kulmat yhteen sidottaa: ja niin sinun pitää tekemän äärimäisen vaatteen reunaan, sen kulmat yhteenpantaa toistamiseen."],[26,5,"Sinun pitää tekemän viisikymmentä silmusta ensimäiseen vaatteesen, niin myös viisikymmentä silmusta äärelle vaatetta, joka toisessa yhdistyksessä on; ja silmukset pitää oleman toinen toisensa kohdalla.","Sinun pitää tekemän viisikymmentä silmusta ensimäiseen vaatteesen, niin myös viisikymmentä silmusta äärelle vaatetta, joka toisessa yhdistyksessä on; ja silmukset pitää oleman toinen toisensa kohdalla."],[26,6,"Ja sinun pitää tekemän viisikymmentä kultaista koukkua, ja ne vaatteet yhdistämän toinen toiseensa niillä koukuilla, niin että se tulis yhdeksi Tabernakliksi.","Ja sinun pitää tekemän viisikymmentä kultaista koukkua, ja ne vaatteet yhdistämän toinen toiseensa niillä koukuilla, niin että se tulis yhdeksi Tabernakliksi."],[26,7,"Ja sinun pitää tekemän yksitoistakymmentä vaatetta vuohen karvoista, peitteeksi Tabernaklin päälle.","Ja sinun pitää tekemän yksitoistakymmentä vaatetta vuohen karvoista, peitteeksi Tabernaklin päälle."],[26,8,"Jokaisen vaatteen pituuden pitää oleman kolmekymmentä kyynärää, ja leveyden neljä kyynärää, ja leveyden neljä kyynärää. Ja kaikki yksitoistakymmentä pitää oleman yhdensuuruiset.","Jokaisen vaatteen pituuden pitää oleman kolmekymmentä kyynärää, ja leveyden neljä kyynärää, ja leveyden neljä kyynärää. Ja kaikki yksitoistakymmentä pitää oleman yhdensuuruiset."],[26,9,"Viisi vaatetta pitää sinun toinen toiseensa yhdistämän erinänsä, ja myös kuusi vaatetta erinänsä; niin ettäs teet sen kuudennen vaatteen kaksikertaiseksi etiseltä puolen Tabernaklia.","Viisi vaatetta pitää sinun toinen toiseensa yhdistämän erinänsä, ja myös kuusi vaatetta erinänsä; niin ettäs teet sen kuudennen vaatteen kaksikertaiseksi etiseltä puolen Tabernaklia."],[26,10,"Ja sinun pitää tekemän viisikymmentä silmusta ensimäisen vaatteen reunaan, äärelle, josta se yhdistetään ja myös viisikymmentä silmusta siihen vaatteen reunaan, josta se toinen kerta yhdistetään.","Ja sinun pitää tekemän viisikymmentä silmusta ensimäisen vaatteen reunaan, äärelle, josta se yhdistetään ja myös viisikymmentä silmusta siihen vaatteen reunaan, josta se toinen kerta yhdistetään."],[26,11,"Niin myös pitää sinun tekemän viisikymmentä vaskikoukkua, ja paneman koukut silmuksiin ja yhdistämän majan, että se olis yksi maja.","Niin myös pitää sinun tekemän viisikymmentä vaskikoukkua, ja paneman koukut silmuksiin ja yhdistämän majan, että se olis yksi maja."],[26,12,"Vaan se liika joka ylitse jää Tabernaklin vaatteesta: nimittäin puolen siitä liiaksi jääneestä vaatteesta, pitää sinun antaman riippua ylitse Tabernaklin, perän puolella.","Vaan se liika joka ylitse jää Tabernaklin vaatteesta: nimittäin puolen siitä liiaksi jääneestä vaatteesta, pitää sinun antaman riippua ylitse Tabernaklin, perän puolella."],[26,13,"Ja yksi kyynärä pitää oleman yhdellä ja yksi kyynärä toisella puolen, sen ylitse jääneen majan vaatteen pituudesta: sen pitää riippuman Tabernaklin sivuilla siellä ja täällä, sitä peittämässä.","Ja yksi kyynärä pitää oleman yhdellä ja yksi kyynärä toisella puolen, sen ylitse jääneen majan vaatteen pituudesta: sen pitää riippuman Tabernaklin sivuilla siellä ja täällä, sitä peittämässä."],[26,14,"Mutta tämän ensimäisen peitteen päälle sinun pitää tekemän toisen peitteen punaisista oinaan nahoista, ja vielä sitten ylimmäisen peitteen tekasjim-nahoista.","Mutta tämän ensimäisen peitteen päälle sinun pitää tekemän toisen peitteen punaisista oinaan nahoista, ja vielä sitten ylimmäisen peitteen tekasjim-nahoista."],[26,15,"Sinun pitää myös tekemän Tabernaklin laudat sittimipuusta, pystyällä olemaan.","Sinun pitää myös tekemän Tabernaklin laudat sittimipuusta, pystyällä olemaan."],[26,16,"Jokaisen laudan pituus pitää oleman kymmenen kyynärää, vaan leveys puolitoista kyynärää.","Jokaisen laudan pituus pitää oleman kymmenen kyynärää, vaan leveys puolitoista kyynärää."],[26,17,"Kaksi vaarnaa pitää jokaisessa laudassa oleman, niin että he taittaisiin yhdistettää toinen toiseensa. Näin pitää sinun tekemän kaikki Tabernaklin laudat.","Kaksi vaarnaa pitää jokaisessa laudassa oleman, niin että he taittaisiin yhdistettää toinen toiseensa. Näin pitää sinun tekemän kaikki Tabernaklin laudat."],[26,18,"Ja sinun pitää tekemän Tabernaklin laudat, niin että kaksikymmentä lautaa pitää oleman etelän puolella.","Ja sinun pitää tekemän Tabernaklin laudat, niin että kaksikymmentä lautaa pitää oleman etelän puolella."],[26,19,"Ja neljäkymmentä hopiajalkaa pitää sinun tekemän kahdenkymmenen laudan alle, niin että jokaisen laudan alla pitää oleman kaksi jalkaa, kahden vaarnansa päällä.","Ja neljäkymmentä hopiajalkaa pitää sinun tekemän kahdenkymmenen laudan alle, niin että jokaisen laudan alla pitää oleman kaksi jalkaa, kahden vaarnansa päällä."],[26,20,"Niin myös majan toisella sivulla pohjan puolella pitää oleman kaksikymmentä lautaa.","Niin myös majan toisella sivulla pohjan puolella pitää oleman kaksikymmentä lautaa."],[26,21,"Ja neljäkymmentä hopiajalkaa: aina kaksi jalkaa kunkin laudan alla.","Ja neljäkymmentä hopiajalkaa: aina kaksi jalkaa kunkin laudan alla."],[26,22,"Mutta perällä Tabernaklia länteen päin pitää sinun tekemän kuusi lautaa.","Mutta perällä Tabernaklia länteen päin pitää sinun tekemän kuusi lautaa."],[26,23,"Ja kaksi lautaa pitää sinun tekemän Tabernaklin perälle, niihin kahteen kulmaan.","Ja kaksi lautaa pitää sinun tekemän Tabernaklin perälle, niihin kahteen kulmaan."],[26,24,"Niin että kumpikin niistä taittaisiin yhdistettää silmuksella sekä alhaalta että ylhäältä: yhdellä tavalla pitää he molemmista kulmista yhdistettämän kulmakiskoilla,","Niin että kumpikin niistä taittaisiin yhdistettää silmuksella sekä alhaalta että ylhäältä: yhdellä tavalla pitää he molemmista kulmista yhdistettämän kulmakiskoilla,"],[26,25,"Niin että yhteen olis kahdeksan lautaa, ja heidän hopiajalkansa kuusitoistakymmentä: aina kaksi jalkaa kunkin laudan alla.","Niin että yhteen olis kahdeksan lautaa, ja heidän hopiajalkansa kuusitoistakymmentä: aina kaksi jalkaa kunkin laudan alla."],[26,26,"Sinun pitää myös tekemän korennot sittimipuusta: viisi niihin lautoihin, jotka yhdellä Tabernaklin sivulla ovat;","Sinun pitää myös tekemän korennot sittimipuusta: viisi niihin lautoihin, jotka yhdellä Tabernaklin sivulla ovat;"],[26,27,"Ja viisi korentoa niihin lautoihin, kuin toisella Tabernaklin sivulla ovat: ja viisi korentoa myös niihin lautoihin, jotka perällä Tabernaklia ovat, länteen päin.","Ja viisi korentoa niihin lautoihin, kuin toisella Tabernaklin sivulla ovat: ja viisi korentoa myös niihin lautoihin, jotka perällä Tabernaklia ovat, länteen päin."],[26,28,"Ja keskimäinen korento pitää keskeltä lautoja käymän yhdestä kulmasta niin toiseen.","Ja keskimäinen korento pitää keskeltä lautoja käymän yhdestä kulmasta niin toiseen."],[26,29,"Ja sinun pitää laudat kullalla silaaman, ja kullasta renkaat niihin tekemän, joihinka korennot pistetään, ja sinun pitää myös korennot kullalla silaaman.","Ja sinun pitää laudat kullalla silaaman, ja kullasta renkaat niihin tekemän, joihinka korennot pistetään, ja sinun pitää myös korennot kullalla silaaman."],[26,30,"Ja niin pitää sinun Tabernaklin pystyälle paneman, sen muodon jälkeen, kuin sinä näit vuorella.","Ja niin pitää sinun Tabernaklin pystyälle paneman, sen muodon jälkeen, kuin sinä näit vuorella."],[26,31,"Esiripun pitää myös sinun tekemän sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratuista liinalangoista, ja tekemään Kerubimit sen päälle taitavasti.","Esiripun pitää myös sinun tekemän sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratuista liinalangoista, ja tekemään Kerubimit sen päälle taitavasti."],[26,32,"Ja sinun pitää ripustaman sen neljän sittimipuisen, kullalla silatun patsaan päälle, ja niiden kultaiset koukut, neljän hopiajalan päälle.","Ja sinun pitää ripustaman sen neljän sittimipuisen, kullalla silatun patsaan päälle, ja niiden kultaiset koukut, neljän hopiajalan päälle."],[26,33,"Ja sinun pitää ripustaman esiripun koukuille, ja paneman todistusarkin sisälliselle puolen esirippua, niin että esirippu olis teille erotus pyhän ja kaikkein pyhimmän vaiheella.","Ja sinun pitää ripustaman esiripun koukuille, ja paneman todistusarkin sisälliselle puolen esirippua, niin että esirippu olis teille erotus pyhän ja kaikkein pyhimmän vaiheella."],[26,34,"Armo-istuimen pitää sinun myös paneman todistusarkin päälle, kaikkein pyhimpään.","Armo-istuimen pitää sinun myös paneman todistusarkin päälle, kaikkein pyhimpään."],[26,35,"Ja paneman pöydän ulkoiselle puolen esirippua, ja kynttiläjalan pöydän kohdalle, päivän puolelle Tabernaklia, niin että pöytä seisoo pohjaan päin.","Ja paneman pöydän ulkoiselle puolen esirippua, ja kynttiläjalan pöydän kohdalle, päivän puolelle Tabernaklia, niin että pöytä seisoo pohjaan päin."],[26,36,"Ja sinun pitää tekemän peittovaatteen Tabernaklin oveen, sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratusta liinalangasta, taitavasti ommellun.","Ja sinun pitää tekemän peittovaatteen Tabernaklin oveen, sinisistä, purpuraisista ja tulipunaisista villoista, niin myös kalliista kerratusta liinalangasta, taitavasti ommellun."],[26,37,"Tätä peittovaatetta varten pitää sinun tekemän viisi patsasta sittimipuusta ja ne kullalla silaaman, ja koukut pitää oleman kullasta: ja sinun pitää valaman niille viisi vaskista jalkaa.","Tätä peittovaatetta varten pitää sinun tekemän viisi patsasta sittimipuusta ja ne kullalla silaaman, ja koukut pitää oleman kullasta: ja sinun pitää valaman niille viisi vaskista jalkaa."],[27,1,"Ja sinun pitää tekemän myös alttarin sittimipuusta: viisi kyynärää pitää oleman pituuden, ja viisi kyynärää leveyden: neljäkulmaisen pitää sen alttarin oleman, ja kolme kyynärää hänen korkeutensa.","Ja sinun pitää tekemän myös alttarin sittimipuusta: viisi kyynärää pitää oleman pituuden, ja viisi kyynärää leveyden: neljäkulmaisen pitää sen alttarin oleman, ja kolme kyynärää hänen korkeutensa."],[27,2,"Sarvet sinun pitää myös tekemän hänen neljään kulmaansa: siitä pitää hänen sarvensa oleman; ja sinun pitää sen vaskella silaaman.","Sarvet sinun pitää myös tekemän hänen neljään kulmaansa: siitä pitää hänen sarvensa oleman; ja sinun pitää sen vaskella silaaman."],[27,3,"Tee myös hänen patansa, joihin tuhka korjataan, ja lapionsa, ja maljansa, ja tadikkonsa ja hiilikattilansa: kaikki hänen kalunsa pitää sinun vaskesta tekemän.","Tee myös hänen patansa, joihin tuhka korjataan, ja lapionsa, ja maljansa, ja tadikkonsa ja hiilikattilansa: kaikki hänen kalunsa pitää sinun vaskesta tekemän."],[27,4,"Ja sinun pitää myös tekemän hänelle häkin, niinkuin verkon vaskesta, ja tekemän sen verkon päälle neljä vaskirengasta hänen neljään kulmaansa.","Ja sinun pitää myös tekemän hänelle häkin, niinkuin verkon vaskesta, ja tekemän sen verkon päälle neljä vaskirengasta hänen neljään kulmaansa."],[27,5,"Sinun pitää sen paneman alhaalta alttarin ympäri, niin että se häkki ulottuu keskelle alttaria.","Sinun pitää sen paneman alhaalta alttarin ympäri, niin että se häkki ulottuu keskelle alttaria."],[27,6,"Ja sinun pitää tekemän sittimipuiset korennot alttarille, ja silaaman ne vaskella;","Ja sinun pitää tekemän sittimipuiset korennot alttarille, ja silaaman ne vaskella;"],[27,7,"Ja pitää pistämän korennot renkaisiin, niin että korennot ovat kahden puolen alttaria, joilla se kannettaisiin.","Ja pitää pistämän korennot renkaisiin, niin että korennot ovat kahden puolen alttaria, joilla se kannettaisiin."],[27,8,"Ja laudoista pitää sinun sen tekemän, niin että se on tyhjä sisältä: niinkuin sinulle osoitettiin vuorella, niin se tehtämän pitää.","Ja laudoista pitää sinun sen tekemän, niin että se on tyhjä sisältä: niinkuin sinulle osoitettiin vuorella, niin se tehtämän pitää."],[27,9,"Sinun pitää myös tekemän Tabernaklin pihan meren puolelle; ja pihan vaatteet pitää oleman kalliista kerratusta liinasta, sata kyynärää pitää oleman yhden sivun pituus.","Sinun pitää myös tekemän Tabernaklin pihan meren puolelle; ja pihan vaatteet pitää oleman kalliista kerratusta liinasta, sata kyynärää pitää oleman yhden sivun pituus."],[27,10,"Ja hänen patsaitansa pitää oleman kaksikymmentä, kahdenkymmenen vaskijalan päällä, ja patsasten koukut ja heidän vyönsä hopiasta.","Ja hänen patsaitansa pitää oleman kaksikymmentä, kahdenkymmenen vaskijalan päällä, ja patsasten koukut ja heidän vyönsä hopiasta."],[27,11,"Niin myös pohjan puoleen, pituudelle pitää oleman esivaatteet sata kyynärää pitkät, ja kaksikymmentä sen patsasta kahdenkymmenen vaskijalan päällä, patsasten koukut vöinensä hopiasta.","Niin myös pohjan puoleen, pituudelle pitää oleman esivaatteet sata kyynärää pitkät, ja kaksikymmentä sen patsasta kahdenkymmenen vaskijalan päällä, patsasten koukut vöinensä hopiasta."],[27,12,"Mutta pihan laveudelle lännen puoleen pitää oleman vaatteet, viisikymmentä kyynärää pitkät, ja kymmenen patsasta kymmenen jalan päällä.","Mutta pihan laveudelle lännen puoleen pitää oleman vaatteet, viisikymmentä kyynärää pitkät, ja kymmenen patsasta kymmenen jalan päällä."],[27,13,"Ja itään päin, pihan laveuden pitää oleman viisikymmentä kyynärää.","Ja itään päin, pihan laveuden pitää oleman viisikymmentä kyynärää."],[27,14,"Niin että vaatteella yhdellä puolella on viisitoistakymmentä kyynärää: ja kolme patsasta kolmen jalan päällä.","Niin että vaatteella yhdellä puolella on viisitoistakymmentä kyynärää: ja kolme patsasta kolmen jalan päällä."],[27,15,"Ja viisitoistakymmentä kyynärää toisella puolella, siihen myös kolme patsasta kolmen jalan päällä.","Ja viisitoistakymmentä kyynärää toisella puolella, siihen myös kolme patsasta kolmen jalan päällä."],[27,16,"Mutta pihan läpikäytävässä pitää oleman yksi vaate kaksikymmentä kyynärää leviä, sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliista liinalangasta taitavasti ommellun: siihen myös neljä patsasta ja neljän jalan päällä.","Mutta pihan läpikäytävässä pitää oleman yksi vaate kaksikymmentä kyynärää leviä, sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliista liinalangasta taitavasti ommellun: siihen myös neljä patsasta ja neljän jalan päällä."],[27,17,"Kaikilla patsailla ympärinsä pihan pitää oleman hopiavanteet, hopiakoukut, ja vaskiset jalat.","Kaikilla patsailla ympärinsä pihan pitää oleman hopiavanteet, hopiakoukut, ja vaskiset jalat."],[27,18,"Ja pihan pituus pitää oleman sata kyynärää, ja leveys kaikelta kohtaa viisikymmentä, ja korkeus viisi kyynärää, kalliista kerratusta liinasta: ja heidän jalkansa vaskesta.","Ja pihan pituus pitää oleman sata kyynärää, ja leveys kaikelta kohtaa viisikymmentä, ja korkeus viisi kyynärää, kalliista kerratusta liinasta: ja heidän jalkansa vaskesta."],[27,19,"Kaikki Tabernaklin astiat, jotka kaikkinaiseen palvelukseen tarvitaan, kaikki hänen vaarnansa ja kaikki pihan vaarnat pitää oleman vaskesta.","Kaikki Tabernaklin astiat, jotka kaikkinaiseen palvelukseen tarvitaan, kaikki hänen vaarnansa ja kaikki pihan vaarnat pitää oleman vaskesta."],[27,20,"Ja käske Israelin lapsille, että he toisivat sinulle kaikkein selkiämpää öljypuun öljyä puserrettua, valkeudeksi: että lamppu aina palais.","Ja käske Israelin lapsille, että he toisivat sinulle kaikkein selkiämpää öljypuun öljyä puserrettua, valkeudeksi: että lamppu aina palais."],[27,21,"Seurakunnan majassa ulkoisella puolella esirippua, joka on todistuksen edessä, pitää Aaron poikinensa sen toimittaman, (valistamaan) ehtoosta niin aamuun asti, Herran edessä. Se pitää teille oleman ijankaikkinen sääty heidän sukukunnissansa, Israelin lasten seassa.","Seurakunnan majassa ulkoisella puolella esirippua, joka on todistuksen edessä, pitää Aaron poikinensa sen toimittaman, (valistamaan) ehtoosta niin aamuun asti, Herran edessä. Se pitää teille oleman ijankaikkinen sääty heidän sukukunnissansa, Israelin lasten seassa."],[28,1,"Ja sinun pitää ottaman tykös sinun veljes Aaronin poikinensa Israelin lasten seasta, että hän olis minun pappini: Aaron ja hänen poikansa Nadab, Abihu, Eleatsar ja Itamar.","Ja sinun pitää ottaman tykös sinun veljes Aaronin poikinensa Israelin lasten seasta, että hän olis minun pappini: Aaron ja hänen poikansa Nadab, Abihu, Eleatsar ja Itamar."],[28,2,"Ja sinun pitää tekemän veljelles Aaronille pyhät vaatteet, kunniaksi ja kaunistukseksi.","Ja sinun pitää tekemän veljelles Aaronille pyhät vaatteet, kunniaksi ja kaunistukseksi."],[28,3,"Ja sinun pitää myös puhuman kaikkein niiden kanssa, joilla taitava sydän on, jotka minä taidon hengellä täyttänyt olen, että he tekevät vaatteita Aaronille hänen pyhittämiseksensä, että hän olis minun pappini.","Ja sinun pitää myös puhuman kaikkein niiden kanssa, joilla taitava sydän on, jotka minä taidon hengellä täyttänyt olen, että he tekevät vaatteita Aaronille hänen pyhittämiseksensä, että hän olis minun pappini."],[28,4,"Ja nämät ovat vaatteet, jotka heidän tekemän pitää: kilpi, päällisvaate, hame, ahdashame, hiippa ja vyö. Ja näin pitää heidän tekemän sinun veljelles Aaronille ja hänen pojillensa pyhät vaatteet, että hän minun pappini olis.","Ja nämät ovat vaatteet, jotka heidän tekemän pitää: kilpi, päällisvaate, hame, ahdashame, hiippa ja vyö. Ja näin pitää heidän tekemän sinun veljelles Aaronille ja hänen pojillensa pyhät vaatteet, että hän minun pappini olis."],[28,5,"Siihen pitää heidän ottaman kultaa, sinisiä, purpuraisia ja tulipunaisia villoja, ja kallista liinaa.","Siihen pitää heidän ottaman kultaa, sinisiä, purpuraisia ja tulipunaisia villoja, ja kallista liinaa."],[28,6,"Päällisvaatteen pitää heidän tekemän kullasta, ja sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliisti kerratusta liinasta, taitavasti.","Päällisvaatteen pitää heidän tekemän kullasta, ja sinisistä, purpuraisista ja tulipunaisista villoista, ja kalliisti kerratusta liinasta, taitavasti."],[28,7,"Että se yhdistettäisiin molempain olkain päältä ja sidottaisiin yhteen molemmilta puolilta.","Että se yhdistettäisiin molempain olkain päältä ja sidottaisiin yhteen molemmilta puolilta."],[28,8,"Ja hänen päällisvaatteensa vyö, kuin sen päällä on, pitää oleman yhdellä tavalla tehty, kullasta, sinivilloista, purpurasta ja tulipunaisista villoista, ja kalliista kerratusta liinalangasta.","Ja hänen päällisvaatteensa vyö, kuin sen päällä on, pitää oleman yhdellä tavalla tehty, kullasta, sinivilloista, purpurasta ja tulipunaisista villoista, ja kalliista kerratusta liinalangasta."],[28,9,"Ja sinun pitää ottaman kaksi onikin kiveä, ja kaivaman niihin Israelin poikain nimet.","Ja sinun pitää ottaman kaksi onikin kiveä, ja kaivaman niihin Israelin poikain nimet."],[28,10,"Heidän kuusi nimeänsä yhteen kiveen, ja toiset kuusi nimeä toiseen kiveen, sen jälkeen kuin he syntyneet ovat.","Heidän kuusi nimeänsä yhteen kiveen, ja toiset kuusi nimeä toiseen kiveen, sen jälkeen kuin he syntyneet ovat."],[28,11,"Niinkuin kivenvuolia sinetin kaivaa, pitää sinun taitavasti kaivaman niihin kahteen kiveen Israelin lasten nimet, ja ne kultaan sisälle sulkeman.","Niinkuin kivenvuolia sinetin kaivaa, pitää sinun taitavasti kaivaman niihin kahteen kiveen Israelin lasten nimet, ja ne kultaan sisälle sulkeman."],[28,12,"Ja sinun pitää ne molemmat kivet paneman hartioille päällisvaatteeseen, että ne ovat muistokivet Israelin lapsille: ja Aaronin pitää kantaman heidän nimensä Herran edessä molemmilla olillansa muistoksi.","Ja sinun pitää ne molemmat kivet paneman hartioille päällisvaatteeseen, että ne ovat muistokivet Israelin lapsille: ja Aaronin pitää kantaman heidän nimensä Herran edessä molemmilla olillansa muistoksi."],[28,13,"Ja sinun pitää tekemän kultaiset nastat.","Ja sinun pitää tekemän kultaiset nastat."],[28,14,"Ja kahdet vitjat puhtaasta kullasta, joilla päät ovat, pitää sinun tekemän, taitavasti väätyt: ne väätyt vitjat pitää sinun yhdistämän nastoihin.","Ja kahdet vitjat puhtaasta kullasta, joilla päät ovat, pitää sinun tekemän, taitavasti väätyt: ne väätyt vitjat pitää sinun yhdistämän nastoihin."],[28,15,"Virankilven pitää sinun myös tekemän taitavasti, niinkuin päällisvaatteenkin pitää sinun sen tekemän: kullasta, sinisistä ja purpuraisista, ja tulipunaisista villoista, ja kerratusta kalliin liinan langasta sinun sen tekemän pitää.","Virankilven pitää sinun myös tekemän taitavasti, niinkuin päällisvaatteenkin pitää sinun sen tekemän: kullasta, sinisistä ja purpuraisista, ja tulipunaisista villoista, ja kerratusta kalliin liinan langasta sinun sen tekemän pitää."],[28,16,"Neljäkulmaisen pitää sen oleman ja kaksinkertaisen, kämmenen leveys hänen pituutensa, ja kämmenen leveytensä.","Neljäkulmaisen pitää sen oleman ja kaksinkertaisen, kämmenen leveys hänen pituutensa, ja kämmenen leveytensä."],[28,17,"Ja sinun pitää täyttämän sen täyttymys kivillä, neljällä kivirivillä. Ensimäinen rivi pitää oleman sardius, topats, smaragdi.","Ja sinun pitää täyttämän sen täyttymys kivillä, neljällä kivirivillä. Ensimäinen rivi pitää oleman sardius, topats, smaragdi."],[28,18,"Toinen rivi: rubiin, saphiir, demanti.","Toinen rivi: rubiin, saphiir, demanti."],[28,19,"Kolmas rivi: linkurius, akat ja ametisti.","Kolmas rivi: linkurius, akat ja ametisti."],[28,20,"Neljäs rivi: turkos, oniks ja jaspis: kultaan pitää ne istutettaman kaikilta riveiltä.","Neljäs rivi: turkos, oniks ja jaspis: kultaan pitää ne istutettaman kaikilta riveiltä."],[28,21,"Ja ne kivet pitää oleman kahdentoistakymmenen Israelin lasten nimen jälkeen, kaivetut kivenvuolialta jokainen nimeltänsä, kahdentoistakymmenen sukukunnan jälkeen.","Ja ne kivet pitää oleman kahdentoistakymmenen Israelin lasten nimen jälkeen, kaivetut kivenvuolialta jokainen nimeltänsä, kahdentoistakymmenen sukukunnan jälkeen."],[28,22,"Ja sinun pitää tekemän vitjat kilpeen, yhden pituiset, taitavasti väätyt, puhtaasta kullasta.","Ja sinun pitää tekemän vitjat kilpeen, yhden pituiset, taitavasti väätyt, puhtaasta kullasta."],[28,23,"Ja sinun pitää tekemän kilpeen kaksi kultarengasta, ja paneman ne molemmat renkaat kahteen kilven kulmaan.","Ja sinun pitää tekemän kilpeen kaksi kultarengasta, ja paneman ne molemmat renkaat kahteen kilven kulmaan."],[28,24,"Ja pistämään ne kaksi kultavitjaa kahteen renkaaseen kilven kulmiin.","Ja pistämään ne kaksi kultavitjaa kahteen renkaaseen kilven kulmiin."],[28,25,"Mutta ne kaksi päätä niistä kahdesta vitjasta pitää sinun antaman tulla kahteen nastaan, ja paneman päällisvaatteeseen hartioille, toinen toisensa kohdalle.","Mutta ne kaksi päätä niistä kahdesta vitjasta pitää sinun antaman tulla kahteen nastaan, ja paneman päällisvaatteeseen hartioille, toinen toisensa kohdalle."],[28,26,"Ja sinun pitää tekemän kaksi kultaista rengasta, ja paneman ne molempiin kilven kulmiin: sen reunaan sisälliselle puolelle päällisvaatetta.","Ja sinun pitää tekemän kaksi kultaista rengasta, ja paneman ne molempiin kilven kulmiin: sen reunaan sisälliselle puolelle päällisvaatetta."],[28,27,"Ja sinun pitää tekemän kaksi kultarengasta, ja paneman ne päällisvaatteen molemmille olkapäille toinen toisensa kohdalle, alaspäin, sen saumaa vasten, vaatteen vyön päälle.","Ja sinun pitää tekemän kaksi kultarengasta, ja paneman ne päällisvaatteen molemmille olkapäille toinen toisensa kohdalle, alaspäin, sen saumaa vasten, vaatteen vyön päälle."],[28,28,"Ja rintavaate pitää yhdistettämän renkaillansa sinisellä siteellä päällisvaatteen renkaisiin, niin että se olis päällisvaatetta liki, ettei rintavaate eriäis päällisvaatteesta.","Ja rintavaate pitää yhdistettämän renkaillansa sinisellä siteellä päällisvaatteen renkaisiin, niin että se olis päällisvaatetta liki, ettei rintavaate eriäis päällisvaatteesta."],[28,29,"Ja niin pitää Aaronin kantaman Israelin lasten nimet virankilvessä sydämensä päällä, koska hän pyhään sisälle menee, muistoksi Herran edessä alinomaisesti.","Ja niin pitää Aaronin kantaman Israelin lasten nimet virankilvessä sydämensä päällä, koska hän pyhään sisälle menee, muistoksi Herran edessä alinomaisesti."],[28,30,"Ja sinun pitää paneman virankilpeen valkeudet ja täydellisyydet, jotka pitää oleman Aaronin sydämen päällä, koska hän menee Herran eteen. Ja niin pitää Aaronin kantaman Israelin lasten oikeuden sydämensä päällä aina Herran edessä.","Ja sinun pitää paneman virankilpeen valkeudet ja täydellisyydet, jotka pitää oleman Aaronin sydämen päällä, koska hän menee Herran eteen. Ja niin pitää Aaronin kantaman Israelin lasten oikeuden sydämensä päällä aina Herran edessä."],[28,31,"Sinun pitää myös tekemän päällisvaatteen alle hameen, kaiken sinisistä villoista.","Sinun pitää myös tekemän päällisvaatteen alle hameen, kaiken sinisistä villoista."],[28,32,"Ja ylinnä siinä pitää keskellä oleman pään läpi, ja sepalus sen läven ympärillä, pallistettu yhteen niinkuin pantsarin läpi, ettei se kehkiäisi.","Ja ylinnä siinä pitää keskellä oleman pään läpi, ja sepalus sen läven ympärillä, pallistettu yhteen niinkuin pantsarin läpi, ettei se kehkiäisi."],[28,33,"Ja alhaalle hänen liepeisiinsä pitää sinun tekemän niinkuin granatin omenat sinisistä, purpuraisista ja tulipunaisista villoista ympärinsä: ja niiden keskelle kultaiset kulkuiset ympärinsä.","Ja alhaalle hänen liepeisiinsä pitää sinun tekemän niinkuin granatin omenat sinisistä, purpuraisista ja tulipunaisista villoista ympärinsä: ja niiden keskelle kultaiset kulkuiset ympärinsä."],[28,34,"Niin että siinä on kultainen kulkuinen, ja sitälikin granatin omena: ja taas kultainen kulkuinen granatin omenan kanssa, ympärinsä hameen liepeitä.","Niin että siinä on kultainen kulkuinen, ja sitälikin granatin omena: ja taas kultainen kulkuinen granatin omenan kanssa, ympärinsä hameen liepeitä."],[28,35,"Ja Aaron pitää sen päällensä pitämän, koska hän palveluksen tekee, niin että siitä kuullaan kulina, koska hän menee pyhään, Herran eteen, ja hän käy ulos, ettei hän kuolisi.","Ja Aaron pitää sen päällensä pitämän, koska hän palveluksen tekee, niin että siitä kuullaan kulina, koska hän menee pyhään, Herran eteen, ja hän käy ulos, ettei hän kuolisi."],[28,36,"Sinun pitää myös tekemän otsalehden puhtaasta kullasta, ja kaivaman siihen, niinkuin sinetti kaivetaan, HERRAN PYHYYS.","Sinun pitää myös tekemän otsalehden puhtaasta kullasta, ja kaivaman siihen, niinkuin sinetti kaivetaan, HERRAN PYHYYS."],[28,37,"Ja sinun pitää sen sitoman sinisellä langalla, niin että se on hiipan päällä: etisellä puolella hiippaa sen pitää oleman.","Ja sinun pitää sen sitoman sinisellä langalla, niin että se on hiipan päällä: etisellä puolella hiippaa sen pitää oleman."],[28,38,"Ja sen pitää oleman Aaronin otsalla, niin että Aaron kantaa pyhäin vääryyden, kuin Israelin lapset pyhittivät, kaikissa heidän pyhyytensä lahjoissa. Ja se pitää alinomati oleman hänen otsassansa, heille mielisuosioksi Herran edessä.","Ja sen pitää oleman Aaronin otsalla, niin että Aaron kantaa pyhäin vääryyden, kuin Israelin lapset pyhittivät, kaikissa heidän pyhyytensä lahjoissa. Ja se pitää alinomati oleman hänen otsassansa, heille mielisuosioksi Herran edessä."],[28,39,"Sinun pitää myös tekemän ahtaan hameen kalliista liinasta, ja hiipan kalliista liinasta: ja taitavasti ommellun vyön pitää myös tekemän.","Sinun pitää myös tekemän ahtaan hameen kalliista liinasta, ja hiipan kalliista liinasta: ja taitavasti ommellun vyön pitää myös tekemän."],[28,40,"Ja Aaronin pojille pitää sinun tekemän hameita, vöitä ja hiippoja, kunniaksi ja kaunistukseksi.","Ja Aaronin pojille pitää sinun tekemän hameita, vöitä ja hiippoja, kunniaksi ja kaunistukseksi."],[28,41,"Ja sinun pitää ne puettaman veljes Aaronin ja hänen poikainsa ylle, ja pitää voiteleman heitä, ja täyttämän heidän kätensä, ja pyhittämän heitä, että he olisivat minun pappini.","Ja sinun pitää ne puettaman veljes Aaronin ja hänen poikainsa ylle, ja pitää voiteleman heitä, ja täyttämän heidän kätensä, ja pyhittämän heitä, että he olisivat minun pappini."],[28,42,"Ja pitää tekemän heille liinaiset alusvaatteet, peittääksensä häpylihansa: kupeista niin reisiin asti pitää ne oleman.","Ja pitää tekemän heille liinaiset alusvaatteet, peittääksensä häpylihansa: kupeista niin reisiin asti pitää ne oleman."],[28,43,"Ja Aaron poikinensa pitää ne yllänsä pitämän, koska he menevät seurakunnan majaan, eli koska he lähestyvät alttaria palvelusta tekemään pyhässä, ettei heille kostettaisi heidän vääryyttänsä, ja he kuolisi. Se pitää oleman hänelle ja hänen siemenellensä hänen jälkeensä ijankaikkinen sääty.","Ja Aaron poikinensa pitää ne yllänsä pitämän, koska he menevät seurakunnan majaan, eli koska he lähestyvät alttaria palvelusta tekemään pyhässä, ettei heille kostettaisi heidän vääryyttänsä, ja he kuolisi. Se pitää oleman hänelle ja hänen siemenellensä hänen jälkeensä ijankaikkinen sääty."],[29,1,"Ja tämä on se kuin sinun pitää tekemän heille, pyhittääkses heitä, että he olisivat minun pappini: ota yksi nuori mulli, ja kaksi virheetöintä oinasta.","Ja tämä on se kuin sinun pitää tekemän heille, pyhittääkses heitä, että he olisivat minun pappini: ota yksi nuori mulli, ja kaksi virheetöintä oinasta."],[29,2,"Ja happamattomia leipiä ja happamattomia kyrsiä sekoitettuja öljyllä, ja happamattomia ohuita kyrsiä voidelluita öljyllä: nisuisista jauhoista pitää sinun ne tekemän.","Ja happamattomia leipiä ja happamattomia kyrsiä sekoitettuja öljyllä, ja happamattomia ohuita kyrsiä voidelluita öljyllä: nisuisista jauhoista pitää sinun ne tekemän."],[29,3,"Ja sinun pitää paneman ne koriin, ja korissa ne kantaman edes, niin myös mullin ja ne kaksi oinasta.","Ja sinun pitää paneman ne koriin, ja korissa ne kantaman edes, niin myös mullin ja ne kaksi oinasta."],[29,4,"Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heitä vedellä.","Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heitä vedellä."],[29,5,"Ja sinun pitää ottaman vaatteet ja puettaman Aaronin ylle, ahtaan hameen, ja päällisvaate-hameen, ja vyöttämän hänen päällisvaatteen vyöllä.","Ja sinun pitää ottaman vaatteet ja puettaman Aaronin ylle, ahtaan hameen, ja päällisvaate-hameen, ja vyöttämän hänen päällisvaatteen vyöllä."],[29,6,"Sinun pitää myös paneman hiipan hänen päähänsä, ja laskeman pyhän kruunun hiipan päälle;","Sinun pitää myös paneman hiipan hänen päähänsä, ja laskeman pyhän kruunun hiipan päälle;"],[29,7,"Ja ottaman voidellusöljyn, ja vuodattaman hänen päänsä päälle, ja voiteleman häntä.","Ja ottaman voidellusöljyn, ja vuodattaman hänen päänsä päälle, ja voiteleman häntä."],[29,8,"Ja hänen poikainsa anna tulla edes, ja pueta heidän yllensä ahtaat hameet.","Ja hänen poikainsa anna tulla edes, ja pueta heidän yllensä ahtaat hameet."],[29,9,"Ja sinun pitää vyöttämän heidän vyöllä, sekä Aaronin että hänen poikansa, ja paneman hiipat heidän päähänsä, että heillä olis pappeus ijankaikkiseksi säädyksi: ja sinun pitää täyttämän Aaronin käden ja hänen poikainsa käden.","Ja sinun pitää vyöttämän heidän vyöllä, sekä Aaronin että hänen poikansa, ja paneman hiipat heidän päähänsä, että heillä olis pappeus ijankaikkiseksi säädyksi: ja sinun pitää täyttämän Aaronin käden ja hänen poikainsa käden."],[29,10,"Ja sinun pitää tuoman mullin seurakunnan majan eteen: ja Aaronin poikinensa pitää paneman kätensä mullin päälle.","Ja sinun pitää tuoman mullin seurakunnan majan eteen: ja Aaronin poikinensa pitää paneman kätensä mullin päälle."],[29,11,"Niin sinun pitää teurastaman mullin Herran edessä, seurakunnan majan oven tykönä.","Niin sinun pitää teurastaman mullin Herran edessä, seurakunnan majan oven tykönä."],[29,12,"Ja sinun pitää ottaman mullin verestä, ja sivuman sormellas alttarin sarviin; mutta kaikki sen muu veri vuodata alttarin pohjaan.","Ja sinun pitää ottaman mullin verestä, ja sivuman sormellas alttarin sarviin; mutta kaikki sen muu veri vuodata alttarin pohjaan."],[29,13,"Ja sinun pitää ottaman kaiken lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, ja lihavuuden, joka on niiden päällä, ja polttaman alttarilla.","Ja sinun pitää ottaman kaiken lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, ja lihavuuden, joka on niiden päällä, ja polttaman alttarilla."],[29,14,"Mutta mullin lihan ja hänen vuotansa ja rapansa pitää sinun polttaman tulella ulkona leiristä; sillä se on rikosuhri.","Mutta mullin lihan ja hänen vuotansa ja rapansa pitää sinun polttaman tulella ulkona leiristä; sillä se on rikosuhri."],[29,15,"Yhden oinaan pitää sinun myös ottaman: ja Aaronin poikinensa pitää paneman kätensä sen oinaan pään päälle.","Yhden oinaan pitää sinun myös ottaman: ja Aaronin poikinensa pitää paneman kätensä sen oinaan pään päälle."],[29,16,"Ja sinun pitää teurastaman oinaan, ja ottaman hänen verensä, ja priiskottaman alttarille ympärinsä.","Ja sinun pitää teurastaman oinaan, ja ottaman hänen verensä, ja priiskottaman alttarille ympärinsä."],[29,17,"Mutta oinaan pitää sinun leikkaaman kappaleiksi, ja pesemän hänen sisällyksensä ja jalkansa, ja paneman sen hänen kappaltensa ja päänsä päälle.","Mutta oinaan pitää sinun leikkaaman kappaleiksi, ja pesemän hänen sisällyksensä ja jalkansa, ja paneman sen hänen kappaltensa ja päänsä päälle."],[29,18,"Ja polttaman koko oinaan alttarilla; sillä se on polttouhri Herralle: makia haju ja tuli Herralle.","Ja polttaman koko oinaan alttarilla; sillä se on polttouhri Herralle: makia haju ja tuli Herralle."],[29,19,"Toisen oinaan pitää sinun myös ottaman, ja Aaron poikinensa pitää paneman kätensä oinaan pään päälle.","Toisen oinaan pitää sinun myös ottaman, ja Aaron poikinensa pitää paneman kätensä oinaan pään päälle."],[29,20,"Ja sinun pitää teurastaman oinaan ja ottaman hänen verestänsä, ja sivuman Aaronin ja hänen poikainsa oikian korvan lehteen, ja oikian käden peukaloon, ja heidän oikian jalkansa isoon varpaaseen: ja priiskottaman veren alttarille ympärinsä.","Ja sinun pitää teurastaman oinaan ja ottaman hänen verestänsä, ja sivuman Aaronin ja hänen poikainsa oikian korvan lehteen, ja oikian käden peukaloon, ja heidän oikian jalkansa isoon varpaaseen: ja priiskottaman veren alttarille ympärinsä."],[29,21,"Ja sinun pitää ottaman verestä, kuin alttarilla on, ja voidellusöljystä, ja priiskottaman Aaronin ja hänen vaatettensa päälle, ja hänen poikainsa ja heidän vaatettensa päälle: niin hän tulee pyhäksi itse vaatteinensa, ja hänen poikansa vaatteinensa.","Ja sinun pitää ottaman verestä, kuin alttarilla on, ja voidellusöljystä, ja priiskottaman Aaronin ja hänen vaatettensa päälle, ja hänen poikainsa ja heidän vaatettensa päälle: niin hän tulee pyhäksi itse vaatteinensa, ja hänen poikansa vaatteinensa."],[29,22,"Sitte pitää sinun ottaman oinaasta lihavuuden, ja saparon, ja sen lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, niin myös sen lihavuuden kuin niiden päällä on, ja oikian lavan; sillä se on täyttämisen oinas.","Sitte pitää sinun ottaman oinaasta lihavuuden, ja saparon, ja sen lihavuuden kuin sisällykset peittää, ja maksan kalvon, ja molemmat munaskuut, niin myös sen lihavuuden kuin niiden päällä on, ja oikian lavan; sillä se on täyttämisen oinas."],[29,23,"Ja yhden kyrsän leipää, ja yhden öljykyrsän, ja ohuen kyrsän korista, jossa happamattomat leivät ovat Herran edessä.","Ja yhden kyrsän leipää, ja yhden öljykyrsän, ja ohuen kyrsän korista, jossa happamattomat leivät ovat Herran edessä."],[29,24,"Ja sinun pitää paneman kaikki nämät Aaronin ja hänen poikainsa kätten päälle, ja häälyttämän ne häälytykseksi Herralle.","Ja sinun pitää paneman kaikki nämät Aaronin ja hänen poikainsa kätten päälle, ja häälyttämän ne häälytykseksi Herralle."],[29,25,"Ja niin pitää sinun ne ottaman heidän käsistänsä, ja polttaman alttarilla polttouhriksi ja makiaksi hajuksi Herralle; sillä se on Herran tuli.","Ja niin pitää sinun ne ottaman heidän käsistänsä, ja polttaman alttarilla polttouhriksi ja makiaksi hajuksi Herralle; sillä se on Herran tuli."],[29,26,"Ja sinun pitää ottaman rinnan Aaronin täyttämisen oinaasta, ja pitää sen häälyttämän häälytysuhriksi Herran eteen: ja se pitää oleman sinun osas.","Ja sinun pitää ottaman rinnan Aaronin täyttämisen oinaasta, ja pitää sen häälyttämän häälytysuhriksi Herran eteen: ja se pitää oleman sinun osas."],[29,27,"Ja sinun pitää pyhittämän häälytysrinnan ja ylennyslavan, joka häälytetty on ja ylennetty on, Aaronin ja hänen poikainsa täyttämisen oinaasta.","Ja sinun pitää pyhittämän häälytysrinnan ja ylennyslavan, joka häälytetty on ja ylennetty on, Aaronin ja hänen poikainsa täyttämisen oinaasta."],[29,28,"Ja sen pitää oleman Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi Israelin lapsilta; sillä se on ylennysuhri: ja ylennysuhrin pitää oleman Herran oman Israelin lapsilta, heidän kiitosuhrissansa ja ylennysuhrissansa.","Ja sen pitää oleman Aaronille ja hänen pojillensa ijankaikkiseksi säädyksi Israelin lapsilta; sillä se on ylennysuhri: ja ylennysuhrin pitää oleman Herran oman Israelin lapsilta, heidän kiitosuhrissansa ja ylennysuhrissansa."],[29,29,"Mutta Aaronin pyhät vaatteet pitää oleman hänen pojillansa hänen jälkeensä, että heidät pitää niissä voideltaman, ja heidän kätensä täytettämän.","Mutta Aaronin pyhät vaatteet pitää oleman hänen pojillansa hänen jälkeensä, että heidät pitää niissä voideltaman, ja heidän kätensä täytettämän."],[29,30,"Joka hänen pojistansa tulee papiksi hänen siaansa, sen pitää pukeman ne yllensä seitsemän päivää; jonka pitää käymän seurakunnan majaan palvelemaan pyhässä.","Joka hänen pojistansa tulee papiksi hänen siaansa, sen pitää pukeman ne yllensä seitsemän päivää; jonka pitää käymän seurakunnan majaan palvelemaan pyhässä."],[29,31,"Sinun pitää myös ottaman täyttämisen oinaan, ja keittämän sen lihan pyhässä siassa.","Sinun pitää myös ottaman täyttämisen oinaan, ja keittämän sen lihan pyhässä siassa."],[29,32,"Ja Aaronin poikinensa pitää syömän sen oinaan lihan, ja leivän, joka on korissa, seurakunnan majan oven edessä.","Ja Aaronin poikinensa pitää syömän sen oinaan lihan, ja leivän, joka on korissa, seurakunnan majan oven edessä."],[29,33,"Ja niiden pitää ne syömän, jotka niiden kautta sovitetut ovat, täytettää heidän käsiänsä, ja pyhitettää heitä. Ei muukalaisen pidä sitä syömän; sillä se on pyhä.","Ja niiden pitää ne syömän, jotka niiden kautta sovitetut ovat, täytettää heidän käsiänsä, ja pyhitettää heitä. Ei muukalaisen pidä sitä syömän; sillä se on pyhä."],[29,34,"Jos jotakin tähteeksi jää täyttymisen lihasta ja leivästä aamuun asti, sen pitää sinun polttaman tulessa: ei sitä pidä syötämän, sillä se on pyhä.","Jos jotakin tähteeksi jää täyttymisen lihasta ja leivästä aamuun asti, sen pitää sinun polttaman tulessa: ei sitä pidä syötämän, sillä se on pyhä."],[29,35,"Ja näin pitää sinun tekemän Aaronille ja hänen pojillensa, kaiken sen jälkeen kuin minä sinulle käskenyt olen: seitsemän päivää pitää sinun heidän kätensä täyttämän;","Ja näin pitää sinun tekemän Aaronille ja hänen pojillensa, kaiken sen jälkeen kuin minä sinulle käskenyt olen: seitsemän päivää pitää sinun heidän kätensä täyttämän;"],[29,36,"Ja joka päivä teurastaman mullin rikosuhrin sovinnoksi. Ja sinun pitää puhdistaman alttarin, koskas sovintoa uhraat sen päällä, ja voiteleman sen, ettäs sen pyhittäisit.","Ja joka päivä teurastaman mullin rikosuhrin sovinnoksi. Ja sinun pitää puhdistaman alttarin, koskas sovintoa uhraat sen päällä, ja voiteleman sen, ettäs sen pyhittäisit."],[29,37,"Ja seitsemän päivää pitää sinun puhdistaman alttarin, ja pyhittämän sen; ja se alttari pitää oleman kaikkein pyhin. Mitä ikänänsä siihen alttariin tarttuu, se on pyhitetty.","Ja seitsemän päivää pitää sinun puhdistaman alttarin, ja pyhittämän sen; ja se alttari pitää oleman kaikkein pyhin. Mitä ikänänsä siihen alttariin tarttuu, se on pyhitetty."],[29,38,"Ja tämä on se kuin sinun pitää tekemän alttarilla: kaksi vuosikuntaista karitsaa pitää sinun uhraaman joka päivä sen päällä.","Ja tämä on se kuin sinun pitää tekemän alttarilla: kaksi vuosikuntaista karitsaa pitää sinun uhraaman joka päivä sen päällä."],[29,39,"Yhden karitsan aamulla, ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä.","Yhden karitsan aamulla, ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä."],[29,40,"Ja kymmenennen osan jauhoja, sekoitettu neljännekseen hinniä puserretun öljyn kanssa; ja neljänneksen hinniä viinaa juomauhriksi, yhdelle karitsalle.","Ja kymmenennen osan jauhoja, sekoitettu neljännekseen hinniä puserretun öljyn kanssa; ja neljänneksen hinniä viinaa juomauhriksi, yhdelle karitsalle."],[29,41,"Ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä: niinkuin aamullisenkin ruokauhrin ja juomauhrin pitää sinun sen uhraaman Herralle makiaksi hajuksi ja tuleksi.","Ja toisen karitsan pitää sinun uhraaman kahden ehtoon välillä: niinkuin aamullisenkin ruokauhrin ja juomauhrin pitää sinun sen uhraaman Herralle makiaksi hajuksi ja tuleksi."],[29,42,"Tämä on alinomainen polttouhri teidän sukukunnillenne seurakunnan majan oven tykönä Herran edessä, kussa minä olen saapuvilla teille, ja puhun sinulle.","Tämä on alinomainen polttouhri teidän sukukunnillenne seurakunnan majan oven tykönä Herran edessä, kussa minä olen saapuvilla teille, ja puhun sinulle."],[29,43,"Siellä minä Israelin lapsille olen saapuvilla: ja se pyhitetään minun kunniassani.","Siellä minä Israelin lapsille olen saapuvilla: ja se pyhitetään minun kunniassani."],[29,44,"Ja minä pyhitän todistuksen majan alttareinensa, ja pyhitän Aaronin poikinensa minulle papiksi.","Ja minä pyhitän todistuksen majan alttareinensa, ja pyhitän Aaronin poikinensa minulle papiksi."],[29,45,"Ja asun Israelin lasten seassa, ja olen heidän Jumalansa.","Ja asun Israelin lasten seassa, ja olen heidän Jumalansa."],[29,46,"Ja heidän pitää tietämän, että minä olen Herra heidän Jumalansa, joka heidät johdatin Egyptin maalta, että minä asuisin heidän seassansa. Minä olen Herra heidän Jumalansa.","Ja heidän pitää tietämän, että minä olen Herra heidän Jumalansa, joka heidät johdatin Egyptin maalta, että minä asuisin heidän seassansa. Minä olen Herra heidän Jumalansa."],[30,1,"Sinun pitää myös tekemän suitsutusalttarin suitsutettaa: sittimipuusta sinun sen tekemän pitää.","Sinun pitää myös tekemän suitsutusalttarin suitsutettaa: sittimipuusta sinun sen tekemän pitää."],[30,2,"Kyynärä pitää oleman hänen pituutensa ja kyynärä leveytensä: nelikulmaisen pitää sen oleman, ja kaksi kyynärää hänen korkeutensa; siitä myös pitää oleman hänen sarvensa.","Kyynärä pitää oleman hänen pituutensa ja kyynärä leveytensä: nelikulmaisen pitää sen oleman, ja kaksi kyynärää hänen korkeutensa; siitä myös pitää oleman hänen sarvensa."],[30,3,"Ja sinun pitää silaaman sen puhtaalla kullalla, hänen lakensa ja seinänsä ympärinsä, ja sen sarvet. Ja sinun pitää tekemän kultaisen vanteen sen ympärinsä.","Ja sinun pitää silaaman sen puhtaalla kullalla, hänen lakensa ja seinänsä ympärinsä, ja sen sarvet. Ja sinun pitää tekemän kultaisen vanteen sen ympärinsä."],[30,4,"Ja kaksi kultaista rengasta pitää sinun tekemän, molemmille tahoille kahteen hänen kulmaansa vanteen alle, että korennot niihin pistettäisiin, joilla se kannettaisiin.","Ja kaksi kultaista rengasta pitää sinun tekemän, molemmille tahoille kahteen hänen kulmaansa vanteen alle, että korennot niihin pistettäisiin, joilla se kannettaisiin."],[30,5,"Sinun pitää myös tekemän korennot sittimipuusta, ja silaaman ne kullalla.","Sinun pitää myös tekemän korennot sittimipuusta, ja silaaman ne kullalla."],[30,6,"Ja asettaman se esiripun eteen, joka on todistusarkin edessä; armo-istuimen edessä, joka on todistuksen päällä, siellä minä tulen sinun tykös.","Ja asettaman se esiripun eteen, joka on todistusarkin edessä; armo-istuimen edessä, joka on todistuksen päällä, siellä minä tulen sinun tykös."],[30,7,"Ja Aaronin pitää sen päällä polttaman hyvänhajullista suitsutusta: joka aamu koska hän valmistaa kynttilät, pitää hänen sen suitsuttaman.","Ja Aaronin pitää sen päällä polttaman hyvänhajullista suitsutusta: joka aamu koska hän valmistaa kynttilät, pitää hänen sen suitsuttaman."],[30,8,"Niin myös koska Aaron sytyttää kynttilät kahden ehtoon välillä, pitää hänen sen suitsuttaman: sen suitsutuksen pitää oleman alinomaisen Herran edessä, teidän sukukunnissanne.","Niin myös koska Aaron sytyttää kynttilät kahden ehtoon välillä, pitää hänen sen suitsuttaman: sen suitsutuksen pitää oleman alinomaisen Herran edessä, teidän sukukunnissanne."],[30,9,"Ei teidän pidä yhtään muukalaista suitsutusta tekemän sen päällä, eli polttouhria, eli ruokauhria, eikä myös juomauhria uhraaman sen päällä.","Ei teidän pidä yhtään muukalaista suitsutusta tekemän sen päällä, eli polttouhria, eli ruokauhria, eikä myös juomauhria uhraaman sen päällä."],[30,10,"Ja Aaron pitää sen sarvein päällä sovittaman kerran vuodessa: rikosuhrin verestä pitää hänen sen päällä kerran vuodessa sovittaman teidän sukukunnissanne: se on kaikkein pyhin Herralle.","Ja Aaron pitää sen sarvein päällä sovittaman kerran vuodessa: rikosuhrin verestä pitää hänen sen päällä kerran vuodessa sovittaman teidän sukukunnissanne: se on kaikkein pyhin Herralle."],[30,11,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[30,12,"Koska Israelin lapset luettelet, niin heidän pitää itsekunkin sielunsa edestä antaman sovinnon Herralle, koska he luetellaan: ettei heidän päällensä joku rangaistus tulisi, koska he luetellaan.","Koska Israelin lapset luettelet, niin heidän pitää itsekunkin sielunsa edestä antaman sovinnon Herralle, koska he luetellaan: ettei heidän päällensä joku rangaistus tulisi, koska he luetellaan."],[30,13,"Ja pitää jokaisen, joka luvussa on, antaman puolen sikliä, pyhän siklin jälkeen: sikli maksaa kaksikymmentä geraa: puoli sikliä pitää oleman Herran ylennysuhri.","Ja pitää jokaisen, joka luvussa on, antaman puolen sikliä, pyhän siklin jälkeen: sikli maksaa kaksikymmentä geraa: puoli sikliä pitää oleman Herran ylennysuhri."],[30,14,"Joka kahdenkymmenen vuotisen luvussa löydetään ja sen ylitse: sen pitää antaman Herralle ylennysuhrin.","Joka kahdenkymmenen vuotisen luvussa löydetään ja sen ylitse: sen pitää antaman Herralle ylennysuhrin."],[30,15,"Varallisen ei pidä siihen lisäämän, ja köyhän ei pidä vähentämän puolesta siklistä, koska he antavat Herralle ylennysuhrin teidän sieluinne sovinnoksi.","Varallisen ei pidä siihen lisäämän, ja köyhän ei pidä vähentämän puolesta siklistä, koska he antavat Herralle ylennysuhrin teidän sieluinne sovinnoksi."],[30,16,"Ja sinun pitää sovintorahan ottaman Israelin lapsilta, ja antaman sen seurakunnan majan palvelukseksi: ja sen pitää Israelin lapsille muistoksi oleman Herran edessä, että teidän sielunne sovitettaisiin.","Ja sinun pitää sovintorahan ottaman Israelin lapsilta, ja antaman sen seurakunnan majan palvelukseksi: ja sen pitää Israelin lapsille muistoksi oleman Herran edessä, että teidän sielunne sovitettaisiin."],[30,17,"Niin Herra taas puhui Mosekselle, sanoen:","Niin Herra taas puhui Mosekselle, sanoen:"],[30,18,"Sinun pitää myös tekemän vaskisen pesoastian, vaskijalan kanssa, pesemistä varten: ja sen pitää sinun asettaman seurakunnan majan ja alttarin vaiheelle, ja paneman siihen vettä.","Sinun pitää myös tekemän vaskisen pesoastian, vaskijalan kanssa, pesemistä varten: ja sen pitää sinun asettaman seurakunnan majan ja alttarin vaiheelle, ja paneman siihen vettä."],[30,19,"Että Aaron ja hänen poikansa pesisivät siitä kätensä ja jalkansa.","Että Aaron ja hänen poikansa pesisivät siitä kätensä ja jalkansa."],[30,20,"Koska he menevät seurakunnan majaan, pitää heidän itsensä pesemän vedellä, ettei he kuolisi, taikka koska he lähestyvät alttarin tykö palvelemaan Herraa savu-uhrilla.","Koska he menevät seurakunnan majaan, pitää heidän itsensä pesemän vedellä, ettei he kuolisi, taikka koska he lähestyvät alttarin tykö palvelemaan Herraa savu-uhrilla."],[30,21,"Ja heidän pitää pesemän kätensä ja jalkansa, ettei he kuolisi ja se pitää heille oleman ijankaikkiseksi säädyksi, hänelle ja hänen siemenellensä heidän sukukunnissansa.","Ja heidän pitää pesemän kätensä ja jalkansa, ettei he kuolisi ja se pitää heille oleman ijankaikkiseksi säädyksi, hänelle ja hänen siemenellensä heidän sukukunnissansa."],[30,22,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[30,23,"Ota sinulles parhaista kaluista: kaikkein kalliimmasta mirhamista viisisataa sikliä, ja puoli sen vertaa kanelia, kaksisataa ja viisikymmentä, ja myös kalmusta kaksisataa ja viisikymmentä.","Ota sinulles parhaista kaluista: kaikkein kalliimmasta mirhamista viisisataa sikliä, ja puoli sen vertaa kanelia, kaksisataa ja viisikymmentä, ja myös kalmusta kaksisataa ja viisikymmentä."],[30,24,"Mutta kasiaa viisisataa pyhän siklin jälkeen, ja öljyä öljypuusta yksi hin,","Mutta kasiaa viisisataa pyhän siklin jälkeen, ja öljyä öljypuusta yksi hin,"],[30,25,"Ja sinun pitää siitä tekemän pyhän voidellusöljyn, parhaan voiteen apotekarin tavalla: sen pitää pyhän voiteen-öljyn oleman.","Ja sinun pitää siitä tekemän pyhän voidellusöljyn, parhaan voiteen apotekarin tavalla: sen pitää pyhän voiteen-öljyn oleman."],[30,26,"Sillä sinun pitää voiteleman seurakunnan majan, niin myös todistusarkin.","Sillä sinun pitää voiteleman seurakunnan majan, niin myös todistusarkin."],[30,27,"Ja pöydän ja kaikki hänen astiansa, ja kynttiläjalan ja sen astiat, niin myös suitsutusalttarin,","Ja pöydän ja kaikki hänen astiansa, ja kynttiläjalan ja sen astiat, niin myös suitsutusalttarin,"],[30,28,"Polttouhrin alttarin ja kaikki sen astiat, niin myös pesoastian jalkoinensa.","Polttouhrin alttarin ja kaikki sen astiat, niin myös pesoastian jalkoinensa."],[30,29,"Ja sinun pitää ne pyhittämän, ja ne pitää kaikkein pyhimmät oleman: mitä ikänänsä niihin tarttuu, se pitää pyhitetty oleman.","Ja sinun pitää ne pyhittämän, ja ne pitää kaikkein pyhimmät oleman: mitä ikänänsä niihin tarttuu, se pitää pyhitetty oleman."],[30,30,"Aaronin ja hänen poikansa pitää sinun myös voiteleman ja pyhittämän heitä minulle papiksi.","Aaronin ja hänen poikansa pitää sinun myös voiteleman ja pyhittämän heitä minulle papiksi."],[30,31,"Sinun pitää myös puhuman Israelin lapsille, sanoen: tämä öljy pitää oleman minulle pyhä voidellus teidän sukukunnissanne.","Sinun pitää myös puhuman Israelin lapsille, sanoen: tämä öljy pitää oleman minulle pyhä voidellus teidän sukukunnissanne."],[30,32,"Ihmisen ruumiin päälle ei pidä se voidellus vuodatettaman, ja ei teidän pidä myös senkaltaista tekemän; sillä se on pyhä, sentähden pitää myös se teiltä pyhitettämän.","Ihmisen ruumiin päälle ei pidä se voidellus vuodatettaman, ja ei teidän pidä myös senkaltaista tekemän; sillä se on pyhä, sentähden pitää myös se teiltä pyhitettämän."],[30,33,"Se joka tekee senkaltaista voidetta, eli joka panee sitä muukalaisen päälle, se pitää hävitettämän kansoistansa.","Se joka tekee senkaltaista voidetta, eli joka panee sitä muukalaisen päälle, se pitää hävitettämän kansoistansa."],[30,34,"Ja Herra sanoi Mosekselle: ota sinulle hyvänhajullisia kaluja, staktea ja galbania (a); näistä hajavista kaluista, puhtaan pyhän savun (b) kanssa, pitää yhden verran oleman. (a) Bdellium. (b) Ollibanum purum.","Ja Herra sanoi Mosekselle: ota sinulle hyvänhajullisia kaluja, staktea ja galbania (a); näistä hajavista kaluista, puhtaan pyhän savun (b) kanssa, pitää yhden verran oleman. (a) Bdellium. (b) Ollibanum purum."],[30,35,"Sinun pitää siitä tekemän suitsutuksen, apotekarin tavalla: suolatun, puhtaan ja pyhän.","Sinun pitää siitä tekemän suitsutuksen, apotekarin tavalla: suolatun, puhtaan ja pyhän."],[30,36,"Ja sinun pitää sen pieneksi survoman, ja paneman siitä todistuksen eteen seurakunnan majaan, kussa minä olen sinua läsnä: sen pitää teille oleman kaikkein pyhimmän.","Ja sinun pitää sen pieneksi survoman, ja paneman siitä todistuksen eteen seurakunnan majaan, kussa minä olen sinua läsnä: sen pitää teille oleman kaikkein pyhimmän."],[30,37,"Ja senkaltaista suitsutusta ei teidän pidä itsellenne tekemän; mutta tämä pitää oleman sinulle pyhä, Herran edessä.","Ja senkaltaista suitsutusta ei teidän pidä itsellenne tekemän; mutta tämä pitää oleman sinulle pyhä, Herran edessä."],[30,38,"Joka senkaltaista tekee suitsuttaaksensa, se pitää hävitettämän kansoistansa.","Joka senkaltaista tekee suitsuttaaksensa, se pitää hävitettämän kansoistansa."],[31,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[31,2,"Katso, minä kutsuin nimeltänsä Betsaleelin Urin pojan, Hurin pojanpojan, Juudan suvusta.","Katso, minä kutsuin nimeltänsä Betsaleelin Urin pojan, Hurin pojanpojan, Juudan suvusta."],[31,3,"Ja täytin hänen Jumalan hengellä: viisaudella ja kaikkinaisella taidolla:","Ja täytin hänen Jumalan hengellä: viisaudella ja kaikkinaisella taidolla:"],[31,4,"Taitoja ylösajattelemaan, ja tekemään kullasta, ja hopiasta, ja vaskesta,","Taitoja ylösajattelemaan, ja tekemään kullasta, ja hopiasta, ja vaskesta,"],[31,5,"Taitavasti leikkaamaan ja sisälle panemaan kivet, ja taitavasti tekemään puusta kaikkinaista työtä.","Taitavasti leikkaamaan ja sisälle panemaan kivet, ja taitavasti tekemään puusta kaikkinaista työtä."],[31,6,"Ja katso, minä annoin myös hänelle avuksi Oholiabin Ahisamakin pojan, Danin suvusta, ja itsekunkin taitavan sydämeen annoin minä taidon tekemään kaikkia, mitä minä olen sinulle käskenyt:","Ja katso, minä annoin myös hänelle avuksi Oholiabin Ahisamakin pojan, Danin suvusta, ja itsekunkin taitavan sydämeen annoin minä taidon tekemään kaikkia, mitä minä olen sinulle käskenyt:"],[31,7,"Seurakunnan majan ja liiton arkin, ja armo-istuimen, joka sen päällä on, ja kaikki majan astiat,","Seurakunnan majan ja liiton arkin, ja armo-istuimen, joka sen päällä on, ja kaikki majan astiat,"],[31,8,"Pöydän ja sen astiat, ja puhtaan kynttilänjalan, ja kaikki sen kalut, ja myös savu-alttarin.","Pöydän ja sen astiat, ja puhtaan kynttilänjalan, ja kaikki sen kalut, ja myös savu-alttarin."],[31,9,"Polttouhri-alttarin ja kaikki sen kalut, ja myös pesoastian jalkoinensa,","Polttouhri-alttarin ja kaikki sen kalut, ja myös pesoastian jalkoinensa,"],[31,10,"Ja virkavaatteet, ja papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, papin virkaan,","Ja virkavaatteet, ja papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, papin virkaan,"],[31,11,"Voidellusöljyn ja suitsutuksen hajavista kaluista, pyhään: kaiken sen jälkeen, kuin minä olen sinulle käskenyt, pitää heidän tekemän.","Voidellusöljyn ja suitsutuksen hajavista kaluista, pyhään: kaiken sen jälkeen, kuin minä olen sinulle käskenyt, pitää heidän tekemän."],[31,12,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[31,13,"Puhu Israelin lapsille, sanoen: teidän pitää kaiketi pitämän minun sabbatini; sillä se on merkki minun välilläni ja teidän, teidän suvuissanne, että te tietäisitte minun olevan Herran, joka teitä pyhitän.","Puhu Israelin lapsille, sanoen: teidän pitää kaiketi pitämän minun sabbatini; sillä se on merkki minun välilläni ja teidän, teidän suvuissanne, että te tietäisitte minun olevan Herran, joka teitä pyhitän."],[31,14,"Sentähden pitäkäät sabbati; sillä se on teillä pyhä. Joka sen rikkoo, hänen pitää totisesti kuoleman; sillä kuka ikänänsä silloin työtä tekee, sen sielu pitää hävitettämän kansansa seasta.","Sentähden pitäkäät sabbati; sillä se on teillä pyhä. Joka sen rikkoo, hänen pitää totisesti kuoleman; sillä kuka ikänänsä silloin työtä tekee, sen sielu pitää hävitettämän kansansa seasta."],[31,15,"Kuusi päivää pitää työtä tehtämän, mutta seitsemäntenä päivänä on sabbatin lepo, pyhä Herralle: kuka ikänänsä työtä tekee sabbatin päivänä, hänen pitää totisesti kuoleman.","Kuusi päivää pitää työtä tehtämän, mutta seitsemäntenä päivänä on sabbatin lepo, pyhä Herralle: kuka ikänänsä työtä tekee sabbatin päivänä, hänen pitää totisesti kuoleman."],[31,16,"Sentähden pitäkään Israelin lapset sabbatin, että he sen pyhittäisivät, sukukunnissansa ijankaikkiseksi liitoksi.","Sentähden pitäkään Israelin lapset sabbatin, että he sen pyhittäisivät, sukukunnissansa ijankaikkiseksi liitoksi."],[31,17,"Minun ja Israelin lasten välillä on se ijankaikkinen merkki; sillä kuutena päivänä teki Herra taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi, ja virvoitti itsensä.","Minun ja Israelin lasten välillä on se ijankaikkinen merkki; sillä kuutena päivänä teki Herra taivaan ja maan, mutta seitsemäntenä päivänä hän lepäsi, ja virvoitti itsensä."],[31,18,"Ja sitte kuin Herra oli lopettanut puheensa Moseksen kanssa Sinain vuorella, antoi hän hänelle kaksi todistuksen taulua, jotka olivat kivestä, Jumalan sormella kirjoitetut.","Ja sitte kuin Herra oli lopettanut puheensa Moseksen kanssa Sinain vuorella, antoi hän hänelle kaksi todistuksen taulua, jotka olivat kivestä, Jumalan sormella kirjoitetut."],[32,1,"Mutta koska kansa näki, että Moses viipyi tulemasta alas vuorelta, niin he kokoontuivat Aaronia vastaan, ja sanoivat hänelle: nouse, tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidät Egyptin maalta johdatti.","Mutta koska kansa näki, että Moses viipyi tulemasta alas vuorelta, niin he kokoontuivat Aaronia vastaan, ja sanoivat hänelle: nouse, tee meille jumalia, jotka meidän edellämme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidät Egyptin maalta johdatti."],[32,2,"Niin sanoi Aaron heille: reväiskäät kultaiset korvarenkaat, jotka ovat emäntienne korvissa, ja teidän poikainne, ja teidän tyttärenne: ja tuokaat minun tyköni.","Niin sanoi Aaron heille: reväiskäät kultaiset korvarenkaat, jotka ovat emäntienne korvissa, ja teidän poikainne, ja teidän tyttärenne: ja tuokaat minun tyköni."],[32,3,"Niin kaikki kansa repäisi ne kultaiset korvarenkaat, jotka olivat heidän korvissansa: ja toivat Aaronin tykö.","Niin kaikki kansa repäisi ne kultaiset korvarenkaat, jotka olivat heidän korvissansa: ja toivat Aaronin tykö."],[32,4,"Jonka hän otti heidän kädestänsä, ja kuvasi sen kaivinraudalla, ja teki siitä valetun vasikan; ja he sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos.","Jonka hän otti heidän kädestänsä, ja kuvasi sen kaivinraudalla, ja teki siitä valetun vasikan; ja he sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos."],[32,5,"Ja koska Aaron sen näki, rakensi hän alttarin heidän eteensä; ja Aaron huusi ja sanoi: huomenna on Herran juhlapäivä.","Ja koska Aaron sen näki, rakensi hän alttarin heidän eteensä; ja Aaron huusi ja sanoi: huomenna on Herran juhlapäivä."],[32,6,"Ja he varhain aamulla nousivat toisena päivänä, ja he uhrasivat polttouhria, ja kantoivat edes kiitosuhria. Ja kansa istui syömään ja juomaan, ja nousivat mässäämään.","Ja he varhain aamulla nousivat toisena päivänä, ja he uhrasivat polttouhria, ja kantoivat edes kiitosuhria. Ja kansa istui syömään ja juomaan, ja nousivat mässäämään."],[32,7,"Mutta Herra puhui Mosekselle: mene, astu alas; sillä sinun kansas, jonka sinä Egyptin maalta johdatit ulos, turmeli itsensä.","Mutta Herra puhui Mosekselle: mene, astu alas; sillä sinun kansas, jonka sinä Egyptin maalta johdatit ulos, turmeli itsensä."],[32,8,"He äkisti poikkesivat pois siltä tieltä, jonka minä heille käskin. He tekivät itsellensä valetun vasikan, ja kumarsivat sitä, ja uhrasivat sille, ja sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos.","He äkisti poikkesivat pois siltä tieltä, jonka minä heille käskin. He tekivät itsellensä valetun vasikan, ja kumarsivat sitä, ja uhrasivat sille, ja sanoivat: nämät ovat sinun jumalas, Israel, jotka sinun Egyptin maalta johdattivat ulos."],[32,9,"Ja Herra sanoi Mosekselle: minä näin tämän kansan; ja katso, se on niskurikansa.","Ja Herra sanoi Mosekselle: minä näin tämän kansan; ja katso, se on niskurikansa."],[32,10,"Sentähden salli nyt minun vihani julmistua heidän päällensä, että minä hukutan heidät: niin minä teen sinun suureksi kansaksi.","Sentähden salli nyt minun vihani julmistua heidän päällensä, että minä hukutan heidät: niin minä teen sinun suureksi kansaksi."],[32,11,"Mutta Moses rukoili hartaasti Herran Jumalansa edessä, ja sanoi: Herra, miksi sinun vihas julmistuu sinun kansan päälle, jonka Egyptin maalta johdatit ulos, suurella voimalla ja väkevällä kädellä?","Mutta Moses rukoili hartaasti Herran Jumalansa edessä, ja sanoi: Herra, miksi sinun vihas julmistuu sinun kansan päälle, jonka Egyptin maalta johdatit ulos, suurella voimalla ja väkevällä kädellä?"],[32,12,"Miksi Egyptiläiset pitäis puhuman ja sanoman: heidän vahingoksensa hän heitä johdatti ulos, tappaaksensa heitä vuorella, ja hävittääksensä heitä maan päältä? Käänny pois sinun vihas hirmuisuudesta, ja kadu sitä pahaa sinun kansaas vastaan.","Miksi Egyptiläiset pitäis puhuman ja sanoman: heidän vahingoksensa hän heitä johdatti ulos, tappaaksensa heitä vuorella, ja hävittääksensä heitä maan päältä? Käänny pois sinun vihas hirmuisuudesta, ja kadu sitä pahaa sinun kansaas vastaan."],[32,13,"Muista sinun palvelioitas Abrahamia, Isaakia ja Israelia, joille sinä itse kauttas vannoit, ja sanoit heille: minä enennän teidän siemenenne niinkuin taivaan tähdet: ja kaiken tämän maan, josta minä sanoin, annan teidän siemenellenne, ja heidän pitää sen perimän ijankaikkisesti.","Muista sinun palvelioitas Abrahamia, Isaakia ja Israelia, joille sinä itse kauttas vannoit, ja sanoit heille: minä enennän teidän siemenenne niinkuin taivaan tähdet: ja kaiken tämän maan, josta minä sanoin, annan teidän siemenellenne, ja heidän pitää sen perimän ijankaikkisesti."],[32,14,"Niin Herra katui sitä pahaa, jonka hän uhkasi tehdä kansallensa.","Niin Herra katui sitä pahaa, jonka hän uhkasi tehdä kansallensa."],[32,15,"Ja Moses käänsi itsensä, ja astui alas vuorelta, ja hänen kädessänsä oli kaksi todistuksen taulua: ja taulut olivat kirjoitetut molemmilta puolilta.","Ja Moses käänsi itsensä, ja astui alas vuorelta, ja hänen kädessänsä oli kaksi todistuksen taulua: ja taulut olivat kirjoitetut molemmilta puolilta."],[32,16,"Ja taulut olivat Jumalan teko: ja kirjoitus oli myös Jumalan kirjoitus, kaivettu tauluihin.","Ja taulut olivat Jumalan teko: ja kirjoitus oli myös Jumalan kirjoitus, kaivettu tauluihin."],[32,17,"Koska Josua kuuli kansan huudon, sanoi hän Mosekselle: sodan ääni leirissä.","Koska Josua kuuli kansan huudon, sanoi hän Mosekselle: sodan ääni leirissä."],[32,18,"Hän vastasi: ei se ole voittajain, eikä voitettuiden huuto: minä kuulen veisaajain äänen.","Hän vastasi: ei se ole voittajain, eikä voitettuiden huuto: minä kuulen veisaajain äänen."],[32,19,"Ja koska hän lähestyi leiriä, näki hän vasikan ja hypyn. Ja Moseksen viha julmistui, ja heitti pois käsistänsä taulut, ja löi ne rikki vuoren alla.","Ja koska hän lähestyi leiriä, näki hän vasikan ja hypyn. Ja Moseksen viha julmistui, ja heitti pois käsistänsä taulut, ja löi ne rikki vuoren alla."],[32,20,"Hän otti myös vasikan, jonka he tehneet olivat, ja poltti tulella, ja musersi sen tuhaksi; sitte hajoitti hän sen veteen, ja antoi sen Israelin lasten juoda.","Hän otti myös vasikan, jonka he tehneet olivat, ja poltti tulella, ja musersi sen tuhaksi; sitte hajoitti hän sen veteen, ja antoi sen Israelin lasten juoda."],[32,21,"Ja Moses sanoi Aaronille: mitä tämä kansa on sinulle tehnyt, ettäs niin suuren rikoksen saatit heidän päällensä?","Ja Moses sanoi Aaronille: mitä tämä kansa on sinulle tehnyt, ettäs niin suuren rikoksen saatit heidän päällensä?"],[32,22,"Ja Aaron sanoi: älköön minun herrani viha julmistuko: sinä tiedät, että tämä kansa on pahuudessa.","Ja Aaron sanoi: älköön minun herrani viha julmistuko: sinä tiedät, että tämä kansa on pahuudessa."],[32,23,"He sanoivat minulle: tee meille jumalia, jotka meidän edellemme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidän Egyptin maalta johdatti.","He sanoivat minulle: tee meille jumalia, jotka meidän edellemme kävisivät; sillä emme tiedä, mitä tälle miehelle Mosekselle tapahtunut on, joka meidän Egyptin maalta johdatti."],[32,24,"Joille minä sanoin: jolla on kultaa, reväiskään sen pois; ja he antoivat sen minulle, ja minä heitin sen tuleen, ja siitä tuli tämä vasikka.","Joille minä sanoin: jolla on kultaa, reväiskään sen pois; ja he antoivat sen minulle, ja minä heitin sen tuleen, ja siitä tuli tämä vasikka."],[32,25,"Kun Moses näki, että kansa oli paljastettu; sillä Aaron oli heidän paljastanut häväistykseksi heidän vihollisillensa,","Kun Moses näki, että kansa oli paljastettu; sillä Aaron oli heidän paljastanut häväistykseksi heidän vihollisillensa,"],[32,26,"Niin Moses seisoi leirin portissa ja sanoi: joka on Herran oma, se tulkaan minun tyköni; niin kokoontuivat hänen tykönsä kaikki Levin pojat,","Niin Moses seisoi leirin portissa ja sanoi: joka on Herran oma, se tulkaan minun tyköni; niin kokoontuivat hänen tykönsä kaikki Levin pojat,"],[32,27,"Joille hän sanoi: näin sanoo Herra Israelin Jumala: jokainen sitokaan miekan kupeillensa: vaeltakaat lävitse, ja palaitkaat portista niin porttiin leirissä, ja tappakaat itsekukin veljensä, ja kukin ystävänsä, ja kukin lähimmäisensä.","Joille hän sanoi: näin sanoo Herra Israelin Jumala: jokainen sitokaan miekan kupeillensa: vaeltakaat lävitse, ja palaitkaat portista niin porttiin leirissä, ja tappakaat itsekukin veljensä, ja kukin ystävänsä, ja kukin lähimmäisensä."],[32,28,"Niin Levin pojat tekivät Moseksen käskyn jälkeen: ja sinä päivänä lankesi kansasta liki kolmetuhatta miestä.","Niin Levin pojat tekivät Moseksen käskyn jälkeen: ja sinä päivänä lankesi kansasta liki kolmetuhatta miestä."],[32,29,"Moses sanoi: pyhittäkäät tänäpänä teidän kätenne Herralle, itsekukin pojassansa ja veljessänsä, että hän tänäpänä antais teille siunauksen.","Moses sanoi: pyhittäkäät tänäpänä teidän kätenne Herralle, itsekukin pojassansa ja veljessänsä, että hän tänäpänä antais teille siunauksen."],[32,30,"Toisna päivänä sanoi Moses kansalle: te olette tehneet suuren synnin; ja nyt minä astun ylös Herran tykö, jos minä mitämaks taidan sovittaa teidän rikoksenne.","Toisna päivänä sanoi Moses kansalle: te olette tehneet suuren synnin; ja nyt minä astun ylös Herran tykö, jos minä mitämaks taidan sovittaa teidän rikoksenne."],[32,31,"Niin Moses palasi Herran tykö, ja sanoi: minä rukoilen; tämä kansa teki suuren synnin, ja he tekivät itsellensä kultaisia jumalia.","Niin Moses palasi Herran tykö, ja sanoi: minä rukoilen; tämä kansa teki suuren synnin, ja he tekivät itsellensä kultaisia jumalia."],[32,32,"Nyt siis anna heidän rikoksensa anteeksi; mutta jollei, niin pyyhi minut nyt pois sinun kirjastas, jonkas kirjoittanut olet.","Nyt siis anna heidän rikoksensa anteeksi; mutta jollei, niin pyyhi minut nyt pois sinun kirjastas, jonkas kirjoittanut olet."],[32,33,"Ja Herra sanoi Mosekselle: joka minua vastaan syntiä tekee, sen minä pyyhin minun kirjastani.","Ja Herra sanoi Mosekselle: joka minua vastaan syntiä tekee, sen minä pyyhin minun kirjastani."],[32,34,"Niin mene sinä nyt, ja johdata kansa sille sialle, josta minä olen sinulle puhunut: Katsos, minun enkelini käy sinun edelläs. Mutta minun etsikkopäivänäni kostan minä heidän rikoksensa.","Niin mene sinä nyt, ja johdata kansa sille sialle, josta minä olen sinulle puhunut: Katsos, minun enkelini käy sinun edelläs. Mutta minun etsikkopäivänäni kostan minä heidän rikoksensa."],[32,35,"Ja niin löi Herra kansaa; että he olivat tehneet vasikan, jonka Aaron teki.","Ja niin löi Herra kansaa; että he olivat tehneet vasikan, jonka Aaron teki."],[33,1,"Ja Herra puhui Mosekselle: mene täältä, sinä ja kansa, jonkas johdatit Egyptin maalta, sille maalle, kuin minä vannoin Abrahamille, Isaakille ja Jakobille, sanoen: sinun siemenelles minä sen annan,","Ja Herra puhui Mosekselle: mene täältä, sinä ja kansa, jonkas johdatit Egyptin maalta, sille maalle, kuin minä vannoin Abrahamille, Isaakille ja Jakobille, sanoen: sinun siemenelles minä sen annan,"],[33,2,"Ja lähetän sinun edelläs enkelin, ja ajan pois Kanaanealaiset, Amorilaiset, ja Hetiläiset, ja Pheresiläiset, Heviläiset, ja Jebusilaiset,","Ja lähetän sinun edelläs enkelin, ja ajan pois Kanaanealaiset, Amorilaiset, ja Hetiläiset, ja Pheresiläiset, Heviläiset, ja Jebusilaiset,"],[33,3,"Sille maalle, jossa rieskaa ja hunajaa vuotaa; sillä en minä mene sinun kanssas, sillä sinä olet niskuri kansa, etten minä sinua joskus tieltä hukuttaisi.","Sille maalle, jossa rieskaa ja hunajaa vuotaa; sillä en minä mene sinun kanssas, sillä sinä olet niskuri kansa, etten minä sinua joskus tieltä hukuttaisi."],[33,4,"Koska kansa kuuli tämän pahan puheen, tulivat he surulliseksi, ja ei yksikään pukenut kaunistusta yllensä.","Koska kansa kuuli tämän pahan puheen, tulivat he surulliseksi, ja ei yksikään pukenut kaunistusta yllensä."],[33,5,"Ja Herra sanoi Mosekselle: sano Israelin lapsille: te olette niskurikansa, minä tulen äkisti sinun päälles, ja hukutan sinun; riisu siis nyt kaunistukses sinultas, että minä tietäisin, mitä minä sinulle tekisin.","Ja Herra sanoi Mosekselle: sano Israelin lapsille: te olette niskurikansa, minä tulen äkisti sinun päälles, ja hukutan sinun; riisu siis nyt kaunistukses sinultas, että minä tietäisin, mitä minä sinulle tekisin."],[33,6,"Niin riisuivat Israelin lapset kaunistuksensa Horebin vuoren tykönä.","Niin riisuivat Israelin lapset kaunistuksensa Horebin vuoren tykönä."],[33,7,"Moses myös otti majan ja pani sen ylös kauvas leiristä, ja kutsui sen seurakunnan majaksi: ja kuka ikänänsä tahtoi kysyä Herralta, hänen piti menemän seurakunnan majan tykö, joka oli ulkona leiristä.","Moses myös otti majan ja pani sen ylös kauvas leiristä, ja kutsui sen seurakunnan majaksi: ja kuka ikänänsä tahtoi kysyä Herralta, hänen piti menemän seurakunnan majan tykö, joka oli ulkona leiristä."],[33,8,"Ja tapahtui, koska Moses meni majan tykö, niin nousi kaikki kansa, ja itsekukin seisoi majansa ovella, ja he katselivat Moseksen jälkeen siihen asti, että hän tuli majaan.","Ja tapahtui, koska Moses meni majan tykö, niin nousi kaikki kansa, ja itsekukin seisoi majansa ovella, ja he katselivat Moseksen jälkeen siihen asti, että hän tuli majaan."],[33,9,"Ja tapahtui, koska Moses tuli majaan, tuli pilven patsas alas, ja seisoi majan ovella: ja puhutteli Mosesta.","Ja tapahtui, koska Moses tuli majaan, tuli pilven patsas alas, ja seisoi majan ovella: ja puhutteli Mosesta."],[33,10,"Ja koska kaikki kansa näki pilven patsaan seisovan majan oven edessä, niin kaikki kansa nousi ja itsekukin kumarsi itsensä majan ovella.","Ja koska kaikki kansa näki pilven patsaan seisovan majan oven edessä, niin kaikki kansa nousi ja itsekukin kumarsi itsensä majan ovella."],[33,11,"Ja Herra puhutteli Mosesta kasvosta niin kasvoon, niinkuin joku ystävätänsä puhuttelee. Ja koska hän palasi leiriin, niin hänen palveliansa Josua Nunin poika, nuorukainen ei lähtenyt majasta.","Ja Herra puhutteli Mosesta kasvosta niin kasvoon, niinkuin joku ystävätänsä puhuttelee. Ja koska hän palasi leiriin, niin hänen palveliansa Josua Nunin poika, nuorukainen ei lähtenyt majasta."],[33,12,"Ja Moses sanoi Herralle: katso, sinä sanot minulle: johdata tämä kansa, ja et sinä ilmoittanut, kenenkä sinä lähetät minun kanssani; ja kuitenkin sinä sanoit minulle: minä tunnen sinun nimeltäs, ja sinä olet myös armon löytänyt minun edessäni.","Ja Moses sanoi Herralle: katso, sinä sanot minulle: johdata tämä kansa, ja et sinä ilmoittanut, kenenkä sinä lähetät minun kanssani; ja kuitenkin sinä sanoit minulle: minä tunnen sinun nimeltäs, ja sinä olet myös armon löytänyt minun edessäni."],[33,13,"Nyt siis, jos minä muutoin olen armon löytänyt sinun edessäs, niin osota nyt minulle sinun ties, että minä sinut tuntisin ja löytäisin armon sinun edessäs: ja katso kuitenkin, että tämä väki on sinun kansas.","Nyt siis, jos minä muutoin olen armon löytänyt sinun edessäs, niin osota nyt minulle sinun ties, että minä sinut tuntisin ja löytäisin armon sinun edessäs: ja katso kuitenkin, että tämä väki on sinun kansas."],[33,14,"Ja hän sanoi: minun kasvoni käy sinun edelläs, ja minä annan sinulle levon.","Ja hän sanoi: minun kasvoni käy sinun edelläs, ja minä annan sinulle levon."],[33,15,"Ja hän sanoi hänelle: jollei sinun kasvos käy edellä, niin älä vie meitä tästä pois.","Ja hän sanoi hänelle: jollei sinun kasvos käy edellä, niin älä vie meitä tästä pois."],[33,16,"Ja mistä se tässä tietää saadaan, että minä ja sinun kansas olemme löytäneet armon sinun edessäs? Eikö, koskas vaellat meidän kanssamme? että me eroitettaisiin, minä ja sinun kansas, kaikista kansoista, jotka ovat maan piirin päällä.","Ja mistä se tässä tietää saadaan, että minä ja sinun kansas olemme löytäneet armon sinun edessäs? Eikö, koskas vaellat meidän kanssamme? että me eroitettaisiin, minä ja sinun kansas, kaikista kansoista, jotka ovat maan piirin päällä."],[33,17,"Ja Herra sanoi Mosekselle: Ja minä myös tämän teen, niinkuin sinä sanoit; sillä sinä olet löytänyt armon minun edessäni, ja minä tunnen sinun nimeltäs.","Ja Herra sanoi Mosekselle: Ja minä myös tämän teen, niinkuin sinä sanoit; sillä sinä olet löytänyt armon minun edessäni, ja minä tunnen sinun nimeltäs."],[33,18,"Mutta hän sanoi: osota siis minulle sinun kunnias.","Mutta hän sanoi: osota siis minulle sinun kunnias."],[33,19,"Ja hän vastasi: minä annan kaikki minun hyvyyteni käydä sinun kasvois edellä, ja tahdon saarnata Herran nimeä sinun edessäs. Ja minä armaitsen, ja olen laupias, jolle minä laupias olen.","Ja hän vastasi: minä annan kaikki minun hyvyyteni käydä sinun kasvois edellä, ja tahdon saarnata Herran nimeä sinun edessäs. Ja minä armaitsen, ja olen laupias, jolle minä laupias olen."],[33,20,"Ja sanoi taas: et sinä taida nähdä minun kasvojani; sillä ei yksikään ihminen, joka minun näkee, taida elää.","Ja sanoi taas: et sinä taida nähdä minun kasvojani; sillä ei yksikään ihminen, joka minun näkee, taida elää."],[33,21,"Vielä sanoi Herra: katsos, sia on minun tykönäni: siellä pitää sinun seisoman kalliolla.","Vielä sanoi Herra: katsos, sia on minun tykönäni: siellä pitää sinun seisoman kalliolla."],[33,22,"Ja pitää tapahtuman, koska minun kunniani vaeltaa ohitse, niin minä panen sinun kallion rotkoon, ja minä peitän sinun minun kädelläni niinkauvan kuin minä vaellan ohitse.","Ja pitää tapahtuman, koska minun kunniani vaeltaa ohitse, niin minä panen sinun kallion rotkoon, ja minä peitän sinun minun kädelläni niinkauvan kuin minä vaellan ohitse."],[33,23,"Sitte koska minä otan pois minun käteni, saat sinä nähdä minun takaa; vaan minun kasvojani ei taideta nähdä.","Sitte koska minä otan pois minun käteni, saat sinä nähdä minun takaa; vaan minun kasvojani ei taideta nähdä."],[34,1,"Ja Herra sanoi Mosekselle: vuole sinulles kaksi kivistä taulua entisten kaltaista: ja minä kirjoitan niihin tauluihin ne sanat, jotka ensimäisissä tauluissa olivat, jotkas löit rikki.","Ja Herra sanoi Mosekselle: vuole sinulles kaksi kivistä taulua entisten kaltaista: ja minä kirjoitan niihin tauluihin ne sanat, jotka ensimäisissä tauluissa olivat, jotkas löit rikki."],[34,2,"Ole siis huomenna valmis, ja astu varhain Sinain vuorelle, ja seiso siellä minun edessäni vuoren kukkulalla.","Ole siis huomenna valmis, ja astu varhain Sinain vuorelle, ja seiso siellä minun edessäni vuoren kukkulalla."],[34,3,"Vaan älkään yksikään astuko ylös sinun kanssas, älkään myös yksikään koko sillä vuorella näkykö; ja eikä lampaita eikä karjaa pidä kaittaman sen vuoren kohdalla.","Vaan älkään yksikään astuko ylös sinun kanssas, älkään myös yksikään koko sillä vuorella näkykö; ja eikä lampaita eikä karjaa pidä kaittaman sen vuoren kohdalla."],[34,4,"Ja Moses teki kaksi kivistä taulua entisten kaltaista, ja nousi aamulla varhain, ja astui ylös Sinain vuorelle, niinkuin Herra hänen käskenyt oli, ja otti ne kaksi kivistä taulua käteensä.","Ja Moses teki kaksi kivistä taulua entisten kaltaista, ja nousi aamulla varhain, ja astui ylös Sinain vuorelle, niinkuin Herra hänen käskenyt oli, ja otti ne kaksi kivistä taulua käteensä."],[34,5,"Ja Herra astui alas pilvessä, ja seisoi hänen kanssansa siellä, ja saarnasi Herran nimestä.","Ja Herra astui alas pilvessä, ja seisoi hänen kanssansa siellä, ja saarnasi Herran nimestä."],[34,6,"Ja Herra vaelsi hänen kasvoinsa edessä, ja huusi: Herra, Herra Jumala (on) laupias ja armollinen, ja pitkämielinen, suuresta armosta ja totuudesta;","Ja Herra vaelsi hänen kasvoinsa edessä, ja huusi: Herra, Herra Jumala (on) laupias ja armollinen, ja pitkämielinen, suuresta armosta ja totuudesta;"],[34,7,"Joka pitää laupiuden tuhanteen polveen, ja ottaa pois vääryyden, ylitsekäymisen ja synnin: jonka edessä ei yksikään ole viatoin, joka etsii isäin vääryyden ja lasten ja lastenlasten päälle, hamaan kolmanteen ja neljänteen polveen.","Joka pitää laupiuden tuhanteen polveen, ja ottaa pois vääryyden, ylitsekäymisen ja synnin: jonka edessä ei yksikään ole viatoin, joka etsii isäin vääryyden ja lasten ja lastenlasten päälle, hamaan kolmanteen ja neljänteen polveen."],[34,8,"Ja Moses kiiruusti kumarsi itsensä maahan ja rukoili.","Ja Moses kiiruusti kumarsi itsensä maahan ja rukoili."],[34,9,"Ja sanoi: Herra, jos minä olen löytänyt armon sinun edessäs, niin käykään siis Herra meidän kanssamme: sillä tämä on niskuri kansa; että olisit meidän vääryydellemme ja synnillemme armollinen, ja omistaisit meitä sinulles perimiseksi.","Ja sanoi: Herra, jos minä olen löytänyt armon sinun edessäs, niin käykään siis Herra meidän kanssamme: sillä tämä on niskuri kansa; että olisit meidän vääryydellemme ja synnillemme armollinen, ja omistaisit meitä sinulles perimiseksi."],[34,10,"Ja hän sanoi: katso, minä teen liiton kaiken sinun kansas edessä, ja minä myös teen ihmeellisiä tekoja, joidenka kaltaisia ei ikänänsä ennen tehty ole jossakussa maassa, eikä yhdenkään kansan seassa: ja kaiken kansan, joiden seassa sinä olet, pitää näkemän Herran teot; sillä se pitää oleman peljättävä, minkä minä sinun kanssas teen.","Ja hän sanoi: katso, minä teen liiton kaiken sinun kansas edessä, ja minä myös teen ihmeellisiä tekoja, joidenka kaltaisia ei ikänänsä ennen tehty ole jossakussa maassa, eikä yhdenkään kansan seassa: ja kaiken kansan, joiden seassa sinä olet, pitää näkemän Herran teot; sillä se pitää oleman peljättävä, minkä minä sinun kanssas teen."],[34,11,"Pidä se, kuin minä sinulle tänäpänä käsken: katso, minä ajan ulos sinun edestäs Amorilaisen, Kanaanealaisen, Hetiläisen, Pheresiläisen, Heviläisen ja Jebusilaisen.","Pidä se, kuin minä sinulle tänäpänä käsken: katso, minä ajan ulos sinun edestäs Amorilaisen, Kanaanealaisen, Hetiläisen, Pheresiläisen, Heviläisen ja Jebusilaisen."],[34,12,"Kavahda sinuas, ettet sinä tee liittoa sen maan asuvaisten kanssa, johonkas tulet: ettei se olisi sinulle paulaksi teidän keskellänne.","Kavahda sinuas, ettet sinä tee liittoa sen maan asuvaisten kanssa, johonkas tulet: ettei se olisi sinulle paulaksi teidän keskellänne."],[34,13,"Vaan heidän alttarinsa pitää teidän kukistaman, ja heidän kuvansa rikkoman: ja heidän metsistönsä maahan lyömän.","Vaan heidän alttarinsa pitää teidän kukistaman, ja heidän kuvansa rikkoman: ja heidän metsistönsä maahan lyömän."],[34,14,"Sillä ei sinun pidä rukoileman muita jumalia: sillä Herran nimi on kiivoittelia, että hän on kiivas Jumala.","Sillä ei sinun pidä rukoileman muita jumalia: sillä Herran nimi on kiivoittelia, että hän on kiivas Jumala."],[34,15,"Ei sinun pidä joskus tekemän liittoa sen maan asuvaisten kanssa: sillä koska he hauristelevat jumalainsa kanssa, ja uhraavat jumalillensa, ja kutsuvat sinun, ettäs söisit heidän uhristansa,","Ei sinun pidä joskus tekemän liittoa sen maan asuvaisten kanssa: sillä koska he hauristelevat jumalainsa kanssa, ja uhraavat jumalillensa, ja kutsuvat sinun, ettäs söisit heidän uhristansa,"],[34,16,"Ja ottaisit heidän tyttäristänsä sinun pojilles emäntiä; jotka hauristelevat jumalainsa kanssa, ja saattavat sinun poikas myös heidän jumalainsa kanssa hauristelemaan.","Ja ottaisit heidän tyttäristänsä sinun pojilles emäntiä; jotka hauristelevat jumalainsa kanssa, ja saattavat sinun poikas myös heidän jumalainsa kanssa hauristelemaan."],[34,17,"Ei sinun pidä valetuita jumalia tekemän sinulles.","Ei sinun pidä valetuita jumalia tekemän sinulles."],[34,18,"Happamattoman leivän juhlan sinun pitää pitämän. Seitsemän päivää pitää sinun happamatointa leipää syömän, niinkuin minä sinulle käskenyt olen, määrätyllä ajalla Abibin kuulla; sillä sinä olet lähtenyt Egyptistä Abibin kuulla.","Happamattoman leivän juhlan sinun pitää pitämän. Seitsemän päivää pitää sinun happamatointa leipää syömän, niinkuin minä sinulle käskenyt olen, määrätyllä ajalla Abibin kuulla; sillä sinä olet lähtenyt Egyptistä Abibin kuulla."],[34,19,"Kaikki, jotka ensin avaavat äitinsä kohdun, ovat minun: kaikki härkyiset karjasta, ja oinaat lampaista, jotka esikoiset ovat.","Kaikki, jotka ensin avaavat äitinsä kohdun, ovat minun: kaikki härkyiset karjasta, ja oinaat lampaista, jotka esikoiset ovat."],[34,20,"Mutta aasin esikoisen pitää sinun lunastaman lampaalla; jos et sinä lunasta, niin väännä hänen niskansa poikki. Jokaisen esikoisen sinun pojistas pitää sinun lunastaman, ja ei yksikään pidä tyhjin käsin minun eteeni tuleman.","Mutta aasin esikoisen pitää sinun lunastaman lampaalla; jos et sinä lunasta, niin väännä hänen niskansa poikki. Jokaisen esikoisen sinun pojistas pitää sinun lunastaman, ja ei yksikään pidä tyhjin käsin minun eteeni tuleman."],[34,21,"Kuusi päivää pitää sinun työtä tekemän, ja seitsemäntenä päivänä pitää sinun lepäämän: sekä pellon kyntämisestä että niittämisestä pitää sinun lepäämän.","Kuusi päivää pitää sinun työtä tekemän, ja seitsemäntenä päivänä pitää sinun lepäämän: sekä pellon kyntämisestä että niittämisestä pitää sinun lepäämän."],[34,22,"Viikkojuhlan sinun pitää pitämän, ensimäisestä nisun elon uutisesta: ja korjaamisen juhlan, vuoden lopulla.","Viikkojuhlan sinun pitää pitämän, ensimäisestä nisun elon uutisesta: ja korjaamisen juhlan, vuoden lopulla."],[34,23,"Kolmasti vuodessa pitää kaikki miehen puoles näkymän kaikkivaltiaan Herran Israelin Jumalan edessä.","Kolmasti vuodessa pitää kaikki miehen puoles näkymän kaikkivaltiaan Herran Israelin Jumalan edessä."],[34,24,"Sillä minä ajan ulos pakanat sinun edestäs ja levitän sinun maas ääret; ja ei pidä yhdenkään himoitseman sinun maatas, koska sinä menet ylös näyttämään itses Herralle sinun Jumalalles, kolmasti vuodessa.","Sillä minä ajan ulos pakanat sinun edestäs ja levitän sinun maas ääret; ja ei pidä yhdenkään himoitseman sinun maatas, koska sinä menet ylös näyttämään itses Herralle sinun Jumalalles, kolmasti vuodessa."],[34,25,"Ei sinun pidä uhraaman minun uhrini verta happaman leivän ohessa. Ja pääsiäisjuhlan uhrista ei pidä mitään jäämän yön yli huomeneksi.","Ei sinun pidä uhraaman minun uhrini verta happaman leivän ohessa. Ja pääsiäisjuhlan uhrista ei pidä mitään jäämän yön yli huomeneksi."],[34,26,"Ensimäisestä sinun maas kasvon uutisesta pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa hänen emäntänsä rieskassa.","Ensimäisestä sinun maas kasvon uutisesta pitää sinun tuoman sinun Herras Jumalas huoneesen. Ei sinun pidä keittämän vohlaa hänen emäntänsä rieskassa."],[34,27,"Ja Herra sanoi Mosekselle: kirjoita sinulles nämät sanat: sillä näiden sanain jälkeen olen minä liiton tehnyt sinun ja Israelin kanssa.","Ja Herra sanoi Mosekselle: kirjoita sinulles nämät sanat: sillä näiden sanain jälkeen olen minä liiton tehnyt sinun ja Israelin kanssa."],[34,28,"Ja hän oli siellä Herran tykönä neljäkymmentä päivää ja neljäkymmentä yötä, ja ei syönyt leipää, eikä juonut vettä: ja hän kirjoitti tauluihin liiton sanat, ne kymmenet sanat.","Ja hän oli siellä Herran tykönä neljäkymmentä päivää ja neljäkymmentä yötä, ja ei syönyt leipää, eikä juonut vettä: ja hän kirjoitti tauluihin liiton sanat, ne kymmenet sanat."],[34,29,"Koska Moses astui Sinain vuorelta alas, oli hänellä kaksi todistustaulua kädessänsä, astuissansa alas vuorelta: ja ei Moses tietänyt, että hänen kasvonsa nahka paisti siitä, että Herra oli puhutellut häntä.","Koska Moses astui Sinain vuorelta alas, oli hänellä kaksi todistustaulua kädessänsä, astuissansa alas vuorelta: ja ei Moses tietänyt, että hänen kasvonsa nahka paisti siitä, että Herra oli puhutellut häntä."],[34,30,"Ja koska Aaron ja kaikki Israelin lapset näkivät hänen kasvonsa nahan paistavan, pelkäsivät he häntä lähestyä.","Ja koska Aaron ja kaikki Israelin lapset näkivät hänen kasvonsa nahan paistavan, pelkäsivät he häntä lähestyä."],[34,31,"Niin kutsui Moses heitänsä hänen puoleensa, sekä Aaron että kaikki ylimmäiset kansan seasta, ja Moses puhutteli heitä.","Niin kutsui Moses heitänsä hänen puoleensa, sekä Aaron että kaikki ylimmäiset kansan seasta, ja Moses puhutteli heitä."],[34,32,"Sitte lähestyivät kaikki Israelin lapset häntä, ja hän käski heille kaikki ne, mitkä Herra puhui hänen kanssansa Sinain vuorella.","Sitte lähestyivät kaikki Israelin lapset häntä, ja hän käski heille kaikki ne, mitkä Herra puhui hänen kanssansa Sinain vuorella."],[34,33,"Ja että Moses olis tainnut päättää puheensa heidän kanssansa, pani hän peitteen kasvoinsa eteen.","Ja että Moses olis tainnut päättää puheensa heidän kanssansa, pani hän peitteen kasvoinsa eteen."],[34,34,"Mutta koska hän meni sisälle Herran eteen puhuttelemaan häntä, pani hän peitteen pois, niin kauvaksi kuin hän läksi jällensä ulos. Ja koska hän läksi ulos, puhui hän Israelin lapsille, mitä hänelle käsketty oli.","Mutta koska hän meni sisälle Herran eteen puhuttelemaan häntä, pani hän peitteen pois, niin kauvaksi kuin hän läksi jällensä ulos. Ja koska hän läksi ulos, puhui hän Israelin lapsille, mitä hänelle käsketty oli."],[34,35,"Niin katsoivat Israelin lapset hänen kasvoihinsa, kuinka hänen kasvoinsa nahka paisti: niin veti jällensä peitteen kasvoinsa päälle, niinkauvaksi kuin hän jällensä meni puhuttelemaan häntä.","Niin katsoivat Israelin lapset hänen kasvoihinsa, kuinka hänen kasvoinsa nahka paisti: niin veti jällensä peitteen kasvoinsa päälle, niinkauvaksi kuin hän jällensä meni puhuttelemaan häntä."],[35,1,"Ja Moses kokosi kaiken Israelin seurakunnan, ja sanoi heille: nämät ovat ne, mitä Herra käskenyt on teidän tehdä.","Ja Moses kokosi kaiken Israelin seurakunnan, ja sanoi heille: nämät ovat ne, mitä Herra käskenyt on teidän tehdä."],[35,2,"Kuusi päivää pitää työtä tehtämän, mutta seitsemännen päivän pitää teille pyhä oleman, sabbatin lepo Herralle: kuka ikänänsä silloin työtä tekee, sen pitää kuoleman.","Kuusi päivää pitää työtä tehtämän, mutta seitsemännen päivän pitää teille pyhä oleman, sabbatin lepo Herralle: kuka ikänänsä silloin työtä tekee, sen pitää kuoleman."],[35,3,"Ei teidän pidä tulta sytyttämän kaikissa teidän asuinsioissanne sabbatin päivänä.","Ei teidän pidä tulta sytyttämän kaikissa teidän asuinsioissanne sabbatin päivänä."],[35,4,"Ja Moses sanoi kaikille Israelin lasten seurakunnalle: tämä on se, jota Herra käskenyt on, sanoen:","Ja Moses sanoi kaikille Israelin lasten seurakunnalle: tämä on se, jota Herra käskenyt on, sanoen:"],[35,5,"Ottakaat teidän seastanne ylennysuhria Herralle: jokainen, jolla hyväntahtoinen sydän on, tuokaan ylennysuhrin Herralle: kultaa, hopiaa ja vaskea.","Ottakaat teidän seastanne ylennysuhria Herralle: jokainen, jolla hyväntahtoinen sydän on, tuokaan ylennysuhrin Herralle: kultaa, hopiaa ja vaskea."],[35,6,"Sinisiä, purpuraisia ja tulipunaisia villoja, kallista liinaa ja vuohen karvoja,","Sinisiä, purpuraisia ja tulipunaisia villoja, kallista liinaa ja vuohen karvoja,"],[35,7,"Punalla painetuita, oinaan nahkoja, ja tekasjim-nahkoja, sittimipuita,","Punalla painetuita, oinaan nahkoja, ja tekasjim-nahkoja, sittimipuita,"],[35,8,"Öljyä lamppuihin, ja hyvänhajuisia kaluja voidellusöljyyn ja hyvään suitsutukseen,","Öljyä lamppuihin, ja hyvänhajuisia kaluja voidellusöljyyn ja hyvään suitsutukseen,"],[35,9,"Onikin kiviä ja sisälle suljetuita kiviä päällisvaatteesen ja rintavaatteesen.","Onikin kiviä ja sisälle suljetuita kiviä päällisvaatteesen ja rintavaatteesen."],[35,10,"Ja jokainen taitava teidän seassanne tulkaan ja tehkään kaikki mitä Herra käskenyt on:","Ja jokainen taitava teidän seassanne tulkaan ja tehkään kaikki mitä Herra käskenyt on:"],[35,11,"Majan vaatteinensa, peitteinensä, renkainensa, lautoinensa, korentoinensa, patsainensa ja jalkoinensa;","Majan vaatteinensa, peitteinensä, renkainensa, lautoinensa, korentoinensa, patsainensa ja jalkoinensa;"],[35,12,"Arkin korentoinensa, armo-istuimen ja esiripun;","Arkin korentoinensa, armo-istuimen ja esiripun;"],[35,13,"Pöydän korentoinensa ja kaikki sen kalut, niin myös katsomusleivän;","Pöydän korentoinensa ja kaikki sen kalut, niin myös katsomusleivän;"],[35,14,"Kynttiläjalan kaluinensa valistamaan, ja hänen lamppunsa ja öljyä valkeudeksi.","Kynttiläjalan kaluinensa valistamaan, ja hänen lamppunsa ja öljyä valkeudeksi."],[35,15,"Ja savu-alttarin korentoinensa, voidellusöljyn ja hyvänhajavia kaluja suitsutukseen, ja vaatteen majan oven eteen.","Ja savu-alttarin korentoinensa, voidellusöljyn ja hyvänhajavia kaluja suitsutukseen, ja vaatteen majan oven eteen."],[35,16,"Polttouhrin alttarin vaskihäkin kanssa, korennot ja kaikki sen astiat: pesoastian jalkoinensa.","Polttouhrin alttarin vaskihäkin kanssa, korennot ja kaikki sen astiat: pesoastian jalkoinensa."],[35,17,"Pihan vaatteet patsainensa ja jalkoinensa, niin myös vaatteen pihan oven eteen;","Pihan vaatteet patsainensa ja jalkoinensa, niin myös vaatteen pihan oven eteen;"],[35,18,"Majan ja pihan vaarnat köysinensä;","Majan ja pihan vaarnat köysinensä;"],[35,19,"Virkavaatteet pyhän palvelukseen: pyhät vaatteet papille Aaronille, hänen poikainsa vaatteen kanssa, papin virkaan.","Virkavaatteet pyhän palvelukseen: pyhät vaatteet papille Aaronille, hänen poikainsa vaatteen kanssa, papin virkaan."],[35,20,"Silloin meni koko Israelin lasten seurakunta ulos Moseksen kasvoin edestä.","Silloin meni koko Israelin lasten seurakunta ulos Moseksen kasvoin edestä."],[35,21,"Ja tuli jokainen, jonka sydän kehoitettiin, ja jolla oli hyvänsuopainen henki, ja toivat ylennysuhrin Herralle, seurakunnan majan tarpeeksi, ja kaikkeen sen palvelukseen, ja pyhiin vaatteisiin.","Ja tuli jokainen, jonka sydän kehoitettiin, ja jolla oli hyvänsuopainen henki, ja toivat ylennysuhrin Herralle, seurakunnan majan tarpeeksi, ja kaikkeen sen palvelukseen, ja pyhiin vaatteisiin."],[35,22,"Ja tulivat sekä miehet että vaimot, kaikki, joilla oli hyvänsuopainen sydän, ja toivat rannerenkaita, korvarenkaita, sormuksia ja solkia, ja kaikkinaisia kultaisia astioita; toi myös joka mies kultaa häälytysuhriksi Herralle.","Ja tulivat sekä miehet että vaimot, kaikki, joilla oli hyvänsuopainen sydän, ja toivat rannerenkaita, korvarenkaita, sormuksia ja solkia, ja kaikkinaisia kultaisia astioita; toi myös joka mies kultaa häälytysuhriksi Herralle."],[35,23,"Ja jokainen toi, joka tyköänsä löysi sinisiä, ja purpuraisia, ja tulipunaisia villoja, ja kallista liinaa, ja vuohenkarvoja, punalla painetuita oinaan nahkoja, ja tekasjim-nahkoja.","Ja jokainen toi, joka tyköänsä löysi sinisiä, ja purpuraisia, ja tulipunaisia villoja, ja kallista liinaa, ja vuohenkarvoja, punalla painetuita oinaan nahkoja, ja tekasjim-nahkoja."],[35,24,"Jokainen joka hopiaa ja vaskea ylensi, hän sen toi ylennysuhriksi Herralle. Ja jokainen, joka tyköänsä löysi sittimipuita, hän toi niitä kaikkinaiseksi Jumalan palveluksen tarpeeksi.","Jokainen joka hopiaa ja vaskea ylensi, hän sen toi ylennysuhriksi Herralle. Ja jokainen, joka tyköänsä löysi sittimipuita, hän toi niitä kaikkinaiseksi Jumalan palveluksen tarpeeksi."],[35,25,"Ja kaikki taitavat vaimot kehräsivät käsillänsä, ja toivat kehräyksensä sinisistä, ja purpuraisista ja tulipunaisista villoista, ja kalliista liinasta.","Ja kaikki taitavat vaimot kehräsivät käsillänsä, ja toivat kehräyksensä sinisistä, ja purpuraisista ja tulipunaisista villoista, ja kalliista liinasta."],[35,26,"Ja ne vaimot, jotka senkaltaisia töitä taisivat ja siihen olivat hyväntahtoiset, kehräsivät vuohen karvoja.","Ja ne vaimot, jotka senkaltaisia töitä taisivat ja siihen olivat hyväntahtoiset, kehräsivät vuohen karvoja."],[35,27,"Mutta päämiehet toivat onikin kiviä, ja kiinnitettyjä kiviä, päällisvaatteesen ja rintavaatteesen.","Mutta päämiehet toivat onikin kiviä, ja kiinnitettyjä kiviä, päällisvaatteesen ja rintavaatteesen."],[35,28,"Ja hyvänhajullisia yrttejä, ja öljyä valkeudeksi, ja voidellusöljyksi, ja yrttein suitsutukseksi.","Ja hyvänhajullisia yrttejä, ja öljyä valkeudeksi, ja voidellusöljyksi, ja yrttein suitsutukseksi."],[35,29,"Ja niin Israelin lapset toivat hyvällä mielellä, sekä miehet että vaimot kaikkinaiseen tarpeesen, niinkuin Herra Mosekselle käskenyt oli että tehtämän piti.","Ja niin Israelin lapset toivat hyvällä mielellä, sekä miehet että vaimot kaikkinaiseen tarpeesen, niinkuin Herra Mosekselle käskenyt oli että tehtämän piti."],[35,30,"Ja Moses sanoi Israelin lapsille: katsokaat, Herra on kutsunut Betsaleelin nimeltä, Urin pojan, Hurin pojanpojan, Juudan suvusta,","Ja Moses sanoi Israelin lapsille: katsokaat, Herra on kutsunut Betsaleelin nimeltä, Urin pojan, Hurin pojanpojan, Juudan suvusta,"],[35,31,"Ja täyttänyt hänen Jumalan hengellä: taidolla, ymmärryksellä ja tiedolla kaikkinaiseen työhön,","Ja täyttänyt hänen Jumalan hengellä: taidolla, ymmärryksellä ja tiedolla kaikkinaiseen työhön,"],[35,32,"Ja taitavasti ylösajattelemaan sitä, mitä tehdä taidetaan kullasta, hopiasta ja vaskesta,","Ja taitavasti ylösajattelemaan sitä, mitä tehdä taidetaan kullasta, hopiasta ja vaskesta,"],[35,33,"Taitavasti kaivamaan ja sisälle kiinnittämään kalliita kiviä, veistämään puita, ja tekemään taitavasti kaikkinaista visua työtä;","Taitavasti kaivamaan ja sisälle kiinnittämään kalliita kiviä, veistämään puita, ja tekemään taitavasti kaikkinaista visua työtä;"],[35,34,"Ja on antanut taidon hänen sydämeensä opettaa: ynnä Oholiabin Ahisamakin pojan kanssa Danin suvusta.","Ja on antanut taidon hänen sydämeensä opettaa: ynnä Oholiabin Ahisamakin pojan kanssa Danin suvusta."],[35,35,"Ja on täyttänyt heidän sydämensä taidolla, tekemään kaikkinaista visua työtä, kaivamaan, kutomaan ja neulomaan sinisiä, ja purpuraisia ja tulipunaisia villoja, ja kallista liinaa, niin että he tekevät ja ylösajattelevat kaikkinaisia, taitavasti.","Ja on täyttänyt heidän sydämensä taidolla, tekemään kaikkinaista visua työtä, kaivamaan, kutomaan ja neulomaan sinisiä, ja purpuraisia ja tulipunaisia villoja, ja kallista liinaa, niin että he tekevät ja ylösajattelevat kaikkinaisia, taitavasti."],[36,1,"Niin Betsaleel ja Oholiab tekivät työtä, ja jokainen taitava mies, joille Herra oli antanut taidon ja ymmärryksen, tietämään tehdä kaikkea pyhän palveluksen työtä: kaiken sen jälkeen kuin Herra käskenyt oli.","Niin Betsaleel ja Oholiab tekivät työtä, ja jokainen taitava mies, joille Herra oli antanut taidon ja ymmärryksen, tietämään tehdä kaikkea pyhän palveluksen työtä: kaiken sen jälkeen kuin Herra käskenyt oli."],[36,2,"Ja Moses kutsui Betsaleelin ja Oholiabin, ja kaikki taitavat miehet, joiden sydämiin Herra oli taidon antanut: kaikki ne, jotka mielellänsä itsensä taritsivat ja menivät sitä työtä tekemään;","Ja Moses kutsui Betsaleelin ja Oholiabin, ja kaikki taitavat miehet, joiden sydämiin Herra oli taidon antanut: kaikki ne, jotka mielellänsä itsensä taritsivat ja menivät sitä työtä tekemään;"],[36,3,"Ja he ottivat Mosekselta kaikkinaiset ylennykset, jotka Israelin lapset toivat pyhän palveluksen tarpeeksi, että sen piti tehdyksi tuleman: ja he toivat joka aamu hyvämielisen lahjansa hänelle.","Ja he ottivat Mosekselta kaikkinaiset ylennykset, jotka Israelin lapset toivat pyhän palveluksen tarpeeksi, että sen piti tehdyksi tuleman: ja he toivat joka aamu hyvämielisen lahjansa hänelle."],[36,4,"Niin he tulivat kaikki taitavat miehet, jotka kaikkea työtä tekivät pyhän rakennuksessa, itsekukin työstänsä kuin hän teki.","Niin he tulivat kaikki taitavat miehet, jotka kaikkea työtä tekivät pyhän rakennuksessa, itsekukin työstänsä kuin hän teki."],[36,5,"Ja he puhuivat Mosekselle, sanoen: kansa tuo ylen paljon: enemmän kuin tämän palveluksen rakennukseen tarvitaan, jonka Herra on käskenyt tehdä.","Ja he puhuivat Mosekselle, sanoen: kansa tuo ylen paljon: enemmän kuin tämän palveluksen rakennukseen tarvitaan, jonka Herra on käskenyt tehdä."],[36,6,"Niin Moses käski kaikille kuuluttaa leirissä, sanoen: älkään yksikään mies elikkä vaimo enempi tuoko ylennykseksi. Ja niin kansa estettiin tuomasta.","Niin Moses käski kaikille kuuluttaa leirissä, sanoen: älkään yksikään mies elikkä vaimo enempi tuoko ylennykseksi. Ja niin kansa estettiin tuomasta."],[36,7,"Sillä jo oli kalua kyllä kaikkinaiseen tarpeesen kuin tehtämän piti, ja vielä sittekin liiaksi.","Sillä jo oli kalua kyllä kaikkinaiseen tarpeesen kuin tehtämän piti, ja vielä sittekin liiaksi."],[36,8,"Ja niin kaikki taitavat miehet, jotka siinä työssä olivat, tekivät majan kymmenen vaatetta: kalliista kerratusta liinasta, sinisistä, purpuraisista ja tulipunaisista villoista; ynnä Kerubimein kanssa tekivät he ne, taitavasti.","Ja niin kaikki taitavat miehet, jotka siinä työssä olivat, tekivät majan kymmenen vaatetta: kalliista kerratusta liinasta, sinisistä, purpuraisista ja tulipunaisista villoista; ynnä Kerubimein kanssa tekivät he ne, taitavasti."],[36,9,"Ja kunkin vaatteen pituus oli kahdeksankolmattakymmentä kyynärää, ja joka vaatteen leveys neljä kyynärää: yksi mitta oli kaikilla vaatteilla.","Ja kunkin vaatteen pituus oli kahdeksankolmattakymmentä kyynärää, ja joka vaatteen leveys neljä kyynärää: yksi mitta oli kaikilla vaatteilla."],[36,10,"Ja hän yhdisti viisi vaatetta toinen toiseensa, ja taas viisi vaatetta toinen toiseensa.","Ja hän yhdisti viisi vaatetta toinen toiseensa, ja taas viisi vaatetta toinen toiseensa."],[36,11,"Ja teki myös silmukset sinisistä villoista sen ensimäisen vaatteen palteesen sauman kohdalle: ja niin hän myös teki sen äärimäisen vaatteen reunaan toisen sauman kohdalle.","Ja teki myös silmukset sinisistä villoista sen ensimäisen vaatteen palteesen sauman kohdalle: ja niin hän myös teki sen äärimäisen vaatteen reunaan toisen sauman kohdalle."],[36,12,"Viisikymmentä silmusta hän teki ensimäiseen vaatteesen, ja viisikymmentä silmusta toisen vaatteen reunaan, joilla ne toinen toisiinsa yhdistettiin: ja silmukset olivat toinen toisensa kohdalla.","Viisikymmentä silmusta hän teki ensimäiseen vaatteesen, ja viisikymmentä silmusta toisen vaatteen reunaan, joilla ne toinen toisiinsa yhdistettiin: ja silmukset olivat toinen toisensa kohdalla."],[36,13,"Ja hän teki myös viisikymmentä kultaista koukkua, joilla hän vaatteet toinen toiseensa yhdisti, niin että se tuli yhdeksi majaksi.","Ja hän teki myös viisikymmentä kultaista koukkua, joilla hän vaatteet toinen toiseensa yhdisti, niin että se tuli yhdeksi majaksi."],[36,14,"Ja hän teki vaatteet vuohen karvoista, peitteeksi majan päälle: yksitoistakymmentä vaatetta hän niistä teki.","Ja hän teki vaatteet vuohen karvoista, peitteeksi majan päälle: yksitoistakymmentä vaatetta hän niistä teki."],[36,15,"Ja jokaisen vaatteen pituus oli kolmekymmentä kyynärää, ja leveys neljä kyynärää: yksi mitta oli kaikilla yhdellätoistakymmenellä vaatteella.","Ja jokaisen vaatteen pituus oli kolmekymmentä kyynärää, ja leveys neljä kyynärää: yksi mitta oli kaikilla yhdellätoistakymmenellä vaatteella."],[36,16,"Ja yhdisti viisi vaatetta erinänsä, ja kuusi vaatetta erinänsä.","Ja yhdisti viisi vaatetta erinänsä, ja kuusi vaatetta erinänsä."],[36,17,"Ja teki viisikymmentä silmusta äärimäisen vaatteen reunalle, sauman kohdalle, ja teki myös viisikymmentä silmusta toisen vaatteen reunaan, sauman kohdalle.","Ja teki viisikymmentä silmusta äärimäisen vaatteen reunalle, sauman kohdalle, ja teki myös viisikymmentä silmusta toisen vaatteen reunaan, sauman kohdalle."],[36,18,"Ja hän teki viisikymmentä vaskikoukkua, joilla maja yhdistettiin, että se yksi olis.","Ja hän teki viisikymmentä vaskikoukkua, joilla maja yhdistettiin, että se yksi olis."],[36,19,"Ja teki peitteen majan päälle, punalla painetuista oinaan nahoista, ja vielä peitteen sen päälle tekasjimnahoista.","Ja teki peitteen majan päälle, punalla painetuista oinaan nahoista, ja vielä peitteen sen päälle tekasjimnahoista."],[36,20,"Ja teki majan laudat sittimipuista, pystyälle olemaan.","Ja teki majan laudat sittimipuista, pystyälle olemaan."],[36,21,"Jokaisen laudan pituus oli kymmenen kyynärää, ja leveys puolitoista kyynärää.","Jokaisen laudan pituus oli kymmenen kyynärää, ja leveys puolitoista kyynärää."],[36,22,"Jokaiseen lautaan teki hän kaksi vaarnaa, joilla ne toinen toiseensa liitettiin: niin teki hän kaikki majan laudat.","Jokaiseen lautaan teki hän kaksi vaarnaa, joilla ne toinen toiseensa liitettiin: niin teki hän kaikki majan laudat."],[36,23,"Ja hän teki ne majan laudat, niin että kaksikymmentä lautaa seisoi etelään päin.","Ja hän teki ne majan laudat, niin että kaksikymmentä lautaa seisoi etelään päin."],[36,24,"Ja teki neljäkymmentä hopiajalkaa kahdenkymmenen laudan alle: joka laudan alle kaksi jalkaa, aina kahden vaarnan kanssa.","Ja teki neljäkymmentä hopiajalkaa kahdenkymmenen laudan alle: joka laudan alle kaksi jalkaa, aina kahden vaarnan kanssa."],[36,25,"Hän teki myös toiselle sivulle majaa, pohjan puolelle, kaksikymmentä lautaa,","Hän teki myös toiselle sivulle majaa, pohjan puolelle, kaksikymmentä lautaa,"],[36,26,"Neljänkymmenen hopiajalan kanssa: aina kaksi jalkaa kunkin laudan alle.","Neljänkymmenen hopiajalan kanssa: aina kaksi jalkaa kunkin laudan alle."],[36,27,"Mutta perälle majaa, länteen päin, teki hän kuusi lautaa,","Mutta perälle majaa, länteen päin, teki hän kuusi lautaa,"],[36,28,"Ja teki kaksi muuta lautaa majan kulmille, molemmille sivuille.","Ja teki kaksi muuta lautaa majan kulmille, molemmille sivuille."],[36,29,"Niin että kumpikin niistä tuli yhteen alhaalta; niin myös ylhäältä yhdistettiin ne yhdellä renkaalla: niin hän teki niille molemmille kulmille.","Niin että kumpikin niistä tuli yhteen alhaalta; niin myös ylhäältä yhdistettiin ne yhdellä renkaalla: niin hän teki niille molemmille kulmille."],[36,30,"Ja oli kahdeksan lautaa, ja kuusitoistakymmentä hopiajalkaa: aina kaksi jalkaa yhden laudan alla.","Ja oli kahdeksan lautaa, ja kuusitoistakymmentä hopiajalkaa: aina kaksi jalkaa yhden laudan alla."],[36,31,"Niin teki hän myös korennot sittimipuusta: viisi niihin lautoihin, jotka olivat yhdellä puolella majaa.","Niin teki hän myös korennot sittimipuusta: viisi niihin lautoihin, jotka olivat yhdellä puolella majaa."],[36,32,"Ja viisi korentoa niihin lautoihin, jotka olivat toisella puolella majaa, ja taas viisi korentoa niihin lautoihin, jotka olivat kahden puolen majaa länteen päin.","Ja viisi korentoa niihin lautoihin, jotka olivat toisella puolella majaa, ja taas viisi korentoa niihin lautoihin, jotka olivat kahden puolen majaa länteen päin."],[36,33,"Ja teki keskimäisen korennon, niin että se piti lautain keskeltä sisälle sysättämän, yhdestä kulmasta toiseen.","Ja teki keskimäisen korennon, niin että se piti lautain keskeltä sisälle sysättämän, yhdestä kulmasta toiseen."],[36,34,"Ja silasi laudat päältä kullalla, mutta heidän renkaansa teki hän kullasta, joihinka korennot pistettiin: ja silasi myös korennot kullalla.","Ja silasi laudat päältä kullalla, mutta heidän renkaansa teki hän kullasta, joihinka korennot pistettiin: ja silasi myös korennot kullalla."],[36,35,"Hän teki myös esiripun, sinisistä, purpuraisista ja tulipunaisista villoista ja kalliista kerratusta liinasta: hän teki myös Kerubimin sen päälle taitavasti.","Hän teki myös esiripun, sinisistä, purpuraisista ja tulipunaisista villoista ja kalliista kerratusta liinasta: hän teki myös Kerubimin sen päälle taitavasti."],[36,36,"Ja teki siihen neljä patsasta sittimipuusta, ja silasi ne kullalla, ja niiden koukut kullasta, ja valoi niille neljä hopiajalkaa.","Ja teki siihen neljä patsasta sittimipuusta, ja silasi ne kullalla, ja niiden koukut kullasta, ja valoi niille neljä hopiajalkaa."],[36,37,"Ja teki vaatteen majan oven eteen, sinisistä, ja purpuraisista, ja tulipunaisista villoista, ja valkiasta kerratusta liinasta: taitavasti neulotun.","Ja teki vaatteen majan oven eteen, sinisistä, ja purpuraisista, ja tulipunaisista villoista, ja valkiasta kerratusta liinasta: taitavasti neulotun."],[36,38,"Ja viisi patsasta heidän koukkuinsa kanssa, ja silasi niiden päät, ja heidän vanteensa kullalla: ja niiden viisi vaskijalkaa.","Ja viisi patsasta heidän koukkuinsa kanssa, ja silasi niiden päät, ja heidän vanteensa kullalla: ja niiden viisi vaskijalkaa."],[37,1,"Ja Betsaleel teki arkin sittimipuusta: puolikolmatta kyynärää pitkän, puolitoista kyynärää leviän, ja puolitoista kyynärää korkian.","Ja Betsaleel teki arkin sittimipuusta: puolikolmatta kyynärää pitkän, puolitoista kyynärää leviän, ja puolitoista kyynärää korkian."],[37,2,"Ja silasi sen puhtaalla kullalla, sekä sisältä että ulkoa, ja teki sen ympärille kultaisen vanteen.","Ja silasi sen puhtaalla kullalla, sekä sisältä että ulkoa, ja teki sen ympärille kultaisen vanteen."],[37,3,"Ja valoi neljä kultarengasta hänen neljään kulmaansa: kaksi rengasta yhdelle puolelle, ja myös kaksi rengasta toiselle puolelle.","Ja valoi neljä kultarengasta hänen neljään kulmaansa: kaksi rengasta yhdelle puolelle, ja myös kaksi rengasta toiselle puolelle."],[37,4,"Ja teki korennot sittimipuusta, ja silasi ne kullalla.","Ja teki korennot sittimipuusta, ja silasi ne kullalla."],[37,5,"Ja pisti ne korennot renkaisiin arkin sivulle, niin että arkki taidettiin kannettaa.","Ja pisti ne korennot renkaisiin arkin sivulle, niin että arkki taidettiin kannettaa."],[37,6,"Ja hän teki armo-istuimen puhtaasta kullasta, puolikolmatta kyynärää pitkän ja puolitoista kyynärää leviän.","Ja hän teki armo-istuimen puhtaasta kullasta, puolikolmatta kyynärää pitkän ja puolitoista kyynärää leviän."],[37,7,"Ja teki kaksi Kerubimia kullasta: vahvaa tekoa, molempiin päihin armo-istuinta.","Ja teki kaksi Kerubimia kullasta: vahvaa tekoa, molempiin päihin armo-istuinta."],[37,8,"Yhden Kerubimin tähän päähän, ja toisen Kerubimin toiseen päähän: molempiin päihin armo-istuinta hän teki Kerubimit.","Yhden Kerubimin tähän päähän, ja toisen Kerubimin toiseen päähän: molempiin päihin armo-istuinta hän teki Kerubimit."],[37,9,"Ja Kerubimit levittivät siipensä sen ylitse, ja peittivät armo-istuimen siivillänsä, ja heidän kasvonsa olivat toinen toisensa puoleen: armo-istuimeen päin olivat Kerubimien kasvot.","Ja Kerubimit levittivät siipensä sen ylitse, ja peittivät armo-istuimen siivillänsä, ja heidän kasvonsa olivat toinen toisensa puoleen: armo-istuimeen päin olivat Kerubimien kasvot."],[37,10,"Hän teki myös pöydän sittimipuusta, kaksi kyynärää pitkäksi, kyynärää leviäksi, ja puolitoista kyynärää korkiaksi.","Hän teki myös pöydän sittimipuusta, kaksi kyynärää pitkäksi, kyynärää leviäksi, ja puolitoista kyynärää korkiaksi."],[37,11,"Ja silasi sen puhtaalla kullalla, ja teki kultaisen vanteen sen ympärille.","Ja silasi sen puhtaalla kullalla, ja teki kultaisen vanteen sen ympärille."],[37,12,"Ja teki partaan sen ympärille kämmentä leviän: teki myös kultaisen vanteen partaan ympärille.","Ja teki partaan sen ympärille kämmentä leviän: teki myös kultaisen vanteen partaan ympärille."],[37,13,"Ja valoi siihen neljä kultaista rengasta, ja pani ne renkaat neljälle kulmalle heidän neljän jalkansa päälle.","Ja valoi siihen neljä kultaista rengasta, ja pani ne renkaat neljälle kulmalle heidän neljän jalkansa päälle."],[37,14,"Juuri partaan kohdalla olivat renkaat, joissa korennot olivat sisällä, joilla pöytä kannettiin.","Juuri partaan kohdalla olivat renkaat, joissa korennot olivat sisällä, joilla pöytä kannettiin."],[37,15,"Ja hän teki myös korennot sittimipuusta, ja silasi ne kullalla, että pöytä niillä kannettaa taidettiin.","Ja hän teki myös korennot sittimipuusta, ja silasi ne kullalla, että pöytä niillä kannettaa taidettiin."],[37,16,"Hän teki myös pöytäastiat, vadit, lusikat, ja maljat, ja pikarit, joilla ulos ja sisälle kaadettiin, puhtaasta kullasta.","Hän teki myös pöytäastiat, vadit, lusikat, ja maljat, ja pikarit, joilla ulos ja sisälle kaadettiin, puhtaasta kullasta."],[37,17,"Hän teki myös kynttiläjalan puhtaasta kullasta: vahvan tekoiseksi hän kynttiläjalan teki ja hänen vartensa, haaransa, maljansa, nuppinsa ja kukkaisensa olivat siitä samasta.","Hän teki myös kynttiläjalan puhtaasta kullasta: vahvan tekoiseksi hän kynttiläjalan teki ja hänen vartensa, haaransa, maljansa, nuppinsa ja kukkaisensa olivat siitä samasta."],[37,18,"Kuusi haaraa kävi hänen kyljestänsä: kolme haaraa kynttiläjalan yhdeltä sivulta, ja myös kolme haaraa sen toiselta sivulta.","Kuusi haaraa kävi hänen kyljestänsä: kolme haaraa kynttiläjalan yhdeltä sivulta, ja myös kolme haaraa sen toiselta sivulta."],[37,19,"Kolme mandelin-muotoista maljaa oli sen yhdessä haarassa, ja yksi nuppi ja kukkainen, niin myös kolme mandelin-kaltaista maljaa toisessa haarassa, yksi nuppi ja kukkainen: niin oli niissä kuudessa haarassa, jotka kynttiläjalasta uloskävivät.","Kolme mandelin-muotoista maljaa oli sen yhdessä haarassa, ja yksi nuppi ja kukkainen, niin myös kolme mandelin-kaltaista maljaa toisessa haarassa, yksi nuppi ja kukkainen: niin oli niissä kuudessa haarassa, jotka kynttiläjalasta uloskävivät."],[37,20,"Mutta kynttiläjalassa oli neljä mandelin-muotoista maljaa toisessa haarassa, nuppeinsa ja kukkaistensa kanssa,","Mutta kynttiläjalassa oli neljä mandelin-muotoista maljaa toisessa haarassa, nuppeinsa ja kukkaistensa kanssa,"],[37,21,"Niin että nuppi oli siinä kahden haaran alla, ja taas nuppi (toisen) kahden haaran alla, ja vielä nuppi kahden jälkimmäisen haaran alla: nimittäin niissä kuudessa haarassa, jotka siitä uloskävivät,","Niin että nuppi oli siinä kahden haaran alla, ja taas nuppi (toisen) kahden haaran alla, ja vielä nuppi kahden jälkimmäisen haaran alla: nimittäin niissä kuudessa haarassa, jotka siitä uloskävivät,"],[37,22,"Ja hänen nuppinsa ja haaransa sen päällä, ja se kaikki oli puhtaasta lujasta kullasta.","Ja hänen nuppinsa ja haaransa sen päällä, ja se kaikki oli puhtaasta lujasta kullasta."],[37,23,"Ja hän teki myös seitsemän lamppua: ja heidän niistimensä ja sammutuskalunsa olivat puhtaasta kullasta.","Ja hän teki myös seitsemän lamppua: ja heidän niistimensä ja sammutuskalunsa olivat puhtaasta kullasta."],[37,24,"Ja hän teki sen, kaikkein astiainsa kanssa, yhdestä leiviskästä puhdasta kultaa.","Ja hän teki sen, kaikkein astiainsa kanssa, yhdestä leiviskästä puhdasta kultaa."],[37,25,"Hän teki myös suitsutusalttarin sittimipuusta: yhtä kyynärää pitkän ja yhtä kyynärää leviän, juuri nelikulmaiseksi, ja kaksi kyynärää korkian; siitä uloskävivät hänen sarvensa.","Hän teki myös suitsutusalttarin sittimipuusta: yhtä kyynärää pitkän ja yhtä kyynärää leviän, juuri nelikulmaiseksi, ja kaksi kyynärää korkian; siitä uloskävivät hänen sarvensa."],[37,26,"Ja silasi sen puhtaalla kullalla, sen katon ja seinät ympärinsä, ja sen sarvet: ja teki sen ympärille vanteen kullasta,","Ja silasi sen puhtaalla kullalla, sen katon ja seinät ympärinsä, ja sen sarvet: ja teki sen ympärille vanteen kullasta,"],[37,27,"Ja kaksi kultaista rengasta vanteen alle molemmin puolin, niin että korennot siihen sysättiin, kannettaa niillä.","Ja kaksi kultaista rengasta vanteen alle molemmin puolin, niin että korennot siihen sysättiin, kannettaa niillä."],[37,28,"Ja korennot hän teki sittimipuusta, ja silasi ne kullalla.","Ja korennot hän teki sittimipuusta, ja silasi ne kullalla."],[37,29,"Ja teki pyhän voidellusöljyn ja puhtaan suitsutuksen, hyvänhajullisista yrteistä, apotekarin tavan jälkeen.","Ja teki pyhän voidellusöljyn ja puhtaan suitsutuksen, hyvänhajullisista yrteistä, apotekarin tavan jälkeen."],[38,1,"Ja teki myös polttouhrin alttarin sittimipuusta, viisi kyynärää pitkän ja viisi kyynärää leviän, juuri nelikulmaiseksi, ja kolme kyynärää korkiaksi.","Ja teki myös polttouhrin alttarin sittimipuusta, viisi kyynärää pitkän ja viisi kyynärää leviän, juuri nelikulmaiseksi, ja kolme kyynärää korkiaksi."],[38,2,"Ja teki neljä sarvea sen neljän kulman päälle: siitä olivat hänen sarvensa; ja silasi sen vaskella.","Ja teki neljä sarvea sen neljän kulman päälle: siitä olivat hänen sarvensa; ja silasi sen vaskella."],[38,3,"Ja teki kaikkinaiset alttarin astiat, tuhka-astiat, lapiot, maljat, hangot, hiiliastiat: kaikki astiat teki hän vaskesta.","Ja teki kaikkinaiset alttarin astiat, tuhka-astiat, lapiot, maljat, hangot, hiiliastiat: kaikki astiat teki hän vaskesta."],[38,4,"Ja teki alttarin ympärille vaskihäkin niinkuin verkon, maasta niin puolialttariin.","Ja teki alttarin ympärille vaskihäkin niinkuin verkon, maasta niin puolialttariin."],[38,5,"Ja valoi neljä rengasta neljään vaskihäkin kulmiin, että korennot niihin pistettiin.","Ja valoi neljä rengasta neljään vaskihäkin kulmiin, että korennot niihin pistettiin."],[38,6,"Ja teki korennot sittimipuusta, ja silasi ne vaskella,","Ja teki korennot sittimipuusta, ja silasi ne vaskella,"],[38,7,"Ja pani renkaisiin alttarin sivulle, joilla se kannettiin. Ja teki laudoista, avojammaksi sisältä.","Ja pani renkaisiin alttarin sivulle, joilla se kannettiin. Ja teki laudoista, avojammaksi sisältä."],[38,8,"Ja hän teki pesoastian vaskesta, ja sen jalan myös vaskesta, niiden vaimoin peileistä, jotka palvelivat seurakunnan majan oven edessä.","Ja hän teki pesoastian vaskesta, ja sen jalan myös vaskesta, niiden vaimoin peileistä, jotka palvelivat seurakunnan majan oven edessä."],[38,9,"Ja hän teki pihan etelään päin, ja pihan vaatteet valkiasta kerratusta liinasta, sata kyynärää pitkäksi,","Ja hän teki pihan etelään päin, ja pihan vaatteet valkiasta kerratusta liinasta, sata kyynärää pitkäksi,"],[38,10,"Hänen kahdenkymmenen patsastensa ja kahdenkymmenen jalkainsa kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta.","Hänen kahdenkymmenen patsastensa ja kahdenkymmenen jalkainsa kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta."],[38,11,"Niin myös pohjaa päin sata kyynärää, kahdenkymmenen patsaan ja kahdenkymmenen jalan kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta.","Niin myös pohjaa päin sata kyynärää, kahdenkymmenen patsaan ja kahdenkymmenen jalan kanssa vaskesta, mutta heidän koukkunsa ja vyönsä hopiasta."],[38,12,"Mutta lännen puolella olivat vaatteet viisikymmentä kyynärää, kymmenen patsaansa ja kymmenen jalkansa kanssa, mutta heidän koukkunsa ja vyönsä hopiasta;","Mutta lännen puolella olivat vaatteet viisikymmentä kyynärää, kymmenen patsaansa ja kymmenen jalkansa kanssa, mutta heidän koukkunsa ja vyönsä hopiasta;"],[38,13,"Mutta itää päin viisikymmentä kyynärää:","Mutta itää päin viisikymmentä kyynärää:"],[38,14,"Vaatteet viisitoistakymmentä kyynärää sivulla: kolmen patsaan ja kolmen jalan kanssa.","Vaatteet viisitoistakymmentä kyynärää sivulla: kolmen patsaan ja kolmen jalan kanssa."],[38,15,"Ja toisella sivulla molemmin puolin, pihan läpikäytävän tykönä, olivat vaatteet viisitoistakymmentä kyynärää: heidän kolmen patsaansa ja jalkansa kanssa.","Ja toisella sivulla molemmin puolin, pihan läpikäytävän tykönä, olivat vaatteet viisitoistakymmentä kyynärää: heidän kolmen patsaansa ja jalkansa kanssa."],[38,16,"Ja kaikki pihan vaatteet ympärinsä olivat valkiasta kerratusta liinasta,","Ja kaikki pihan vaatteet ympärinsä olivat valkiasta kerratusta liinasta,"],[38,17,"Ja patsasten jalat vaskesta, ja heidän koukkunsa ja vyönsä hopiasta, niin että heidän nuppinsa olivat silatut hopialla: ja kaikki myös ne pihan patsaat olivat vyötetyt hopiavyöllä.","Ja patsasten jalat vaskesta, ja heidän koukkunsa ja vyönsä hopiasta, niin että heidän nuppinsa olivat silatut hopialla: ja kaikki myös ne pihan patsaat olivat vyötetyt hopiavyöllä."],[38,18,"Ja peitevaatteet pihan sisällekäytävään teki hän sinisistä ja purpuraisista ja tulipunaisista villoista, ja valkiasta kerratusta liinasta, taitavasti neulotut, kaksikymmentä kyynärää pitkäksi, ja viisi kyynärää korkiaksi leveydessä pihan vaatteen kohdalla,","Ja peitevaatteet pihan sisällekäytävään teki hän sinisistä ja purpuraisista ja tulipunaisista villoista, ja valkiasta kerratusta liinasta, taitavasti neulotut, kaksikymmentä kyynärää pitkäksi, ja viisi kyynärää korkiaksi leveydessä pihan vaatteen kohdalla,"],[38,19,"Niin myös niiden neljä patsasta ja niiden neljä jalkaa vaskesta, ja heidän koukkunsa hopiasta, ja heidän päänsä silatut ja vyötetyt hopiavöillä.","Niin myös niiden neljä patsasta ja niiden neljä jalkaa vaskesta, ja heidän koukkunsa hopiasta, ja heidän päänsä silatut ja vyötetyt hopiavöillä."],[38,20,"Ja kaikki vaarnat majassa, ja koko piha ympärinsä, olivat vaskesta.","Ja kaikki vaarnat majassa, ja koko piha ympärinsä, olivat vaskesta."],[38,21,"Tämä on kaluin luku joka todistuksen majaan tarvittiin, jotka ovat luetut Moseksen käskyn jälkeen: Leviläisten palveluksen kautta, Itamarin papin Aaronin pojan käden alla.","Tämä on kaluin luku joka todistuksen majaan tarvittiin, jotka ovat luetut Moseksen käskyn jälkeen: Leviläisten palveluksen kautta, Itamarin papin Aaronin pojan käden alla."],[38,22,"Ja Betsaleel Urin poika, Hurin pojanpoika Juudan suvusta, teki kaikki kuin Herra Mosekselle oli käskenyt,","Ja Betsaleel Urin poika, Hurin pojanpoika Juudan suvusta, teki kaikki kuin Herra Mosekselle oli käskenyt,"],[38,23,"Ja hänen kanssansa Oholiab Ahisamakin poika Danin suvusta; sillä hän oli taitava ja ymmärtäväinen neulomaan sinisillä, ja purpuraisilla, ja tulipunaisilla villoilla, ja valkialla liinalla.","Ja hänen kanssansa Oholiab Ahisamakin poika Danin suvusta; sillä hän oli taitava ja ymmärtäväinen neulomaan sinisillä, ja purpuraisilla, ja tulipunaisilla villoilla, ja valkialla liinalla."],[38,24,"Kaikki se kulta mikä tehtiin kaiken tämän pyhän tarpeeksi, se kuin annettu oli ylennykseksi, oli yhdeksänkolmattakymmentä leiviskää, seitsemänsataa ja kolmekymmentä sikliä, pyhän siklin jälkeen.","Kaikki se kulta mikä tehtiin kaiken tämän pyhän tarpeeksi, se kuin annettu oli ylennykseksi, oli yhdeksänkolmattakymmentä leiviskää, seitsemänsataa ja kolmekymmentä sikliä, pyhän siklin jälkeen."],[38,25,"Mutta hopia, joka siihen yhteiseltä kansalta annettiin, oli sata leiviskää, tuhannen seitsemänsataa viisikahdeksattakymmentä sikliä, pyhän siklin jälkeen:","Mutta hopia, joka siihen yhteiseltä kansalta annettiin, oli sata leiviskää, tuhannen seitsemänsataa viisikahdeksattakymmentä sikliä, pyhän siklin jälkeen:"],[38,26,"Niin monta puolta sikliä, kuin monta henkeä, pyhän siklin jälkeen: kaikilta niiltä, jotka luetut olivat kahdestakymmenestä ajastajasta ja sen ylitse, kuusisataa tuhatta, kolmetuhatta, viisisataa ja viisikymmentä.","Niin monta puolta sikliä, kuin monta henkeä, pyhän siklin jälkeen: kaikilta niiltä, jotka luetut olivat kahdestakymmenestä ajastajasta ja sen ylitse, kuusisataa tuhatta, kolmetuhatta, viisisataa ja viisikymmentä."],[38,27,"Sadasta leiviskästä hopiaa valettiin pyhät jalat, ja esiripun jalat: sata jalkaa sadasta leiviskästä, leiviskä kullekin jalalle.","Sadasta leiviskästä hopiaa valettiin pyhät jalat, ja esiripun jalat: sata jalkaa sadasta leiviskästä, leiviskä kullekin jalalle."],[38,28,"Mutta tuhannesta seitsemästäsadasta ja viidestäkahdeksattakymmenestä siklistä tehtiin koukut patsaisiin: ja heidän päänsä silattiin, ja vyöllä vyötettiin.","Mutta tuhannesta seitsemästäsadasta ja viidestäkahdeksattakymmenestä siklistä tehtiin koukut patsaisiin: ja heidän päänsä silattiin, ja vyöllä vyötettiin."],[38,29,"Mutta vaski, joka annettiin ylennysuhriksi, oli seitsemänkymmentä leiviskää, kaksituhatta ja neljäsataa sikliä.","Mutta vaski, joka annettiin ylennysuhriksi, oli seitsemänkymmentä leiviskää, kaksituhatta ja neljäsataa sikliä."],[38,30,"Siitä tehtiin jalat seurakunnan majan oveen, ja vaski-alttari ja vaskihäkki kuin siinä oli, ja myös kaikki alttarin astiat,","Siitä tehtiin jalat seurakunnan majan oveen, ja vaski-alttari ja vaskihäkki kuin siinä oli, ja myös kaikki alttarin astiat,"],[38,31,"Niin myös jalat ympärinsä pihaa, ja jalat pihan sisällekäytävään, ja kaikki majan vaarnat, ja kaikki pihan vaarnat ympärinsä.","Niin myös jalat ympärinsä pihaa, ja jalat pihan sisällekäytävään, ja kaikki majan vaarnat, ja kaikki pihan vaarnat ympärinsä."],[39,1,"Mutta sinisistä, ja purpuraisista, ja tulipunaisista villoista tekivät he virkavaatteita palvelukseen pyhässä: ja he tekivät pyhiä vaatteita Aaronille, niinkuin Herra oli käskenyt Mosekselle.","Mutta sinisistä, ja purpuraisista, ja tulipunaisista villoista tekivät he virkavaatteita palvelukseen pyhässä: ja he tekivät pyhiä vaatteita Aaronille, niinkuin Herra oli käskenyt Mosekselle."],[39,2,"Ja hän teki päällisvaatteen kullasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta.","Ja hän teki päällisvaatteen kullasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta."],[39,3,"Ja he takoivat kullan kiskoksi, jonka hän leikkasi langaksi, että se taittiin taitavasti kudottaa sinisten, purpuraisten ja tulipunaisten villain ja valkian liinan seassa.","Ja he takoivat kullan kiskoksi, jonka hän leikkasi langaksi, että se taittiin taitavasti kudottaa sinisten, purpuraisten ja tulipunaisten villain ja valkian liinan seassa."],[39,4,"He tekivät hänelle olkavaatteet, yhteensidotut: kahdelta kulmalta se yhdistettiin.","He tekivät hänelle olkavaatteet, yhteensidotut: kahdelta kulmalta se yhdistettiin."],[39,5,"Ja vyö sen päällä oli myös tehty sillä tavalla taitavasti kullasta, sinisistä, purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta: niinkuin Herra oli käskenyt Mosekselle.","Ja vyö sen päällä oli myös tehty sillä tavalla taitavasti kullasta, sinisistä, purpuraisista, ja tulipunaisista villoista ja valkiasta kerratusta liinasta: niinkuin Herra oli käskenyt Mosekselle."],[39,6,"Ja he tekivät onikin kivet, kiinnitetyt kultaan: kaivetut sinetin tavalla Israelin lasten nimein jälkeen.","Ja he tekivät onikin kivet, kiinnitetyt kultaan: kaivetut sinetin tavalla Israelin lasten nimein jälkeen."],[39,7,"Ja istuttivat ne olkapäille päällisvaatteesen, että ne kivet piti oleman Israelin lapsille muistoksi: niinkuin Herra oli käskenyt Mosekselle.","Ja istuttivat ne olkapäille päällisvaatteesen, että ne kivet piti oleman Israelin lapsille muistoksi: niinkuin Herra oli käskenyt Mosekselle."],[39,8,"Ja he tekivät rintavaatteen sillä tavalla taitavasti, kuin päällisvaatekin oli tehty: kullasta, sinisistä, ja purpuraisista villoista, ja kalliista kerratusta liinasta,","Ja he tekivät rintavaatteen sillä tavalla taitavasti, kuin päällisvaatekin oli tehty: kullasta, sinisistä, ja purpuraisista villoista, ja kalliista kerratusta liinasta,"],[39,9,"Niin että se oli nelitahkoinen ja kaksikertainen: vaaksa pituudelta ja vaaksa leveydeltä, aina kaksikertaisesti.","Niin että se oli nelitahkoinen ja kaksikertainen: vaaksa pituudelta ja vaaksa leveydeltä, aina kaksikertaisesti."],[39,10,"Ja täytti sen neljällä kivirivillä: ensimäinen rivi oli sardius, topatsius ja smaragdi;","Ja täytti sen neljällä kivirivillä: ensimäinen rivi oli sardius, topatsius ja smaragdi;"],[39,11,"Toinen rivi: rubin, saphiir ja demanti;","Toinen rivi: rubin, saphiir ja demanti;"],[39,12,"Kolmas rivi: lynkurius, akat ja ametisti;","Kolmas rivi: lynkurius, akat ja ametisti;"],[39,13,"Ja neljäs rivi: turkos, oniks ja jaspis: kiinnitetyt ympäriltä kullalla joka riviltä.","Ja neljäs rivi: turkos, oniks ja jaspis: kiinnitetyt ympäriltä kullalla joka riviltä."],[39,14,"Ja nämät kivet olivat Israelin lasten nimein jälkeen kaksitoistakymmentä, kaivetut sinetin tavalla, itsekukin nimeltänsä, kahdentoistakymmentä sukukunnan jälkeen.","Ja nämät kivet olivat Israelin lasten nimein jälkeen kaksitoistakymmentä, kaivetut sinetin tavalla, itsekukin nimeltänsä, kahdentoistakymmentä sukukunnan jälkeen."],[39,15,"He tekivät myös rintavaatteen päälle vitjat kahden pään kanssa, vääten puhtaasta kullasta.","He tekivät myös rintavaatteen päälle vitjat kahden pään kanssa, vääten puhtaasta kullasta."],[39,16,"Ja he tekivät kaksi kultanastaa, ja kaksi kultarengasta, ja yhdistivät ne kaksi rengasta kahteen rintavaatteen palteesen.","Ja he tekivät kaksi kultanastaa, ja kaksi kultarengasta, ja yhdistivät ne kaksi rengasta kahteen rintavaatteen palteesen."],[39,17,"Ja pistivät ne kaksi kultavitjaa niihin kahteen renkaasen, rintavaatteen kulmiin.","Ja pistivät ne kaksi kultavitjaa niihin kahteen renkaasen, rintavaatteen kulmiin."],[39,18,"Mutta ne kaksi päätä vitjoista panivat he ylös niihin kahteen nastaan, ja yhdistivät ne päällisvaatteen kulmilta, juuri toinen toisensa kohdalle.","Mutta ne kaksi päätä vitjoista panivat he ylös niihin kahteen nastaan, ja yhdistivät ne päällisvaatteen kulmilta, juuri toinen toisensa kohdalle."],[39,19,"Niin he tekivät kaksi muuta kultarengasta, ja yhdistivät ne niihin toisiin kahteen rintavaatteen kulmaan, sen palteesen joka on päällisvaatteen sivussa sisällisellä puolella.","Niin he tekivät kaksi muuta kultarengasta, ja yhdistivät ne niihin toisiin kahteen rintavaatteen kulmaan, sen palteesen joka on päällisvaatteen sivussa sisällisellä puolella."],[39,20,"Ja he tekivät kaksi muuta kultarengasta: ne panivat he kahteen kulmaan alhaallepäin päällisvaatteesen, toinen toisensa kohdalle, sitä saumaa kohden, päällisvaatteen vyön ylimmäiselle puolelle,","Ja he tekivät kaksi muuta kultarengasta: ne panivat he kahteen kulmaan alhaallepäin päällisvaatteesen, toinen toisensa kohdalle, sitä saumaa kohden, päällisvaatteen vyön ylimmäiselle puolelle,"],[39,21,"Niin että rintavaate yhdistettiin renkainensa niihin renkaisiin, kuin oli päällisvaatteessa, sinisellä nuoralla, niin että se olis liki päällisvaatetta, ja ei eriäis päällisvaatteesta: niinkuin Herra käski Mosekselle.","Niin että rintavaate yhdistettiin renkainensa niihin renkaisiin, kuin oli päällisvaatteessa, sinisellä nuoralla, niin että se olis liki päällisvaatetta, ja ei eriäis päällisvaatteesta: niinkuin Herra käski Mosekselle."],[39,22,"Hän teki myös hameen päällisvaatteen alle, kokonansa kudotun sinisistä villoista.","Hän teki myös hameen päällisvaatteen alle, kokonansa kudotun sinisistä villoista."],[39,23,"Ja päänläven keskelle, niinkuin pantsarin päänläven; sepaluksen päänläven ympärille pallistetun, ettei se kehkiäisi.","Ja päänläven keskelle, niinkuin pantsarin päänläven; sepaluksen päänläven ympärille pallistetun, ettei se kehkiäisi."],[39,24,"Ja he tekivät granaatin omenat alhaalle hameen liepeisiin sinisistä, ja purpuraisista ja tulipunaisista villoista, jotka kerratut olivat.","Ja he tekivät granaatin omenat alhaalle hameen liepeisiin sinisistä, ja purpuraisista ja tulipunaisista villoista, jotka kerratut olivat."],[39,25,"Ja tekivät kulkuiset puhtaasta kullasta, ja panivat ne kulkuiset granaatin omenain välille ympärille, hameen liepeisiin.","Ja tekivät kulkuiset puhtaasta kullasta, ja panivat ne kulkuiset granaatin omenain välille ympärille, hameen liepeisiin."],[39,26,"Niin että kulkuinen ja granaatin omena oli vuoroin ympärinsä hameen liepeitä: palvelemaan sillä, niinkuin Herra käskenyt oli Mosekselle.","Niin että kulkuinen ja granaatin omena oli vuoroin ympärinsä hameen liepeitä: palvelemaan sillä, niinkuin Herra käskenyt oli Mosekselle."],[39,27,"Ja he tekivät myös ahtaat hameet, kudotut valkiasta kalliista liinasta, Aaronille ja hänen pojillensa,","Ja he tekivät myös ahtaat hameet, kudotut valkiasta kalliista liinasta, Aaronille ja hänen pojillensa,"],[39,28,"Ja hiipan valkiasta kalliista liinasta, ja kauniit lakit valkiasta kalliista liinasta, ja alusvaatteet valkiasta kerratusta liinasta,","Ja hiipan valkiasta kalliista liinasta, ja kauniit lakit valkiasta kalliista liinasta, ja alusvaatteet valkiasta kerratusta liinasta,"],[39,29,"Ja taitavasti neulotun vyön valkiasta kerratusta kalliista liinasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista: niinkuin Herra käskenyt oli Mosekselle:","Ja taitavasti neulotun vyön valkiasta kerratusta kalliista liinasta, sinisistä, ja purpuraisista, ja tulipunaisista villoista: niinkuin Herra käskenyt oli Mosekselle:"],[39,30,"He tekivät myös otsalehden, pyhän kruunun päälle, puhtaasta kullasta, ja kaivoivat kirjoituksen siihen, niinkuin sinetti kaivetaan: HERRAN PYHYYS.","He tekivät myös otsalehden, pyhän kruunun päälle, puhtaasta kullasta, ja kaivoivat kirjoituksen siihen, niinkuin sinetti kaivetaan: HERRAN PYHYYS."],[39,31,"Ja sitoivat sen päälle sinisen nuoran, että sen piti yhdistämän hiipan ylhäältä: niinkuin Herra oli käskenyt Mosekselle.","Ja sitoivat sen päälle sinisen nuoran, että sen piti yhdistämän hiipan ylhäältä: niinkuin Herra oli käskenyt Mosekselle."],[39,32,"Ja niin kaikki seurakunnan majan rakennus päätettiin. Ja Israelin lapset tekivät kaikki sen jälkeen, kuin Herra oli käskenyt Mosekselle; niin he tekivät.","Ja niin kaikki seurakunnan majan rakennus päätettiin. Ja Israelin lapset tekivät kaikki sen jälkeen, kuin Herra oli käskenyt Mosekselle; niin he tekivät."],[39,33,"Ja he kantoivat majan Moseksen tykö kaluinensa: sen koukut, laudat, korennot, patsaat ja jalat.","Ja he kantoivat majan Moseksen tykö kaluinensa: sen koukut, laudat, korennot, patsaat ja jalat."],[39,34,"Ja peitteen punalla painetuista oinaan nahoista, peitteen tekasjim-nahoista: ja peitteen esiripun,","Ja peitteen punalla painetuista oinaan nahoista, peitteen tekasjim-nahoista: ja peitteen esiripun,"],[39,35,"Todistusarkin korentoinensa, ja myös armo-istuimen,","Todistusarkin korentoinensa, ja myös armo-istuimen,"],[39,36,"Pöydän kaikkein astiainsa kanssa, ja katsomusleivät,","Pöydän kaikkein astiainsa kanssa, ja katsomusleivät,"],[39,37,"Puhtaan kynttiläjalan valmistetun lamppuinensa, kaiken sen kanssa kuin siihen tarvittiin, ja öljyä valkeudeksi,","Puhtaan kynttiläjalan valmistetun lamppuinensa, kaiken sen kanssa kuin siihen tarvittiin, ja öljyä valkeudeksi,"],[39,38,"Kulta-alttarin ja voidellusöljyn, ja yrttein suitsutuksen, ja majan ovivaatteen,","Kulta-alttarin ja voidellusöljyn, ja yrttein suitsutuksen, ja majan ovivaatteen,"],[39,39,"Vaskisen alttarin ja vaskisen häkin korentoinensa, ja kaikkein kaluinsa kanssa, ja pesoastian jalkoinensa,","Vaskisen alttarin ja vaskisen häkin korentoinensa, ja kaikkein kaluinsa kanssa, ja pesoastian jalkoinensa,"],[39,40,"Pihan vaatteet patsainensa ja jalkoinensa, vaatteen pihan sisällekäytävän eteen, köysinensä ja vaajoinensa, ja kaikki seurakunnan majan palveluksen astiat,","Pihan vaatteet patsainensa ja jalkoinensa, vaatteen pihan sisällekäytävän eteen, köysinensä ja vaajoinensa, ja kaikki seurakunnan majan palveluksen astiat,"],[39,41,"Virkavaatteet palveltaa pyhässä, papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, joilla heidän piti tekemän papin viran palveluksen:","Virkavaatteet palveltaa pyhässä, papin Aaronin pyhät vaatteet, ja hänen poikainsa vaatteet, joilla heidän piti tekemän papin viran palveluksen:"],[39,42,"Kaikkein niiden jälkeen mitkä Herra oli käskenyt Mosekselle: niin tekivät Israelin lapset kaiken sen työn.","Kaikkein niiden jälkeen mitkä Herra oli käskenyt Mosekselle: niin tekivät Israelin lapset kaiken sen työn."],[39,43,"Ja Moses näki kaiken tämän rakennuksen, että he olivat tehneet sen, niinkuin Herra oli käskenyt; ja Moses siunasi heitä.","Ja Moses näki kaiken tämän rakennuksen, että he olivat tehneet sen, niinkuin Herra oli käskenyt; ja Moses siunasi heitä."],[40,1,"Ja Herra puhui Mosekselle, sanoen:","Ja Herra puhui Mosekselle, sanoen:"],[40,2,"Ensimäisenä päivänä ensimäisestä kuusta pitää sinun paneman ylös seurakunnan majan.","Ensimäisenä päivänä ensimäisestä kuusta pitää sinun paneman ylös seurakunnan majan."],[40,3,"Ja sinun pitää siihen paneman sisälle todistuksen arkin, ja sinun pitää peittämän arkin esiripulla.","Ja sinun pitää siihen paneman sisälle todistuksen arkin, ja sinun pitää peittämän arkin esiripulla."],[40,4,"Ja sinun pitää myös sinne sisälle tuoman pöydän, ja valmistaman sen, ja asettaman siihen kynttiläjalan, ja paneman lamput sen päälle.","Ja sinun pitää myös sinne sisälle tuoman pöydän, ja valmistaman sen, ja asettaman siihen kynttiläjalan, ja paneman lamput sen päälle."],[40,5,"Ja sinun pitää asettaman kultaisen savualttarin todistusarkin eteen, ja ripustaman vaatteen majan eteen.","Ja sinun pitää asettaman kultaisen savualttarin todistusarkin eteen, ja ripustaman vaatteen majan eteen."],[40,6,"Mutta polttouhrin alttarin pitää sinun asettaman seurakunnan majan oven eteen,","Mutta polttouhrin alttarin pitää sinun asettaman seurakunnan majan oven eteen,"],[40,7,"Ja paneman pesoastian seurakunnan majan ja alttarin välille, ja paneman siihen vettä,","Ja paneman pesoastian seurakunnan majan ja alttarin välille, ja paneman siihen vettä,"],[40,8,"Ja tekemän pihan sen ympärille, ja ripustaman vaatteen pihan portin eteen,","Ja tekemän pihan sen ympärille, ja ripustaman vaatteen pihan portin eteen,"],[40,9,"Ja ottaman voidellusöljyn, ja voiteleman majan ja kaikki ne mitkä siinä ovat, ja pyhittämän sen kaluinensa, että ne olisivat pyhät,","Ja ottaman voidellusöljyn, ja voiteleman majan ja kaikki ne mitkä siinä ovat, ja pyhittämän sen kaluinensa, että ne olisivat pyhät,"],[40,10,"Ja voiteleman polttouhrin alttarin kaluinensa, ja pyhittämän alttarin: ja se alttari pitää oleman kaikkein pyhin.","Ja voiteleman polttouhrin alttarin kaluinensa, ja pyhittämän alttarin: ja se alttari pitää oleman kaikkein pyhin."],[40,11,"Sinun pitää myös voiteleman pesinastian jalkoinensa, ja sen pyhittämän.","Sinun pitää myös voiteleman pesinastian jalkoinensa, ja sen pyhittämän."],[40,12,"Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heidät vedellä,","Ja sinun pitää tuoman Aaronin poikinensa seurakunnan majan oven eteen, ja pesemän heidät vedellä,"],[40,13,"Ja puettaman Aaronin pyhiin vaatteisiin, ja voiteleman ja pyhittämän hänen, minun papikseni.","Ja puettaman Aaronin pyhiin vaatteisiin, ja voiteleman ja pyhittämän hänen, minun papikseni."],[40,14,"Ja sinun pitää myös tuoman hänen poikansa ja puettaman heidän yllensä ahtaat hameet,","Ja sinun pitää myös tuoman hänen poikansa ja puettaman heidän yllensä ahtaat hameet,"],[40,15,"Ja voiteleman heidät, niinkuin sinä heidän isänsä voitelit, minun papikseni. Ja tämän voidelluksen pitää oleman heille ijankaikkiseksi pappeudeksi, heidän sukukunnissansa.","Ja voiteleman heidät, niinkuin sinä heidän isänsä voitelit, minun papikseni. Ja tämän voidelluksen pitää oleman heille ijankaikkiseksi pappeudeksi, heidän sukukunnissansa."],[40,16,"Ja Moses teki kaikki kuin Herra oli hänelle käskenyt.","Ja Moses teki kaikki kuin Herra oli hänelle käskenyt."],[40,17,"Niin tapahtui toisena vuonna, ensimäisenä päivänä ensimäisestä kuusta, että maja pantiin ylös.","Niin tapahtui toisena vuonna, ensimäisenä päivänä ensimäisestä kuusta, että maja pantiin ylös."],[40,18,"Ja koska Moses pani ylös majan, niin hän asetti jalat ja laudat ja korennot, ja nosti patsaat pystyälle,","Ja koska Moses pani ylös majan, niin hän asetti jalat ja laudat ja korennot, ja nosti patsaat pystyälle,"],[40,19,"Ja levitti peitteen majan ylitse, ja pani katon sen päälle: niinkuin Herra oli käskenyt Mosekselle.","Ja levitti peitteen majan ylitse, ja pani katon sen päälle: niinkuin Herra oli käskenyt Mosekselle."],[40,20,"Ja otti todistuksen ja pani arkkiin, ja asetti korennot arkin päälle, ja pani myös armoistuimen arkin päälle.","Ja otti todistuksen ja pani arkkiin, ja asetti korennot arkin päälle, ja pani myös armoistuimen arkin päälle."],[40,21,"Ja toi arkin majaan, ja ripusti esiripun todistusarkin eteen: niinkuin Herra oli käskenyt Mosekselle.","Ja toi arkin majaan, ja ripusti esiripun todistusarkin eteen: niinkuin Herra oli käskenyt Mosekselle."],[40,22,"Niin asetti hän myös pöydän seurakunnan majaan, pohjan puoliselle sivulle, ulkoiselle puolelle esirippua.","Niin asetti hän myös pöydän seurakunnan majaan, pohjan puoliselle sivulle, ulkoiselle puolelle esirippua."],[40,23,"Ja asetti leivät sen päälle järjestykseen, Herran eteen: niinkuin Herra oli käskenyt Mosekselle.","Ja asetti leivät sen päälle järjestykseen, Herran eteen: niinkuin Herra oli käskenyt Mosekselle."],[40,24,"Niin pani hän myös kynttiläjalan seurakunnan majaan, juuri pöydän kohdalle, etelän sivulle majaa.","Niin pani hän myös kynttiläjalan seurakunnan majaan, juuri pöydän kohdalle, etelän sivulle majaa."],[40,25,"Ja pani lamput niiden päälle Herran eteen: niinkuin Herra oli käskenyt Mosekselle.","Ja pani lamput niiden päälle Herran eteen: niinkuin Herra oli käskenyt Mosekselle."],[40,26,"Ja pani myös kultaisen alttarin seurakunnan majaan, esiripun eteen.","Ja pani myös kultaisen alttarin seurakunnan majaan, esiripun eteen."],[40,27,"Ja suitsutti yrttein suitsutuksen sen päällä: niinkuin Herra oli käskenyt Mosekselle.","Ja suitsutti yrttein suitsutuksen sen päällä: niinkuin Herra oli käskenyt Mosekselle."],[40,28,"Ja ripusti vaatteen majan oven eteen.","Ja ripusti vaatteen majan oven eteen."],[40,29,"Vaan polttouhrin alttarin pani hän seurakunnan majan oven eteen, ja uhrasi sen päällä polttouhrin ja ruokauhrin: niinkuin Herra oli käskenyt Mosekselle.","Vaan polttouhrin alttarin pani hän seurakunnan majan oven eteen, ja uhrasi sen päällä polttouhrin ja ruokauhrin: niinkuin Herra oli käskenyt Mosekselle."],[40,30,"Ja pesoastian pani hän seurakunnan majan ja alttarin välille, ja pani siihen vettä pestä heitänsä.","Ja pesoastian pani hän seurakunnan majan ja alttarin välille, ja pani siihen vettä pestä heitänsä."],[40,31,"Ja Moses ja Aaron ja hänen poikansa pesivät kätensä ja jalkansa siitä.","Ja Moses ja Aaron ja hänen poikansa pesivät kätensä ja jalkansa siitä."],[40,32,"Sillä heidän piti pesemän itsensä, koska he menivät seurakunnan majaan eli kävivät alttarin tykö; niinkuin Herra oli käskenyt Mosekselle.","Sillä heidän piti pesemän itsensä, koska he menivät seurakunnan majaan eli kävivät alttarin tykö; niinkuin Herra oli käskenyt Mosekselle."],[40,33,"Ja hän pani pihan ylös, majan ja alttarin ympärille, ja ripusti vaatteen pihan sisällekäytävään. Ja niin Moses päätti sen työn.","Ja hän pani pihan ylös, majan ja alttarin ympärille, ja ripusti vaatteen pihan sisällekäytävään. Ja niin Moses päätti sen työn."],[40,34,"Ja pilvi peitti seurakunnan majan, ja Herran kunnia täytti majan.","Ja pilvi peitti seurakunnan majan, ja Herran kunnia täytti majan."],[40,35,"Ja ei Moses taitanut käydä seurakunnan majaan; sillä pilvi oli sen päällä, ja Herran kunnia täytti majan.","Ja ei Moses taitanut käydä seurakunnan majaan; sillä pilvi oli sen päällä, ja Herran kunnia täytti majan."],[40,36,"Ja koska pilvi meni ylös majan päältä niin Israelin lapset vaelsivat, kaikissa matkoissansa.","Ja koska pilvi meni ylös majan päältä niin Israelin lapset vaelsivat, kaikissa matkoissansa."],[40,37,"Vaan koska ei pilvi mennyt ylös, silloin ei he vaeltaneet, siihen päivään asti, että se meni ylös.","Vaan koska ei pilvi mennyt ylös, silloin ei he vaeltaneet, siihen päivään asti, että se meni ylös."],[40,38,"Sillä Herran pilvi oli päivällä majan ylitse, ja yöllä oli tuli siinä, koko Israelin huoneen silmäin edessä, kaikissa heidän vaelluksissansa.","Sillä Herran pilvi oli päivällä majan ylitse, ja yöllä oli tuli siinä, koko Israelin huoneen silmäin edessä, kaikissa heidän vaelluksissansa."]]}};